const DATA = [{"id":"s1","name":"1. semester","subjects":[{"id":"pravo","name":"Pravo družb in poslovno pravo","tier":"S","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[{"id":"pk1-uvod","name":"Uvod v pravoznanstvo","questions":[{"q":"Kaj je pravo?","options":["Skupek moralnih priporočil, ki jih družba prostovoljno upošteva","Nominativni sistem pravil, podprt s kredibilno grožnjo uporabe fizične sile proti kršitelju","Zbirka sodnih odločb, ki veljajo samo za stranke v sporu","Sistem tehničnih pravil o razmerju med vzrokom in posledico"],"correct":1,"explanation":"Pravo je nominativni sistem pravil, podprt s kredibilno grožnjo uporabe fizične sile proti kršitelju teh norm. Sestavljajo ga pravila države, ki urejajo ravnanje države in njenih državljanov.","wrong":{"0":"Pravo je obvezno in sankcionirano, ne prostovoljno kot morala.","3":"To so tehnična pravila (naravoslovje/tehnologija) - pravo je odvisno od človeških odločitev."}},{"q":"Katera značilnost je tipična za pravo common law (anglo-ameriško pravo)?","options":["Obsežni zakoni in dejavna vloga sodnikov","Sodnik navaja precedense, družbene norme in poslovne prakse ter je nevtralen razsodnik","Sodnik svojo razlago utemeljuje izključno z navajanjem pomena zakonov","Porota ne obstaja, odloča izključno sodnik"],"correct":1,"explanation":"Common law: podobne primere rešujejo na podoben način (precedensi), sodnik je nevtralen razsodnik, sodi porota. Kontinentalno pravo: obsežni zakoni, sodniki imajo dejavno vlogo in razlagajo pomen zakonov."},{"q":"Katera dva elementa ima načelo delitve oblasti?","options":["Ločitev posameznih funkcij oblasti in obstoj zavor in ravnovesij med njimi","Nadrejenost zakonodajne veje in podrejenost sodne veje","Združitev izvršilne in zakonodajne oblasti ter neodvisnost sodstva","Hierarhijo pravnih aktov in pravno državo"],"correct":0,"explanation":"Delitev oblasti (zakonodajna, izvršilna, sodna) preprečuje zlorabo oblasti. Elementa: ločitev funkcij oblasti + zavore in ravnovesja (checks and balances). Je temeljno ustavno načelo v RS."},{"q":"Kaj je bistvo pravne države?","options":["Da država z zakoni ureja vsa družbena razmerja","Da je delovanje vseh državnih organov urejeno s pravnimi pravili","Da o vseh sporih odloča neodvisno sodišče","Da državljani sami sprejemajo zakone na referendumih"],"correct":1,"explanation":"Pravna država: delovanje državnih organov je pravno vezano - urejeno s pravnimi pravili. Navezuje se na meščansko državo."},{"q":"Katere tri sestavine ima pravno pravilo (pravna norma)?","options":["Hipotezo, dispozicijo in sankcijo","Zapoved, prepoved in dovoljenje","Splošnost, abstraktnost in konkretnost","Zakon, uredbo in pravilnik"],"correct":0,"explanation":"Hipoteza = okoliščine/dejansko stanje (vožnja v križišče), dispozicija = pravno dopusten način obnašanja (ustavi pred znakom STOP), sankcija = pravne posledice kršitve dispozicije (plačaš 200 EUR).","wrong":{"1":"Zapovedi, prepovedi in dovoljenja so tri VRSTE dispozicije, ne sestavine pravila."}},{"q":"Dispozicija pravnega pravila določa:","options":["okoliščine, v katerih se moramo ravnati po pravilu","pravno dopusten način obnašanja (zapoved, prepoved ali dovoljenje)","pravne posledice kršitve pravila","organ, ki nadzoruje izvajanje pravila"],"correct":1,"explanation":"Dispozicija je osrednji del pravnega pravila in določa pravno dopusten način obnašanja. Tri vrste: zapovedi, prepovedi, dovoljenja. Okoliščine določa hipoteza, posledice kršitve sankcija."},{"q":"Na kaj se nanašata splošnost in abstraktnost tipskega pravnega pravila?","options":["Splošnost na subjekte urejanja (kdor, vsakdo, državljan), abstraktnost na tipski opis dejanskega stanu","Splošnost na dejanski stan, abstraktnost na subjekte urejanja","Obe se nanašata na krajevno veljavnost pravila","Splošnost na sankcijo, abstraktnost na dispozicijo"],"correct":0,"explanation":"Splošnost = naslovljenci niso individualno določeni, označeni so s tipsko lastnostjo (kdor, vsakdo, študent). Abstraktnost = tipski opis vnaprej zamišljenega, predvidenega dejanskega stanu."},{"type":"match","q":"Poveži vrsto pravnega akta z opisom.","pairs":[{"term":"Splošni pravni akt","def":"Vzpostavlja, spreminja ali odpravlja splošna in abstraktna pravna pravila (ustava, zakon, pravilnik)"},{"term":"Posamični pravni akt","def":"Vzpostavlja ali odpravlja posamične in konkretne pravne norme (sodba, odločba, pogodba)"},{"term":"Materialni pravni akt","def":"Dejansko ravnanje, s katerim subjekt udejanja dispozicije ali sankcije (plačilo davka)"},{"term":"Oblastni pravni akt","def":"Izdaja ga država, lokalne skupnosti in nosilci javnih pooblastil"},{"term":"Neoblastni pravni akt","def":"Izdajajo ga društva, zavodi, gospodarske družbe"}],"explanation":"Normativni pravni akti (splošni + posamični) neposredno ustvarjajo, spreminjajo in ukinjajo pravna pravila; materialni akti so dejanska ravnanja, ki jih udejanjajo."},{"q":"Kdaj začnejo veljati splošni pravni akti z državnimi predpisi, če ni določeno drugače?","options":["Z dnem objave v Uradnem listu RS","8. dan po objavi v Uradnem listu RS","15. dan po objavi v Uradnem listu RS","30. dan po sprejetju v Državnem zboru"],"correct":2,"explanation":"Splošni pravni akti z državnimi predpisi začnejo veljati 15. dan po objavi v Uradnem listu Republike Slovenije, če ni določeno drugače. (Pozor: uredbe EU začnejo veljati 20. dan po objavi v Uradnem listu EU.)"},{"q":"Novi splošni pravni akt ne vsebuje derogacijske klavzule, akta pa si nasprotujeta. Katero pravilo NE velja pri razreševanju?","options":["Višji pravni akt razveljavi nižjega","Mlajši pravni akt razveljavi starejšega","Specialnejši pravni akt razveljavi splošnejšega","Starejši pravni akt razveljavi mlajšega"],"correct":3,"explanation":"Velja ravno obratno: mlajši razveljavi starejšega (lex posterior). Ostali pravili: višji razveljavi nižjega (lex superior), specialnejši razveljavi splošnejšega (lex specialis)."},{"q":"Pod katerimi pogoji je retroaktivnost izjemoma dopustna?","options":["Če jo sprejme vlada z uredbo in velja za celoten zakon","Retroaktivno učinkujejo samo posamezne zakonske določbe, terja jo javna korist in ne posega v pridobljene pravice","Če se z njo strinja večina naslovljencev in jo potrdi ustavno sodišče","Retroaktivnost v pravu nikoli ni dopustna"],"correct":1,"explanation":"Trije pogoji: (1) samo posamezne zakonske določbe, (2) terja jo javna korist, (3) ne posega v pridobljene pravice. Načeloma pa retroaktivnost ni dopustna.","wrong":{"3":"Načeloma res ni dopustna, a zakon pozna izjemo pod tremi strogimi pogoji."}},{"q":"Kako se lahko spremeni Ustava RS?","options":["Z navadno večino glasov v Državnem zboru","Z 2/3 večino vseh glasov v Državnem zboru (60 glasov)","Z referendumom, ki ga razpiše predsednik republike","S soglasjem vlade in ustavnega sodišča"],"correct":1,"explanation":"Ustavo sprejme ali spremeni samo Državni zbor kot ustavodajni organ, in sicer z 2/3 večino VSEH glasov, tj. 60 glasov (od 90 poslancev)."},{"q":"Kaj je zakonik?","options":["Vsak zakon, ki ga sprejme Državni zbor","Zakon, ki naj bi v celoti in sistematično urejal vsebinsko zaokroženo pravno področje (npr. Obligacijski zakonik)","Podzakonski akt, ki podrobneje ureja zakonsko materijo","Zbirka vseh veljavnih zakonov v državi"],"correct":1,"explanation":"Zakonik celovito in sistematično ureja zaokroženo pravno področje družbenega življenja - npr. Obligacijski zakonik, pomorski zakonik, kazenski zakonik."},{"q":"Kdo sprejema uredbe kot najpomembnejše podzakonske akte in kakšna je njihova omejitev?","options":["Državni zbor; lahko spreminjajo pravice in dolžnosti subjektov","Vlada RS; z uredbo podrobneje izpelje določbe zakona, ne sme pa posegati v pravice in dolžnosti pravnih subjektov","Posamezni minister; veljajo samo za njegovo ministrstvo","Predsednik republike; potrjuje jih ustavno sodišče"],"correct":1,"explanation":"Uredbe sprejme Vlada RS. Z njimi podrobneje izpelje določbe zakona, ne sme pa vplivati na pravice in dolžnosti pravnih subjektov. Pravilnike sprejemajo ministri (če tako določi zakon/uredba ali po lastni oceni)."},{"q":"Katera pravna panoga ureja osebna in premoženjska razmerja, v katerih so pravni subjekti prirejeni (enakopravni) in avtonomni?","options":["Upravno pravo","Civilno pravo","Kazensko pravo","Ustavno pravo"],"correct":1,"explanation":"Civilno pravo - subjekti so prirejeni in avtonomni. Podpanoge: stvarno pravo, obligacijsko pravo (odškodninsko), dedno pravo, avtorsko pravo.","wrong":{"0":"V upravnem pravu je država nadrejena stranka (gradbeno dovoljenje, tehnični pregled)."}},{"q":"Načelo zakonitosti v kazenskem pravu pomeni:","options":["da mora vsak zakon sprejeti Državni zbor","da nikomur ne sme biti izrečena kazenska sankcija za dejanje, ki ga zakon ni določil kot kaznivo, še preden je bilo storjeno","da so vsi državljani enaki pred zakonom","da kazenske zadeve obravnavajo samo okrožna sodišča"],"correct":1,"explanation":"Nullum crimen, nulla poena sine lege: kaznivo dejanje in kazen morata biti z zakonom določena VNAPREJ, pred storitvijo dejanja. V kazenskem pravu zato tudi pravne praznine niso dopustne."},{"type":"match","q":"Poveži pravno panogo z njenim predmetom urejanja.","pairs":[{"term":"Ustavno pravo","def":"Temelji državnopravne ureditve, človekove pravice in svoboščine"},{"term":"Gospodarsko pravo","def":"Pravni status gospodarskih subjektov in gospodarski pravni posli (ZGD-1, ZIL-1)"},{"term":"Delovno pravo","def":"Sklenitev in prenehanje pogodbe o zaposlitvi, pravice pogodbenih strank"},{"term":"Upravno pravo","def":"Organizacija in delovanje državne uprave ter upravnopravna razmerja (gradbeno dovoljenje)"},{"term":"Mednarodno zasebno pravo","def":"Civilnopravna razmerja z mednarodnim elementom (osebna, družinska, premoženjska)"}],"explanation":"Klasične pravne panoge: civilno, ustavno, delovno, gospodarsko, kazensko, družinsko, mednarodno javno in zasebno pravo."},{"q":"Kaj je avtentična razlaga?","options":["Razlaga, ki jo poda vrhovno sodišče v konkretnem sporu","Preoblikovanje spornega besedila s strani organa, ki je akt izdal - ima značilnosti novega pravnega besedila","Teoretična razlaga pravnih strokovnjakov brez zavezujoče narave","Jezikovna razlaga pravne norme po slovnici"],"correct":1,"explanation":"Avtentična razlaga ni prava razlaga zakona: organ, ki je izdal prvotno sporno/dvoumno besedilo, ga na novo definira. Ima vse značilnosti novega pravnega besedila. Vrste razlag sicer: jezikovna, logična, sistematična, namenska, zgodovinska, teleološka."},{"q":"Kaj so pravne praznine?","options":["Pravna pravila brez sankcije","Družbena razmerja, ki niso pravno urejena, čeprav bi morala biti","Členi zakona, ki so bili razveljavljeni","Razmerja, ki jih pravo namenoma prepušča morali"],"correct":1,"explanation":"Klasične pravne praznine se pojavijo v zakonu (konfliktno razmerje zahteva normo, a je zakon ne vsebuje); praznine v širšem smislu = celotna pravna področja niso urejena (nova država, revolucija). V kazenskem pravu niso dopustne. Ugotovitev praznine izhaja iz poglobljene pravne analize."},{"q":"Katera sodišča so v Sloveniji sodišča prve stopnje?","options":["Okrajna in okrožna sodišča","Okrajna in višja sodišča","Okrožna in vrhovno sodišče","Višja sodišča in ustavno sodišče"],"correct":0,"explanation":"Prva stopnja: okrajna sodišča (44; splošno pristojna - manj hude kazenske zadeve, odškodninski zahtevki, služnosti, zemljiška knjiga, civilna izvršba) in okrožna sodišča (11; hujše zadeve, mladoletniki, izvrševanje sankcij, stečaj). Pritožbena stopnja: 4 višja sodišča. Najvišje: vrhovno sodišče (izredna pravna sredstva)."},{"q":"Koliko je v Sloveniji okrajnih in koliko okrožnih sodišč?","options":["44 okrajnih in 11 okrožnih","11 okrajnih in 44 okrožnih","4 okrajna in 11 okrožnih","44 okrajnih in 4 okrožna"],"correct":0,"explanation":"44 okrajnih sodišč, 11 okrožnih sodišč, 4 višja (pritožbena) sodišča in eno vrhovno sodišče. Specializirana: 4 delovna sodišča + 1 socialno, upravno sodišče (status višjega sodišča)."},{"q":"Kakšen je položaj Ustavnega sodišča RS?","options":["Je najvišja instanca rednega sodstva, nadrejeno vrhovnemu sodišču","Je ločen organ za varstvo ustavnosti, zakonitosti in človekovih pravic; ni del enotnega sodnega sistema; 9 sodnikov izvoli DZ na predlog predsednika republike","Je del vlade in nadzoruje zakonitost dela ministrstev","Njegove sodnike imenuje Sodni svet za dobo 6 let"],"correct":1,"explanation":"Ustavno sodišče je najvišji organ sodne oblasti za varstvo ustavnosti, zakonitosti in človekovih pravic, vendar je LOČEN organ (ni del rednega sodstva). 9 sodnikov na predlog predsednika republike izvoli Državni zbor. Odloča o skladnosti zakonov z ustavo, z mednarodnimi pogodbami itd."},{"q":"Kaj velja za Računsko sodišče?","options":["Je revizijski organ kontrole javne porabe brez sodnih pristojnosti","Odloča o pritožbah zoper davčne odločbe","Je specializirano sodišče za gospodarske spore","Nadzoruje delo Ustavnega sodišča"],"correct":0,"explanation":"Računsko sodišče je najvišji revizijski organ kontrole državnih računov, proračuna in celotne javne porabe. NIMA sodnih pristojnosti; je samostojen in neodvisen organ."},{"q":"Kdaj nastopi pravnomočnost sodne odločbe?","options":["Takoj z izdajo sodbe","Ko poteče rok za pritožbo (če se stranke ne pritožijo) oziroma ko višje sodišče odloči o pritožbi","Šele ko vrhovno sodišče zavrne revizijo","Ko sodba postane izvršljiva"],"correct":1,"explanation":"Pravnomočnost = odločbe ni več mogoče izpodbijati z REDNIMI pravnimi sredstvi (pritožba, ugovor). Zoper pravnomočno odločbo je mogoče le še izredno pravno sredstvo (revizija; v kazenskih postopkih zahteva za varstvo zakonitosti in obnova)."},{"q":"Kateri so trije pritožbeni razlogi?","options":["Napačno ali nepopolno ugotovljeno dejansko stanje, bistvena kršitev postopka, napačna uporaba materialnega predpisa","Zamuda roka, previsoka kazen, pristranskost sodnika","Nova dejstva, novi dokazi, nova zakonodaja","Kršitev ustave, kršitev zakona, kršitev podzakonskega akta"],"correct":0,"explanation":"V pritožbi mora stranka navesti sodbo, obseg izpodbijanja in razloge: (1) napačno/nepopolno ugotovljeno dejansko stanje, (2) bistvena kršitev postopka, (3) napačna uporaba materialnega predpisa."},{"q":"Kakšno je razmerje med arbitražo in sodnim postopkom?","options":["Dopolnjujeta se - arbitražno odločbo vedno potrdi sodišče","Izključujeta se - z dogovorom o arbitraži stranki izključita pristojnost sodišča; arbitraža je hitrejša","Arbitraža je obvezna prva stopnja pred sodnim postopkom","Arbitraža je mogoča samo v delovnih sporih"],"correct":1,"explanation":"Arbitraža je sodnemu reševanju najbolj podoben alternativni mehanizem (ureja jo ZArbit). Sprti strani spor predložita arbitraži in s tem izključita pristojnost sodišča. Je hitrejša. Drugi mehanizmi: mediacija, konciliacija."}]},{"id":"pk1-eu","name":"Pravo EU","questions":[{"q":"Po čem se EU razlikuje od klasičnih mednarodnih organizacij?","options":["Nastala je brez mednarodne pogodbe","Njene institucije lahko sprejemajo zakonodajo z neposrednimi pravnimi učinki v državah članicah","Nima lastnih institucij","Njeno pravo velja samo, če ga potrdi nacionalni parlament"],"correct":1,"explanation":"EU je nastala z mednarodno pogodbo kot druge mednarodne organizacije, loči pa se po: institucionalni sestavi (evropski skupni interes), obsežnem prenosu pristojnosti in lastnem pravnem redu, neodvisnem od prava DČ. Njena zakonodaja ima neposredne pravne učinke."},{"q":"Na katerih pogodbah temelji pravo EU?","options":["Na Rimski deklaraciji in Schengenskem sporazumu","Na Pogodbi o EU, Pogodbi o delovanju EU in Listini EU o temeljnih pravicah","Na Evropski konvenciji o človekovih pravicah","Na ustavah držav članic"],"correct":1,"explanation":"Pravo EU temelji na PEU, PDEU in Listini EU o temeljnih pravicah ter na sodni praksi Sodišča EU. Je nadnacionalno pravo - ima prednost pred nacionalnim."},{"q":"Katere so štiri glavne svoboščine skupnega trga EU?","options":["Prost pretok blaga, storitev (in svoboda ustanavljanja), prosto gibanje delavcev/oseb in prost pretok kapitala","Svoboda govora, tiska, vere in združevanja","Prost pretok blaga, carin, davkov in subvencij","Svoboda potovanja, dela, šolanja in upokojevanja"],"correct":0,"explanation":"Štiri svoboščine: prost pretok blaga, prost pretok storitev in svoboda ustanavljanja, prosto gibanje delavcev/oseb, prost pretok kapitala. Tipične ovire, ki so prepovedane: carine in dajatve z enakim učinkom, diskriminatorna notranja obdavčitev, količinske omejitve."},{"q":"Katerih je sedem uradnih institucij EU?","options":["Parlament, Evropski svet, Svet, Komisija, Sodišče EU, ECB, Računsko sodišče","Parlament, Svet Evrope, Komisija, NATO, ECB, Sodišče EU, Europol","Parlament, Svet, Komisija, Evropska investicijska banka, ECB, Sodišče EU, Odbor regij","Parlament, Evropski svet, Svet, Komisija, Varuh človekovih pravic, ECB, Eurostat"],"correct":0,"explanation":"Sedem institucij: Evropski parlament, Evropski svet, Svet (EU), Evropska komisija, Sodišče EU, Evropska centralna banka, Računsko sodišče. Pozor: Svet Evrope NI institucija EU."},{"q":"Kdo sestavlja Svet (EU)?","options":["Predsedniki držav ali vlad držav članic","Po en predstavnik vsake DČ na ministrski ravni, pooblaščen za prevzemanje obveznosti v imenu svoje vlade","Neposredno izvoljeni poslanci","Po en komisar iz vsake države članice"],"correct":1,"explanation":"Svet sestavljajo ministri DČ; sestava ni fiksna, menja se glede na tematiko. Delo pripravlja Odbor stalnih predstavnikov (Coreper). Svetu vsake pol leta predseduje ena država članica. Je najpomembnejši zakonodajni organ (zakonodajno moč si deli s Parlamentom).","wrong":{"0":"To je Evropski svet - najvišje politično telo, ki ne sprejema zakonov."}},{"q":"Kaj je kvalificirana (dvojna) večina pri odločanju Sveta?","options":["Vsaj 55 % držav članic, ki predstavljajo vsaj 65 % prebivalstva EU","Vsaj 65 % držav članic, ki predstavljajo vsaj 55 % prebivalstva EU","2/3 vseh držav članic","Soglasje vseh držav članic"],"correct":0,"explanation":"Dvojna večina: vsaj 55 % DČ + vsaj 65 % prebivalstva EU. Svet tako odloča, razen ko pogodbe določajo drugače. Soglasje (veto) je potrebno za temeljne ukrepe (sprejem novih članic), navadna večina za odločitve brez neposrednega spreminjanja zakonodaje."},{"q":"Kje je uradni sedež Evropskega parlamenta?","options":["Bruselj","Strasbourg","Luksemburg","Frankfurt"],"correct":1,"explanation":"Uradni sedež EP je v Strasbourgu; drugi dve lokaciji sta Bruselj in Luksemburg. Poslance vsakih 5 let neposredno izvolijo državljani DČ; predsednik EP ima mandat 2,5 leti. Poslanci zastopajo svoje volivce in evropske politične stranke, ne države."},{"q":"Kaj velja za glasovanje o nezaupnici Evropski komisiji?","options":["Izglasuje jo Svet s kvalificirano večino; odstopi predsednik Komisije","Za izglasovanje sta potrebni 2/3 na seji navzočih poslancev in hkrati absolutna večina vseh poslancev EP; odstopiti mora cela Komisija","Zadostuje navadna večina navzočih poslancev; odstopi posamezni komisar","Nezaupnico lahko izglasuje samo Evropski svet s soglasjem"],"correct":1,"explanation":"Nezaupnica je najmočnejše nadzorno orožje EP: 2/3 navzočih poslancev + absolutna večina vseh poslancev EP. Če je izglasovana, mora odstopiti CELA Komisija. Drugi nadzorni instrumenti: poslanska vprašanja (1x mesečno), preiskovalne komisije (zahteva 1/4 poslancev), letno poročilo Komisije, evropski varuh človekovih pravic."},{"q":"Katera institucija ima izključno zakonodajno iniciativo v EU?","options":["Evropski parlament","Svet (EU)","Evropska komisija","Evropski svet"],"correct":2,"explanation":"Komisija ima v postopku sprejemanja sekundarne zakonodaje izključno pravico in dolžnost zakonodajne iniciative - zato jo imenujejo 'motor integracije'. O sprejemu nato po rednem zakonodajnem postopku skupaj odločita Svet (kvalificirana dvojna večina) in Parlament (enakopravna)."},{"q":"Kako se imenuje predsednik Evropske komisije?","options":["Neposredno ga izvolijo državljani EU","Evropski svet ga s kvalificirano večino predlaga, potrdi ga Evropski parlament","Imenuje ga Svet (EU) s soglasjem","Izvolijo ga komisarji med seboj"],"correct":1,"explanation":"Evropski svet s kvalificirano večino predlaga kandidata, o predlogu odloča EP. Nato Evropski svet v soglasju s kandidatom sprejme seznam kandidatov za komisarje; celotno Komisijo z glasovanjem potrdi EP, imenuje pa jo Evropski svet s kvalificirano večino. Komisarji (27, mandat 5 let) zastopajo interese EU, ne svojih držav."},{"q":"Kaj je Evropski svet in kdo ga sestavlja?","options":["Zakonodajni organ, sestavljen iz ministrov DČ","Najvišje politično telo EU - predsedniki držav ali vlad DČ in predsednik Komisije; sprejema politične odločitve, ne zakonov","Posvetovalni organ regij in mest","Skupščina nacionalnih parlamentov"],"correct":1,"explanation":"Evropski svet (institucija po Lizbonski pogodbi) sestavljajo predsedniki držav/vlad DČ in predsednik Komisije. Ima predsednika z mandatom 2,5 leti, sestane se 4x letno. Ne sprejema zakonov, temveč politične odločitve.","wrong":{"0":"To je Svet (EU) - drug organ!"}},{"q":"Kako je sestavljeno Sodišče EU?","options":["Sodišče: po en sodnik iz vsake DČ; Splošno sodišče: po dva sodnika iz vsake DČ; pomaga 11 pravobranilcev","En sam senat s 27 sodniki, ki jih imenuje Parlament","Po trije sodniki iz vsake DČ brez pravobranilcev","Sodniki so izbrani izmed članov nacionalnih vrhovnih sodišč po žrebu"],"correct":0,"explanation":"Sodišče EU sestavljata Sodišče (1 sodnik/DČ) in Splošno sodišče (2 sodnika/DČ). Pri Sodišču pomaga 11 pravobranilcev (sklepni predlogi). Naloga: zagotavljanje upoštevanja prava pri razlagi in uporabi PEU in PDEU."},{"q":"Katera trditev o Evropskem računskem sodišču in ECB je pravilna?","options":["Računsko sodišče izdaja pravno zavezujoče sodbe; ECB vodi fiskalno politiko","Računsko sodišče nima sodnih pristojnosti (poročila niso zavezujoča); ECB neodvisno upravlja evro in monetarno politiko","Obe instituciji sta podrejeni Komisiji","Člane Računskega sodišča imenuje vsaka DČ za dosmrtni mandat"],"correct":1,"explanation":"Računsko sodišče: po en član iz vsake DČ, mandat 6 let (enkrat ponovljiv), nima sodnih pristojnosti. ECB: upravljanje evra ter izvajanje in oblikovanje monetarne politike EU, deluje povsem neodvisno; najvišji organ je svet guvernerjev (6 članov izvršilnega odbora + guvernerji centralnih bank evrskega območja)."},{"type":"match","q":"Poveži sekundarni pravni akt EU z njegovo značilnostjo.","pairs":[{"term":"Uredba","def":"Splošno uporabna, v celoti zavezujoča, neposredno se uporablja v vseh DČ - 'zakon na ravni Unije'"},{"term":"Direktiva","def":"Zavezuje glede cilja, DČ izbere metodo; treba jo je prenesti v nacionalni pravni red"},{"term":"Sklep","def":"Individualni pravni akt - zavezujoč za naslovljenega posameznega subjekta"},{"term":"Priporočila in mnenja","def":"Nezavezujoče 'mehko pravo' - oblikovanje politike na določenem področju"}],"explanation":"Sekundarne akte sprejemajo organi EU na podlagi pooblastil iz ustanovitvenih pogodb. Uredba in direktiva se objavita v Uradnem listu EU in začneta veljati 20. dan po objavi, če ni določeno drugače."},{"q":"V čem se direktiva razlikuje od uredbe?","options":["Direktiva je hierarhično nad uredbo","Direktiva ni nujno zavezujoča za vse DČ in je zavezujoča samo glede cilja/rezultata; uredba je v celoti zavezujoča in velja neposredno","Uredbo je treba prenesti v nacionalni pravni red, direktive ne","Direktivo sprejemajo DČ, uredbo pa organi EU"],"correct":1,"explanation":"Dve razliki: (1) direktiva ni nujno naslovljena na vse DČ, (2) zavezujoča je samo glede cilja - DČ izbere metodo in jo mora prenesti v svoj pravni red. Uredba avtomatično velja v vseh DČ z dnem uveljavitve, brez prenosa."},{"q":"Med primarne pravne vire EU štejemo:","options":["uredbe, direktive in sklepe","ustanovitvene pogodbe, pristopne pogodbe, pogodbe s tretjimi državami in splošna pravna načela, skupna pravnim redom DČ","sodbe Sodišča EU in mnenja Komisije","nacionalne ustave držav članic"],"correct":1,"explanation":"Primarni viri: pogodbe, ki jih sklepajo DČ (PEU, PDEU, pristopne pogodbe, pogodbe s tretjimi državami) + splošna pravna načela. Sprejemajo se soglasno in jih morajo ratificirati DČ. Sekundarne akte sprejemajo organi EU. Dopolnilni viri: sodbe Sodišča EU."},{"q":"Kaj pomeni načelo primarnosti prava EU?","options":["Pravo EU nastaja in se razlaga izključno po pravilih EU","Pravna pravila, sprejeta na ravni EU, prevladajo nad pravili notranjega pravnega reda DČ","EU deluje le v mejah pristojnosti, ki so jih nanjo prenesle DČ","Norme EU veljajo brez posredovanja nacionalnega organa"],"correct":1,"explanation":"Primarnost = pravo EU prevlada nad notranjim pravom DČ (uredbe so celo nad ustavo nacionalne države). Avtonomnost = pravo EU nastaja, velja in se razlaga izključno po pravilih EU. Neposredna uporabnost = norme veljajo brez posredovanja nacionalnega organa in se posamezniki nanje lahko sklicujejo."},{"q":"Pod katerimi pogoji je direktiva neposredno uporabna?","options":["Vedno, takoj ko je objavljena v Uradnem listu EU","Gre za razmerje med posameznikom in državo, rok za implementacijo je potekel, pravila so jasna in konkretna","Samo če jo DČ prenese v nacionalni pravni red","Nikoli - direktive nikoli nimajo neposrednega učinka"],"correct":1,"explanation":"Trije pogoji: (1) razmerje posameznik (pravna oseba) - država, (2) rok za implementacijo je potekel, (3) pravila so jasna in konkretna. Ne glede na te pogoje je neposredno uporabna tudi, če konkretizira splošna načela prava EU. Določbe ustanovitvenih pogodb so neposredno uporabne, če so jasne, popolne in dovolj konkretne."},{"q":"Na katerih področjih ima EU izključno pristojnost?","options":["Kultura, turizem, izobraževanje","Carinska unija, skupna trgovinska politika, konkurenca","Dedno, družinsko in kazensko pravo","Notranji trg"],"correct":1,"explanation":"Izključna pristojnost EU: carinska unija, skupna trgovinska politika, konkurenca - DČ tu ne smejo sprejemati zavezujočih pravil. Deljena pristojnost (najširša): npr. notranji trg. Podporni ukrepi: kultura, turizem, izobraževanje. Izključna pristojnost DČ: dedno, družinsko, kazensko pravo.","wrong":{"3":"Notranji trg spada med DELJENE pristojnosti."}},{"q":"Kaj ureja načelo subsidiarnosti?","options":["Prednost prava EU pred nacionalnim pravom","Razmerje med pristojnostmi EU in držav članic - Unija deluje le v mejah prenesenih pristojnosti","Odgovornost DČ za škodo zaradi neprenesene direktive","Hierarhijo med primarnimi in sekundarnimi viri"],"correct":1,"explanation":"Subsidiarnost (podrednost) ureja razmerje med pristojnostmi EU in DČ: Unija deluje le v mejah pristojnosti, ki so jih DČ z ustanovitvenimi pogodbami prenesle nanjo za uresničevanje ciljev pogodb."}]},{"id":"pk1-stvarno","name":"Stvarno pravo","questions":[{"q":"Kaj ureja stvarno pravo?","options":["Obveznostna razmerja med upniki in dolžniki","Razmerja pripadnosti in oblasti na stvareh v pravnih razmerjih med posamezniki","Prehod premoženja umrlega na druge osebe","Statusna vprašanja gospodarskih družb"],"correct":1,"explanation":"Stvarno pravo je del civilnega prava, ki ureja razmerje pripadnosti in oblasti na stvareh. Je premoženjsko pravo; pravice so prenosljive (razen osebnih služnosti). Osrednji pravni vir je Stvarnopravni zakonik (SPZ)."},{"q":"Katera je temeljna značilnost stvarnih pravic?","options":["Relativnost - učinkujejo samo med strankama","Absolutnost - učinkujejo proti vsem tretjim osebam","Neprenosljivost","Časovna omejenost na 10 let"],"correct":1,"explanation":"Temeljna značilnost je absolutnost (učinkovanje proti vsem - erga omnes). Klasične značilnosti še: avtonomija in abstraktnost. Število stvarnih pravic je omejeno z zakonom (numerus clausus), njihov predmet je individualno določena stvar."},{"q":"Katere so stvarne pravice po SPZ?","options":["Lastninska, zastavna, služnostna, stavbna pravica in pravica stvarnega bremena","Lastninska pravica, posest, imetništvo, najem in zakup","Lastninska, avtorska, patentna in znamkovna pravica","Terjatev, dolg, poroštvo in hipoteka"],"correct":0,"explanation":"Stvarne pravice: lastninska pravica, zastavna pravica, služnost, stavbna pravica, stvarno breme (in zemljiški dolg). Posest NI pravica, ampak dejanska oblast, ki je pravno varovana.","wrong":{"1":"Posest in imetništvo nista pravici; najem in zakup sta obligacijski razmerji."}},{"type":"match","q":"Poveži načelo stvarnega prava z vsebino.","pairs":[{"term":"Povezanost zemljišča in objekta","def":"Kar je trajno spojeno z nepremičnino (nad ali pod njo), je njena sestavina"},{"term":"Domneva dobre vere","def":"Dobra vera se domneva, dokler se ne dokaže nasprotno"},{"term":"Zaupanje v zemljiško knjigo","def":"Kdor se zanese na podatke v ZK, zaradi tega ne sme trpeti škodljivih posledic"},{"term":"Prepoved zlorabe","def":"Stvarnih pravic ni dovoljeno izvrševati v nasprotju z njihovim namenom"}],"explanation":"Pomembna načela stvarnega prava po SPZ. Načelo povezanosti zemljišča in objekta (superficies solo cedit) pomeni, da zgradba deli usodo zemljišča - izjema je stavbna pravica in etažna lastnina."},{"q":"Kakšna je razlika med posestjo in imetništvom?","options":["Posest je pravica, imetništvo je dejansko stanje","Posest je dejanska in izključna oblast nad stvarjo; imetnik izvršuje oblast ZA DRUGEGA po njegovih navodilih (npr. natakar)","Imetnik ima vedno tudi lastninsko pravico, posestnik ne","Razlike ni - pojma sta sinonima"],"correct":1,"explanation":"Posest = dejanska in izključna oblast nad stvarjo (ni pravica, je pa pravno varovana - varuje se posest ne glede na pravico do posesti). Imetništvo = izvrševanje dejanske oblasti za drugega, po navodilih druge osebe (natakar v restavraciji)."},{"q":"Katera upravičenja daje lastninska pravica?","options":["Samo uporabo stvari","Posest, uporabo in uživanje ter razpolaganje s stvarjo","Samo razpolaganje in obremenitev","Uporabo stvari z dovoljenjem države"],"correct":1,"explanation":"Lastninska pravica omogoča imeti stvar v posesti, jo uporabljati in uživati ter z njo razpolagati. Omejitve lahko določi le zakon. Ustavnopravno je lastnina splošna pravica posameznika do pridobivanja premoženja."},{"q":"Na katerih podlagah se pridobi lastninska pravica?","options":["Samo s pravnim poslom","S pravnim poslom, dedovanjem, zakonom ali odločbo državnega organa","Samo z vpisom v zemljiško knjigo","S posestjo, ki traja vsaj eno leto"],"correct":1,"explanation":"Štiri pridobitne podlage: pravni posel, dedovanje, zakon (npr. priposestvovanje) in odločba državnega organa. Pri pravnem poslu so pogoji: prenosnik je lastnik, veljaven zavezovalni posel in razpolagalni posel; za nepremičnine še vpis v zemljiško knjigo."},{"q":"Kaj je zemljiškoknjižno dovolilo (intabulacijska klavzula)?","options":["Sodna odločba o vpisu lastninske pravice","Izrecna in nepogojna izjava tistega, čigar pravica se prenaša, da dovoljuje vpis v ZK; podpis mora biti notarsko overjen","Potrdilo notarja o plačilu davka na promet nepremičnin","Dovoljenje upravne enote za gradnjo"],"correct":1,"explanation":"Zemljiškoknjižno dovolilo je izrecna in nepogojna izjava osebe, čigar pravica se prenaša, spreminja, obremenjuje ali preneha, da dovoljuje vpis v zemljiško knjigo; podpis mora biti notarsko overjen. Lastninska pravica na premičnini pa se prenese z izročitvijo v posest pridobitelja."},{"q":"Kakšni sta priposestvovalni dobi za premičnine in nepremičnine?","options":["1 leto za premičnine, 5 let za nepremičnine","3 leta za premičnine, 10 let za nepremičnine","5 let za premičnine, 20 let za nepremičnine","10 let za premičnine, 30 let za nepremičnine"],"correct":1,"explanation":"Priposestvovanje zahteva dobroverno lastniško posest: 3 leta za premičnine, 10 let za nepremičnine. Pogoji: dobra vera (misliš, da je stvar tvoja), lastniška posest (obnašaš se kot lastnik) in potek dobe. Priposestvovati je mogoče tudi stvarno služnost."},{"q":"Najditelj premičnine pridobi lastninsko pravico:","options":["takoj, ko stvar najde","s pretekom enega leta od obvestila/prijave, če upravičenec ni zahteval izročitve in je stvar še v hrambi najditelja ali policije","nikoli - najdena stvar vedno pripade državi","po treh letih dobroverne posesti"],"correct":1,"explanation":"Pri najdbi: lastninska pravica po 1 letu od obvestila ali prijave, če upravičenec ni zahteval izročitve. Najdeni zaklad pa pripada po enakih delih najditelju in lastniku premičnine/nepremičnine."},{"q":"Kako preneha lastninska pravica?","options":["Samo s prodajo stvari","Če jo pridobi kdo drug, z opustitvijo, s fizičnim uničenjem stvari ali v drugih zakonskih primerih","Samo s smrtjo lastnika","Z neuporabo stvari več kot 10 let"],"correct":1,"explanation":"Prenehanje: pridobitev s strani drugega, opustitev (premičnina postane nikogaršnja; velja samo pri premičninah - nepremičnine ne moreš kar opustiti), fizično uničenje, drugi zakonski primeri."},{"q":"Kakšna je razlika med solastnino in skupno lastnino?","options":["Pri solastnini so deleži računsko določeni, pri skupni lastnini deleži niso vnaprej določeni in lastniki odgovarjajo solidarno","Pri skupni lastnini so deleži določeni, pri solastnini ne","Solastnina je mogoča samo na nepremičninah","Razlike ni - gre za isti institut"],"correct":0,"explanation":"Solastnina: vsakemu pripada računsko določen delež (če niso določeni, so enaki); solastnik lahko vedno zahteva delitev (razen ob neprimernem času). Skupna lastnina: deleži niso vnaprej določeni, lastniki stvar skupno uporabljajo in SOLIDARNO odgovarjajo (npr. zakonca, sodediči)."},{"q":"Kakšno soglasje solastnikov je potrebno za posle rednega upravljanja stvari?","options":["Soglasje vseh solastnikov","Soglasje solastnikov, katerih deleži sestavljajo več kot polovico vrednosti stvari","Odločitev sodišča","Zadostuje odločitev kateregakoli solastnika"],"correct":1,"explanation":"Redno upravljanje: soglasje deležev nad 1/2 vrednosti. Posli, ki presegajo redno upravljanje (razpolaganje s celotno stvarjo, določitev načina rabe, določitev upravitelja): soglasje VSEH. Solastniki imajo pri prodaji predkupno pravico; stroške krijejo sorazmerno z deleži."},{"q":"Kdaj morajo etažni lastniki določiti upravnika in ustanoviti rezervni sklad?","options":["Vedno, ne glede na velikost stavbe","Če ima nepremičnina več kot 2 etažna lastnika in več kot 8 posameznih delov","Če ima stavba več kot 5 nadstropij","Samo če tako odloči sodišče"],"correct":1,"explanation":"Etažna lastnina = lastnina posameznega dela zgradbe + solastnina skupnih delov (streha, stopnice, dvigalo). Nastane s pravnim poslom ali odločbo sodišča + vpisom v ZK. Pri več kot 2 lastnikih in več kot 8 delih: obvezen upravnik in rezervni sklad. Medsebojna razmerja uredijo s pisno pogodbo."},{"q":"S katerimi tožbami se varuje lastninska pravica?","options":["Lastninska, publicijanska in negatorna tožba","Pritožba, ugovor in revizija","Izbrisna in izpodbojna tožba","Posestna in odškodninska tožba"],"correct":0,"explanation":"Varstvo lastninske pravice: lastninska tožba (rei vindicatio - zahteva vrnitev stvari), publicijanska tožba (varstvo dobrovernega lastniškega posestnika) in negatorna tožba (proti vznemirjanju)."},{"q":"Kaj je zastavna pravica?","options":["Pravica uporabljati tujo stvar za lastne potrebe","Omejena stvarna pravica na tuji stvari, ki upniku omogoča poplačilo zavarovane terjatve iz vrednosti zastavljenega predmeta pred drugimi upniki","Pravica države zaseči premoženje dolžnika","Obligacijska pravica upnika do obresti"],"correct":1,"explanation":"Zastavna pravica služi zavarovanju terjatve: ob neplačilu ob zapadlosti se zastavni upnik poplača (z obrestmi in stroški) iz vrednosti zastavljenega predmeta PRED vsemi drugimi upniki. Predmet: stvari, pravice, vrednostni papirji. Izvršitev: sodna ali zunajsodna prodaja."},{"q":"Katera trditev o hipoteki je NAPAČNA?","options":["Je neposestna zastavna pravica na nepremičninah - zastavitelj nepremičnino obdrži in jo uporablja","Če je terjatev delno plačana, se hipoteka sorazmerno zmanjša","Na isti nepremičnini se lahko ustanovi več hipotek","Nastane s pisno pogodbo, notarskim zapisom, sodno odločbo ali zakonom - vedno z vpisom v ZK"],"correct":1,"explanation":"Hipoteka zavaruje terjatev vse do njenega DOKONČNEGA poplačila - delno plačilo je ne zmanjša. Ostale trditve držijo. Ničen je dogovor, da zastavljena stvar ob neplačilu preide v last upnika (komisorni dogovor) ali da se proda po vnaprej določeni ceni.","given":"Pri solastnini lahko vsak solastnik ustanovi hipoteko na svojem idealnem deležu brez soglasja; pri skupni lastnini je hipoteka mogoča le na celotni nepremičnini."},{"q":"Kako nastane neposestna zastavna pravica na premičninah?","options":["Z izročitvijo premičnine upniku","Z notarskim zapisom - premičnina ostane v posesti zastavitelja","Z vpisom v zemljiško knjigo","Z ustnim dogovorom strank"],"correct":1,"explanation":"Neposestna zastavna pravica na premičninah nastane z notarskim zapisom; stvar (lahko tudi zaloge ali poslovna oprema) ostane v posesti zastavitelja, ki jo lahko ekonomsko uporablja. Ročna zastava (pignus) pa nastane z zastavno pogodbo IN izročitvijo premičnine upniku v neposredno posest; upnik jo hrani kot dober gospodar in je ne sme uporabljati ali prodati brez dovoljenja."},{"q":"Kakšna je razlika med stvarno in osebno služnostjo?","options":["Stvarna služi drugi nepremičnini in prehaja na pravne naslednike; osebna je ustanovljena v korist osebe in je časovno omejena","Osebna služnost prehaja na dediče, stvarna ne","Stvarna služnost je vedno odplačna, osebna neodplačna","Razlika je samo v načinu vpisa v ZK"],"correct":0,"explanation":"Stvarna služnost: služeča nepremičnina služi gospodujoči nepremičnini; imetnik je lastnik gospodujoče nepremičnine; prehaja na naslednike; mogoče jo je priposestvovati. Osebne služnosti (užitek, raba, služnost stanovanja): v korist osebe, časovno omejene, neprenosljive. Nastanejo z zakonom, pravnim poslom ali odločbo organa."},{"q":"Kaj je stvarno breme?","options":["Pravica uporabljati tujo stvar","Pravica, na podlagi katere je vsakokratni lastnik obremenjene nepremičnine zavezan k prihodnjim ponavljajočim se dajatvam ali storitvam","Prepoved gradnje na sosednjem zemljišču","Davčna obveznost lastnika nepremičnine"],"correct":1,"explanation":"Stvarno breme zahteva AKTIVNO ravnanje (ponavljajoče se dajatve/storitve) - za razliko od služnosti, ki je pasivna (dopustitev/opustitev). Nepremičnina jamči za posamične izpolnitve. Ustanovi se z zakonom ali pravnim poslom (ZK dovolilo + vpis v ZK)."},{"q":"Kaj je stavbna pravica?","options":["Pravica imeti v lasti zgrajeno zgradbo nad ali pod tujo nepremičnino","Dovoljenje za gradnjo, ki ga izda upravna enota","Pravica souporabe skupnih delov stavbe","Služnost napeljave komunalnih vodov"],"correct":0,"explanation":"Stavbna pravica = pravica imeti v lasti zgradbo nad ali pod tujo nepremičnino (izjema od načela superficies solo cedit). Imetnik nepremičnino uporablja in uživa; lahko je za določen ali nedoločen čas; je prenosljiva."}]},{"id":"pk1-oblig","name":"Obligacijsko pravo","questions":[{"q":"Kaj ureja obligacijsko pravo?","options":["Razmerja pripadnosti in oblasti na stvareh","Obveznostna razmerja: ena stranka je zavezana nekaj storiti, opustiti ali dopustiti, druga je upravičena zahtevati izpolnitev","Statusna vprašanja pravnih oseb","Kazniva dejanja in sankcije"],"correct":1,"explanation":"Obligacijsko pravo ureja obveznostna razmerja med pravnimi subjekti. Deli se na pogodbeno in odškodninsko pravo. Temeljni predpis je Obligacijski zakonik (OZ)."},{"type":"match","q":"Poveži temeljno načelo obligacijskega prava z vsebino.","pairs":[{"term":"Načelo dispozitivnosti","def":"Stranki lahko določita svoja pravila; če jih ne, veljajo pravila OZ"},{"term":"Prosto urejanje razmerij","def":"Udeleženci svobodno urejajo obligacijska razmerja, a ne v nasprotju z ustavo, prisilnimi predpisi ali moralo"},{"term":"Vestnost in poštenje","def":"Upoštevanje posamičnih in skupnih interesov ter pošteno ravnanje"},{"term":"Dolžnost izpolnitve","def":"Prevzete obveznosti je treba spoštovati in izpolniti, sicer dolžnik odgovarja upniku"}],"explanation":"Za strokovnjake velja še skrbnost dobrega strokovnjaka (ravnati morajo, kot bi ravnal skrben strokovnjak), za ostale skrbnost dobrega gospodarstvenika."},{"q":"Kakšna je razlika med dispozitivno in kogentno pravno normo?","options":["Dispozitivna velja samo v gospodarskem pravu, kogentna v civilnem","Pri dispozitivni se stranke lahko dogovorijo drugače, kot določa zakon; kogentna velja prisilno - samo tako, kot pravi zakon","Kogentne norme veljajo samo za državo","Razlike ni"],"correct":1,"explanation":"Dispozitivna norma: stranke se lahko dogovorijo drugače (značilno za obligacije in notranja razmerja v družbah). Kogentna (prisilna) norma: velja samo, kar pravi zakon - drugačen dogovor ni mogoč."},{"q":"Na katerih pravnih temeljih lahko nastane obligacijsko razmerje?","options":["Samo na podlagi pogodbe","Pogodba, enostranski pravni posli, povzročitev škode in neupravičena pridobitev","Samo na podlagi zakona ali sodne odločbe","Dedovanje, priposestvovanje in najdba"],"correct":1,"explanation":"Štirje temelji: pogodba (dvostranski posel, soglasje), enostranski pravni posli (javna obljuba nagrade, ponudba), povzročitev škode (oškodovanec zahteva povrnitev) in neupravičena pridobitev (korist brez veljavne podlage)."},{"q":"Kakšna je razlika med zavezovalnim in razpolagalnim pravnim poslom?","options":["Zavezovalni povzroči nastanek obveznosti; razpolagalni je druga faza, s katero upravičenec dobi stvar oziroma premoženjsko pravico","Razpolagalni je vedno pisen, zavezovalni usten","Zavezovalni sklene prodajalec, razpolagalni kupec","Gre za sinonima"],"correct":0,"explanation":"Zavezovalni posel (npr. prodajna pogodba) povzroči nastanek/prenehanje obligacijskih pravic in obveznosti. Razpolagalni posel je druga faza - pravno dejanje, s katerim upravičenec dobi stvar ali pravico (npr. izročitev, vpis v ZK). Lastnina preide, ko je razpolagalni posel končan v vseh sestavinah."},{"q":"Kdaj fizična oseba pridobi pravno in kdaj poslovno sposobnost?","options":["Obe z rojstvom","Pravno sposobnost z rojstvom, poslovno sposobnost pri 18 letih (delno pri 15)","Pravno pri 15, poslovno pri 18 letih","Obe pri 18 letih"],"correct":1,"explanation":"Pravna sposobnost (biti nosilec pravic in obveznosti): fizične osebe z rojstvom, pravne osebe z registracijo/vpisom v register. Poslovna sposobnost (sklepati pravne posle): pri 18 letih, delna pri 15. Kazenska odgovornost nastopi pri 14 letih.","more":"Delno poslovno sposobni ne morejo sklepati poslov, ki bi pomembno vplivali na njihovo življenje (velja tudi za osebe z motnjami ali opite). Posel 10-letnika bi bil ničen."},{"q":"Kdaj je pogodba sklenjena?","options":["Ko jo podpišeta obe stranki pri notarju","Ko se stranki sporazumeta o bistvenih sestavinah pogodbe (soglasje volj)","Ko je izpolnjena prva obveznost","Ko jo potrdi sodišče"],"correct":1,"explanation":"Pogodba je sklenjena, ko stranki dosežeta soglasje volj o bistvenih sestavinah. Volja mora biti svobodno izražena - brez sile, grožnje ali prevare. Praviloma oblika ni predpisana (izjeme: npr. prodaja nepremičnine pisno, nekatere pogodbe notarski zapis)."},{"q":"Ali so pogajanja pred sklenitvijo pogodbe zavezujoča?","options":["Da, stranka pogajanj ne sme prekiniti","Ne - vsaka stranka jih lahko prekine; odgovarja pa za škodo, če od pogajanj odstopi neupravičeno","Da, če trajajo več kot mesec dni","Ne, in odškodninska odgovornost nikoli ne nastane"],"correct":1,"explanation":"Pogajanja niso zavezujoča, edina obveznost je vestnost in poštenost. Kdor od pogajanj odstopi neupravičeno, odgovarja za škodo (dejanske stroške, ne izgubljenega dobička). Z opravičljivim razlogom lahko stranka odstopi brez odgovornosti."},{"q":"Kaj velja za ponudbo?","options":["Ponudnik jo lahko kadarkoli prekliče","Ponudba zavezuje ponudnika; preklic učinkuje le, če naslovnik prejme preklic, preden prejme ponudbo","Ponudba brez roka veljavnosti ne velja","Molk naslovnika vedno pomeni sprejem ponudbe"],"correct":1,"explanation":"Ponudba zavezuje ponudnika - ne more je preklicati, umakniti ali od nje odstopiti (razen če preklic prispe pred ponudbo ali hkrati z njo). Pogodba je sklenjena, ko ponudnik prejme izjavo naslovnika o sprejemu. Molk NE pomeni sprejema, razen pri stalni poslovni vezi.","hint":"Praktični nasvet z vaj: v ponudbi vedno napiši, do kdaj velja - sicer lahko velja 'za skos'."},{"q":"Kaj je predpogodba?","options":["Nezavezujoče pismo o nameri","Pogodba, s katero se stranka zaveže, da bo kasneje sklenjena glavna pogodba; stranki zavezuje in mora vsebovati bistvene sestavine glavne pogodbe","Osnutek pogodbe brez pravnih učinkov","Pogodba, sklenjena pod odložnim pogojem"],"correct":1,"explanation":"Predpogodba je zavezujoča in mora vsebovati bistvene sestavine glavne pogodbe. Spada v predpogodbeno fazo skupaj z zbiranjem informacij, pogajanji, pismom o nameri in dajanjem ponudb."},{"q":"Katere predpostavke morajo biti izpolnjene za veljavnost pogodbe?","options":["Samo podpis obeh strank","Pravna in poslovna sposobnost strank, soglasje volj, možen/dopusten/določen ali določljiv predmet, dopustna poslovna podlaga in ustrezna oblika, kadar jo zakon zahteva","Notarska overitev in plačilo davka","Pisna oblika in dve priči"],"correct":1,"explanation":"Predpostavke veljavnosti: sposobnost strank, soglasje volj, predmet (možen, dopusten, določen/določljiv), dopustna podlaga (kavza) in oblika, kadar jo zakon določa. Predmet je nedopusten, če nasprotuje ustavi, prisilnim predpisom ali morali."},{"q":"Kdaj govorimo o zmoti, kdaj o nesporazumu in kdaj o simuliranem pravnem poslu?","options":["Zmota = enostranska napaka volje; nesporazum = obojestranska; simuliran posel = zavestno neskladje med voljo in izjavo","Zmota = zavestna napaka; nesporazum = enostranska; simuliran posel = obojestranska","Vsi trije pojmi so sinonimi za prevaro","Zmota in nesporazum sta kaznivi dejanji, simulacija ne"],"correct":0,"explanation":"Napake volje (neskladje izjavljene in prave volje): zmota = enostranska nezavedna napaka (tudi pri prevari gre za zmoto, ki jo povzroči druga stranka); nesporazum = obojestranski; simuliran (navidezen) pravni posel = stranki zavestno izjavita nekaj drugega, kot v resnici hočeta - med strankama je ničen."},{"q":"Kakšna je razlika med ničnostjo in izpodbojnostjo pogodbe?","options":["Ničnost je absolutna neveljavnost (pogodba nasprotuje ustavi, prisilnim predpisom, morali) in nima učinkov; izpodbojna pogodba učinkuje, dokler se ne izpodbije","Nična pogodba velja, dokler je sodišče ne razveljavi; izpodbojna nikoli ne velja","Ničnost velja samo pri gospodarskih pogodbah","Izpodbojnost je strožja sankcija od ničnosti"],"correct":0,"explanation":"Ničnost = absolutna neveljavnost (nasprotovanje ustavi, prisilnim predpisom, morali); pogodba nima učinkov (za nazaj). Izpodbojnost = relativna neveljavnost; pogodba povzroča učinke, dokler je upravičenec ne izpodbije (npr. pogodba, sklenjena pod utemeljeno grožnjo, v zmoti).","more":"Primer z vaj: pogodba o 'zanositvi s sosedom' je nemoralna - sodišče se z njo sploh ne ukvarja, je nična. Pogodba pod grožnjo je izpodbojna, če je grožnja nedopustna in strah utemeljen; legalna grožnja, povezana z obveznostjo (prijava na FURS zaradi neplačevanja davkov), ni nujno nedopustna."},{"q":"Kateri so pogoji za nastanek odškodninske obveznosti?","options":["Nedopustno škodljivo dejstvo, nastanek škode, vzročna zveza in odškodninska odgovornost","Pogodba, zamuda, opomin in obresti","Samo nastanek škode","Naklep, obsodba in kazen"],"correct":0,"explanation":"Štirje pogoji: (1) nedopustno škodljivo dejstvo, (2) škoda, (3) vzročna zveza med dejstvom in škodo, (4) odškodninska odgovornost. Velja adekvatna vzročnost: upoštevajo se le posledice, ki po življenjski izkušnji niso povsem izredne. Namen: povrnitev škode + spodbude za preprečevanje."},{"q":"Katera sredstva utrjujejo obveznosti STVARNO in katera OSEBNO?","options":["Stvarna: ara, zastavna in pridržna pravica; osebna: poroštvo, pogodbena kazen, odstopnina","Stvarna: poroštvo in kazen; osebna: ara in hipoteka","Vsa sredstva so osebna","Stvarna: menica in ček; osebna: hipoteka"],"correct":0,"explanation":"Stvarna utrditev: ara, zastavna pravica, pridržna pravica. Osebna utrditev: poroštvo, pogodbena kazen, odstopnina. Poleg tega še: zamudne obresti, avans, bančna garancija, menica, izvršnica."},{"q":"Kaj je ara?","options":["Denarni znesek, ki ga ob sklenitvi pogodbe ena stranka izroči drugi v znamenje, da je pogodba sklenjena","Plačilo celotne kupnine vnaprej","Obresti za zamudo pri plačilu","Zavarovanje, ki ga izda banka"],"correct":0,"explanation":"Ara zagotavlja pogodbeno disciplino. Če je za razvezo kriva stranka, ki je aro dala, jo izgubi (druga stranka lahko zahteva tudi izpolnitev in povrnitev škode); če je kriva stranka, ki je aro prejela, lahko druga zahteva vrnitev DVOJNE are (ali izpolnitev in povrnitev škode). Ob izpolnitvi se ara vračuna ali vrne. Brez posebnega dogovora ara NE daje pravice do odstopa; če je dogovorjena pravica odstopa, se ara šteje za odstopnino."},{"q":"Kaj velja za pogodbeno kazen?","options":["Upnik jo lahko zahteva samo do višine dejanske škode","Je dogovorjen denarni znesek ali premoženjska korist za primer neizpolnitve ali zamude; upnik jo lahko zahteva, tudi če presega nastalo škodo","Določi jo sodišče po prostem preudarku","Dovoljena je samo v gospodarskih pogodbah"],"correct":1,"explanation":"Pogodbena kazen je s pogodbo določen znesek/korist, ki jo dolžnik plača ob neizpolnitvi ali zamudi (če ni določeno drugače, velja za zamudo). Upnik jo lahko zahteva, tudi če presega nastalo škodo."},{"q":"Kakšna je razlika med poroštvom in patronatsko izjavo?","options":["Poroštvo je pravno formalna (pisna) zaveza poroka izpolniti dolžnikovo obveznost; patronatska izjava je le častna/moralna zaveza brez pravne obveznosti","Patronatska izjava je strožja od poroštva","Poroštvo je ustni dogovor, patronatska izjava pisni","Gre za isti institut z različnima imenoma"],"correct":0,"explanation":"Poroštvo: porok se zaveže upniku izpolniti veljavno in zapadlo obveznost dolžnika, če je ta ne izpolni; mora biti pisno; porokova obveznost ne sme biti večja od dolžnikove. Patronatska izjava: le častna (moralna, nepravna) zaveza izdajatelja."},{"q":"Kaj je bančna garancija?","options":["Poroštvo banke, vezano na veljavnost osnovne pogodbe","Nepreklicna obveza banke, da bo ob predložitvi ustrezne pisne zahteve upravičencu plačala do zneska iz garancije - je abstraktno zavarovanje","Kredit z ugodno obrestno mero","Zavarovanje vloge do 100.000 EUR"],"correct":1,"explanation":"Bančna garancija je nepreklicno jamstvo banke, da bo ob predložitvi pisne zahteve v skladu z garancijskimi pogoji plačala zahtevani znesek do višine iz garancije. Je ABSTRAKTNO zavarovanje - neodvisno od osnovnega posla."},{"q":"Kakšna je razlika med trasirano in lastno menico?","options":["Pri trasirani izdajatelj (trasant) pozove trasata, da plača upniku (remitentu); pri lastni se izdajatelj sam zaveže plačati","Lastna menica se glasi na prinosnika, trasirana na ime","Trasirana menica ni prenosljiva","Razlika je samo v roku plačila"],"correct":0,"explanation":"Trasirana menica: trasant pozove drugo osebo (trasata), naj plača meničnemu upniku (remitentu). Lastna menica: izdajatelj se sam zaveže plačati ('obljuba plačila', podobna zadolžnici). Menica je individualni vrednostni papir; uporablja se kot zavarovanje, kreditno in plačilno sredstvo."},{"q":"Katera trditev o izvršnici je pravilna?","options":["Lahko jo izda vsak potrošnik za zavarovanje kredita","Je neprenosljiva listina z izjavo dolžnika (gospodarski subjekt ali javni organ), ki je izvršilni naslov in omogoča poplačilo brez sodne poti","Je enaka menici in prosto prenosljiva","Uporablja se lahko tudi pri finančnih pogodbah bank"],"correct":1,"explanation":"Izvršnica (ZPreZP-1, 2012, proti plačilni nedisciplini): dolžnik in upnik sta lahko SAMO gospodarska subjekta ali javni organ; le pri dobavi blaga/storitev (NE pri finančnih pogodbah). Je izvršilni naslov (več kot menica, ki je verodostojna listina), NI prenosljiva, vsebuje nepreklicno pooblastilo za plačilo v breme dolžnikovih računov pri bankah."},{"q":"Kdaj lahko stranka zahteva razvezo pogodbe zaradi spremenjenih okoliščin?","options":["Kadarkoli si premisli","Če se okoliščine po sklenitvi pogodbe tako spremenijo, da otežijo izpolnitev ene stranke; zahteva jo stranka, katere izpolnitev je otežena","Če so okoliščine nastale pred sklenitvijo pogodbe","Samo ob soglasju obeh strank"],"correct":1,"explanation":"Institut spremenjenih okoliščin (rebus sic stantibus) je izjema od načela pacta sunt servanda (pogodbe je treba spoštovati). Pogoji: okoliščine otežijo izpolnitev, nastanejo PO sklenitvi, razvezo zahteva prizadeta stranka. Na okoliščine, nastale pred sklenitvijo, se ni mogoče sklicevati; prav tako ne po že opravljeni izpolnitvi.","more":"Primeri z vaj: covid ali vojna (skok cen materialov) so spremenjene okoliščine; redne spremembe občinskih načrtov niso. Razlika od višje sile: pri višji sili izpolnitev fizično NI mogoča (naravne nesreče), pri spremenjenih okoliščinah je mogoča, a ni več ekonomsko smiselna."},{"q":"Kateri so pogoji za veljavno pobotanje (kompenzacijo)?","options":["Terjatvi morata biti vzajemni, istovrstni, zapadli, iztožljivi in likvidni; izražena mora biti volja","Zadostuje, da sta terjatvi denarni","Pobotanje odredi sodišče po uradni dolžnosti","Terjatvi morata biti enako visoki"],"correct":0,"explanation":"Pobot: vzajemnost (isti stranki sta si medsebojno upnik in dolžnik), istovrstnost (npr. obe denarni), zapadlost, iztožljivost (zastarelih terjatev ni mogoče pobotati), likvidnost (nesporna, določena terjatev) + izjava volje. Terjatve tretje osebe ni mogoče pobotati.","wrong":{"3":"Višini ni treba biti enaki - pobotata se do višine nižje terjatve, razlika ostane."}},{"q":"Kdaj nastopi dolžnikova zamuda in kaj so zamudne obresti?","options":["Zamuda nastopi ob izteku roka oziroma ko upnik pozove dolžnika; zamudne obresti (8 % letno) plača dolžnik poleg glavnice pri denarnih obveznostih","Zamuda nastopi šele s tožbo; obresti določi sodišče","Zamuda nastopi ob sklenitvi pogodbe","Zamudne obresti so kazen, ki jo izreče inšpektor"],"correct":0,"explanation":"Dolžnik zamudi, ko ob zapadlosti ne izpolni; če rok ni določen, ko ga upnik pozove. Dolžnik mora povrniti tudi škodo. Pri denarnih obveznostih tečejo zamudne obresti (8 % letni pribitek). Če zamudi upnik, preneha zamuda dolžnika (in nehajo teči obresti); breme naključnega uničenja preide na stranko v zamudi."},{"q":"Kaj sta nemožnost izpolnitve in višja sila?","options":["Nemožnost je trajno stanje, ki prepreči izpolnitev: če obstaja že ob sklenitvi, je pogodba nična; če nastane zaradi višje sile, obveznost preneha","Nemožnost izpolnitve vedno pomeni odškodninsko odgovornost dolžnika","Višja sila je vsaka sprememba cen na trgu","Pri višji sili mora dolžnik vseeno izpolniti pogodbo"],"correct":0,"explanation":"Nemožnost ob sklenitvi = ničnost; naknadna nemožnost zaradi višje sile = prenehanje obveznosti (brez odškodninske odgovornosti - stranka, kriva za ničnost, pa mora drugi povrniti škodo). Višja sila = dogodek izven našega vpliva (naravne nesreče); spremembe na trgu so 'le' spremenjene okoliščine.","more":"Primer z vaj: študentka zaradi operacije fizično ni mogla na izpit - sodišče je priznalo višjo silo in ji ni bilo treba vrniti štipendije."},{"q":"Katera je bistvena sestavina prodajne pogodbe?","options":["Cena","Določitev stvari (cena ni bistvena sestavina - mora biti le določljiva)","Rok izročitve","Pisna oblika"],"correct":1,"explanation":"V vseh pravnih sistemih je bistvena sestavina prodajne pogodbe določitev STVARI; cena ni bistvena (mora biti določljiva). Prodajalec se zavezuje stvar izročiti tako, da kupec pridobi lastninsko pravico, kupec pa plačati kupnino. Če kupnine ni, je to darilna pogodba; če je namesto kupnine nekaj drugega, menjalna pogodba."},{"q":"V kakšnem roku mora kupec grajati očitne stvarne napake?","options":["V 8 dneh od pregleda; pri gospodarskih pogodbah nemudoma; skrito napako v 8 dneh od odkritja","V 30 dneh v vseh primerih","V 6 mesecih od izročitve","Rok ni predpisan"],"correct":0,"explanation":"Kupec mora stvar pregledati in očitne napake grajati v 8 dneh (gospodarske pogodbe: nemudoma); skrite napake v 8 dneh od odkritja. Stvarna napaka: stvar nima lastnosti za običajno rabo, za posebno rabo (znano prodajalcu), dogovorjenih lastnosti ali se ne ujema z vzorcem/modelom. Prodajalec ne odgovarja za napake, ki so bile kupcu znane. Kupčevi zahtevki: odprava napake ali zamenjava, znižanje kupnine ali odstop od pogodbe."},{"q":"Kaj velja za podjemno pogodbo?","options":["Podjemnik se zavezuje opraviti posel (izdelava, popravilo); iz svojega materiala mora dati material srednje kakovosti in opozoriti na napake naročnikovega materiala","Podjemnik se zavezuje prenesti lastninsko pravico na stvari","Podjemnik ne odgovarja za napake dela","Naročnik ni dolžan prevzeti izvršenega dela"],"correct":0,"explanation":"Podjemna pogodba: podjemnik opravi posel (izdelava/popravilo) v določenem času. Iz svojega materiala da material srednje kakovosti; na napake naročnikovega materiala mora opozoriti, sicer odgovarja za škodo. Naročnik mora delo pregledati in takoj obvestiti podjemnika, skrito napako prijaviti v enem mesecu, delo pa prevzeti."},{"q":"Servis noče vrniti popravljenega avtomobila, dokler stranka ne plača računa za popravilo. Za kateri institut gre?","options":["Zastavna pravica","Pridržna (retencijska) pravica","Ara","Samovoljno ravnanje - servis avto mora vrniti"],"correct":1,"explanation":"Pridržna pravica je akcesorna pravica: imetnik sme pridržati stvar, ki jo je dolžan izročiti, dokler mu dolžnik ne plača. Pogoji: zapadla terjatev, ki izhaja iz pridržane stvari; predmet je stvar; dolg je denaren; stvar je pri upniku."},{"q":"Odstopnina (skesnina) je:","options":["denarni znesek ali količina nadomestljivih stvari, ki jo stranka plača, če želi odstopiti od pogodbe; izjava o odstopu učinkuje le skupaj z izročitvijo odstopnine","kazen, ki jo izreče sodišče ob razvezi pogodbe","obvezna sestavina vsake pogodbe","vračilo are v dvojnem znesku"],"correct":0,"explanation":"Stranki se lahko dogovorita, da ena ali vsaka lahko odstopi od pogodbe, če da odstopnino. Izjava o odstopu deluje le, če je hkrati dana odstopnina. Ko stranka izjavi, da bo dala odstopnino, ne more več zahtevati izpolnitve. Avans (predplačilo) pa je vnaprejšnja izpolnitev na račun obveznosti, ki še ni zapadla."}]}],"notes":"<h2>Pravo · 1. kolokvij · povzetek snovi</h2>\n<div class=\"note-card\">\n<h3>1. Uvod v pravoznanstvo</h3>\n<ul>\n<li><b>Pravo</b> = nominativni sistem pravil, podprt s kredibilno grožnjo uporabe fizične sile proti kršitelju. <b>Common law</b>: precedensi, nevtralen sodnik, porota; <b>kontinentalno</b>: obsežni zakoni, dejavna vloga sodnika.</li>\n<li><b>Delitev oblasti</b> (zakonodajna, izvršilna, sodna): ločitev funkcij + zavore in ravnovesja. <b>Pravna država</b>: delovanje organov je pravno vezano.</li>\n<li><b>Pravna norma</b>: hipoteza (okoliščine) → dispozicija (zapoved/prepoved/dovoljenje) → sankcija. Tipsko pravilo: <b>splošno</b> (subjekti: kdor, vsakdo) in <b>abstraktno</b> (tipski dejanski stan).</li>\n<li><b>Pravni akti</b>: normativni (splošni - ustava, zakon, pravilnik; posamični - sodba, odločba, pogodba) in materialni (dejanska ravnanja); oblastni / neoblastni.</li>\n<li><b>Veljavnost</b>: državni predpisi 15. dan po objavi v Uradnem listu RS. Kolizija brez derogacijske klavzule: višji > nižji, mlajši > starejši, specialnejši > splošnejši. <b>Retroaktivnost</b> izjemoma: posamezne določbe + javna korist + brez posega v pridobljene pravice.</li>\n<li><b>Hierarhija</b>: Ustava (sprememba: 2/3 vseh = 60 glasov DZ) > zakoni (zakonik = celovita ureditev področja) > mednarodne pogodbe (po ratifikaciji nad zakoni) > podzakonski akti (uredbe - vlada; pravilniki - minister).</li>\n<li><b>Sodni sistem</b>: 44 okrajnih + 11 okrožnih (1. stopnja), 4 višja (pritožbena), vrhovno (izredna sredstva). Specializirana: 4 delovna + 1 socialno, upravno (status višjega). <b>Ustavno sodišče</b>: ločen organ, 9 sodnikov (izvoli DZ na predlog predsednika republike). <b>Računsko sodišče</b>: revizijski organ brez sodnih pristojnosti. Sodnike imenuje DZ na predlog Sodnega sveta (sui generis).</li>\n<li><b>Pravna sredstva</b>: redna (pritožba, ugovor) → pravnomočnost; izredna (revizija; kazensko: zahteva za varstvo zakonitosti, obnova). Pritožbeni razlogi: dejansko stanje, kršitev postopka, napačna uporaba materialnega predpisa. <b>Arbitraža</b> izključuje sodišče (ZArbit); še mediacija, konciliacija.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>2. Pravo EU</h3>\n<ul>\n<li>Temelji: <b>PEU, PDEU, Listina EU o temeljnih pravicah</b> + sodna praksa Sodišča EU. Nadnacionalno pravo. Štiri svoboščine: blago, storitve/ustanavljanje, osebe/delavci, kapital.</li>\n<li><b>7 institucij</b>: Parlament, Evropski svet, Svet, Komisija, Sodišče EU, ECB, Računsko sodišče.</li>\n<li><b>Svet</b>: ministri DČ, Coreper, predsedovanje 6 mesecev; kvalificirana dvojna večina = 55 % DČ + 65 % prebivalstva; soglasje za temeljne ukrepe. <b>Parlament</b>: sedež Strasbourg; volitve 5 let; nadzor: vprašanja, preiskovalne komisije (1/4), nezaupnica Komisiji (2/3 navzočih + absolutna večina vseh → odstopi cela Komisija). <b>Komisija</b>: 27 komisarjev, 5 let; izključna zakonodajna iniciativa (motor integracije), varuh pogodb, izvršilna. <b>Evropski svet</b>: šefi držav/vlad + predsednik Komisije; politične odločitve, 4x letno. <b>Sodišče EU</b>: 1 sodnik/DČ (+ Splošno sodišče 2/DČ, 11 pravobranilcev). <b>Računsko sodišče</b>: 1 član/DČ, 6 let, ni zavezujoče. <b>ECB</b>: evro, monetarna politika, neodvisna.</li>\n<li><b>Viri</b>: primarni (ustanovitvene in pristopne pogodbe, pogodbe s tretjimi državami, splošna načela); sekundarni: <b>uredba</b> (splošna, v celoti zavezujoča, neposredna; 20. dan po objavi), <b>direktiva</b> (cilj; prenos v nacionalni red), <b>sklep</b> (individualen, zavezujoč), <b>priporočila in mnenja</b> (mehko pravo).</li>\n<li><b>Načela</b>: avtonomnost, primarnost (EU > nacionalno, uredbe celo nad ustavo), neposredna uporabnost (pogodbe: jasne, popolne, konkretne; direktiva: posameznik-država + iztekel rok + jasna pravila), subsidiarnost. <b>Pristojnosti</b>: izključne EU (carinska unija, trgovinska politika, konkurenca), deljene (notranji trg), podporne (kultura, turizem, izobraževanje), izključne DČ (dedno, družinsko, kazensko).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>3. Stvarno pravo</h3>\n<ul>\n<li>Del civilnega prava: pripadnost in oblast na stvareh. Značilnost: <b>absolutnost</b> (erga omnes). Načela: povezanost zemljišča in objekta (superficies solo cedit), dobra vera, zaupanje v ZK, prepoved zlorabe. Vir: <b>SPZ</b>. Stvarne pravice (numerus clausus): lastninska, zastavna, služnost, stavbna, stvarno breme.</li>\n<li><b>Posest</b> = dejanska izključna oblast (ni pravica, je varovana); <b>imetništvo</b> = oblast za drugega (natakar).</li>\n<li><b>Lastninska pravica</b>: posest + uporaba in uživanje + razpolaganje. Pridobitev: pravni posel (zavezovalni + razpolagalni; nepremičnine: ZK dovolilo z overjenim podpisom + vpis), dedovanje, zakon, odločba organa. <b>Priposestvovanje</b>: dobroverna lastniška posest 3 leta (premičnine) / 10 let (nepremičnine). Najdba: 1 leto; zaklad: pol najditelj, pol lastnik. Prenehanje: pridobitev drugega, opustitev, uničenje.</li>\n<li><b>Solastnina</b>: določeni deleži; redno upravljanje > 1/2, ostalo soglasje vseh; predkupna pravica; delitev kadarkoli (razen ob neprimernem času). <b>Skupna lastnina</b>: deleži nedoločeni, solidarna odgovornost. <b>Etažna</b>: del zgradbe + solastnina skupnih delov; nad 2 lastnika in 8 delov → upravnik + rezervni sklad.</li>\n<li>Varstvo: lastninska, publicijanska, negatorna tožba.</li>\n<li><b>Zastavna pravica</b>: poplačilo iz vrednosti zastave pred drugimi upniki. <b>Hipoteka</b>: neposestna, na nepremičninah, vpis v ZK; delno plačilo je ne zmanjša; več hipotek mogoče; komisorni dogovor ničen. Neposestna na premičninah: notarski zapis (tudi zaloge, oprema). <b>Ročna zastava (pignus)</b>: pogodba + izročitev.</li>\n<li><b>Služnost</b> (pasivna): stvarne (za gospodujočo nepremičnino, prehajajo, priposestvovanje) in osebne (užitek, raba, stanovanje - časovno omejene). <b>Stvarno breme</b> (aktivno): ponavljajoče se dajatve/storitve. <b>Stavbna pravica</b>: lastna zgradba na/pod tujo nepremičnino, prenosljiva.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>4. Obligacijsko pravo</h3>\n<ul>\n<li>Obveznostna razmerja; vir <b>OZ</b>. Načela: dispozitivnost, prosto urejanje (meje: ustava, prisilni predpisi, morala), vestnost in poštenje, dolžnost izpolnitve (pacta sunt servanda). Kogentna proti dispozitivna norma. Skrbnost: dober strokovnjak / dober gospodarstvenik.</li>\n<li>Nastanek: pogodba, enostranski posli, škoda, neupravičena pridobitev. <b>Zavezovalni</b> (nastanek obveznosti) proti <b>razpolagalni</b> posel (izpolnitev, prenos).</li>\n<li>Sposobnosti: pravna (rojstvo / registracija), poslovna (18; delna 15), kazenska odgovornost 14.</li>\n<li><b>Sklenitev</b>: soglasje o bistvenih sestavinah. Pogajanja nezavezujoča (odgovornost ob neupravičenem odstopu - stroški, ne izgubljeni dobiček). Ponudba zavezuje; molk ne (razen stalne zveze). Predpogodba zavezuje. Predpostavke veljavnosti: sposobnost, soglasje volj, predmet (možen, dopusten, določljiv), podlaga, oblika (če predpisana).</li>\n<li><b>Napake volje</b>: zmota (enostranska), nesporazum (obojestranski), simuliran posel (zavesten - ničen). <b>Ničnost</b> (ustava, prisilni predpisi, morala; brez učinkov) proti <b>izpodbojnost</b> (grožnja z utemeljenim strahom, zmota; učinkuje do izpodbitja).</li>\n<li><b>Odškodnina</b>: nedopustno dejstvo + škoda + vzročna zveza (adekvatna) + odgovornost.</li>\n<li><b>Utrditev</b>: stvarna (ara, zastavna, pridržna pravica) in osebna (poroštvo - pisno; pogodbena kazen - tudi nad škodo; odstopnina). Ara: krivda dajalca → izguba; krivda prejemnika → dvojna ara. Poroštvo proti patronatski izjavi (moralna). Zamudne obresti 8 %. Bančna garancija = abstraktna. Menica: trasirana (trasant → trasat → remitent) / lastna. <b>Izvršnica</b>: samo gospodarski subjekti/javni organi, dobava blaga/storitev, izvršilni naslov, neprenosljiva (ZPreZP-1).</li>\n<li><b>Spremenjene okoliščine</b> (rebus sic stantibus): po sklenitvi, otežena izpolnitev (covid, vojna) - ekonomsko nesmiselno; <b>višja sila</b>: fizično nemogoče (naravne nesreče). Nemožnost ob sklenitvi = ničnost. <b>Pobot</b>: vzajemnost, istovrstnost, zapadlost, iztožljivost, likvidnost + izjava. Prenehanje še: izpolnitev, odpust dolga, prenovitev, pretek časa, smrt.</li>\n<li><b>Prodajna pogodba</b>: bistvena sestavina stvar (ne cena!); brez kupnine = darilna; zamenjava = menjalna. Stvarne napake: graja 8 dni (gospodarske: nemudoma), skrite 8 dni od odkritja; zahtevki: odprava/zamenjava, znižanje, odstop. <b>Podjemna</b>: izdelava/popravilo; material srednje kakovosti; skrite napake 1 mesec.</li>\n</ul>\n</div>"},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[{"id":"pk2-korp","name":"Korporacijsko pravo - splošno","questions":[{"q":"Kaj določa Ustava RS kot temeljni pravni vir korporacijskega prava?","options":["Gospodarska pobuda je svobodna; zakon določa pogoje za ustanavljanje; dejavnost se ne sme izvajati v nasprotju z javno koristjo","Vse gospodarske družbe morajo biti v državni lasti","Gospodarsko dejavnost lahko opravljajo samo pravne osebe","Ustanovitev družbe mora odobriti vlada"],"correct":0,"explanation":"Ustava RS: (1) gospodarska pobuda je svobodna, (2) zakon določa pogoje za ustanavljanje gospodarskih organizacij, (3) gospodarska dejavnost se ne sme izvajati v nasprotju z javno koristjo. Osrednji zakon je ZGD-1."},{"q":"Kaj je gospodarska družba?","options":["Vsaka skupina ljudi, ki skupaj posluje","Pravna oseba, ki na trgu samostojno opravlja pridobitno dejavnost kot svojo izključno dejavnost","Fizična oseba, ki opravlja registrirano dejavnost","Državna ustanova za pospeševanje gospodarstva"],"correct":1,"explanation":"Gospodarska družba je pravna oseba, ki na trgu samostojno opravlja pridobitno dejavnost (dejavnost zaradi pridobivanja dobička) kot izključno dejavnost. Pravna oseba postane z vpisom v sodni register; s tem in z imenovanjem zakonitega zastopnika pridobi tudi poslovno sposobnost."},{"q":"Kakšen je pravni položaj družbenikov do gospodarske družbe?","options":["So lastniki družbe in njenega premoženja","So upniki družbe in lahko kadarkoli zahtevajo vračilo vložka","Niso lastniki niti upniki - imajo 'zgolj' korporacijska upravičenja (premoženjska in upravljavska)","So solidarno odgovorni za vse dolgove družbe"],"correct":2,"explanation":"Družbeniki NISO lastniki družbe (družba ni stvar, ampak pravna oseba - si imetnik deleža) in ne morejo prosto razpolagati s premoženjem, ki so ga prenesli nanjo, niti niso njeni upniki. Imajo korporacijska upravičenja: premoženjska (delež dobička) in upravljavska (vodenje, odločanje)."},{"q":"Katere pravnoorganizacijske oblike so OSEBNE in katere KAPITALSKE družbe?","options":["Osebne: d.n.o. in k.d.; kapitalske: d.o.o., d.d., k.d.d. in evropska delniška družba","Osebne: d.o.o. in d.d.; kapitalske: d.n.o. in k.d.","Osebne: s.p. in d.o.o.; kapitalske: d.d. in k.d.","Vse družbe so kapitalske"],"correct":0,"explanation":"Osebne: družba z neomejeno odgovornostjo (d.n.o.) in komanditna družba (k.d.). Kapitalske: d.o.o., delniška družba (d.d.), komanditna delniška družba (k.d.d.), evropska delniška družba. Družbe se lahko ustanovijo SAMO v zakonsko določenih oblikah (numerus clausus). S.p. NI družba, ampak fizična oseba."},{"q":"Katera je temeljna razlika med osebnimi in kapitalskimi družbami?","options":["Število družbenikov","Odgovornost družbenikov za dolgove: pri osebnih vsaj en družbenik odgovarja z vsem premoženjem, pri kapitalskih družbeniki ne odgovarjajo","Višina osnovnega kapitala","Osebne družbe ne smejo zaposlovati delavcev"],"correct":1,"explanation":"Temeljna razlika je odgovornost za dolgove družbe: osebne družbe - vsaj en družbenik odgovarja subsidiarno z vsem svojim premoženjem; kapitalske - družbeniki ne odgovarjajo (njihova obveznost je le vplačilo vložka). Za obveznosti družbe pa vedno primarno odgovarja družba sama z vsem svojim premoženjem."},{"q":"Kaj je firma in katere so njene obvezne sestavine?","options":["Firma je ime, s katerim družba nastopa v pravnem prometu; obvezni sestavini sta navedba dejavnosti in pravnoorganizacijske oblike","Firma je poslovni prostor družbe; obvezna sestavina je naslov","Firma je logotip družbe brez predpisanih sestavin","Firma je davčna številka družbe"],"correct":0,"explanation":"Firma je ime družbe - omogoča individualizacijo. Obvezne sestavine: navedba dejavnosti + pravnoorganizacijska oblika. Osebne družbe: še imena osebno odgovornih družbenikov (ali oznaka, da jih je več); kapitalske: fantazijski dodatek. Jasno se mora ločiti od drugih firm, biti v slovenskem jeziku in ne posegati v pravice intelektualne lastnine.","more":"Tuji izrazi so izjemoma dovoljeni, če: ustrezajo imenom/priimkom družbenikov, registriranim znamkam, gre za domišljijska poimenovanja ali za mrtvi jezik. V prometu se lahko uporablja skrajšana firma (fantazijski dodatek + oblika)."},{"q":"Kaj je sedež družbe?","options":["Točen poslovni naslov z ulico in hišno številko","Kraj, ki je kot sedež vpisan v sodni register (npr. Ljubljana) - ne poslovni naslov","Kraj, kjer prebiva direktor","Kraj, kjer je družba plačala največ davkov"],"correct":1,"explanation":"Sedež je KRAJ (ne naslov!), vpisan v sodni register - kraj opravljanja dejavnosti, poslov ali poslovodstva. Poslovni naslov je točen naslov, prav tako vpisan v register, a NI sestavina ustanovitvene pogodbe. O spremembi sedeža odločajo družbeniki/skupščina (sprememba akta + registra)."},{"q":"Katero trojno funkcijo ima osnovni kapital v kapitalskih družbah?","options":["Temelj za ugotovitev korporacijskega deleža družbenika, pridobitev premoženja za začetek poslovanja, jamstvo upnikom","Plačilo davkov, plač in dividend","Rezerva za izgube, sklad za investicije, nagrada poslovodstvu","Osnova za obračun DDV, dobička in prispevkov"],"correct":0,"explanation":"Trojna funkcija OK: (1) temelj za ugotovitev korporacijskega deleža družbenika, (2) zagotavlja premoženje za začetek poslovanja, (3) jamstvo upnikom. OK mora biti opredeljen v statutu (d.d.) oz. družbeni pogodbi (d.o.o.) in registriran. Vplača se z denarjem ali stvarnim vložkom."},{"q":"Kateri načeli varujeta upnike v zvezi z osnovnim kapitalom?","options":["Načelo zagotovitve kapitala in načelo ohranitve osnovnega kapitala","Načelo javnosti in načelo zaupanja","Načelo subsidiarnosti in solidarnosti","Načelo dispozitivnosti in kogentnosti"],"correct":0,"explanation":"Načelo zagotovitve kapitala (OK mora biti dejansko vplačan) in načelo ohranitve OK (družbeniki si vplačanega kapitala ne smejo izplačati; prepovedana so izplačila iz premoženja, potrebnega za ohranitev OK). Družbeniki pa niso dolžni dopolnjevati OK, če se premoženje zmanjša - družba lahko posluje z minusom."},{"type":"match","q":"Poveži družbo z njenim zakonitim zastopnikom.","pairs":[{"term":"d.n.o.","def":"Vsak družbenik"},{"term":"k.d. in k.d.d.","def":"Komplementar"},{"term":"d.o.o.","def":"Direktor (poslovodja)"},{"term":"d.d.","def":"Uprava oziroma upravni odbor"}],"explanation":"Družba kot pravna oseba ne more izražati svoje volje - zastopajo jo zakoniti zastopniki, ki lahko opravljajo vsa pravna dejanja iz pravne sposobnosti družbe."},{"q":"Kakšna je razlika med zakonitim zastopnikom in pooblaščencem?","options":["Zakoniti zastopnik ima upravičenje na podlagi zakona/akta družbe in nima omejitev; pooblaščenec ga dobi z izjavo volje zastopanega in je omejen z obsegom pooblastila","Pooblaščenec ima vedno več pravic kot zakoniti zastopnik","Zakoniti zastopnik zastopa samo pred sodiščem","Razlike ni"],"correct":0,"explanation":"Zakoniti zastopnik: določen z zakonom ali aktom o ustanovitvi, lahko dela vse. Pooblaščenec: upravičenje na podlagi izjave volje zastopanega. Generalno (splošno) pooblastilo: vsi redni posli, NE pa menične obveznosti, poroštvo, poravnava, odtujitev/obremenitev nepremičnine, spor, arbitražni sporazum. Specialno: samo posli, za katere je pooblaščen."},{"q":"Kaj lahko dela prokurist?","options":["Vse posle družbe, vključno s prodajo nepremičnin","Vse posle družbe, RAZEN odsvojitve in obremenitve nepremičnin","Samo posle, navedene v pooblastilu","Samo sklepati pogodbe o zaposlitvi"],"correct":1,"explanation":"Prokura je zastopniško upravičenje, določeno z zakonom: prokurist lahko opravlja VSE posle, razen odsvojitve in obremenitve nepremičnin. Omejitve prokure proti tretjim osebam nimajo pravnega učinka - sklepanje poslov s prokuristom je za tretje varno. Prokurist je vpisan v register (AJPES), navadni pooblaščenec ni. Prokuro podeli zakoniti zastopnik (enemu ali več osebam).","more":"Druga posebna pooblastila: pooblastilo po zaposlitvi (prodajalci v trgovini - posli, povezani z njihovim delom) in trgovski potnik (samo posli prodaje blaga, navedeni v pooblastilu)."},{"q":"Kaj je spregled pravne osebnosti?","options":["Redni način poplačila upnikov kapitalske družbe","Izjemen institut, ko za obveznosti družbe odgovarjajo z vsem premoženjem tudi njeni družbeniki - uporablja se subsidiarno, ko druga sredstva ne zagotavljajo poplačila upnikom","Postopek izbrisa družbe iz registra","Kazenska sankcija zoper poslovodstvo"],"correct":1,"explanation":"Spregled pravne osebnosti je izjema od pravila, da družbeniki kapitalskih družb ne odgovarjajo. Uporablja se subsidiarno in samo za poplačilo upnikom. V praksi ga je težko dokazati."},{"q":"Kateri od naštetih NI pogoj za spregled pravne osebnosti?","options":["Družbeniki so družbo zlorabili za dosego cilja, ki je zanje prepovedan","Družbeniki so družbo zlorabili za oškodovanje upnikov","Družbeniki niso spoštovali ločenosti premoženja družbe od svojega","Družba je poslovala z izgubo tri leta zapored"],"correct":3,"explanation":"Izguba sama po sebi NI razlog za spregled. Pogoji (alternativno): zloraba za prepovedan cilj, zloraba za oškodovanje upnikov, mešanje premoženja družbe s svojim, zmanjšanje premoženja družbe v svojo korist ob vedenju (ali dolžnem vedenju), da družba ne bo mogla poravnati obveznosti.","more":"Kriterij je objektiven: ni treba dokazati, da sta družbenika vedela - dovolj je, da bi kot skrbna strokovnjaka morala vedeti (standard dobrega strokovnjaka)."},{"q":"Katere zahteve morajo biti izpolnjene, da je podatek poslovna skrivnost?","options":["Je skrivnost (ni splošno znan), ima tržno vrednost in imetnik je razumno ukrepal za ohranitev tajnosti","Podatek mora biti registriran pri Uradu za intelektualno lastnino","Zadostuje ustni dogovor med zaposlenimi","Podatek mora biti starejši od petih let"],"correct":0,"explanation":"Tri zahteve (Zakon o poslovni skrivnosti): ni splošno znan, ima tržno vrednost, razumni ukrepi za tajnost (pisna določitev + seznanjenost vseh oseb, ki prihajajo v stik - NDA, omejitev dostopa). Poslovna skrivnost ne morejo biti javne informacije, informacije o kršitvi zakona ali dobrih poslovnih običajev.","wrong":{"1":"Registracija je značilna za patent - ta je javno dostopen, poslovna skrivnost pa ravno ni."}},{"q":"Na koga se nanaša konkurenčna prepoved po ZGD-1?","options":["Samo na delavce v delovnem razmerju","Na družbenike d.n.o., komplementarje k.d., družbenike in poslovodje d.o.o., člane uprave, upravnega odbora in nadzornega sveta d.d. ter prokuriste","Na vse državljane","Samo na direktorje delniških družb"],"correct":1,"explanation":"ZGD-1 (ne delovnopravna zakonodaja!): navedene osebe ne smejo sodelovati v teh vlogah v drugi konkurenčni družbi. Sankcija: odškodninska odgovornost. Delovnopravna konkurenčna prepoved pa delavcu med trajanjem razmerja brez pisnega soglasja delodajalca prepoveduje konkurenčno dejavnost; konkurenčna klavzula lahko velja še največ 2 leti po prenehanju."},{"q":"Kdo vodi sodni register in kdo javno objavlja podatke?","options":["Vodijo ga okrožna sodišča, za javno objavo skrbi AJPES","Vodi ga AJPES, objavlja ministrstvo","Vodi ga vlada, objavlja Uradni list","Vodijo ga upravne enote, objavlja FURS"],"correct":0,"explanation":"Sodni register je javna knjiga s pravno pomembnimi dejstvi o subjektih vpisa. Vodijo ga okrožna sodišča, javno objavo zagotavlja AJPES. Družbe in podjetniki morajo voditi poslovne knjige, jih letno zaključiti in letna poročila objaviti na AJPES."},{"q":"Kakšna je razlika med konstitutivnim in deklaratornim vpisom v sodni register?","options":["Konstitutivni: pravica/razmerje nastane šele z vpisom (ustanovitev družbe); deklaratorni: razmerje je že nastalo, vpis je le obvestilo javnosti (imenovanje direktorja)","Konstitutivni vpis opravi notar, deklaratornega sodišče","Deklaratorni vpis je obvezen, konstitutivni prostovoljen","Razlika je samo v ceni vpisa"],"correct":0,"explanation":"Konstitutivni vpis = pravno razmerje nastane šele z vpisom (ustanovitev družbe, sprememba družbene pogodbe). Deklaratorni = razmerje je že nastalo, vpis je obvestilo javnosti (imenovanje novega direktorja/poslovodje, izbris)."},{"type":"match","q":"Poveži načelo sodnega registra z vsebino.","pairs":[{"term":"Načelo obveznega vpisa","def":"Vsak subjekt vpisa je dolžan vložiti predlog za vpis"},{"term":"Načelo javnosti","def":"Podatki so dostopni vsakomur"},{"term":"Načelo zaupanja","def":"Vsakdo se lahko zanese na vpisane podatke"},{"term":"Publicitetno načelo","def":"Od dneva objave vpisa se nihče ne more sklicevati, da podatka ni poznal"}],"explanation":"Štiri načela sodnega registra. Handoff z vaj: 'Nauči se načela sodnega registra' - profesor jih rad vpraša."},{"q":"Družba sklene pogodbo v okviru dejavnosti, ki je nima registrirane. Kakšna je posledica?","options":["Pogodba je nična","Pogodba je veljavna (razen če je tretja oseba vedela za prekoračitev), družba pa stori prekršek","Pogodba je izpodbojna v roku enega leta","Pogodbo mora potrditi sodišče"],"correct":1,"explanation":"Posli izven registrirane dejavnosti so VELJAVNI, razen če je tretja oseba vedela, da dejavnost ni registrirana. Posledica za družbo je prekršek (denarna globa). Družbeniki so pri izbiri dejavnosti sicer avtonomni."},{"q":"Kaj je sistem SPOT?","options":["Sistem vstopnih točk, prek katerih stranke vlagajo vloge za registracijo gospodarskih družb in drugih subjektov","Register plačilno nesposobnih podjetij","Davčna blagajna za gotovinsko poslovanje","Borza vrednostnih papirjev"],"correct":0,"explanation":"SPOT (prej e-VEM) ponuja storitve, prek katerih stranke vlagajo vloge za registracijo gospodarskih družb in drugih subjektov. Prijava s.p. je mogoča na vsaki točki SPOT, z digitalnim potrdilom tudi elektronsko."},{"q":"Ali lahko upnik družbe poseže na osebno premoženje družbenika d.o.o.?","options":["Da, vedno","Ne - premoženje družbe in družbenika sta ločeni; izjema je le spregled pravne osebnosti","Da, če dolg presega 10.000 EUR","Da, s soglasjem sodišča"],"correct":1,"explanation":"Premoženje družbe je ločeno od premoženja družbenikov - upnik lahko predlaga izvršbo samo na premoženje pravne osebe. Družbeniki kapitalskih družb za dolgove ne odgovarjajo; izjema je spregled pravne osebnosti (zloraba, mešanje premoženja). Prav tako ni mogoče pobotati terjatve do družbe s terjatvijo do družbenika - sta različni osebi."}]},{"id":"pk2-sp","name":"S.p. in osebne družbe","questions":[{"q":"Kaj je samostojni podjetnik (s.p.)?","options":["Najmanjša oblika gospodarske družbe","Fizična oseba, ki na trgu samostojno opravlja pridobitno dejavnost v okviru organiziranega podjetja","Pravna oseba z enim družbenikom","Vsak, ki občasno opravi delo za plačilo"],"correct":1,"explanation":"S.p. NI gospodarska družba in ni pravna oseba - je fizična oseba, ki poklicno opravlja pridobitno dejavnost. Pravico opravljati dejavnost pridobi z vpisom v Poslovni register Slovenije (PRS), ki ga vodi AJPES. Prijava je brezplačna (točke SPOT, e-VEM)."},{"q":"Kakšen osnovni kapital je predpisan za s.p. in kako podjetnik odgovarja za dolgove?","options":["7.500 EUR; odgovarja samo s poslovnim premoženjem","Osnovni kapital ni predpisan; za dolgove odgovarja z vsem svojim premoženjem","25.000 EUR; odgovarja subsidiarno","1 EUR; ne odgovarja"],"correct":1,"explanation":"Za s.p. minimalni OK ni predpisan. Podjetnik odgovarja z VSEM svojim premoženjem - premoženje s.p. ni ločeno od osebnega (ločnica deloma obstaja le za davčne namene). V osebnem stečaju se upniki poplačajo tako iz poslovnega kot osebnega premoženja."},{"q":"Kaj mora podjetnik storiti najkasneje 8 dni po vpisu v poslovni register?","options":["Odpreti trgovino","Vpisati dejavnost v davčni register, register za DDV in podati prijavo na ZZZS","Zaposliti vsaj enega delavca","Objaviti letno poročilo"],"correct":1,"explanation":"V 8 dneh po vpisu v PRS: vpis v davčni register, register za davek na dodano vrednost in prijava na Zavod za zdravstveno zavarovanje Slovenije. Če so za dejavnost predpisana dovoljenja (npr. obrtno dovoljenje), dejavnosti ne sme opravljati, dokler jih ne pridobi."},{"q":"Kakšna je razlika med podjetnikom in obrtnikom?","options":["Ni razlike","Obrtnik je ožji pojem - podjetnik, ki opravlja obrtno dejavnost; potrebuje dovoljenje (licenco) obrtne zbornice","Obrtnik je pravna oseba, podjetnik fizična","Podjetnik potrebuje licenco, obrtnik ne"],"correct":1,"explanation":"Obrtnik (Obrtni zakon) je podjetnik, ki opravlja obrtno dejavnost - bistvo je usposobljenost, opravljanje z veščino; potrebna je licenca obrtne zbornice. Svobodni poklic: dejavnost, ki jo posameznik opravlja osebno z znanjem iz formalnega izobraževanja (odvetniki, notarji, zasebni zdravniki)."},{"q":"Kdaj lahko podjetnik vodi poslovne knjige po sistemu enostavnega knjigovodstva?","options":["Vedno","Če ima manj kot 3 delavce, letne prihodke pod 50.000 EUR in aktivo pod 25.000 EUR","Če ima manj kot 10 delavcev in prihodke pod 700.000 EUR","Enostavno knjigovodstvo ni dovoljeno"],"correct":1,"explanation":"Praviloma dvostavno knjigovodstvo; enostavno je dovoljeno, če ima manj kot 3 delavce, letne prihodke pod 50.000 EUR in povprečno aktivo pod 25.000 EUR."},{"q":"Podjetnik se preoblikuje v d.o.o. Kako odgovarja za dolgove, nastale pred preoblikovanjem?","options":["Zanje ne odgovarja več - prevzame jih d.o.o.","Še naprej odgovarja z vsem svojim premoženjem - upniki zaradi preoblikovanja niso oškodovani","Odgovarja samo do višine osnovnega kapitala d.o.o.","Dolgovi s preoblikovanjem ugasnejo"],"correct":1,"explanation":"Dolg z univerzalnim pravnim nasledstvom preide na d.o.o., vendar podjetnik za stare dolgove še vedno odgovarja z vsem svojim premoženjem: subsidiarno (če družba ne poravna) in solidarno. Upniki preoblikovanja ne morejo preprečiti, so pa tako zaščiteni.","more":"Dva načina preoblikovanja: prenos podjetja na NOVO kapitalsko družbo ali na PREVZEMNO kapitalsko družbo. Začne se s pisnim sklepom o prenosu (firma in sedež, izjava o prenosu, vrednost podjetja). Nova družba celostno vstopi v pravni položaj podjetnika (univerzalno pravno nasledstvo). Prenos podjetja na podjetnika prevzemnika: pogodba v obliki notarskega zapisa."},{"q":"Kateri elementi so bistveni za delovno razmerje?","options":["Prostovoljna vključenost, plačilo, osebno in nepretrgano opravljanje dela po navodilih in pod nadzorom delodajalca","Pisna pogodba in polni delovni čas","Delo v prostorih delodajalca","Članstvo v sindikatu"],"correct":0,"explanation":"Elementi delovnega razmerja: prostovoljna vključenost, plačilo za delo, osebno opravljanje, nepretrgano opravljanje, delo po navodilih in pod nadzorom delodajalca. Ekonomsko odvisna oseba: nima elementov delovnega razmerja, a ima zaradi ekonomske odvisnosti posebno zakonsko zaščito. Prekarno delo: atipične oblike (krajši čas, določen čas, agencijsko delo, navidezne samozaposlitve)."},{"q":"Kaj je družba z neomejeno odgovornostjo (d.n.o.)?","options":["Družba dveh ali več oseb, ki za obveznosti družbe odgovarjajo z vsem svojim premoženjem","Družba z enim družbenikom brez odgovornosti","Kapitalska družba z minimalnim OK 7.500 EUR","Društvo, ki opravlja pridobitno dejavnost"],"correct":0,"explanation":"D.n.o. = družba dveh ali več oseb (fizičnih ali pravnih), ki za obveznosti družbe odgovarjajo z vsem svojim premoženjem. Nastane s sklenitvijo družbene pogodbe in vpisom v sodni register (konstitutiven učinek). Pogodba: notarski zapis ali zasebna listina z overjenimi podpisi. En sam ustanovitelj ni mogoč (to bi bil s.p.); navzgor družbeniki niso omejeni."},{"q":"Kako odgovarjajo družbeniki d.n.o. za dolgove družbe?","options":["Vsak do višine svojega vložka","Solidarno (nerazdelno) z vsem svojim premoženjem - upnik lahko celoten dolg zahteva od kateregakoli družbenika; drugačen dogovor proti tretjim ni mogoč","Samo glavni družbenik","Sorazmerno s svojimi deleži, če se tako dogovorijo"],"correct":1,"explanation":"Vsi družbeniki odgovarjajo solidarno z vsem premoženjem: vsak za celoten dolg, dokler ni poplačan; upnik si prosto izbere, od koga bo terjal. Odgovornost je subsidiarna (najprej terja družbo). Dogovor o drugačni odgovornosti učinkuje samo znotraj družbe, ne proti tretjim. Družbenik, ki plača, ima regresni zahtevek do ostalih.","more":"Družbenik odgovarja tudi za dolgove, nastale pred njegovim izstopom iz družbe. Notranja razmerja pa so dispozitivna - uredijo jih z družbeno pogodbo."},{"q":"Kako se po ZGD-1 deli dobiček v d.n.o., če družbena pogodba ne določa drugače?","options":["Po enakih delih","Vsakemu družbeniku najprej pripada 5 % njegovega kapitalskega deleža, preostanek se deli po enakih delih","Sorazmerno z opravljenim delom","O delitvi vsako leto odloči sodišče"],"correct":1,"explanation":"Zakonska delitev: najprej 5 % kapitalskega deleža vsakemu (če ni mogoče, se odstotek zniža), preostanek enakomerno. Kapitalski deleži niso stalni - povečujejo se z dobičkom in zmanjšujejo z izgubo ali izplačili. Družbenik ima tudi pravico vpogleda v poslovne knjige ter pravico/dolžnost vodenja poslov (če ni drugače dogovorjeno); velja konkurenčna prepoved."},{"q":"Kaj se zgodi z d.n.o., če družbenik umre ali odpove pogodbo?","options":["Družba avtomatično nadaljuje z dediči","Družba preneha, razen če družbena pogodba določa drugače","Družba se preoblikuje v d.o.o.","Delež pripade državi"],"correct":1,"explanation":"Smrt ali odpoved družbenika je razlog za prenehanje, RAZEN če pogodba določa drugače (dedič ne vstopi kar prek oporoke - ostali se morajo strinjati; vstop novega družbenika zahteva soglasje vseh). Drugi razlogi: potek časa, sklep družbenikov, stečaj, sodna odločba, manj kot dva družbenika (zakon daje 1 leto za novega družbenika, sicer prenehanje). Preneha z izbrisom iz registra."},{"q":"Kdo sta komplementar in komanditist v komanditni družbi?","options":["Komplementar odgovarja z vsem svojim premoženjem in vodi posle; komanditist ne odgovarja (oziroma le do višine nevplačanega vložka) in prispeva kapital","Komanditist vodi posle, komplementar prispeva denar","Oba odgovarjata enako z vsem premoženjem","Komplementar je vedno pravna oseba"],"correct":0,"explanation":"K.d. = družba dveh ali več oseb: vsaj en komplementar (odgovarja z vsem premoženjem, vodi posle, zakoniti zastopnik) in vsaj en komanditist (ne odgovarja; upnikom odgovarja samo do višine NEVPLAČANEGA vložka - če je vložek vplačal, ne odgovarja). Običajno komplementar prispeva znanje in delo, komanditist premoženje. Uporabljajo se pravila o d.n.o."},{"q":"Ali je ime komanditista lahko v firmi komanditne družbe?","options":["Da, obvezno","Ne - v firmi so samo imena komplementarjev","Da, če s tem soglaša","Da, a le pri dvojni družbi"],"correct":1,"explanation":"Firma k.d. je podobna kot pri d.n.o., vendar ime in priimek komanditista NISTA vključena - v firmi so samo (osebno odgovorni) komplementarji. Komanditist tudi ni upravičen zastopati družbe, razen če mu komplementar podeli prokuro ali posebno pooblastilo.","more":"Če komanditist kljub temu nastopa kot zastopnik/v firmi, so posli veljavni, a ga bodo tretji lahko obravnavali kot komplementarja (odgovornost!)."},{"q":"Kako se deli dobiček komanditistu v k.d.?","options":["Komanditist dobička nikoli ne dobi","Dobiček se pripisuje njegovemu kapitalskemu deležu, dokler ta ne doseže dogovorjenega vložka; šele nato se mu dobiček izplačuje","Komanditist vedno dobi polovico dobička","Dobiček se izplačuje samo komplementarjem"],"correct":1,"explanation":"Vsakemu družbeniku pripada 5 % kapitalskega deleža, presežek po razmerju deležev. Ključno: komanditistu ni dovoljeno izplačevati dobička, dokler njegov kapitalski delež ne doseže vložka, ki bi ga moral vplačati - do takrat se dobiček pripisuje deležu."},{"q":"Kaj je dvojna družba?","options":["Družba z dvema družbenikoma","Osebna družba (k.d. ali d.n.o.), v kateri so vsi osebno odgovorni družbeniki kapitalske družbe (npr. edini komplementar je d.o.o.)","Družba z dvema dejavnostma","Holding z dvema hčerinskima družbama"],"correct":1,"explanation":"Dvojna družba = k.d., kjer je edini komplementar (oz. vsi komplementarji) kapitalska družba, ali d.n.o., kjer so vsi družbeniki kapitalske družbe. Ostane osebna družba (komplementar odgovarja z vsem premoženjem), a družbeniki tega d.o.o. za dolgove ne odgovarjajo. V firmi mora biti navedena celotna firma komplementarja - kapitalske družbe; posle vodi kapitalska družba (fizično njen direktor)."},{"q":"Metka prispeva 50.000 EUR, Nina znanje in delo ter bo vodila posle. Ustanovita k.d. Kdo je kdo?","options":["Metka je komplementarka, Nina komanditistka","Metka je komanditistka (prispeva denar, ne odgovarja), Nina je komplementarka (vodi posle, zakonita zastopnica, odgovarja z vsem premoženjem)","Obe sta komplementarki","Obe sta komanditistki"],"correct":1,"explanation":"Tipična delitev vlog v k.d.: komanditist prispeva kapital in ne odgovarja, komplementar prispeva delo, vodi in zastopa družbo ter odgovarja z vsem premoženjem. V firmi bo samo Nina."},{"q":"Ali ima družbenik d.n.o. zakonsko pravico do izstopa iz družbe?","options":["Da, kadarkoli s pisno izjavo","Ne - lahko pa toži na izstop; če uspe, družba preneha (razen po pogodbi drugače)","Da, z odpovednim rokom 3 mesecev","Da, a izgubi ves vložek"],"correct":1,"explanation":"V d.n.o. družbenik nima zakonske pravice do izstopa; izstop se lahko uredi z družbeno pogodbo. Odpoved pogodbe s strani družbenika je razlog za prenehanje družbe."},{"q":"Kakšna je razlika med navadnim in normiranim s.p. pri obdavčitvi?","options":["Ni razlike","Navadni: dobiček = prihodki - dejanski stroški, progresivni davek; normirani: stroški so vnaprej priznani v višini 80 % prihodkov, davek se plača od preostalih 20 %","Normirani s.p. ne plačuje davkov","Navadni s.p. plačuje samo DDV"],"correct":1,"explanation":"Navadni s.p.: davek od dejanskega dobička (prihodki minus stroški), progresivno. Normirani s.p.: normirani stroški 80 % prihodkov - obdavčenih je 20 % prihodkov (efektivno 4 % od prihodkov oz. 20 % od dobička).","more":"Podatek z vaj: trenutna meja za normirance je 60.000 EUR prihodkov, po napovedani spremembi (2026) 120.000 EUR."}]},{"id":"pk2-doo","name":"Družba z omejeno odgovornostjo (d.o.o.)","questions":[{"q":"Koliko družbenikov ima lahko d.o.o. in kakšen je minimalni osnovni kapital?","options":["1 do 50 družbenikov; minimalni OK 7.500 EUR, osnovni vložek najmanj 50 EUR","Najmanj 2 družbenika; OK 25.000 EUR","Neomejeno družbenikov; OK 1 EUR","1 do 10 družbenikov; OK 10.000 EUR"],"correct":0,"explanation":"D.o.o. lahko ustanovi 1 do največ 50 fizičnih ali pravnih oseb. Minimalni OK je 7.500 EUR, posamezni osnovni vložek najmanj 50 EUR. Družbenik na podlagi vložka pridobi poslovni delež (izražen v % ali ulomku), sorazmeren z vrednostjo vložka."},{"q":"Koliko vložka mora biti vplačanega pred prijavo za vpis d.o.o. v sodni register?","options":["Celoten znesek vseh vložkov","Vsak družbenik vsaj 1/4 svojega osnovnega vložka, skupaj vsaj 7.500 EUR; stvarni vložki v celoti","Vsaj polovica OK, stvarni vložki lahko kasneje","Nič - vplača se po vpisu"],"correct":1,"explanation":"Pred prijavo: vsak družbenik vsaj 1/4 osnovnega vložka, skupna vrednost zagotovljenih vložkov vsaj 7.500 EUR. Stvarne vložke (premičnine, nepremičnine, pravice, podjetje) je treba zagotoviti V CELOTI pred vpisom. Denarni vložki na bančni račun; poslovodja mora z vložki prosto razpolagati.","more":"Če je vrednost stvarnega vložka nad 100.000 EUR, je potreben cenilec. Znanje, izkušnje in veze ne morejo biti stvarni vložek (nimajo določljive vrednosti)."},{"q":"Ali je družbenik lahko oproščen vplačila osnovnega vložka ali ga pobota s svojo terjatvijo do družbe?","options":["Da, s sklepom skupščine","Ne - oprostitev ni mogoča niti pobot; mogoča je le ob zmanjšanju OK; ob neplačilu grozi kaducitetni postopek (izključitev)","Da, če ima družba dovolj premoženja","Pobot je vedno mogoč"],"correct":1,"explanation":"Oprostitev vplačila ni mogoča; družbenik tudi ne more pobotati svoje terjatve z zahtevkom družbe za vplačilo vložka. Oprostitev je mogoča samo z zmanjšanjem OK (sorazmerni znesek). Če družbenik kljub pozivu ne plača, se začne kaducitetni postopek - izključitev iz družbe zaradi neplačila."},{"q":"V kakšni obliki se sklene družbena pogodba d.o.o.?","options":["Ustno pred pričami","V obliki notarskega zapisa ali na posebnem obrazcu (fizično ali elektronsko) z overjenimi podpisi","Z navadno pisno pogodbo brez overitve","S sklepom skupščine"],"correct":1,"explanation":"Družbena pogodba: notarski zapis ALI poseben obrazec (fizičen/elektronski, podpisi overjeni). Obvezna vsebina: podatki o družbenikih; firma, sedež, dejavnost; višina OK, vložki in deleži; morebitne dodatne obveznosti; pri stvarnih vložkih predmet in znesek. Družba postane pravna oseba z vpisom v sodni register."},{"q":"S kakšno večino se spreminja družbena pogodba d.o.o. in kakšen je učinek vpisa spremembe?","options":["Navadna večina; vpis je deklaratoren","3/4 večina glasov družbenikov; vpis spremembe v sodni register je konstitutiven (velja šele od vpisa)","Soglasje vseh; vpis ni potreben","2/3 večina; velja takoj s sklepom"],"correct":1,"explanation":"Sprememba pogodbe: 3/4 glasov družbenikov; če nalaga dodatne obveznosti, soglasno (razen povečanja OK). Sklep praviloma potrdi notar; poslovodja spremembo prijavi v register s prečiščenim besedilom. Vpis spremembe je KONSTITUTIVEN - velja šele od vpisa."},{"type":"match","q":"Poveži pravice družbenika d.o.o. s kategorijo.","pairs":[{"term":"Udeležba pri dobičku","def":"Premoženjska pravica - deli se sorazmerno s poslovnimi deleži"},{"term":"Delež likvidacijske mase","def":"Premoženjska pravica - po poplačilu upnikov in 6 mesecih od zadnjega poziva"},{"term":"Prednostna pravica pri povečanju OK","def":"Premoženjska pravica do 'novega' poslovnega deleža"},{"term":"Glasovanje na skupščini","def":"Upravljavska pravica - na vsakih dopolnjenih 50 EUR vložka en glas"},{"term":"Pravica do informacij in vpogleda","def":"Upravljavska pravica do poslovne dokumentacije"}],"explanation":"Pravice so urejene v ZGD-1 in z družbeno pogodbo (večina določb je dispozitivnih). Iz delitve dobička družbenika s pogodbo NI mogoče izključiti."},{"q":"Kdaj ima družbenik d.o.o. pravico do izplačila dobička?","options":["Vsako leto avtomatično","Če družba ustvari dobiček (ob spoštovanju vseh pravil) IN skupščina sklene, da se dobiček razdeli","Kadarkoli na zahtevo družbenika","Samo ob likvidaciji"],"correct":1,"explanation":"Pravica je pogojna: (1) obstoj (bilančnega) dobička v skladu z zakonom in pogodbo, (2) sklep skupščine o razdelitvi (lahko ga tudi investirajo). Deli se sorazmerno z deleži."},{"q":"Družbenik d.o.o. želi prodati poslovni delež tretji osebi. Kaj mora storiti?","options":["Delež lahko proda prosto brez omejitev","Druge družbenike mora pisno obvestiti o nameri in pogojih ter jih pozvati, da morebitni kupec sporoči pripravljenost za nakup v enem mesecu - družbeniki imajo predkupno pravico","Potrebuje dovoljenje sodišča","Delež lahko proda samo družbi"],"correct":1,"explanation":"Predkupna pravica družbenikov velja pri prodaji TRETJIM osebam (ne med družbeniki): pisno obvestilo o nameri in pogojih + rok 1 mesec. Če je kupcev več družbenikov, postanejo imetniki skupaj. Pogodba lahko določi, da je za odsvojitev tretjim potrebno soglasje (vinkuliran poslovni delež); če soglasja ni in nihče ne kupi, ima družbenik izstopno upravičenje. Za pridobitelja se šteje le tisti, ki poslovodji prijavi in dokaže pridobitev."},{"q":"Kako se skliče skupščina d.o.o.?","options":["Z objavo v Uradnem listu 30 dni prej","Poslovodja jo skliče s priporočenim pismom družbenikom z dnevnim redom, poslanim vsaj 25 dni pred skupščino","Prek AJPES 15 dni prej","Ustno na zadnji skupščini"],"correct":1,"explanation":"Skupščino (načeloma 1x letno) skliče poslovodja s priporočenim pismom z dnevnim redom, vsaj 25 dni prej. Družbeniki lahko ob soglasju sklenejo tudi, da se skupščina ne opravi in glasove sporočijo poslovodji pisno. Sklepi se sprejemajo z večino oddanih glasov, če zakon/pogodba ne določa drugače.","wrong":{"0":"30-dnevni javni sklic velja za skupščino DELNIŠKE družbe."}},{"q":"O čem odločajo družbeniki na skupščini d.o.o.?","options":["Samo o delitvi dobička","O sprejetju letnega poročila in uporabi bilančnega dobička, zahtevi za vplačilo vložkov, vračanju naknadnih vplačil, delitvi in prenehanju poslovnih deležev itd.","O vsakodnevnem vodenju poslov","O sklepanju vseh pogodb družbe"],"correct":1,"explanation":"Skupščina je temeljni organ (vsi družbeniki): letno poročilo in bilančni dobiček, vplačila vložkov, naknadna vplačila, delitev/prenehanje deležev itd. Vsakodnevno vodenje poslov je naloga poslovodje."},{"q":"Kdo je poslovodja d.o.o. in kako ga je mogoče odpoklicati?","options":["Poslovodja (direktor) na lastno odgovornost vodi posle in zastopa družbo; skupščina ga lahko odpokliče KADARKOLI, ne glede na mandat","Poslovodjo imenuje sodišče in ga ni mogoče odpoklicati","Poslovodja je vedno največji družbenik","Odpoklic je mogoč samo iz utemeljenih razlogov"],"correct":0,"explanation":"Družba ima enega ali več poslovodij; imenuje jih skupščina (oz. nadzorni svet, če obstaja). Skupščina lahko poslovodjo odpokliče kadarkoli (drugače kot upravo d.d., kjer so potrebni utemeljeni razlogi!). Vpis poslovodje v register je deklaratoren. Obvezna organa d.o.o.: skupščina in poslovodja; nadzorni svet je opcijski (pogodba).","wrong":{"3":"Utemeljeni razlogi so potrebni za odpoklic člana UPRAVE d.d. s strani nadzornega sveta."}},{"q":"Kdaj lahko družbenik s tožbo izstopi iz d.o.o.?","options":["Kadarkoli brez razloga","Če mu drugi družbeniki ali poslovodja povzročajo škodo, ovirajo uresničevanje pravic ali mu nalagajo nesorazmerne obveznosti","Samo ob prodaji celotne družbe","Izstop s tožbo ni mogoč"],"correct":1,"explanation":"Pogodbena pravica do izstopa ni zakonska - mora biti dogovorjena. S tožbo pa lahko izstopi iz utemeljenih razlogov: škoda s strani drugih, oviranje pogodbene pravice do izstopa, oviranje pri uresničevanju pravic, nesorazmerne obveznosti. Izstopivši ima pravico do izplačila ocenjene vrednosti deleža (družba jo mora izplačati v 3 letih); ostali morajo v 3 mesecih zmanjšati OK ali prevzeti nove vložke."},{"q":"Kaj je lastni delež d.o.o.?","options":["Delež, ki ga ima družba v drugi družbi","Poslovni delež, ki je v lasti družbe same; družba ne more pridobiti vseh deležev, ker bi ostala brez družbenikov","Delež največjega družbenika","Rezervni sklad družbe"],"correct":1,"explanation":"Lastni delež je poslovni delež v lasti družbe. Vseh deležev družba ne more pridobiti - ostala bi brez družbenikov."},{"q":"Katere posebnosti veljajo za enoosebno d.o.o.?","options":["Ne sme zaposlovati delavcev","Ustanovi se z aktom o ustanovitvi (enostranska izjava volje); OK 7.500 EUR (za nevplačani denarni del varščina); sklepi se vpisujejo v knjigo sklepov","Osnovni kapital ni potreben","Družbenik ne more biti poslovodja"],"correct":1,"explanation":"Enoosebna d.o.o. ('samostojni podjetnik z omejeno odgovornostjo'): akt o ustanovitvi namesto pogodbe; OK 7.500 EUR - za nevplačani denarni del pred prijavo je potrebna varščina; knjiga sklepov (fizična ali elektronska, sklepe potrdi notar). Poslovodja je lahko družbenik ali kdo drug; edini družbenik kot poslovodja z družbo sklene pogodbo o zaposlitvi."},{"q":"Kaj pomeni, da je d.o.o. 'hibrid' med osebno in delniško družbo?","options":["Družbeniki delno odgovarjajo za dolgove","Združuje pogodbeno svobodo in aktivno vlogo družbenikov (kot osebne družbe) z omejeno odgovornostjo in predpisanim minimalnim OK (kot d.d.)","Lahko izdaja delnice","Polovica družbenikov odgovarja, polovica ne"],"correct":1,"explanation":"D.o.o. je fleksibilna: pogodbena svoboda pri notranjih razmerjih (dispozitivnost - kot pri osebnih družbah), preprosto upravljanje, aktivno vključevanje družbenikov + omejena odgovornost, minimalni OK in preprosta sprememba družbenikov (kot pri kapitalskih). Nasprotje: d.d. s statutarno strogostjo."},{"q":"Kdaj se lahko družbenikom d.o.o. izplača premoženje družbe?","options":["Kadarkoli po sklepu poslovodje","Samo če ima družba bilančni dobiček ali ob zmanjšanju OK po postopku, ki spoštuje pravice upnikov; prepovedana so prikrita izplačila","Vsak mesec v obliki 'posojil'","Nikoli"],"correct":1,"explanation":"Načelo ohranjanja OK: prepovedana izplačila iz premoženja, potrebnega za ohranitev OK. Dovoljeno: izplačilo bilančnega dobička ali ob predpisanem zmanjšanju OK. Prepovedane so vse oblike prikritega izplačila dobička; sankcija je vrnitev prepovedanih izplačil. Posojilo družbeniku je sicer mogoče, a mora biti vrnjeno - sicer davčne posledice."},{"q":"Koliko glasov ima družbenik na skupščini d.o.o. po zakonu?","options":["Vsak družbenik en glas","Na vsakih dopolnjenih 50 EUR osnovnega vložka en glas","Glasove določi poslovodja","Sorazmerno s starostjo deleža"],"correct":1,"explanation":"ZGD-1: en glas na vsakih dopolnjenih 50 EUR osnovnega vložka (če pogodba ne določa drugače). Za preprečitev spremembe družbene pogodbe torej zadostuje več kot 25 % glasov (sprememba zahteva 3/4)."},{"q":"Posameznik želi v treh mesecih ustanoviti tri d.o.o. Ali lahko?","options":["Da, brez omejitev","Ne - v treh mesecih lahko ustanovi le eno d.o.o. oziroma pridobi delež le v eni d.o.o.","Da, če ima dovolj kapitala","Da, a le z dovoljenjem AJPES"],"correct":1,"explanation":"Omejitev ustanavljanja (ZGD-1, proti veriženju): posameznik lahko v treh mesecih ustanovi eno d.o.o. oziroma pridobi poslovni delež le v eni d.o.o."}]},{"id":"pk2-dd","name":"Delniška družba (d.d.)","questions":[{"q":"Kakšen je minimalni osnovni kapital delniške družbe in koliko ga mora biti vplačanega pred vpisom?","options":["7.500 EUR; vplačan v celoti","25.000 EUR; vsaj 25 % emisijskega zneska vsake delnice, stvarni vložki v celoti; vsaj 1/3 OK mora biti v denarju","50.000 EUR; vsaj polovica","25.000 EUR; nič pred vpisom"],"correct":1,"explanation":"Min. OK d.d. je 25.000 EUR. Pred vpisom v register: vsaj 25 % emisijskega zneska delnice; stvarni vložek v celoti. Vsaj 1/3 OK mora biti v denarju. Temeljna dolžnost delničarja je vplačilo emisijskega zneska delnice; za dolgove družbe delničarji ne odgovarjajo."},{"q":"Kaj pomeni statutarna strogost pri d.d.?","options":["Statut lahko določi karkoli","V statutu se lahko dogovori le tisto, kar zakon izrecno dovoljuje - nasprotje pogodbene svobode pri d.o.o.","Statut mora potrditi ustavno sodišče","Statuta ni mogoče spreminjati"],"correct":1,"explanation":"Temeljni akt d.d. je STATUT, za katerega velja statutarna strogost: dogovoriti se je mogoče le tisto, kar zakon izrecno dovoljuje. Pri d.o.o. velja obratno - pogodbena svoboda (vse, česar zakon ne prepoveduje). D.d. je zato manj fleksibilna."},{"q":"Kateri je trojni pomen delnice?","options":["Alikvotni del OK, skupek korporacijskih pravic, vrednostni papir","Denar, blago, storitev","Lastnina, posest, imetništvo","Dividenda, obresti, kupnina"],"correct":0,"explanation":"Delnica je: (1) alikvotni (sorazmerni) del OK, (2) skupek korporacijskih pravic (premoženjskih in upravljavskih), (3) vrednostni papir. Delnice lahko izdajo samo delniške družbe; celoten OK je razdeljen na delnice."},{"q":"Kakšna je razlika med nominalnimi in kosovnimi delnicami?","options":["Nominalne se glasijo na nominalni znesek (najmanj 1 EUR ali večkratnik); kosovne nimajo nominalnega zneska - vsaki pripada enak pripadajoči znesek v OK glede na število delnic","Kosovne delnice so vredne več","Nominalne delnice nimajo glasovalne pravice","Kosovne delnice se ne smejo prodajati"],"correct":0,"explanation":"Nominalna delnica: glasi se na nominalni znesek (min. 1 EUR ali večkratnik); OK = št. delnic x nominalna vrednost. Kosovna delnica: pripadajoči znesek v OK = OK / število delnic (ne sme biti pod 1 EUR). V Sloveniji so skoraj vse delnice kosovne."},{"q":"Kakšno je razmerje med emisijsko, nominalno in tržno vrednostjo delnice?","options":["Emisijska vrednost ne sme biti manjša od nominalne (lahko je večja); tržna je lahko višja ali nižja od obeh","Vse tri morajo biti enake","Tržna vrednost ne sme presegati nominalne","Emisijska mora biti nižja od nominalne"],"correct":0,"explanation":"Emisijska vrednost (ob izdaji, plača jo prvi delničar) ne sme biti pod nominalno/pripadajočim zneskom - zaradi zagotavljanja OK; lahko je večja. Tržna vrednost (na trgu) je lahko višja ali nižja od obeh. Nominalna vrednost je računovodska kategorija za izračun OK."},{"q":"Ali sme d.d. delničarjem vrniti ali obrestovati vplačane vložke?","options":["Da, s sklepom skupščine","Ne - velja načelo trajnosti in nespremenljivosti delniškega kapitala; družba lahko izplača samo bilančni dobiček","Da, po petih letih","Da, do višine 10 % OK"],"correct":1,"explanation":"Vložki se delničarjem ne smejo vrniti niti obrestovati (načeli zagotovitve in ohranitve OK). Delničar 'izstopi' samo tako, da delnico proda drugemu. Družba lahko izplača le bilančni dobiček. Delničarji lahko do premoženja družbe pridejo le: pri izplačilu bilančnega dobička, pri zmanjšanju OK in ob prenehanju družbe."},{"type":"match","q":"Poveži pravico delničarja s kategorijo.","pairs":[{"term":"Pravica do dividende","def":"Premoženjska - pogoja: dobiček in sklep skupščine o delitvi"},{"term":"Prednostni nakup novih emisij","def":"Premoženjska - sorazmerno z deležem v OK pri povečanju OK"},{"term":"Alikvotni delež pri likvidaciji","def":"Premoženjska - po absolutni prednosti poplačila upnikov"},{"term":"Glasovalna pravica","def":"Upravljavska - temeljno pravilo: ena delnica, en glas"},{"term":"Izpodbijanje sklepov skupščine","def":"Upravljavska - vsak delničar, če je sklep v nasprotju s statutom ali zakonom"}],"explanation":"Delničarji niso lastniki družbe niti njeni upniki - delnica prinaša korporacijska upravičenja. Iz delitve dobička s statutom ni mogoče izključiti določene skupine delničarjev."},{"q":"Kdaj postane delnica vrednostni papir?","options":["S podpisom statuta","Ko KDD vpiše delnice v centralni register nematerializiranih vrednostnih papirjev (po vpisu družbe v sodni register)","Z natisom listine","S prvo prodajo na borzi"],"correct":1,"explanation":"D.d. lahko delnice izda šele po vpisu v sodni register; delnica postane vrednostni papir z vpisom v centralni register pri KDD. Delnice so nematerializirani vrednostni papirji (NVP) - pravice se pridobijo, omejijo ali prenehajo samo z vpisom v centralni register. Temeljna značilnost: preprosta in prosta prenosljivost."},{"q":"Kaj so vinkulirane delnice?","options":["Delnice brez glasovalne pravice","Delnice z omejenim prenosom - prodaja tretji osebi le z odobritvijo družbe; mogoče samo pri imenskih delnicah, če statut tako določa ob ustanovitvi","Delnice v lasti države","Delnice, ki kotirajo na borzi"],"correct":1,"explanation":"Vinkulacija = omejitev prenosa delnice (soglasje družbe). Mogoča samo pri imenskih delnicah in samo, če je določena v statutu ob ustanovitvi; za delnice izven organiziranega trga iz utemeljenih razlogov v statutu; za javne d.d. (organiziran trg) vinkulacija ni mogoča oziroma je še bolj omejena."},{"q":"Kakšna je razlika med navadnimi in prednostnimi delnicami?","options":["Navadne dajejo upravljavske in premoženjske pravice; prednostne dajejo še dodatne prednosti (npr. pri dividendi, likvidaciji), a ne pri glasovanju; prednostnih je lahko največ polovica","Prednostne delnice imajo več glasov","Navadne delnice nimajo pravice do dividende","Prednostne delnice so vedno državne"],"correct":0,"explanation":"Prednostne delnice dajejo dodatne pravice (prednost pri dividendi, pri likvidaciji), NE smejo pa dajati prednosti pri glasovanju; lahko so tudi brez glasovalne pravice. Največ polovica delnic je lahko prednostnih. Če prednostni znesek ni izplačan (in zaostanek ni poravnan naslednje leto), delnice brez glasovalne pravice pridobijo glasovalno pravico do poplačila."},{"q":"Kakšna je razlika med kumulativnimi in participativnimi prednostnimi delnicami?","options":["Kumulativna daje pravico do dividende za vsako leto z dobičkom, tudi če skupščina odloči, da se dobiček ne deli; participativna daje prednostno dividendo pred navadnimi delničarji (in še delež preostanka)","Kumulativne delnice imajo dva glasova","Participativne delnice se ne smejo prodajati","Razlike ni"],"correct":0,"explanation":"Kumulativna (zbirna): pravica do dividende za vsako poslovno leto z dobičkom, tudi če skupščina odloči, da se ne deli (a dobiček mora obstajati - sicer bi kršili ohranitev OK). Participativna (udeležbena): prednostna dividenda pred navadnimi delničarji + udeležba pri preostanku."},{"q":"Kaj velja za lastne delnice d.d.?","options":["Družba jih lahko prosto kupuje","Izvirno pridobivanje je prepovedano; derivativno močno omejeno; iz lastnih delnic družba nima nobenih pravic; presežek nad 10 % mora odsvojiti v 3 letih","Iz njih družba prejema dividende","Družba lahko z njimi glasuje na skupščini"],"correct":1,"explanation":"ZGD-1 prepoveduje izvirno pridobivanje lastnih delnic (ob ustanovitvi ali povečanju OK) in omejuje derivativno (na sekundarnem trgu). Če dovoljeno pridobljene delnice presegajo 10 %, jih mora družba odsvojiti v 3 letih. Iz lastnih delnic družba NIMA pravic (ni dividend, ni glasovanja). Razlogi omejitev: varstvo OK, preprečitev diskriminacije delničarjev in glasovanja uprave sami sebi."},{"q":"Katera sta postopka ustanovitve d.d.?","options":["Sočasna (simultana) - ustanovitelji sami prevzamejo vse delnice; postopna (sukcesivna) - delnice se vpisujejo na podlagi oglasa z vabilom k javnemu vpisu","Redna in skrajšana","Notarska in sodna","Zasebna in državna"],"correct":0,"explanation":"Simultana: vsi ustanovitelji sprejmejo in podpišejo statut ter sami prevzamejo vse delnice; imenujejo prvi nadzorni svet/upravni odbor, ta upravo/izvršne direktorje. Sukcesivna: del delnic prevzamejo ustanovitelji, investitorje iščejo z oglasom (prospekt). Tri faze: predinkorporacijska (dogovor), organiziranje in strukturiranje (statut, vpis OK), inkorporiranje (vpis v register - pravna osebnost)."},{"q":"Kateri organi sestavljajo dvotirni in kateri enotirni sistem upravljanja d.d.?","options":["Dvotirni: skupščina, nadzorni svet, uprava; enotirni: skupščina in upravni odbor (ta lahko imenuje izvršne direktorje)","Dvotirni: dva direktorja; enotirni: en direktor","Dvotirni: skupščina in uprava; enotirni: samo uprava","Oba sistema imata iste organe, razlika je v imenu"],"correct":0,"explanation":"Dvotirni (tradicionalni germanski): skupščina + nadzorni svet + uprava; ločenost delničarjev od uprave - skupščina uprave ne more neposredno zamenjati (le prek NS). Enotirni: skupščina + upravni odbor (vodi IN nadzira); večja fleksibilnost in avtonomija; javne d.d. morajo imenovati izvršne direktorje. Sistem določijo ustanovitelji v statutu."},{"q":"Kdo imenuje upravo v dvotirnem sistemu in za koliko časa?","options":["Skupščina za 4 leta","Nadzorni svet za največ 6 let z možnostjo neomejenega ponovnega imenovanja","Sodišče za nedoločen čas","Delavci za 2 leti"],"correct":1,"explanation":"Upravo imenuje nadzorni svet za največ 6 let (ponovna imenovanja neomejena). Uprava vodi posle samostojno in na lastno odgovornost ter zastopa družbo brez omejitev (omejitve ne učinkujejo proti tretjim). Predsednik uprave je v veččlanski upravi obvezen. Član uprave ni nujno delničar."},{"q":"Iz katerih razlogov lahko nadzorni svet odpokliče člana uprave?","options":["Brez razloga, kadarkoli","Iz utemeljenih razlogov: hujša kršitev obveznosti, nesposobnost vodenja poslov, izrek nezaupnice na skupščini, drugi ekonomsko-poslovni razlogi","Samo s soglasjem člana uprave","Samo ob stečaju"],"correct":1,"explanation":"Za odpoklic uprave so potrebni UTEMELJENI razlogi (za razliko od poslovodje d.o.o. in izvršnih direktorjev, ki jih je mogoče odpoklicati brez razlogov). Uprava mora vsaj 1x letno poročati NS o poslovni politiki, donosnosti, poteku poslov in poslih, pomembnih za donosnost/plačilno sposobnost. Vpis člana uprave v register je deklaratoren."},{"q":"Kakšne so pristojnosti nadzornega sveta?","options":["Vodi tekoče posle družbe","Nadzoruje vodenje poslov, pregleduje knjige, zahteva poročila, imenuje in odpokliče upravo, pregleda letno poročilo, lahko zahteva revizijo in predlaga sklic skupščine","Izplačuje dividende","Sprejema statut"],"correct":1,"explanation":"NS je nadzorni organ: nadzor vodenja poslov, pregled knjig in dokumentacije, vprašanja in poročila od uprave, IZKLJUČNA pristojnost imenovanja/odpoklica uprave, mnenje o letnem poročilu (če ga potrdi, je sprejeto), revizija, predlog sklica skupščine. Predsednik NS zastopa družbo proti članom uprave. Najmanj 3 člani: predstavniki delničarjev (voli skupščina) + predstavniki delavcev (voli svet delavcev). Člani NS ne morejo biti udeleženi pri dobičku."},{"q":"O čem odloča skupščina d.d.?","options":["O vodenju vsakodnevnih poslov","O letnem poročilu (pogojno), bilančnem dobičku, imenovanju NS/upravnega odbora, razrešnici, spremembah statuta, povečanju/zmanjšanju kapitala, prenehanju družbe, imenovanju revizorja, politiki prejemkov","O sklepanju pogodb z dobavitelji","O zaposlovanju delavcev"],"correct":1,"explanation":"Skupščina je hierarhično najvišji organ (vsi delničarji), odloča o temeljnih vprašanjih. O vodenju poslov NE more odločati, razen če to zahteva poslovodstvo. Letno poročilo sprejema le, če ga NS/UO ni potrdil, če ji odločitev prepustijo ali če določa statut. Zaseda vsaj 1x letno; skliče jo poslovodstvo, NS ali manjšina delničarjev."},{"q":"Kako se skliče skupščina d.d.?","options":["S priporočenim pismom 25 dni prej","Objava vsaj 30 dni pred skupščino (AJPES ali dnevnik/glasilo); sklic vsebuje čas, kraj, dnevni red in predloge sklepov; vsak sklep potrdi notar","Po elektronski pošti 8 dni prej","Sklica ni treba objaviti"],"correct":1,"explanation":"Sklic skupščine d.d.: objava vsaj 30 dni prej (AJPES ali dnevnik na celotnem območju Slovenije + glasilo/elektronski medij). Vsak skupščinski sklep potrdi notar v notarskem zapisniku; poslovodja v 24 urah prepis pošlje sodnemu registru. Sklepi se sprejemajo z navadno večino, razen če zakon/statut določata drugače. (Primerjaj: d.o.o. - priporočeno pismo 25 dni.)"},{"q":"Kdo ne more biti član organa vodenja ali nadzora v d.d.?","options":["Oseba, mlajša od 40 let","Poslovno nesposobna oseba; član drugega organa vodenja/nadzora iste družbe; pravnomočno obsojeni za kazniva dejanja zoper gospodarstvo, delovno razmerje, pravni promet, premoženje, okolje; oseba s prepovedjo opravljanja poklica","Oseba brez univerzitetne izobrazbe","Tujec"],"correct":1,"explanation":"Omejitve: poslovna nesposobnost, hkratno članstvo v drugem organu vodenja ali nadzora TE družbe, pravnomočna obsodba (gospodarstvo, delovno razmerje in socialna varnost, pravni promet, premoženje, okolje), varnostni ukrep prepovedi poklica (dokler traja). Član upravnega odbora tudi ne sme biti že član NS/UO v treh družbah."},{"q":"Kakšna je razlika med upravo in izvršnimi direktorji?","options":["Uprava vodi posle samostojno in na lastno odgovornost, odpokliče se le iz utemeljenih razlogov; izvršni direktorji upoštevajo navodila in omejitve ter so lahko odpoklicani brez posebnih razlogov","Izvršni direktorji so nadrejeni upravi","Uprava obstaja v enotirnem, izvršni direktorji v dvotirnem sistemu","Razlike ni"],"correct":0,"explanation":"Uprava (dvotirni): samostojno, na lastno odgovornost; odpoklic le iz utemeljenih razlogov. Izvršni direktorji (enotirni): vodijo tekoče posle po navodilih skupščine, statuta, upravnega odbora in poslovnika; odpoklic brez posebnih razlogov; če je izvršni direktor hkrati član UO, po odpoklicu ostane član UO. UO nanje lahko prenese: vodenje tekočih poslov, prijave registru, poslovne knjige, sestavo letnega poročila.","more":"Upravni odbor: najmanj 3 člani, voli jih skupščina (odpoklic s 3/4 oddanih glasov), vsaj en predstavnik delavcev (svet delavcev). Predsednik UO (razen pri malih d.d.) ne sme biti izvršni direktor; pri javnih d.d. mora biti vsaj en član UO izvršni direktor."},{"q":"Kaj je razrešnica?","options":["Odpoved člana uprave","Sklep, s katerim skupščina potrdi in odobri delo organov vodenja ali nadzora v poslovnem letu","Odpoklic nadzornega sveta","Razveljavitev statuta"],"correct":1,"explanation":"Z razrešnico skupščina potrdi in odobri delo organov vodenja/nadzora - izraz zadovoljstva. Nepodelitev razrešnice še NE pomeni nezaupnice posameznemu članu."},{"q":"Kakšna je razlika med holdingom in koncernom?","options":["Holding: matična družba samo obvladuje (owna) druge družbe brez lastne dejavnosti; koncern: matična družba ima poleg obvladovanja tudi svojo dejavnost","Holding je osebna, koncern kapitalska družba","Koncern je prepovedan","Holding je vedno v državni lasti"],"correct":0,"explanation":"Holding: mati ne opravlja lastne dejavnosti, samo obvladuje hčerinske družbe. Koncern: mati ima tudi svojo dejavnost. Pravo povezanih družb ureja razmerja, da mati ne bi preveč obvladovala hčerinskih družb (pogosto tudi davčni razlogi)."},{"q":"D.d. ima OK 100.000 EUR, razdeljen na 10.000 kosovnih delnic. Kolikšen je pripadajoči znesek ene delnice in koliko glasov ima delničar s 500 delnicami?","options":["10 EUR; 500 glasov","100 EUR; 50 glasov","1 EUR; 5.000 glasov","10 EUR; 50 glasov"],"correct":0,"explanation":"Pripadajoči znesek = OK / število delnic = 100.000 / 10.000 = 10 EUR. Temeljno pravilo: ena delnica, en glas - 500 delnic = 500 glasov. Statut lahko določi omejitev glasov (npr. največ X % - a ne samo za enega delničarja; v javnih d.d. omejitev ni mogoča)."}]},{"id":"pk2-pren","name":"Prenehanje družb, izvršba in intelektualna lastnina","questions":[{"q":"Kdaj gospodarska družba pravno preneha?","options":["Ko preneha poslovati","Z izbrisom iz sodnega registra","S sklepom skupščine o prenehanju","Z objavo v Uradnem listu"],"correct":1,"explanation":"Družbe nastanejo z vpisom in prenehajo z IZBRISOM iz sodnega registra. Razlog za prenehanje = vzrok; način prenehanja = postopek. Načini: likvidacija, skrajšani postopek, izbris brez likvidacije, prisilna likvidacija, stečaj."},{"q":"Kateri od naštetih NI razlog za prenehanje kapitalske družbe?","options":["Sklep skupščine z najmanj 3/4 večino zastopanega OK","Poslovodstvo ne deluje več kot 12 mesecev (velja za d.d.)","Zmanjšanje OK pod predpisani minimum","Enoletna izguba pri poslovanju"],"correct":3,"explanation":"Izguba NI razlog za prenehanje (družba lahko posluje z minusom). Razlogi: potek časa, sklep skupščine (3/4 zastopanega OK), nedelovanje poslovodstva nad 12 mesecev (samo d.d.), ničnost družbe, stečaj, sodna odločba, združitev, zmanjšanje OK pod minimum."},{"q":"Kakšen je cilj likvidacije in v čem se razlikuje od stečaja?","options":["Cilj likvidacije je razdelitev premoženja med družbenike (družba ima dovolj premoženja za poplačilo upnikov); cilj stečaja je najvišje poplačilo upnikov iz premoženja dolžnika","Likvidacija in stečaj sta sinonima","Stečaj vodi družba sama, likvidacijo sodišče","Likvidacija je mogoča samo pri osebnih družbah"],"correct":0,"explanation":"Likvidacija: prostovoljno prenehanje - družba poplača VSE upnike, preostalo premoženje se razdeli med družbenike (sorazmerno z deleži). Temeljni pogoj: dovolj premoženja; če ga ni, se začne stečaj. Stečaj: prisilno prenehanje zaradi finančne nesposobnosti - cilj je čim višje poplačilo upnikov."},{"q":"Kako poteka redna likvidacija?","options":["Sodišče imenuje stečajnega upravitelja","Skupščina sprejme sklep o prenehanju in začetku likvidacije (rok za prijavo terjatev vsaj 30 dni); k firmi se doda 'v likvidaciji'; vodi jo likvidacijski upravitelj (praviloma član poslovodstva)","AJPES izbriše družbo po uradni dolžnosti","Upniki prevzamejo vodenje družbe"],"correct":1,"explanation":"Redna likvidacija: sklep skupščine (razlogi + rok za prijavo terjatev, ne krajši od 30 dni), vpis v register, firma dobi dodatek 'v likvidaciji'. Likvidacijski upravitelj (eden ali več, praviloma poslovodstvo) poplača dolgove, pripravi poročilo in predlog razdelitve; preostanek se razdeli med družbenike. Prisilno likvidacijo pa uvede sodišče po uradni dolžnosti in imenuje upravitelja - namen je enak."},{"q":"Kaj je pogoj za prenehanje družbe po skrajšanem postopku?","options":["Družba mora imeti dobiček","Družba nima upnikov oziroma nerešenih razmerij s partnerji in delavci; družbeniki podajo izjavo (pri notarju) in nato eno leto po izbrisu odgovarjajo za morebitne obveznosti z vsem svojim premoženjem","Soglasje vseh upnikov","Družba mora poslovati manj kot 5 let"],"correct":1,"explanation":"Skrajšani postopek = prostovoljno prenehanje BREZ likvidacije: pogoj je, da družba nima upnikov/nerešenih razmerij. Skupščina sprejme sklep, poda predlog registrskemu organu. Varovalka za upnike: v enem letu po objavi izbrisa lahko uveljavijo terjatve do družbenikov, ki so podali izjavo - ti odgovarjajo z VSEM svojim premoženjem."},{"q":"Kdaj se družba izbriše iz sodnega registra brez likvidacije?","options":["Na predlog kateregakoli upnika","Če je prenehala poslovati, nima premoženja in je izpolnila obveznosti; če ne posluje na registriranem poslovnem naslovu; ali iz drugih zakonskih razlogov","Po desetih letih poslovanja","Če ima več kot tri upnike"],"correct":1,"explanation":"Izbris brez likvidacije (po uradni dolžnosti): (1) prenehala poslovati + ni premoženja + obveznosti izpolnjene, (2) ne posluje na poslovnem naslovu iz registra, (3) drugi zakonski razlogi. Namen: odvzem pravne osebnosti subjektom, ki ne poslujejo oziroma nimajo urejenih osnovnih pogojev."},{"q":"Kaj velja za izvršbo denarne terjatve po ZIZ?","options":["Upnik lahko izbere izvršilno sredstvo (nepremičnine, premičnine, računi, plača, vrednostni papirji); sodišče pazi, da dovoli sredstvo, ki je za dolžnika manj obremenjujoče","Sredstvo izvršbe vedno izbere dolžnik","Izvršba je mogoča samo na plačo","Sodišče vedno proda dolžnikovo nepremičnino"],"correct":0,"explanation":"Upnik prosto predlaga izvršilno sredstvo (prodaja nepremičnin, premičnin, sredstva na računih, plača, vrednostni papirji/deleži), sodišče pa po uradni dolžnosti pazi na manj obremenjujoče sredstvo (npr. če je nepremičnina edini dom). Velja načelo prioritete: upniki se poplačajo po vrstnem redu pridobitve pravice do poplačila. Pri nedenarnih terjatvah: sodni penali, prisilna izvršitev po izvršitelju."},{"q":"Kakšna je razlika med izvršbo na podlagi izvršilnega naslova in na podlagi verodostojne listine?","options":["Izvršilni naslov je sodba ali sklep sodišča; verodostojna listina je npr. račun ali menica - namenjena enostavni izterjavi nespornih terjatev","Verodostojna listina je močnejša od izvršilnega naslova","Izvršilni naslov izda upnik sam","Razlike ni"],"correct":0,"explanation":"Delitev po vrsti listine: izvršilni naslov (sodba, sklep sodišča, tudi izvršnica) proti verodostojni listini (račun, menica). Izvršba na podlagi verodostojne listine je mogoča SAMO za denarne terjatve; začne se na predlog upnika pri COVL (Centralni oddelek za verodostojno listino) pri Okrajnem sodišču v Ljubljani.","more":"Dolžnik lahko zoper sklep o izvršbi na podlagi verodostojne listine v 8 dneh vloži ugovor - z izvršilnega sodišča gre zadeva potem v pravdo. Insolventnost = dolgoročna nesposobnost poravnavanja obveznosti (trenutna plačilna nesposobnost še ni insolventnost)."},{"q":"Kdo je lahko avtor avtorskega dela?","options":["Fizična ali pravna oseba","Samo fizična oseba, ki delo ustvari; pravna oseba je lahko le nosilec avtorskih pravic","Samo registrirani umetniki","Vsak, ki delo objavi"],"correct":1,"explanation":"Avtor je lahko SAMO fizična oseba (delo nastane z ustvarjalnostjo). Domneva: za avtorja velja tisti, čigar ime je navedeno na običajen način, dokler se ne dokaže nasprotno. Več avtorjev = soavtorstvo. Ureditev: ZASP (in ZKUASP); najpomembnejši mednarodni vir je Bernska konvencija."},{"q":"Kateri so elementi generalne klavzule avtorskega dela po ZASP?","options":["Individualna intelektualna stvaritev človeka, s področja književnosti, znanosti in umetnosti, ki je na kakršenkoli način izražena","Registracija, objava in plačilo takse","Novost, inventivnost in industrijska uporabnost","Pisna oblika in notarska overitev"],"correct":0,"explanation":"Trije elementi: (1) individualna intelektualna stvaritev človeka, (2) s področja književnosti, znanosti ali umetnosti, (3) izraženost navzven (zaznavna s človeškim čutom). Avtorska pravica nastane s samo stvaritvijo - brez registracije! Izvedena dela (prevodi, priredbe) so avtorska dela, a je potrebno dovoljenje avtorja izvirnika.","wrong":{"2":"Novost in industrijska uporabnost sta pogoja za PATENT, ne za avtorsko delo."}},{"type":"match","q":"Poveži moralno avtorsko pravico z vsebino.","pairs":[{"term":"Pravica priznanja avtorstva","def":"Avtor odloči o navedbi svojega avtorstva; kršitev = plagiat"},{"term":"Pravica prve objave","def":"Avtor odloči, kdaj in kako bo delo prvič objavljeno"},{"term":"Pravica do spoštovanja dela","def":"Upre se skazitvi in posegom, ki bi okrnili njegovo osebnost"},{"term":"Pravica skesanja","def":"Preklic upravičenja imetniku materialne pravice iz resnih moralnih razlogov, s povrnitvijo škode"}],"explanation":"Moralne avtorske pravice varujejo duhovne in osebne vezi avtorja z delom. Prenašajo se lahko SAMO z dedovanjem (materialne in druge pravice pa s pisnimi pogodbami)."},{"q":"Koliko časa traja avtorska pravica?","options":["20 let od stvaritve","Za časa avtorjevega življenja in 70 let po njegovi smrti","50 let od objave","Neomejeno"],"correct":1,"explanation":"Avtorska pravica traja avtorjevo življenje + 70 let po smrti. Pri soavtorjih od smrti zadnjega; pri neznanem avtorju/filmu od objave. Če delo v 70 letih od stvaritve ni objavljeno, pravica preneha. Temeljno načelo materialnih pravic: in dubio pro auctore (v dvomu v prid avtorju)."},{"q":"Kaj je sledna pravica?","options":["Pravica avtorja prepovedati nadaljnjo prodajo dela","Pravica avtorja, da je ob prodaji izvirnika obveščen in prejme nadomestilo 3 % od maloprodajne cene; ni se ji mogoče odpovedati, se pa deduje","Pravica slediti uporabi dela na internetu","Pravica do brezplačnega vstopa na razstave"],"correct":1,"explanation":"Sledna pravica (pravica zasledovanja) spada med DRUGE pravice avtorja (niso izključne): ob prodaji dela obvestilo + 3 % od maloprodajne cene. Ne more prepovedati prodaje, lahko zahteva provizijo. Druge pravice še: pravica dostopa in izročitve, javnega posojanja, do nadomestila za privatno reproduciranje."},{"q":"Kdaj je reproduciranje avtorskega dela prosto (brez dovoljenja in plačila)?","options":["Vedno za študijske namene","V največ treh primerkih za zasebno uporabo fizične osebe ali lastno uporabo arhivov, javnih knjižnic ter izobraževalnih in znanstvenih ustanov","Do desetih primerkov za podjetja","Nikoli"],"correct":1,"explanation":"Prosta uporaba: reproduciranje v največ 3 primerkih za zasebno uporabo fizične osebe ali lastno uporabo arhivov, knjižnic, izobraževalnih/znanstvenih ustanov. Cele knjige ni dovoljeno prosto reproducirati (razen če je razprodana že 2 leti). Zakonita licenca pa je ODPLAČNA uporaba po zakonu (čitanke in učbeniki, pregledi tiska) - posega le v pravico reproduciranja, avtorja in vir je treba navesti."},{"q":"Delavec v okviru delovnega razmerja ustvari avtorsko delo. Kdo ima materialne pravice?","options":["Delavec v celoti","Materialne in druge pravice se prenesejo na delodajalca za 10 let, razen če je s pogodbo določeno drugače","Delodajalec trajno","Država"],"correct":1,"explanation":"Delo iz delovnega razmerja: materialne in druge avtorske pravice preidejo na delodajalca za 10 let (če pogodba ne določa drugače). Prenos pravic sicer: samo materialne in druge (moralne le z dedovanjem), s pisnimi pogodbami; na avtorsko pravico ni mogoče seči s prisilno izvršbo."},{"q":"Kaj je patent?","options":["Pravica, ki jo država podeli izumitelju, da za omejen čas (20 let) drugim prepove gospodarsko uporabo izuma - kot nadomestilo za razkritje izuma","Trajna pravica do blagovne znamke","Dokazilo o lastništvu podjetja","Zaščita imena podjetja"],"correct":0,"explanation":"Patent varuje izum (rešitev tehničnega problema - izdelek ali postopek); mora biti industrijsko uporaben. Traja 20 let od prijave (izjemoma 25: vojno/izredno stanje ali izdelki, ki potrebujejo oblastno dovoljenje). Po poteku je izum v javni domeni. Prijava pri Uradu RS za intelektualno lastnino; patent velja samo na ozemlju države, ki ga je podelila.","more":"Patent lahko preneha prej: odpoved nosilca, prenehanje nosilca, ničnost, neplačevanje taks. Razlika od poslovne skrivnosti: patent je JAVNO razkrit, poslovna skrivnost ravno ne."},{"q":"Kakšna je razlika med modelom in vzorcem?","options":["Model varuje novo vidno zunanjo obliko izdelka (3D), vzorec novo sliko ali risbo, prenosljivo na izdelek (2D) - vse ostalo je enako","Model je za stroje, vzorec za tekstil","Model traja 20 let, vzorec neomejeno","Vzorec je mednarodni model"],"correct":0,"explanation":"Model = nova vidna zunanja oblika industrijskega izdelka (3D); vzorec = nova vidna slika/risba, prenosljiva na izdelek (2D). Pogoji: vidnost, uporabnost v industriji, novost (ožja kot pri patentu, omejena na Slovenijo). Ne morejo biti zavarovani: fotografska in kartografska dela, tehnični načrti in skice."},{"q":"Kaj velja za blagovno oziroma storitveno znamko?","options":["Traja 20 let brez podaljšanja","Varuje znak za razlikovanje blaga/storitev; traja 10 let in se lahko poljubno podaljšuje po 10 let; ob 5-letni neuporabi jo Urad lahko razveljavi","Nastane avtomatično z uporabo znaka","Varuje izum"],"correct":1,"explanation":"Znamka zavaruje znak (slika, beseda, risba, kombinacija barv...) za razlikovanje blaga/storitev; imetnik sme uporabljati (R). Traja 10 let + neomejena podaljšanja po 10 let; ob 5 letih neuporabe možna razveljavitev. Sloveče znamke pozna tudi potrošnik, ki jih ne kupuje (Coca-Cola, Nike, Aspirin). Postopek je formalen - vloga pri uradu."},{"q":"Kateri znak bi bil zavrnjen pri registraciji znamke?","options":["Domišljijski znak 'Zvezdolet' za kolesa","Znak 'mleko' za mleko (označuje le vrsto blaga) ali znak, podoben že zavarovanemu (npr. 'Uho' ob obstoječem 'Oho')","Kombinacija barv","Beseda v mrtvem jeziku"],"correct":1,"explanation":"Razlogi za zavrnitev: znaki brez razlikovalnosti ('night club' za igrala je sicer neprimeren za razlikovanje), zgolj opisni znaki ('mleko' za mleko - za avto pa bi šlo!), običajne oznake vrste ('piano' za kitaro), zavajajoči ('Columbia' za kenijsko kavo), istovetni ali podobni že zavarovanim (Oho/Uho, Martini/Martin, Lanol/Lanoll), uradni znaki, grbi in zastave (brez dovoljenja). Podoba/ime osebe le z dovoljenjem (umrli: zakonec, otroci, starši; zgodovinske osebe: ministrstvo za notranje zadeve)."},{"q":"Kaj velja za označbo geografskega porekla?","options":["Je individualna pravica enega proizvajalca s trajanjem 10 let","Je kolektivna pravica - uporabljajo jo lahko vsi proizvajalci z območja; trajanje ni časovno omejeno in je ni treba podaljševati","Velja samo za vina","Podeli jo Evropska komisija za 5 let"],"correct":1,"explanation":"Označba porekla zavaruje geografsko ime proizvodov, katerih lastnosti so odvisne od kraja (podnebje, tla, ustaljeni postopki). Je KOLEKTIVNA pravica (vsi proizvajalci z območja; drugi je ne smejo uporabljati), časovno neomejena, brez podaljševanja. Zahtevo vloži državni organ, občina, lokalna skupnost ali zbornica."},{"q":"Kaj je prednostna pravica pri prijavi pravic industrijske lastnine?","options":["Pravica prvega kupca izdelka","Od datuma pravilne prijave ima prijavitelj prednost pred vsakomer, ki enako stvaritev prijavi kasneje; rok uveljavljanja: 12 mesecev za izum, 6 mesecev za model in znamko","Pravica do znižane takse","Prednost domačih prijaviteljev pred tujimi"],"correct":1,"explanation":"Prednostna pravica teče od prejema pravilne prijave. Roki: izum 12 mesecev, model in znamka 6 mesecev. Prijava vsebuje: podatke o prijavitelju in pravici, zahtevek (varstvo zajema samo, kar je v zahtevku!), opis, stanje tehnike, novost, skico/fotografijo; prijava znamke še znak in seznam proizvodov/storitev."},{"q":"Družba je v hudih finančnih težavah in premoženje ne zadošča za poplačilo upnikov. Kateri postopek je pravilen?","options":["Redna likvidacija","Stečaj - ker premoženje ne zadošča za poplačilo obveznosti; vodi ga stečajni upravitelj, ki ga določi sodišče","Prenehanje po skrajšanem postopku","Izbris brez likvidacije"],"correct":1,"explanation":"Likvidacija zahteva dovolj premoženja za poplačilo VSEH upnikov; če ga ni, se začne stečaj. Likvidacijskega upravitelja določijo družbeniki (po navadi direktor), stečajnega pa sodišče. Skrajšani postopek zahteva, da družba sploh nima upnikov."}]}],"notes":"<h2>Pravo · 2. kolokvij · povzetek snovi</h2>\n<div class=\"note-card\">\n<h3>1. Korporacijsko pravo - splošno</h3>\n<ul>\n<li>Ustava: svobodna gospodarska pobuda; zakon določa pogoje; ne proti javni koristi. Vir: <b>ZGD-1</b>. <b>Gospodarska družba</b> = pravna oseba, ki na trgu samostojno opravlja pridobitno dejavnost; pravna osebnost + poslovna sposobnost z vpisom v sodni register (+ zakoniti zastopnik).</li>\n<li>Družbeniki <b>niso lastniki niti upniki</b> - imajo korporacijska upravičenja (premoženjska + upravljavska). Oblike (numerus clausus): osebne (d.n.o., k.d.) / kapitalske (d.o.o., d.d., k.d.d., SE); s.p. NI družba. Temeljna razlika: odgovornost družbenikov.</li>\n<li><b>Firma</b> = ime (dejavnost + oblika; osebne: imena družbenikov; kapitalske: fantazijski dodatek; slovenščina, izjeme za tuje izraze). <b>Sedež</b> = kraj (ne naslov!).</li>\n<li><b>OK</b>: trojna funkcija (delež, zagon, jamstvo); načeli zagotovitve in ohranitve. <b>Zastopanje</b>: d.n.o. vsak družbenik, k.d. komplementar, d.o.o. direktor, d.d. uprava/UO. Pooblastila: generalno/specialno; po zaposlitvi; trgovski potnik; <b>prokura</b> (vse razen nepremičnin; vpis v register; omejitve proti tretjim brez učinka).</li>\n<li><b>Spregled pravne osebnosti</b> (izjemoma, subsidiarno, samo za upnike): zloraba za prepovedan cilj, oškodovanje upnikov, mešanje premoženja, zmanjšanje premoženja ob (dolžnem) vedenju o nezmožnosti poplačila. Objektivni standard dobrega strokovnjaka.</li>\n<li><b>Poslovna skrivnost</b>: tajnost + tržna vrednost + razumni ukrepi (pisno, NDA). <b>Konkurenčna prepoved</b> po ZGD-1: družbeniki d.n.o., komplementarji, družbeniki in poslovodje d.o.o., člani uprave/UO/NS d.d., prokuristi; sankcija odškodnina. Delovnopravna: med razmerjem; klavzula max 2 leti po prenehanju.</li>\n<li><b>Sodni register</b>: vodijo okrožna sodišča, objavlja AJPES. Načela: obvezni vpis, javnost, zaupanje, publiciteta. Vpis <b>konstitutiven</b> (ustanovitev, sprememba pogodbe) / <b>deklaratoren</b> (direktor, izbris). SPOT = vstopne točke. Posli izven dejavnosti: veljavni + prekršek.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>2. S.p. in osebne družbe</h3>\n<ul>\n<li><b>S.p.</b>: fizična oseba; vpis v PRS (AJPES, brezplačno, SPOT); brez min. OK; odgovarja z vsem premoženjem; 8 dni → davčni register, DDV, ZZZS. Obrtnik: licenca obrtne zbornice; svobodni poklici. Enostavno knjigovodstvo: < 3 delavci, prihodki < 50k, aktiva < 25k. Firma: dejavnost + ime in priimek + s.p. Normirani s.p.: 80 % normiranih stroškov. <b>Preoblikovanje v d.o.o.</b>: univerzalno pravno nasledstvo; za stare dolgove odgovarja subsidiarno + solidarno z vsem premoženjem.</li>\n<li><b>D.n.o.</b>: 2+ oseb, vsi odgovarjajo solidarno in subsidiarno z vsem premoženjem (kogentno navzven!); družbena pogodba (notarski zapis / overjeni podpisi) + vpis. Notranja razmerja dispozitivna. Dobiček: 5 % kapitalskega deleža, ostalo po enakih delih. Konkurenčna prepoved; vpogled v knjige; vstop novega: soglasje vseh. Prenehanje: potek, sklep, stečaj, smrt/odpoved (razen po pogodbi), sodna odločba, < 2 družbenika (1 leto).</li>\n<li><b>K.d.</b>: komplementar (vodi, zastopa, odgovarja z vsem) + komanditist (kapital; odgovarja do nevplačanega vložka; ni v firmi; ne zastopa - razen prokura/pooblastilo). Dobiček komanditista se pripisuje deležu do višine vložka. <b>Dvojna družba</b>: vsi komplementarji so kapitalske družbe.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>3. D.o.o.</h3>\n<ul>\n<li>1-50 družbenikov; OK ≥ 7.500 EUR, vložek ≥ 50 EUR; pred vpisom ≥ 1/4 vsakega vložka (skupaj ≥ 7.500), stvarni vložki v celoti (cenilec > 100k; znanje/veze ne štejejo). Brez oprostitve in pobota; kaducitetni postopek. Pogodba: notarski zapis ali obrazec; sprememba 3/4 (vpis konstitutiven!). Hibrid: pogodbena svoboda + omejena odgovornost.</li>\n<li><b>Premoženjske pravice</b>: dobiček (pogojno: dobiček + sklep skupščine; sorazmerno; izključitev ni mogoča), likvidacijska masa (po upnikih + 6 mesecev), prednost pri povečanju OK in nakupu deleža. Prodaja tretjim: obvestilo + 1 mesec; vinkulacija; pridobitelj: prijava poslovodji.</li>\n<li><b>Upravljavske</b>: glas / 50 EUR vložka; skupščina 1x letno (priporočeno pismo, 25 dni); sklepi z večino oddanih; izstop (pogodba ali tožba iz utemeljenih razlogov; izplačilo v 3 letih); izključitev (pogodba ali tožba). Dolžnosti: vplačilo vložka + ohranjanje OK (izplačila le iz bilančnega dobička ali ob zmanjšanju OK; prikrita izplačila prepovedana).</li>\n<li>Organa: <b>skupščina + poslovodja</b> (NS opcijski). Poslovodja: vodi na lastno odgovornost, odpoklic KADARKOLI, vpis deklaratoren. Lastni delež; enoosebna d.o.o.: akt o ustanovitvi, varščina, knjiga sklepov. Omejitev: 1 d.o.o. / 3 mesece.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>4. Delniška družba</h3>\n<ul>\n<li>OK ≥ 25.000 EUR; ≥ 1/3 v denarju; pred vpisom ≥ 25 % emisijskega zneska (stvarni vložki v celoti). <b>Statut - statutarna strogost</b> (le kar zakon izrecno dovoljuje). Vložki se ne vračajo in ne obrestujejo (trajnost kapitala); izplača se le bilančni dobiček.</li>\n<li><b>Delnica</b>: alikvotni del OK + skupek korporacijskih pravic + vrednostni papir. Nominalne (≥ 1 EUR) / kosovne (OK / št. delnic; v Slo prevladujejo). Emisijska ≥ nominalna; tržna poljubna. NVP - vpis v centralni register KDD. Vinkulacija: imenske, statut ob ustanovitvi; javne d.d. ne.</li>\n<li>Pravice: dividenda (dobiček + sklep skupščine), prednostni vpis novih delnic, likvidacijski delež (upniki absolutno prej); glasovanje (1 delnica = 1 glas; omejitve možne, ne za posameznika; javne d.d. ne), informacije, izpodbijanje sklepov. <b>Prednostne delnice</b> (max 1/2): kumulativne / participativne; lahko brez glasu (ob neizplačilu ga pridobijo). <b>Lastne delnice</b>: izvirna pridobitev prepovedana, > 10 % odsvojiti v 3 letih, brez pravic.</li>\n<li>Ustanovitev: simultana / sukcesivna (prospekt); faze: predinkorporacijska, organiziranje, inkorporiranje. <b>Dvotirni sistem</b>: skupščina + NS + uprava (NS imenuje upravo, max 6 let; odpoklic le iz utemeljenih razlogov; poročanje 1x letno). NS: ≥ 3, delničarski + delavski predstavniki, ne pri dobičku. <b>Enotirni</b>: skupščina + upravni odbor (+ izvršni direktorji - odpoklic brez razlogov; javne d.d. obvezno). Skupščina: sklic 30 dni (AJPES/dnevnik), notar potrjuje sklepe, navadna večina; razrešnica.</li>\n<li><b>Holding</b> (mati samo obvladuje) / <b>koncern</b> (mati ima tudi svojo dejavnost).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>5. Prenehanje družb in izvršba</h3>\n<ul>\n<li><b>Razlogi</b> (kapitalske): potek časa, sklep skupščine (3/4 zastopanega OK), poslovodstvo ne deluje > 12 mesecev (d.d.), ničnost, stečaj, sodna odločba, združitev, OK pod minimum. <b>Načini</b>: likvidacija, skrajšani postopek, izbris brez likvidacije, prisilna likvidacija, stečaj.</li>\n<li><b>Likvidacija</b>: dovolj premoženja; sklep (terjatve ≥ 30 dni), firma 'v likvidaciji', likvidacijski upravitelj (družbeniki/direktor); cilj: razdelitev preostanka družbenikom. <b>Stečaj</b>: premoženje ne zadošča; stečajni upravitelj (sodišče); cilj: max poplačilo upnikov. <b>Skrajšani postopek</b>: brez upnikov; izjava pri notarju; družbeniki 1 leto odgovarjajo z vsem premoženjem. <b>Prisilna likvidacija</b>: sodišče po uradni dolžnosti.</li>\n<li><b>Izvršba</b> (ZIZ): denarne (sredstva: nepremičnine, premičnine, računi, plača, papirji; sodišče izbere manj obremenjujoče; načelo prioritete) / nedenarne (penali, izvršitelj). Podlaga: izvršilni naslov (sodba, izvršnica) / verodostojna listina (račun, menica; samo denarne; COVL pri Okrajnem sodišču v Ljubljani; ugovor 8 dni). Insolventnost = dolgoročna nesposobnost.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>6. Intelektualna lastnina</h3>\n<ul>\n<li><b>Avtorsko pravo</b> (ZASP; Bernska konvencija): delo = individualna intelektualna stvaritev človeka (književnost, znanost, umetnost), izražena navzven; brez registracije. Avtor = samo fizična oseba. <b>Moralne pravice</b>: priznanje avtorstva (plagiat!), prva objava, spoštovanje dela, skesanje - prenos le z dedovanjem. <b>Materialne</b>: in dubio pro auctore; prenos pisno. <b>Druge</b>: sledna (3 %), dostop, javno posojanje, nadomestilo. Omejitve: zakonita licenca (odplačno: učbeniki, pregledi tiska), prosta uporaba (3 primerki zasebno/knjižnice). Trajanje: življenje + 70 let. Delovno razmerje: na delodajalca za 10 let. <b>Sorodne pravice</b>: izvajalci.</li>\n<li><b>Industrijska lastnina</b> (ZIL-1): izum → <b>patent</b> (20 let, izjemoma 25; industrijska uporabnost; javno razkritje; velja v državi podelitve); oblika telesa → <b>model</b> (3D) / slika, risba → <b>vzorec</b> (2D); znak → <b>znamka</b> (10 let + podaljševanja; 5 let neuporabe → razveljavitev; zavrnitve: opisni, zavajajoči, podobni znaki...); geografsko ime → <b>označba porekla</b> (kolektivna, neomejena). Prijava: Urad RS za intelektualno lastnino; prednostna pravica: 12 mesecev (izum), 6 mesecev (model, znamka). <b>Poslovna skrivnost</b> ni patent - ni javna.</li>\n</ul>\n</div>"},{"id":"izpit","name":"Izpit","type":"izpit","decks":[],"flashcards":[{"id":"fc-pravo-uvod","name":"Pravoznanstvo in EU","cards":[{"front":"Tri sestavine pravne norme","back":"Hipoteza (okoliščine) → dispozicija (zapoved/prepoved/dovoljenje) → sankcija (posledice kršitve)."},{"front":"Veljavnost državnih predpisov","back":"15. dan po objavi v Uradnem listu RS (uredbe EU: 20. dan po objavi v UL EU)."},{"front":"Kolizijska pravila (brez derogacijske klavzule)","back":"Višji razveljavi nižjega, mlajši starejšega, specialnejši splošnejšega."},{"front":"Pogoji dopustne retroaktivnosti","back":"Samo posamezne določbe + javna korist + brez posega v pridobljene pravice."},{"front":"Sprememba Ustave RS","back":"Državni zbor z 2/3 večino VSEH glasov = 60 glasov."},{"front":"Sodni sistem RS","back":"44 okrajnih, 11 okrožnih (1. stopnja), 4 višja, vrhovno; ustavno sodišče je ločen organ (9 sodnikov, izvoli DZ)."},{"front":"Trije pritožbeni razlogi","back":"Napačno/nepopolno dejansko stanje, bistvena kršitev postopka, napačna uporaba materialnega predpisa."},{"front":"Kvalificirana večina v Svetu EU","back":"Dvojna: ≥ 55 % držav članic + ≥ 65 % prebivalstva EU."},{"front":"Nezaupnica Evropski komisiji","back":"2/3 navzočih poslancev + absolutna večina vseh; odstopi CELA Komisija."},{"front":"Uredba proti direktivi","back":"Uredba: v celoti zavezujoča, neposredna. Direktiva: zavezuje glede cilja, potreben prenos v nacionalni red."},{"front":"Neposredna uporabnost direktive","back":"Posameznik proti državi + rok za implementacijo potekel + jasna in konkretna pravila."},{"front":"Izključne pristojnosti EU","back":"Carinska unija, skupna trgovinska politika, konkurenca. (DČ: dedno, družinsko, kazensko pravo.)"}]},{"id":"fc-pravo-stvarno-oblig","name":"Stvarno in obligacijsko pravo","cards":[{"front":"Stvarne pravice (SPZ)","back":"Lastninska, zastavna, služnost, stavbna pravica, stvarno breme. Posest NI pravica."},{"front":"Priposestvovanje","back":"Dobroverna lastniška posest: 3 leta premičnine, 10 let nepremičnine."},{"front":"Solastnina proti skupni lastnini","back":"Solastnina: določeni deleži (redno upravljanje > 1/2, ostalo vsi). Skupna: deleži nedoločeni, solidarna odgovornost."},{"front":"Hipoteka","back":"Neposestna zastavna pravica na nepremičnini; vpis v ZK; delno plačilo je ne zmanjša; komisorni dogovor ničen."},{"front":"Tožbe za varstvo lastnine","back":"Lastninska (vrnitev), publicijanska (dobroverni posestnik), negatorna (vznemirjanje)."},{"front":"Sposobnosti (starost)","back":"Pravna: rojstvo. Poslovna: 18 let (delna 15). Kazenska odgovornost: 14 let."},{"front":"Predpostavke veljavnosti pogodbe","back":"Sposobnost strank, soglasje volj, predmet (možen, dopusten, določljiv), dopustna podlaga, oblika (če predpisana)."},{"front":"Ničnost proti izpodbojnosti","back":"Ničnost: absolutna (ustava, prisilni predpisi, morala), brez učinkov. Izpodbojnost: relativna (zmota, grožnja), učinkuje do izpodbitja."},{"front":"Pravila o ari","back":"Kriv dajalec → izgubi aro. Kriv prejemnik → vrne dvojno aro. Ob izpolnitvi se vračuna ali vrne."},{"front":"Pogoji pobota","back":"Vzajemnost, istovrstnost, zapadlost, iztožljivost, likvidnost + izjava volje."},{"front":"Višja sila proti spremenjenim okoliščinam","back":"Višja sila: izpolnitev fizično nemogoča (naravne nesreče). Spremenjene okoliščine: mogoča, a ekonomsko nesmiselna (covid, vojna)."},{"front":"Roki za grajanje napak (prodajna pogodba)","back":"Očitne: 8 dni (gospodarske: nemudoma). Skrite: 8 dni od odkritja. Podjemna: skrite 1 mesec."},{"front":"Izvršnica","back":"Samo gospodarski subjekti/javni organi, dobava blaga/storitev; izvršilni naslov, neprenosljiva; poplačilo brez sodne poti (ZPreZP-1)."}]},{"id":"fc-pravo-korp","name":"Korporacijsko pravo","cards":[{"front":"Zakoniti zastopniki družb","back":"d.n.o.: vsak družbenik; k.d.: komplementar; d.o.o.: direktor; d.d.: uprava/upravni odbor."},{"front":"Prokura","back":"Vse posle RAZEN odsvojitve/obremenitve nepremičnin; vpis v register; omejitve proti tretjim brez učinka."},{"front":"Spregled pravne osebnosti (pogoji)","back":"Zloraba za prepovedan cilj, oškodovanje upnikov, mešanje premoženja, zmanjšanje premoženja ob (dolžnem) vedenju."},{"front":"Načela sodnega registra","back":"Obvezni vpis, javnost, zaupanje, publiciteta. Vpis: konstitutiven (ustanovitev) / deklaratoren (direktor)."},{"front":"Minimalni osnovni kapital","back":"d.o.o.: 7.500 EUR (vložek ≥ 50 EUR). d.d.: 25.000 EUR (≥ 1/3 denar). s.p. in osebne družbe: ni predpisan."},{"front":"Odgovornost v d.n.o.","back":"Vsi družbeniki: subsidiarno (najprej družba) in solidarno (vsak za celoten dolg) z vsem premoženjem; navzven kogentno."},{"front":"Komanditist","back":"Ne vodi in ne zastopa; odgovarja le do nevplačanega vložka; ni v firmi; dobiček se pripisuje deležu do višine vložka."},{"front":"Delitev dobička d.n.o./k.d. (zakonsko)","back":"Najprej 5 % kapitalskega deleža vsakemu, preostanek: d.n.o. po enakih delih, k.d. po razmerju deležev."},{"front":"Vplačilo pred vpisom","back":"d.o.o.: ≥ 1/4 vsakega vložka, skupaj ≥ 7.500 EUR. d.d.: ≥ 25 % emisijskega zneska. Stvarni vložki vedno v celoti."},{"front":"Sprememba družbene pogodbe d.o.o.","back":"3/4 glasov družbenikov; vpis v register je KONSTITUTIVEN. (Glas = 50 EUR vložka.)"},{"front":"Odpoklic poslovodstva","back":"Poslovodja d.o.o.: kadarkoli. Uprava d.d.: le iz utemeljenih razlogov (NS). Izvršni direktorji: brez razlogov."},{"front":"Trojni pomen delnice","back":"Alikvotni del OK + skupek korporacijskih pravic + vrednostni papir (NVP, vpis pri KDD)."},{"front":"Vrednosti delnice","back":"Emisijska ≥ nominalna (oz. pripadajoči znesek); tržna poljubna. Kosovna: OK / število delnic."},{"front":"Prednostne delnice","back":"Max 1/2; dodatne premoženjske prednosti, ne pri glasovanju; kumulativne (dividenda za vsako leto z dobičkom) / participativne (prednostna + preostanek)."},{"front":"Lastne delnice","back":"Izvirna pridobitev prepovedana; nad 10 % odsvojiti v 3 letih; iz njih družba nima pravic."},{"front":"Dvotirni proti enotirnemu sistemu","back":"Dvotirni: skupščina + NS + uprava. Enotirni: skupščina + upravni odbor (+ izvršni direktorji; javna d.d. obvezno)."},{"front":"Sklic skupščine","back":"d.o.o.: priporočeno pismo, 25 dni. d.d.: objava (AJPES/dnevnik), 30 dni; sklepe potrjuje notar."},{"front":"Holding proti koncernu","back":"Holding: mati samo obvladuje hčerinske družbe. Koncern: mati ima tudi lastno dejavnost."}]},{"id":"fc-pravo-pren-il","name":"Prenehanje in intelektualna lastnina","cards":[{"front":"Likvidacija proti stečaju","back":"Likvidacija: dovolj premoženja, cilj razdelitev družbenikom, upravitelja določijo družbeniki. Stečaj: premoženje ne zadošča, cilj poplačilo upnikov, upravitelja določi sodišče."},{"front":"Skrajšani postopek prenehanja","back":"Brez upnikov; izjava pri notarju; družbeniki še 1 leto odgovarjajo z vsem premoženjem."},{"front":"Izvršba - podlagi","back":"Izvršilni naslov (sodba, izvršnica) ali verodostojna listina (račun, menica - samo denarne terjatve, COVL, ugovor 8 dni)."},{"front":"Avtorsko delo (generalna klavzula)","back":"Individualna intelektualna stvaritev človeka s področja književnosti, znanosti, umetnosti, izražena navzven. Brez registracije; avtor le fizična oseba."},{"front":"Moralne avtorske pravice","back":"Priznanje avtorstva, prva objava, spoštovanje dela, skesanje. Prenos samo z dedovanjem."},{"front":"Trajanje avtorske pravice","back":"Življenje avtorja + 70 let po smrti. Delovno razmerje: materialne pravice delodajalcu za 10 let."},{"front":"Patent","back":"Izum (izdelek/postopek), industrijsko uporaben; 20 let (izjemoma 25); javno razkritje; velja v državi podelitve."},{"front":"Model proti vzorcu","back":"Model: nova vidna zunanja oblika izdelka (3D). Vzorec: nova slika/risba za prenos na izdelek (2D)."},{"front":"Znamka","back":"Znak za razlikovanje blaga/storitev; 10 let + neomejena podaljševanja; 5 let neuporabe → razveljavitev."},{"front":"Označba geografskega porekla","back":"Kolektivna pravica proizvajalcev z območja; časovno neomejena, brez podaljševanja."},{"front":"Prednostna pravica (prijava)","back":"Izum: 12 mesecev; model in znamka: 6 mesecev od prijave."},{"front":"Poslovna skrivnost (3 zahteve)","back":"Ni splošno znana + tržna vrednost + razumni ukrepi za tajnost (pisno, NDA). Ni patent - ni javna."}]}]}]},{"id":"mikro","name":"Mikroekonomija 1","tier":"A","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[]},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[]},{"id":"izpit","name":"Izpit","type":"izpit","decks":[]}]},{"id":"mng","name":"Temelji managementa","tier":"A","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[]},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[]},{"id":"izpit","name":"Izpit","type":"izpit","decks":[]}]},{"id":"uvod","name":"Uvod v poslovanje","tier":"A","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[{"id":"gospodarjenje","name":"Gospodarjenje in poslovne prvine","questions":[{"q":"Kaj je gospodarjenje?","options":["Spontano zadovoljevanje potreb brez načrta","Zavestna človekova dejavnost z namenom zmanjšati omejenost dobrin, s katerimi zadovoljujemo potrebe","Izključno proizvodnja dobrin v tovarnah","Trošenje dobrin, ki jih je na razpolago v izobilju"],"correct":1,"explanation":"Gospodarjenje je zavestna (ne spontana) dejavnost; trije elementi: zavestna dejavnost, potrebe ljudi, omejenost dobrin."},{"q":"Kaj so proste dobrine?","options":["Dobrine, ki jih je na razpolago manj, kot znašajo potrebe","Dobrine, ki imajo ceno, pri kateri se izenačita ponudba in povpraševanje","Dobrine, ki jih je na razpolago več, kot znašajo potrebe po njih (tudi pri ceni 0 je ponudba večja od povpraševanja)","Vse storitve"],"correct":2,"explanation":"Proste dobrine: ponudba > povpraševanje tudi pri ceni 0. Ekonomske (redke) dobrine so tiste, ki jih je manj, kot znašajo potrebe, zato imajo ceno."},{"q":"Kaj je temeljni ekonomski problem in temeljni razlog za gospodarjenje?","options":["Previsoke cene","Omejenost (redkost) dobrin, s katerimi zadovoljujemo potrebe","Pomanjkanje delovne sile","Inflacija"],"correct":1,"explanation":"Omejenost dobrin je temeljni ekonomski problem; rešitev je proizvodnja dobrin, kar je temeljni razlog za gospodarjenje."},{"q":"Katere so štiri prvine poslovnega procesa (poslovne prvine)?","options":["Kapital, delo, zemlja, podjetništvo","Delovna sredstva, predmeti dela, delo, storitve","Nabava, proizvodnja, prodaja, financiranje","Prihodki, odhodki, sredstva, obveznosti"],"correct":1,"explanation":"Produkcijski faktorji / poslovne prvine: delovna sredstva, predmeti dela, delo, storitve. Tudi te so omejene dobrine."},{"q":"Po čem se delovna sredstva ločijo od predmetov dela?","options":["Delovna sredstva se potrošijo v enem procesu, predmeti dela pa sodelujejo v več procesih","Delovna sredstva se ne spremenijo v poslovni učinek, sodelujejo v več procesih in se postopoma obrabljajo; predmeti dela se spremenijo v učinek in potrošijo v enem procesu","Med njima ni razlike","Predmeti dela ohranijo svojo obliko, delovna sredstva pa ne"],"correct":1,"explanation":"Delovna sredstva (stroji, oprema) ohranijo obliko, sodelujejo v več procesih, se postopoma obrabljajo. Predmeti dela (surovine, material) se spremenijo v učinek in potrošijo v enem procesu."},{"q":"Kaj pravi temeljno načelo gospodarjenja (minimaks načelo)?","options":["Vedno proizvajaj čim več, ne glede na stroške","Dani rezultat doseči z minimalno porabo sredstev ALI z danimi sredstvi doseči maksimalni rezultat","Minimiziraj prodajno ceno in maksimiraj količino","Zmanjšaj število zaposlenih na minimum"],"correct":1,"explanation":"Minimaks (minimax): (1) dani rezultat z minimalno porabo vložkov ali (2) z danimi vložki maksimalni rezultat. V praksi iščemo optimum pri danih omejitvah."},{"q":"Kaj pomeni, da podjetje ustvarja dodano vrednost?","options":["Da poveča število zaposlenih","Da nastane nekaj novega, bolj uporabnega, kar ima za kupca višjo vrednost kot vsota vrednosti vhodnih prvin","Da dvigne prodajno ceno brez sprememb izdelka","Da zniža stroške materiala"],"correct":1,"explanation":"Primer: iz lesa, žebljev in dela nastane miza, vredna več kot vsota delov. To je dodana vrednost."},{"q":"Kaj je angažiranje poslovnih prvin?","options":["Uporaba (trošenje) prvin v procesu ustvarjanja učinkov","Pridobitev (zaposlitev) poslovnih prvin; predpogoj za trošenje – v vrednostnem smislu premoženje podjetja","Prodaja poslovnih učinkov kupcem","Odpis vrednosti delovnih sredstev"],"correct":1,"explanation":"Angažiranje = pridobitev prvin (predpogoj trošenja). V naturalnem smislu: sredstva v podjetju; v vrednostnem: premoženje = sredstva v aktivi bilance stanja."},{"q":"Kaj je trošenje in kako je povezano s stroški?","options":["Trošenje je pridobivanje prvin; strošek je njihova nabavna cena","Trošenje je uporaba prvin v procesu; v vrednostnem smislu so to stroški (strošek = potrošek × cena prvine)","Trošenje in stroški nista povezana","Trošenje je izplačilo denarja dobaviteljem"],"correct":1,"explanation":"Trošenje je uporaba prvin (nastajajo učinki). Naturalno = potroški (fizične enote), vrednostno = stroški. C = ΣQi·Pi."},{"q":"Kako zapišemo strošek prek potroška in cene?","options":["C = Q / P","C = Q + P","Strošek (C) = potrošek (Q) × cena prvine (P), skupaj C = Σ Qi·Pi","C = P − Q"],"correct":2,"explanation":"Strošek je v denarju izražen potrošek: C = Q·P, za več prvin C = Σ Qi·Pi."},{"q":"Kje se pokaže rezultat trošenja v enem letu?","options":["V bilanci stanja","V izkazu poslovnega izida","V izkazu denarnih tokov","Nikjer, ker se ne evidentira"],"correct":1,"explanation":"Stroški (rezultat trošenja) se v enem letu pokažejo v izkazu poslovnega izida; premoženje (angažiranje) pa v bilanci stanja."}]},{"id":"sredstva","name":"Sredstva podjetja in amortizacija","questions":[{"q":"Na kaj delimo poslovna sredstva podjetja?","options":["Na kapital in dolg","Na osnovna sredstva, obratna sredstva in finančne naložbe","Na prihodke in odhodke","Na fiksna in variabilna sredstva"],"correct":1,"explanation":"Poslovna sredstva = osnovna sredstva (OS) + obratna sredstva (ObS: denar, zaloge, terjatve do kupcev) + finančne naložbe (FN). SRS delijo na dolgoročna in kratkoročna."},{"q":"Kaj so osnovna sredstva (OS)?","options":["Kratkoročno vezana sredstva, ki se obrnejo večkrat na leto","Dolgoročno vezan del premoženja, ki svojo vrednost preko amortizacije postopoma prenaša na poslovne učinke","Denar in terjatve do kupcev","Isto kot delovna sredstva"],"correct":1,"explanation":"OS so dolgoročno vezana (zemljišča, zgradbe, oprema, večletni nasadi, osnovna čreda, dolg. neopredmetena sredstva), vrednost prenašajo preko amortizacije. OS ≠ delovna sredstva."},{"q":"Po kateri vrednosti so osnovna sredstva izkazana v bilanci stanja?","options":["Po nabavni vrednosti","Po odpisani vrednosti","Po neodpisani (sedanji) vrednosti","Po reprodukcijski vrednosti"],"correct":2,"explanation":"V bilanci stanja so OS izkazana po neodpisani (preostali, sedanji) vrednosti = nabavna − odpisana (kumulativa amortizacije)."},{"q":"Kaj vključuje nabavna vrednost osnovnega sredstva?","options":["Samo ceno po fakturi","Nabavno ceno in vse stroške, da je OS sposobno delovati (carina, transport, montaža, izobraževanje delavcev)","Nabavno ceno minus amortizacijo","Le stroške montaže"],"correct":1,"explanation":"Nabavna vrednost = nabavna cena + vsi potrebni stroški, da OS lahko deluje (transport, carina, montaža, usposabljanje)."},{"q":"Kaj je integralna zmogljivost osnovnega sredstva?","options":["Število proizvodov na časovno enoto (intenzivna)","Število časovnih enot delovanja (ekstenzivna)","Zmnožek intenzivne in ekstenzivne zmogljivosti (proizvodi v nekem obdobju)","Delež izkoriščenosti naprave"],"correct":2,"explanation":"Intenzivna = proizvodi/čas. enoto; ekstenzivna = število čas. enot delovanja; integralna = njun zmnožek (proizvodi v obdobju)."},{"q":"Kaj so obratna sredstva (ObS)?","options":["Zemljišča, zgradbe in oprema","Denar, vse vrste zalog in terjatve do kupcev; običajno se obrnejo večkrat na leto","Dolgoročne finančne naložbe","Patenti in licence"],"correct":1,"explanation":"ObS: denar, zaloge (material, nedokončana proizvodnja, gotovi proizvodi), terjatve do kupcev. So širši pojem od predmetov dela in se v letu večkrat obrnejo."},{"q":"Kako izračunamo koeficient obračanja obratnih sredstev?","options":["Povprečno stanje ObS / stroškovna vrednost proizvodnje","Stroškovna vrednost proizvodnje / povprečno stanje ObS","Število dni v obdobju / dnevi vezave","Prihodki − odhodki"],"correct":1,"explanation":"KO = stroškovna vrednost proizvodnje / povprečno stanje ObS. Dnevi vezave = 360 / KO (leto = 360 dni)."},{"q":"Kako izračunamo potrebni obseg obratnih sredstev?","options":["Načrtovana stroškovna vrednost proizvodnje × koeficient obračanja","Načrtovana stroškovna vrednost proizvodnje / koeficient obračanja ObS","Koeficient obračanja / dnevi vezave","Prihodki / odhodki"],"correct":1,"explanation":"Potrebni obseg ObS = načrtovana stroškovna vrednost proizvodnje / KO. Večji obseg poslovanja ali počasnejše obračanje → večja potreba po virih."},{"q":"Kateri so primeri finančnih naložb?","options":["Zaloge materiala in terjatve do kupcev","Posojila, delnice in deleži drugih podjetij, obveznice, bančni depoziti","Stroji in oprema","Plače zaposlenih"],"correct":1,"explanation":"FN: posojila, delnice/deleži drugih podjetij, obveznice, depoziti. Po SRS so kratkoročne FN med kratkoročnimi, dolgoročne med dolgoročnimi sredstvi."},{"q":"Kaj je amortizacija?","options":["Strošek predmetov dela","Strošek delovnega sredstva – postopno razporejanje vrednosti DS na obdobja koristnosti","Odplačilo posojila","Povečanje vrednosti osnovnega sredstva"],"correct":1,"explanation":"Amortizacija = strošek delovnega sredstva. Amortiziranje razporeja vrednost DS na dobo koristnosti; osnovni namen je zagotoviti enostavno reprodukcijo (zamenjavo DS v enakem obsegu)."},{"q":"Katera sredstva se NE amortizirajo?","options":["Oprema","Zgradbe","Zemljišča","Neopredmetena sredstva s končno dobo koristnosti"],"correct":2,"explanation":"Amortiziramo opredmetena OS in neopredmetena sredstva s končno dobo koristnosti. Zemljišča se ne amortizirajo."},{"q":"Glede na katero dobo koristnosti amortiziramo, če se fizična in ekonomska razlikujeta?","options":["Glede na daljšo dobo","Glede na krajšo dobo","Vedno glede na fizično","Povprečje obeh"],"correct":1,"explanation":"Amortiziramo glede na krajšo od obeh dob koristnosti (fizična = sposobnost delovati; ekonomska = kdaj DS ekonomsko zastari)."},{"q":"Po čem se ločijo časovne in funkcionalne metode amortiziranja?","options":["Časovne temeljijo na uporabi (endogeni dejavniki), funkcionalne na času (eksogeni)","Časovne temeljijo na eksogenih dejavnikih (čas); funkcionalne na endogenih (uporaba/obseg proizvodnje)","Med njima ni razlike","Funkcionalne se uporabljajo samo za zemljišča"],"correct":1,"explanation":"Časovne: vrednost pada zaradi eksogenih dejavnikov (čas); letna Am fiksna, Am/izdelek pada. Funkcionalne (npr. proizvodna): endogeni dejavniki (uporaba); Am/izdelek fiksna, letna Am odvisna od obsega."}]},{"id":"stroski-kalkulacije","name":"Stroški in kalkulacije","questions":[{"q":"Katere so štiri naravne vrste stroškov (glede na prvino, ki jih povzroča)?","options":["Fiksni, variabilni, neposredni, posredni","Stroški delovnih sredstev, stroški dela, stroški predmetov dela, stroški storitev","Materialni, nematerialni, denarni, nedenarni","Proizvodni, prodajni, upravni, nabavni"],"correct":1,"explanation":"Naravne vrste stroškov (po prvini): stroški delovnih sredstev (amortizacija), stroški dela, stroški predmetov dela (material), stroški storitev."},{"q":"Katere metode vrednotenja porabe materiala SRS NE dovoljuje?","options":["FIFO","Metoda povprečnih cen","LIFO","Vse so dovoljene"],"correct":2,"explanation":"FIFO (prve nabavne cene) in povprečne cene so dovoljene; LIFO (zadnje nabavne cene) po SRS ni dovoljena."},{"q":"Kaj upošteva metoda FIFO?","options":["Da gredo iz skladišča najprej predmeti, ki so prišli zadnji","Da gredo iz skladišča najprej predmeti, ki so vanj prišli prvi (prve nabavne cene)","Povprečno ceno vseh zalog","Najvišjo nabavno ceno"],"correct":1,"explanation":"FIFO (first in, first out): najprej se porabijo najstarejši predmeti dela – uporabimo prve (najzgodnejše) nabavne cene."},{"q":"Kaj so neposredni (direktni) stroški?","options":["Stroški, ki so skupni več stroškovnim objektom in jih ne moremo natančno pripisati","Stroški, za katere natančno vemo, kateri stroškovni objekt jih je povzročil in koliko","Samo stroški amortizacije","Stroški, ki niso odvisni od obsega poslovanja"],"correct":1,"explanation":"Neposredni stroški: točno vemo, kateri stroškovni objekt jih je povzročil in v kakšnem znesku. Posredni (splošni) so skupni za več objektov in jih razporejamo s ključi."},{"q":"Kaj je stroškovni nosilec?","options":["Prostorsko in funkcionalno zaokrožena celota z nosilcem odgovornosti","Poslovni učinek – proizvod ali storitev","Oddelek v podjetju","Vodja stroškovnega mesta"],"correct":1,"explanation":"Stroškovni nosilec = poslovni učinek (proizvod/storitev). Stroškovno mesto = zaokrožena celota z vodjo. Stroškovni objekt = karkoli, za kar ločeno ugotavljamo stroške."},{"q":"Kako izračunamo ključ za razporejanje splošnih stroškov?","options":["osnova za razporejanje / splošni stroški × 100","splošni stroški / osnova za razporejanje × 100","splošni stroški − osnova","neposredni stroški / splošni stroški"],"correct":1,"explanation":"Ključ = splošni stroški / osnova za razporejanje × 100. Bistvena je izbira pravilne osnove (čim bolj povezane z vrsto splošnih stroškov)."},{"q":"Kaj nam pove lastna cena (LC)?","options":["Prodajno ceno izdelka","Koliko znašajo stroški ene enote poslovnega učinka","Maržo trgovca","Dobiček na enoto"],"correct":1,"explanation":"LC pove stroške ene enote poslovnega učinka. Je podlaga za postavljanje prodajnih cen in presojanje donosnosti."},{"q":"Zakaj razporejanje stroškov v sodobnih podjetjih poteka dvostopenjsko?","options":["Ker to zahteva zakon","Da lažje spremljamo stroške (kje so kritične točke) in da pravilneje razporedimo stroške na stroškovne nosilce","Da povečamo splošne stroške","Da se izognemo amortizaciji"],"correct":1,"explanation":"1. stopnja: s podjetja na stroškovna mesta; 2. stopnja: s stroškovnih mest na nosilce (proizvode). Namen: boljši nadzor in pravilnejše razporejanje."},{"q":"Katera od naštetih NI metoda kalkuliranja?","options":["Kalkulacija z dodatki","Enostavna delitvena kalkulacija","Kalkulacija z ekvivalentnimi števili","Kalkulacija z vsoto letnih števil"],"correct":3,"explanation":"Metode kalkulacij: enostavna delitvena, z ekvivalentnimi števili, z dodatki, vezanih proizvodov, po spremenljivih stroških. \"Vsota letnih števil\" je metoda amortiziranja, ne kalkulacije."},{"q":"Za kakšno proizvodnjo je primerna kalkulacija z dodatki?","options":["Za homogeno proizvodnjo enega samega proizvoda","Za heterogeno proizvodnjo (različne vrste proizvodov), kjer splošne stroške razdelimo s ključi","Samo za storitvene dejavnosti","Samo kadar ni splošnih stroškov"],"correct":1,"explanation":"Kalkulacija z dodatki je primerna za heterogeno proizvodnjo: splošne (posredne) stroške obdobja razdelimo na proizvode s pomočjo ključev, prištejemo neposredne, dobimo LC."},{"q":"Kaj sestavlja strukturo lastne cene?","options":["Samo neposredni material in delo","Neposredni material, neposredno delo, (neposredna) amortizacija, proizvodna režija ter upravno-prodajno-nabavna režija","Marža in rabat","Prihodki minus odhodki"],"correct":1,"explanation":"LC = nep. stroški materiala + nep. stroški dela + amortizacija (če je neposredna) + splošni stroški proizvajanja (proizvodna režija) + splošni stroški uprave/prodaje/nabave."}]},{"id":"uspeh-ekon-produkt","name":"Uspeh, ekonomičnost, produktivnost","questions":[{"q":"Kaj je uspeh poslovanja (poslovni izid)?","options":["Razlika med prejemki in izdatki","Razlika med prihodki in odhodki (dobiček, če prihodki > odhodki; izguba, če prihodki < odhodki)","Vsota vseh stroškov","Denarno stanje na računu"],"correct":1,"explanation":"Poslovni izid = prihodki − odhodki. Prihodki > odhodki → dobiček; prihodki < odhodki → izguba. Prihodki = vrednost prodanih količin, odhodki = stroški prodanih količin."},{"q":"Kakšna je razlika med stroški in odhodki?","options":["Sta sinonima","Stroški se nanašajo na proizvedene učinke, odhodki pa na prodane poslovne učinke","Odhodki se nanašajo na proizvedene, stroški na prodane učinke","Odhodki so odlivi denarja"],"correct":1,"explanation":"Stroški = ovrednoteni potroški, nanašajo se na proizvedeno. Odhodki = stroški prodanih učinkov. Izdatki so odlivi denarja (vplivajo le na plačilno sposobnost)."},{"q":"Če so proizvedene količine večje od prodanih (zaloge naraščajo), kakšno je razmerje med stroški in odhodki?","options":["Stroški < odhodki","Stroški = odhodki","Stroški > odhodki","Razmerja ni mogoče določiti"],"correct":2,"explanation":"Proizvedeno > prodano (zaloge rastejo) → stroški > odhodki. Če proizvedeno < prodano (zaloge padajo) → stroški < odhodki."},{"q":"Kaj je primer stroška, ki ni izdatek?","options":["Nakup zemljišča","Izplačilo plač","Amortizacija","Nabava materiala z gotovino"],"correct":2,"explanation":"Amortizacija je strošek, a ni izdatek (ni odliva denarja). Nasprotno: nakup zemljišča je izdatek, ki ni strošek."},{"q":"Kaj pomeni likvidnost podjetja?","options":["Da je podjetje dolgoročno sposobno poravnavati obveznosti","Da lahko podjetje poravna zapadle obveznosti v nekem trenutku (denarna sredstva zadoščajo za obveznosti, ki ta dan zapadejo)","Da ima podjetje dobiček","Da so obveznosti večje od premoženja"],"correct":1,"explanation":"Likvidnost = sposobnost poravnati zapadle obveznosti v danem trenutku. Solventnost = likvidnost na dolgi rok. Podjetje ima lahko dobiček in je hkrati nelikvidno."},{"q":"Kako izračunamo ekonomičnost poslovanja?","options":["E = odhodki / prihodki","E = Q / C (količina učinkov na enoto stroškov); v praksi E = prihodki / odhodki","E = dobiček / kapital","E = Q / L"],"correct":1,"explanation":"Ekonomičnost E = Q/C (učinki na stroške), v praksi prihodki/odhodki. E > 1 = dobiček, E < 1 = izguba, E = 1 = na pragu."},{"q":"Zakaj je pri izračunu produktivnosti dela nujno upoštevati stalne (ne tekoče) cene?","options":["Ker tekoče cene vključujejo DDV","Ker inflacija (rast prodajnih cen) sicer navidezno poveča produktivnost, čeprav se je dejansko zmanjšala","Ker stalne cene vključujejo dobiček","Ker to zahteva zakon"],"correct":1,"explanation":"Ob uporabi tekočih cen inflacija zamegli sliko: prihodki na zaposlenega rastejo tudi ob padcu fizičnega obsega. Zato heterogeno proizvodnjo vrednotimo po stalnih cenah."},{"q":"Kaj meri produktivnost dela?","options":["Razmerje med prihodki in odhodki","Razmerje med proizvedeno količino učinkov (Q) in vloženim delovnim časom (L): PL = Q/L","Razmerje med dobičkom in kapitalom","Razmerje med sredstvi in obveznostmi"],"correct":1,"explanation":"Produktivnost dela PL = Q/L. Poveča se, če Q na enoto časa raste ali če se čas za enoto učinka zmanjša."},{"q":"Kaj meri rentabilnost kapitala (ROE)?","options":["Dobiček / povprečna sredstva","Dobiček / povprečni kapital","Prihodki / odhodki","Q / L"],"correct":1,"explanation":"ROE (return on equity) = dobiček / povprečni kapital. ROA (return on assets) = dobiček / povprečna sredstva."},{"q":"Če je indeks produktivnosti I(2019/2018) = 84, kaj to pomeni?","options":["Produktivnost je bila v 2019 za 84 % višja kot v 2018","Produktivnost se je v 2019 zmanjšala za 16 % glede na 2018","Produktivnost je ostala enaka","Produktivnost se je povečala za 16 %"],"correct":1,"explanation":"Indeks 84 pomeni 84 % vrednosti iz baznega leta → zmanjšanje za 16 %. (100 = enako, 120 = +20 %.)"},{"q":"Kakšna je razlika med učinkovitostjo (efficiency) in uspešnostjo (effectiveness)?","options":["Učinkovitost = delati prave stvari; uspešnost = delati stvari pravilno","Učinkovitost = delati stvari pravilno; uspešnost = delati prave stvari","Sta sinonima","Učinkovitost se meri le z dobičkom"],"correct":1,"explanation":"Učinkovitost (efficiency) = delati stvari pravilno; uspešnost (effectiveness) = delati prave stvari. (Pilot: odličen pristanek na napačnem letališču = učinkovit, a ne uspešen.)"},{"q":"Po kateri metodi Slovenija ugotavlja prihodke?","options":["Po metodi plačane realizacije","Po metodi fakturirane (zaračunane) realizacije – prihodek ob izstavitvi računa, nastane terjatev do kupca","Šele ob prejemu denarja","Po metodi povprečnih cen"],"correct":1,"explanation":"V Sloveniji velja metoda fakturirane realizacije: prihodek se evidentira ob izstavitvi računa; razliko med fakturirano in plačano realizacijo predstavljajo terjatve do kupcev."}]},{"id":"racunske","name":"Računske naloge","calc":true,"questions":[{"q":"Podjetje ima premoženje 400 mio EUR, stopnja kapitalizacije je 70 %. Koliko znašajo dolgovi?","options":["280 mio EUR","120 mio EUR","400 mio EUR","70 mio EUR"],"correct":1,"explanation":"Kapital = 0,7 × 400 = 280 mio. Dolg = 400 − 280 = 120 mio EUR (oz. 0,3 × 400)."},{"q":"Prihodki so 540 mio EUR, povprečno stanje obratnih sredstev 90 mio EUR. Koliko znaša koeficient obračanja ObS?","options":["4","5","6","0,17"],"correct":2,"explanation":"KO = 540 / 90 = 6. ObS se v letu obrnejo 6-krat; dnevi vezave = 360 / 6 = 60 dni."},{"q":"KO obratnih sredstev je 6, načrtovani prihodki leta 2 so 660 mio EUR, lastni viri za financiranje ObS znašajo 100 mio EUR. Za koliko se mora podjetje zadolžiti?","options":["110 mio EUR","10 mio EUR","60 mio EUR","0 – zadolževanje ni potrebno"],"correct":1,"explanation":"Potrebni obseg ObS = 660 / 6 = 110 mio. Dolg = 110 − 100 = 10 mio EUR."},{"q":"Amortizacijska osnova je 50.000 EUR, doba koristnosti 5 let. Koliko znaša letna amortizacija po linearni metodi?","options":["25.000 EUR","10.000 EUR","5.000 EUR","50.000 EUR"],"correct":1,"explanation":"Linearna metoda: Am = osnova / n = 50.000 / 5 = 10.000 EUR na leto (vsako leto enako)."},{"q":"Računalniška oprema: osnova 9.000 EUR, doba koristnosti 3 leta, metoda z vsoto letnih števil. Koliko znaša amortizacija v 1. letu?","options":["3.000 EUR","4.500 EUR","1.500 EUR","9.000 EUR"],"correct":1,"explanation":"Vsota letnih števil = n(n+1)/2 = 3·4/2 = 6. Leto 1: stopnja 3/6 × 9.000 = 4.500 EUR (nato 3.000 in 1.500)."},{"q":"Proizvodna oprema: osnova 40.000 EUR, doba 5 let, metoda padajoče osnove. Koliko znaša amortizacija v 1. letu?","options":["8.000 EUR","16.000 EUR","40.000 EUR","9.600 EUR"],"correct":1,"explanation":"Stopnja = 100 %/n × 2 = 100/5 × 2 = 40 %. Leto 1: 40 % × 40.000 = 16.000 EUR (osnova je vsakokratna neodpisana vrednost)."},{"q":"Oprema (nab. vrednost 90.000 EUR) bo v dobi koristnosti proizvedla 1.200.000 proizvodov; v 1. letu 250.000. Amortizacija 1. leta po proizvodni metodi?","options":["22.500 EUR","18.750 EUR","0,075 EUR","90.000 EUR"],"correct":1,"explanation":"Am/enoto = 90.000 / 1.200.000 = 0,075 EUR. Leto 1: 0,075 × 250.000 = 18.750 EUR."},{"q":"Zaloga: 300 kg po 5 €, 500 kg po 7 €, 400 kg po 10 €, 800 kg po 12 €. V proizvodnjo gre 1.100 kg. Kolikšni so stroški po metodi FIFO?","options":["12.600 EUR","8.000 EUR","10.230 EUR","18.600 EUR"],"correct":1,"explanation":"FIFO porabi najprej najstarejše: 300×5 + 500×7 + 300×10 = 1.500 + 3.500 + 3.000 = 8.000 EUR. (LIFO bi bil 12.600, povprečna cena 10.230.)"},{"q":"Ista zaloga (skupaj 18.600 € za 2.000 kg), poraba 1.100 kg. Kolikšni so stroški po metodi povprečnih cen?","options":["8.000 EUR","10.230 EUR","12.600 EUR","9.300 EUR"],"correct":1,"explanation":"Povprečna cena = 18.600 / 2.000 = 9,30 €/kg. Stroški = 1.100 × 9,30 = 10.230 EUR."},{"q":"Trgovec nabavi monitor za 100 EUR (nabavna cena) in doda 20 % maržo. Kolikšna je maloprodajna cena?","options":["80 EUR","120 EUR","96 EUR","125 EUR"],"correct":1,"explanation":"Marža je % od nabavne cene: MPC = 100 + 0,2 × 100 = 120 EUR."},{"q":"Maloprodajna cena je 120 EUR, trgovec dobi 20 % rabat. Po kakšni ceni je nabavil izdelek?","options":["144 EUR","100 EUR","96 EUR","24 EUR"],"correct":2,"explanation":"Rabat je % od prodajne cene: NC = 120 − 0,2 × 120 = 96 EUR. Za pokrivanje stroškov in dobiček mu ostane 24 EUR."},{"q":"Podjetje je proizvedlo 1.000 proizvodov po lastni ceni 5 EUR, prodalo pa 800 po ceni 6 EUR. Kolikšen je poslovni izid?","options":["Dobiček 1.000 EUR","Dobiček 800 EUR","Izguba 200 EUR","Dobiček 4.800 EUR"],"correct":1,"explanation":"Prihodki = 800 × 6 = 4.800; odhodki (stroški prodanih) = 800 × 5 = 4.000. Izid = 4.800 − 4.000 = 800 EUR dobička."}]}],"notes":"\n<h2>1 · Gospodarjenje in poslovne prvine</h2>\n<div class=\"note-card\">\n<h3>Temeljni pojmi</h3>\n<ul>\n<li><b>Gospodarjenje</b> = zavestna dejavnost za zmanjševanje omejenosti dobrin. Trije elementi: zavestna dejavnost, potrebe, omejenost dobrin.</li>\n<li><b>Proste dobrine</b>: ponudba > povpraševanje tudi pri ceni 0. <b>Ekonomske (redke)</b>: manj, kot znašajo potrebe → imajo ceno.</li>\n<li><b>Temeljni ekonomski problem</b> = omejenost dobrin → rešitev je proizvodnja → razlog za gospodarjenje.</li>\n<li><b>Minimaks načelo</b>: dani rezultat z minimalno porabo ALI z danimi vložki maksimalni rezultat (iščemo optimum).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Poslovne prvine, angažiranje, trošenje</h3>\n<ul>\n<li>4 prvine: <b>delovna sredstva</b> (ne spremenijo se v učinek, več procesov, obraba), <b>predmeti dela</b> (spremenijo se v učinek, en proces), <b>delo</b>, <b>storitve</b>.</li>\n<li><b>Angažiranje</b> = pridobitev prvin (vrednostno = premoženje = aktiva bilance stanja).</li>\n<li><b>Trošenje</b> = uporaba prvin; naturalno = potroški, vrednostno = <b>stroški</b>. Strošek C = Σ Qi·Pi. Pokaže se v izkazu poslovnega izida.</li>\n<li>Podjetje ustvarja <b>dodano vrednost</b> (nekaj bolj uporabnega, večje vrednosti kot vsota vhodov).</li>\n</ul>\n</div>\n\n<h2>2 · Sredstva podjetja in amortizacija</h2>\n<div class=\"note-card\">\n<h3>Poslovna sredstva</h3>\n<ul>\n<li>Delitev: <b>osnovna sredstva (OS)</b>, <b>obratna sredstva (ObS)</b>, <b>finančne naložbe (FN)</b>. SRS: dolgoročna / kratkoročna.</li>\n<li><b>OS</b>: dolgoročno vezana, vrednost prek amortizacije prenašajo na učinke. V bilanci po <b>neodpisani</b> vrednosti. Nabavna vrednost = cena + vsi stroški do delovanja. OS ≠ delovna sredstva.</li>\n<li>Zmogljivost: <b>intenzivna</b> (proizvodi/čas), <b>ekstenzivna</b> (čas delovanja), <b>integralna</b> (zmnožek).</li>\n<li><b>ObS</b>: denar, zaloge, terjatve do kupcev; obrnejo se večkrat na leto. <b>KO</b> = strošk. vrednost proizvodnje / povpr. stanje ObS; <b>dnevi vezave</b> = 360/KO; <b>potrebni obseg</b> = načrt. strošk. vrednost / KO.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Amortizacija</h3>\n<ul>\n<li>= strošek delovnega sredstva; namen: <b>enostavna reprodukcija</b>. Zemljišča se ne amortizirajo. Amortiziramo po <b>krajši</b> dobi koristnosti.</li>\n<li><b>Časovne metode</b> (eksogeni dejavniki, čas): linearna, padajoči zneski (vsota letnih števil, padajoča osnova), linearna s spremenjenimi stopnjami. Letna Am fiksna, Am/izdelek pada.</li>\n<li><b>Funkcionalne</b> (endogeni, uporaba): proizvodna. Am/izdelek fiksna, letna Am odvisna od obsega. <b>Kombinirane</b>: npr. linearno-proizvodna.</li>\n</ul>\n</div>\n\n<h2>3 · Stroški in kalkulacije</h2>\n<div class=\"note-card\">\n<h3>Vrste stroškov</h3>\n<ul>\n<li><b>4 naravne vrste</b> (po prvini): stroški delovnih sredstev (amortizacija), dela, predmetov dela (material), storitev.</li>\n<li>Vrednotenje materiala: <b>FIFO</b> (prve cene), <b>povprečne cene</b>; <b>LIFO ni dovoljen</b> po SRS.</li>\n<li><b>Neposredni</b> (direktni): vemo, kdo jih je povzročil in koliko. <b>Posredni/splošni</b>: skupni, razporejamo s <b>ključi</b>.</li>\n<li>Stroškovni <b>nosilec</b> = proizvod/storitev; <b>mesto</b> = zaokrožena celota z vodjo; <b>objekt</b> = karkoli, za kar ločeno merimo stroške.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Kalkulacije</h3>\n<ul>\n<li><b>Ključ</b> = splošni stroški / osnova × 100. Razporejanje dvostopenjsko (podjetje → mesta → nosilci).</li>\n<li><b>LC</b> = stroški ene enote učinka. Struktura: nep. material + nep. delo + amortizacija + proizvodna režija + upravno-prodajno-nabavna režija.</li>\n<li>Metode: enostavna delitvena, z ekvivalentnimi števili, <b>z dodatki</b> (heterogena proizvodnja), vezanih proizvodov, po spremenljivih stroških.</li>\n</ul>\n</div>\n\n<h2>4 · Uspeh, ekonomičnost, produktivnost</h2>\n<div class=\"note-card\">\n<h3>Uspeh in tokovi</h3>\n<ul>\n<li><b>Poslovni izid</b> = prihodki − odhodki (dobiček / izguba). Prihodki = vrednost prodanih količin, odhodki = stroški prodanih količin.</li>\n<li><b>Stroški</b> (proizvedeno) vs <b>odhodki</b> (prodano) vs <b>izdatki</b> (odliv denarja). Amortizacija = strošek, ki ni izdatek; nakup zemljišča = izdatek, ki ni strošek.</li>\n<li>Proizvedeno > prodano → stroški > odhodki (zaloge rastejo) in obratno.</li>\n<li><b>Likvidnost</b> = poravnava zapadlih obveznosti zdaj; <b>solventnost</b> = likvidnost na dolgi rok. SI: metoda <b>fakturirane realizacije</b>.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Kazalniki uspešnosti</h3>\n<ul>\n<li><b>Produktivnost dela</b> PL = Q/L. <b>Ekonomičnost</b> E = Q/C (v praksi prihodki/odhodki; E>1 dobiček). <b>Rentabilnost</b>: ROE = dobiček/kapital, ROA = dobiček/sredstva.</li>\n<li>Pri heterogeni proizvodnji vrednotimo po <b>stalnih cenah</b> (tekoče cene zaradi inflacije zavajajo). Indeks 84 = −16 %, 120 = +20 %.</li>\n<li><b>Učinkovitost</b> = delati stvari pravilno; <b>uspešnost</b> = delati prave stvari.</li>\n<li><b>Oblikovanje PC</b>: stroški plus (LC + pribitek), glede na povpraševanje (elastičnost), glede na konkurenco. Trgovina: <b>marža</b> (% od NC), <b>rabat</b> (% od PC, popust proizvajalca).</li>\n</ul>\n</div>\n","flashcards":[{"id":"uvp-k1-pojmi","name":"Pojmi in prvine","cards":[{"front":"Gospodarjenje","back":"Zavestna dejavnost za zmanjševanje omejenosti dobrin. Elementi: zavestna dejavnost, potrebe, omejenost dobrin."},{"front":"Proste vs ekonomske dobrine","back":"Proste: ponudba > povpraševanje tudi pri ceni 0. Ekonomske (redke): manj, kot znašajo potrebe → imajo ceno."},{"front":"Temeljni ekonomski problem","back":"Omejenost (redkost) dobrin. Rešitev = proizvodnja; je temeljni razlog za gospodarjenje."},{"front":"Minimaks (minimax) načelo","back":"Dani rezultat z minimalno porabo vložkov ALI z danimi vložki maksimalni rezultat. V praksi optimum."},{"front":"4 poslovne prvine","back":"Delovna sredstva, predmeti dela, delo, storitve."},{"front":"Delovna sredstva vs predmeti dela","back":"DS: ne spremenijo se v učinek, več procesov, postopna obraba, ohranijo obliko. PD: spremenijo se v učinek, potrošijo v enem procesu."},{"front":"Angažiranje","back":"Pridobitev (zaposlitev) prvin; predpogoj trošenja. Vrednostno = premoženje = aktiva bilance stanja."},{"front":"Trošenje in strošek","back":"Trošenje = uporaba prvin. Naturalno = potroški, vrednostno = stroški. C = Σ Qi·Pi."},{"front":"Dodana vrednost","back":"Nastane nekaj novega, bolj uporabnega, z višjo vrednostjo za kupca kot vsota vhodnih prvin."}]},{"id":"uvp-k1-sredstva","name":"Sredstva in amortizacija","cards":[{"front":"Delitev poslovnih sredstev","back":"Osnovna sredstva (OS), obratna sredstva (ObS), finančne naložbe (FN). SRS: dolgoročna / kratkoročna."},{"front":"Osnovna sredstva – vrednost v bilanci","back":"Izkazana po neodpisani (sedanji) vrednosti = nabavna − odpisana (kumulativa amortizacije)."},{"front":"Zmogljivost OS","back":"Intenzivna (proizvodi/čas. enoto), ekstenzivna (čas delovanja), integralna (zmnožek obeh)."},{"front":"Koeficient obračanja ObS","back":"KO = stroškovna vrednost proizvodnje / povprečno stanje ObS. Dnevi vezave = 360 / KO."},{"front":"Potrebni obseg ObS","back":"= načrtovana stroškovna vrednost proizvodnje / koeficient obračanja."},{"front":"Amortizacija – kaj in namen","back":"Strošek delovnega sredstva; namen = enostavna reprodukcija (zamenjava DS v enakem obsegu)."},{"front":"Katera sredstva se ne amortizirajo?","back":"Zemljišča. (Amortiziramo opredmetena OS in neopredmetena s končno dobo koristnosti; po krajši dobi.)"},{"front":"Časovne vs funkcionalne metode amortiziranja","back":"Časovne: eksogeni dejavniki (čas), letna Am fiksna. Funkcionalne (proizvodna): endogeni (uporaba), Am/izdelek fiksna."}]},{"id":"uvp-k1-stroski","name":"Stroški, kalkulacije, uspeh","cards":[{"front":"4 naravne vrste stroškov","back":"Stroški delovnih sredstev (amortizacija), dela, predmetov dela (material), storitev."},{"front":"FIFO / LIFO / povprečne cene","back":"FIFO = prve nabavne cene; povprečne = po povprečju; LIFO (zadnje cene) po SRS NI dovoljen."},{"front":"Neposredni vs posredni stroški","back":"Neposredni: vemo, kdo in koliko jih je povzročil. Posredni (splošni): skupni, razporejamo s ključi."},{"front":"Ključ za splošne stroške","back":"Ključ = splošni stroški / osnova za razporejanje × 100."},{"front":"Lastna cena – struktura","back":"Nep. material + nep. delo + amortizacija + proizvodna režija + upravno-prodajno-nabavna režija."},{"front":"Poslovni izid","back":"Prihodki − odhodki. Prihodki = vrednost prodanih količin; odhodki = stroški prodanih količin."},{"front":"Stroški vs odhodki vs izdatki","back":"Stroški = proizvedeno; odhodki = prodano; izdatki = odliv denarja. Amortizacija = strošek brez izdatka."},{"front":"Ekonomičnost / produktivnost / rentabilnost","back":"E = Q/C (prihodki/odhodki); PL = Q/L; ROE = dobiček/kapital, ROA = dobiček/sredstva."},{"front":"Marža vs rabat","back":"Marža = % od nabavne cene (določi trgovina). Rabat = % popust od prodajne cene (prizna proizvajalec)."}]}]},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[]},{"id":"izpit","name":"Izpit","type":"izpit","decks":[]}]},{"id":"mat","name":"Matematika za posl. in ekon. vede","tier":"C","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[]},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[]},{"id":"izpit","name":"Izpit","type":"izpit","decks":[]}]}]},{"id":"s2","name":"2. semester","subjects":[{"id":"makro","name":"Makroekonomija 1","tier":"A","parts":[{"id":"izpit","name":"Izpit","type":"izpit","decks":[{"id":"mk1","name":"Temelji in tržne pomanjkljivosti","questions":[{"q":"S čim se ukvarja makroekonomija (v nasprotju z mikroekonomijo)?","options":["Z individualno enoto, npr. posameznikom in podjetjem","Z agregatno ravnjo: agregatna potrošnja, investicije, raven cen","Samo z davčno politiko","Samo z borznimi indeksi"],"correct":1,"explanation":"Makroekonomija je usmerjena na agregatno raven; mikroekonomija proučuje individualne enote."},{"q":"Kdo je avtor teorije nevidne roke trga?","options":["John Maynard Keynes","Milton Friedman","Adam Smith","J. B. Say"],"correct":2,"explanation":"Nevidno roko je razvil Adam Smith: posameznik, ki sledi lastnim interesom, doseže najboljše za vse — odpove pri monopolu in onesnaževanju."},{"q":"Kaj opisuje pozitivna ekonomija?","options":["Kaj naj bi bilo (vrednostne sodbe)","Kako stvari so (analiza dejstev)","Samo etična vprašanja","Cilje javne politike"],"correct":1,"explanation":"Pozitivna ekonomija analizira »kot stvari so«; normativna se nanaša na »kaj naj bi bilo«."},{"q":"Kaj so oportunitetni stroški?","options":["Stroški surovin","Stroški izgubljene alternative","Fiksni stroški podjetja","Davčna obremenitev"],"correct":1,"explanation":"Oportunitetni strošek je strošek druge najboljše alternative, ki se ji odpovemo."},{"q":"Kaj meri Ginijev koeficient?","options":["Stopnjo inflacije","Neenakost porazdelitve dohodka (0 = enakost, 1 = neenakost)","Rast BDP","Stopnjo brezposelnosti"],"correct":1,"explanation":"Gini meri neenakost; 0 pomeni popolno enakost, 1 popolno neenakost. Grafično jo prikaže Lorenzova krivulja."},{"q":"Kaj ponazarja Okunovo »luknjičasto vedro«?","options":["Davčno utajo","Trade-off med enakostjo in učinkovitostjo","Multiplikator","Devizni tečaj"],"correct":1,"explanation":"Prerazdelitev k revnim zmanjša motivacijo za delo — del 'dolarja' uhaja skozi luknjo (izguba učinkovitosti)."}]},{"id":"mk2","name":"BDP in merjenje","questions":[{"q":"Kako je sestavljen BDP po izdatkovni metodi?","options":["C + I + G + NX","C + S + T","M × V","BDP − amortizacija"],"correct":0,"explanation":"BDP = potrošnja + investicije + državni izdatki + neto izvoz."},{"q":"Kako izračunamo neto domači proizvod (NDP)?","options":["BDP + amortizacija","BDP − amortizacija","BDP − neto izvoz","BDP × deflator"],"correct":1,"explanation":"NDP = BDP − amortizacija."},{"q":"Kaj je potencialni BDP?","options":["BDP po tekočih cenah","Maksimalna količina ob razumni stabilnosti cen","BDP minus uvoz","Dejanski BDP v recesiji"],"correct":1,"explanation":"Potencialni BDP je najvišja vzdržna raven outputa ob stabilnih cenah (pri LSUR)."},{"q":"Kaj meri indeks potrošnih cen (IPC)?","options":["Donosnost delnic","Strošek stalne košarice dobrin povprečnega potrošnika","Količino denarja v obtoku","Devizni tečaj"],"correct":1,"explanation":"IPC meri stroške stalne košarice dobrin, ki jih kupi povprečni potrošnik."},{"q":"Kdaj govorimo o recesiji?","options":["Ko BDP raste 2 trimesečji","Ko BDP upade v vsaj dveh trimesečjih","Ko inflacija pade pod 0","Ko se poveča izvoz"],"correct":1,"explanation":"Recesija je pot navzdol v ciklu — pogosto opredeljena kot padec BDP v vsaj dveh trimesečjih."},{"q":"Kako izračunamo neto naložbe?","options":["Bruto naložbe + amortizacija","Bruto naložbe − amortizacija","BDP − C","I + G"],"correct":1,"explanation":"Neto naložbe = bruto naložbe − amortizacija."}]},{"id":"mk3","name":"AD–AS, multiplikator, cikli","questions":[{"q":"Katere so štiri sestavine agregatnega povpraševanja (AD)?","options":["C, I, G, NX","Plače, obresti, rente, dobički","M1, M2, M3, M4","T, G, S, I"],"correct":0,"explanation":"AD = C + I + G + NX (potrošnja, naložbe, državni izdatki, neto izvoz)."},{"q":"Kakšna je dolgoročna krivulja agregatne ponudbe (AS)?","options":["Padajoča","Navpična","Vodoravna","Naraščajoča"],"correct":1,"explanation":"Dolgoročno je AS navpična, ker se vsi stroški prilagodijo; spremembe AD ne vplivajo na output."},{"q":"Kaj je stagflacija?","options":["Hkratna deflacija in rast","Upočasnjena rast skupaj z višjo inflacijo","Hitra rast z nizko inflacijo","Stabilne cene ob polni zaposlenosti"],"correct":1,"explanation":"Stagflacija je kombinacija upočasnjene gospodarske rasti in visoke inflacije (premik AS)."},{"q":"Čemu je enak investicijski multiplikator?","options":["MNP / MNV","1 / MNV oz. 1/(1−MNP)","MNV / MNP","1 / obrestna mera"],"correct":1,"explanation":"Investicijski multiplikator = 1/MNV = 1/(1−MNP)."},{"q":"Zakaj je davčni multiplikator nižji od multiplikatorja državnih izdatkov?","options":["Ker davki ne vplivajo na BDP","Ker se del dohodka prelije v varčevanje","Ker je MNP enak 1","Ker davki povečajo izvoz"],"correct":1,"explanation":"Ob spremembi davkov se del dohodka prelije v varčevanje, zato je učinek na BDP manjši."},{"q":"Kaj pravi paradoks varčevanja?","options":["Več varčevanja vedno pomeni več bogastva","Pretirano varčevanje zmanjša dohodek in na koncu tudi varčevanje","Varčevanje ne vpliva na AD","Varčevanje vedno dvigne obrestne mere"],"correct":1,"explanation":"Povečano varčevanje zniža AD in dohodek, zato se v končni fazi zmanjša tudi samo varčevanje."}]},{"id":"mk4","name":"Denar in monetarna politika","questions":[{"q":"Koliko funkcij ima denar po opredelitvi?","options":["3","4","5","6"],"correct":2,"explanation":"5 funkcij: menjalno sredstvo, plačilno sredstvo, merilec vrednosti, hranilec vrednosti, svetovni denar."},{"q":"Kaj vsebuje denarni agregat M1?","options":["Samo dolgoročne depozite","Gotovino (kovance, papirnati) in knjižni denar","Tuje valute","Delnice in obveznice"],"correct":1,"explanation":"M1 je transakcijski denar: kovanci, papirnati in knjižni denar."},{"q":"Od česa je odvisno špekulativno povpraševanje po denarju?","options":["Od dohodka (BDP)","Predvsem od obrestne mere (padajoče)","Od deviznega tečaja","Od stopnje brezposelnosti"],"correct":1,"explanation":"Špekulativno povpraševanje (LŠ) je odvisno od obrestne mere; ob višji obrestni meri pada (višji oportunitetni stroški gotovine)."},{"q":"Čemu je enak denarni multiplikator?","options":["1 / stopnja obveznih rezerv","Stopnja obveznih rezerv × 2","1 / MNV","M × V"],"correct":0,"explanation":"Denarni multiplikator je inverzna vrednost stopnje obveznih rezerv."},{"q":"Kaj stori centralna banka ob inflaciji?","options":["Ekspanzivno MP — poveča denar","Restriktivno MP — zmanjša denar, dvigne obrestne mere","Zniža obvezne rezerve","Kupuje vrednostne papirje"],"correct":1,"explanation":"Ob inflaciji CB izvaja restriktivno monetarno politiko: manj denarja, višje obrestne mere → nižji AD."},{"q":"Kako zapišemo kvantitativno teorijo denarja?","options":["M + V = P + Q","M × V = P × Q","M / V = P / Q","M − V = P − Q"],"correct":1,"explanation":"M·V = P·Q; obtočno hitrost V = nominalni BDP / M."}]},{"id":"mk5","name":"Javne finance in fiskalna politika","questions":[{"q":"Kateri davki omogočajo prevaljevanje?","options":["Neposredni (dohodnina, davek na dobiček)","Posredni (DDV, trošarine)","Nobeni","Samo progresivni"],"correct":1,"explanation":"Pri posrednih davkih plačanec in zavezanec nista nujno ista oseba — prevaljevanje je možno."},{"q":"Kaj velja za progresivni (napredujoč) davek?","options":["MDS = PDS","MDS > PDS","MDS < PDS","Davek je pavšalen"],"correct":1,"explanation":"Pri progresivnem davku (npr. dohodnina) je mejna davčna stopnja večja od povprečne."},{"q":"Kaj prikazuje Lafferjeva krivulja?","options":["Povezavo inflacije in brezposelnosti","Povezavo davčnih prihodkov in davčne stopnje (obrnjen U)","Krivuljo AD","Plačilno bilanco"],"correct":1,"explanation":"Lafferjeva krivulja ima obliko obrnjenega U; pri 0 % in 100 % davčni stopnji so prihodki 0."},{"q":"Kaj je učinek izrinjanja (crowding-out)?","options":["Deficit spodbudi naložbe","Strukturni deficit dvigne obrestne mere in izrine zasebne naložbe","Znižanje davkov poveča izvoz","Inflacija zniža BDP"],"correct":1,"explanation":"Strukturni proračunski primanjkljaj dvigne obrestne mere in izrine zasebne naložbe; v recesiji ne deluje."},{"q":"Kaj so avtomatski stabilizatorji?","options":["Ukrepi CB na odprtem trgu","Nadomestila za brezposelnost in progresivni davki, ki blažijo cikel","Carine in kvote","Devizne rezerve"],"correct":1,"explanation":"Samodejno zmanjšujejo nihanja dohodka — npr. nadomestila za brezposelnost in naraščajoči davki."},{"q":"Kdaj nastane proračunski deficit?","options":["T > G","T < G","T = G","ko ni javnega dolga"],"correct":1,"explanation":"Deficit (primanjkljaj) nastane, ko so prihodki manjši od izdatkov: T < G."}]},{"id":"mk6","name":"Odprto gospodarstvo in tečaji","questions":[{"q":"Čemu je enaka vsota vseh postavk plačilne bilance?","options":["BDP","Nič (tekoči + kapitalsko-finančni račun + stat. napaka = 0)","Neto izvozu","Deviznim rezervam"],"correct":1,"explanation":"Temeljno pravilo: tekoči račun + kapitalsko-finančni račun + statistična napaka = 0."},{"q":"Kaj vsebuje tekoči račun plačilne bilance?","options":["Patente in licence","Blago, storitve, dohodke in tekoče transferje","Samo devizne rezerve","Neposredne tuje naložbe"],"correct":1,"explanation":"Tekoči račun: trgovinska bilanca (blago), storitve, dohodki in tekoči transferji."},{"q":"Pri katerem režimu se uporabljata izraza devalvacija in revalvacija?","options":["Pri drsečem tečaju","Pri stalnem deviznem tečaju (uradna odločitev)","Pri nadzorovanem drsenju","Pri barter menjavi"],"correct":1,"explanation":"Devalvacija/revalvacija sta uradni spremembi pri stalnem tečaju; apreciacija/depreciacija pa nastopata pri drsečem (trg)."},{"q":"Kaj pravi teorija komparativne (primerjalne) prednosti?","options":["Država proizvaja vse dobrine sama","Država proizvaja, kjer ima relativno nižje stroške","Tečaji so vedno fiksni","Carine povečajo blaginjo"],"correct":1,"explanation":"Po komparativni prednosti se država specializira za dobrine, ki jih proizvaja po relativno nižjih stroških."},{"q":"Kaj je prohibitivna carina?","options":["Carina, ki rahlo zmanjša trgovino","Tako visoka carina, da prepreči ves uvoz","Kvota","Subvencija izvozu"],"correct":1,"explanation":"Prohibitivna carina je tako visoka, da dejansko prepreči vsak uvoz."},{"q":"Kaj pravi pariteta kupne moči (zakon ene cene)?","options":["Tečaji so neodvisni od inflacije","Tečaji sledijo razliki v inflaciji med državami","Cene so povsod enake v nominalnih zneskih","Devizne rezerve niso potrebne"],"correct":1,"explanation":"Tečaji težijo h gibanju skladno z relativnimi cenami; valute držav z višjo inflacijo praviloma depreciirajo."}]},{"id":"mk7","name":"Šole, brezposelnost, inflacija, rast","questions":[{"q":"Kaj zagovarja keynesianizem?","options":["Da naj se država ne vmešava","Uravnavanje AD prek fiskalne politike (davki, državni izdatki)","Da je inflacija samo denarni pojav","Da je ponudba vedno navpična"],"correct":1,"explanation":"Keynesianci zagovarjajo večjo vlogo države in uravnavanje agregatnega povpraševanja; cene/mezde so lepljive."},{"q":"Čigav je nauk, da je inflacija predvsem denarni pojav?","options":["Keynes","Monetarizem (Milton Friedman)","Adam Smith","J. B. Say"],"correct":1,"explanation":"Monetaristi (Friedman) trdijo, da inflacijo povzroča prehitra rast količine denarja."},{"q":"Kaj pravi Okunov zakon?","options":["Vsak +1 % inflacije zniža BDP za 2 %","~2 % padca BDP pod potencialom dvigne brezposelnost za ~1 odstotno točko","Davki ne vplivajo na BDP","Tečaji sledijo inflaciji"],"correct":1,"explanation":"Okunov zakon povezuje gibanje BDP in brezposelnosti: ~2 % zaostanka BDP ≈ +1 o.t. brezposelnosti."},{"q":"Katera brezposelnost nastane zaradi neusklajenosti ponudbe in povpraševanja po delu (npr. propad panoge)?","options":["Frikcijska","Strukturna","Ciklična","Prostovoljna"],"correct":1,"explanation":"Strukturna brezposelnost = neusklajenost ponudbe in povpraševanja (npr. propad jeklarske industrije)."},{"q":"Kaj prikazuje kratkoročna Phillipsova krivulja?","options":["Inverzno povezavo med inflacijo in brezposelnostjo","Povezavo BDP in obrestne mere","Krivuljo ponudbe denarja","Lafferjev učinek"],"correct":0,"explanation":"Kratkoročno obstaja trade-off: nižja brezposelnost ↔ višja inflacija. Dolgoročno je krivulja navpična (LSUR/NAIRU)."},{"q":"Kaj predstavlja IS krivulja v modelu IS-LM?","options":["Ravnovesje trga denarja (M = L)","Ravnovesje trga blaga (S = I)","Krivuljo agregatne ponudbe","Phillipsovo krivuljo"],"correct":1,"explanation":"IS = ravnovesje na trgu blaga (izenačeni prihranki in investicije); LM = ravnovesje na trgu denarja."}]}],"notes":"\n<h2>1 · Temelji in tržne pomanjkljivosti</h2>\n<div class=\"note-card\">\n<h3>Osnovni pojmi</h3>\n<ul>\n<li><b>Mikroekonomija</b> proučuje individualno enoto (posameznik, podjetje, trg ene dobrine); <b>makroekonomija</b> agregatno raven (agregatna potrošnja, investicije, splošna raven cen).</li>\n<li><b>Temeljni ekonomski problem</b> = redkost in izbira med alternativami (kaj, koliko, kako, za koga).</li>\n<li><b>Pozitivna</b> ekonomija opisuje »kot stvari so«; <b>normativna</b> »kaj naj bi bilo« (vrednostne sodbe).</li>\n<li><b>Oportunitetni strošek</b> = strošek izgubljene alternative.</li>\n<li><b>Transformacijska krivulja</b> kaže maksimalni output ob danem znanju in inputih; usločena zaradi padajočega mejnega produkta.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Tržni sistemi in pomanjkljivosti</h3>\n<ul>\n<li><b>Nevidna roka</b> (A. Smith): posameznik, ki sledi lastnim interesom, doseže najboljše za vse — odpove pri monopolu, onesnaževanju.</li>\n<li><b>Laissez-faire</b>: država se sploh ne vmešava. <b>Mešano gospodarstvo</b>: vlada poseže, kjer trg ni učinkovit.</li>\n<li>Tržne slabosti: nepopolna konkurenca, zunanji učinki, neenakost dohodka.</li>\n<li><b>Gini</b> meri neenakost (0 = popolna enakost, 1 = popolna neenakost); <b>Lorenzova krivulja</b> jo prikaže grafično.</li>\n<li><b>Okunovo luknjičasto vedro</b>: prerazdelitev k revnim zmanjša motivacijo za delo → trade-off med enakostjo in učinkovitostjo.</li>\n</ul>\n</div>\n\n<h2>2 · Merjenje: BDP in makroagregati</h2>\n<div class=\"note-card\">\n<h3>BDP in sorodne mere</h3>\n<ul>\n<li><b>BDP = C + I + G + NX</b> (izdatkovna metoda); stroškovno-dohodkovna = plače + dobički + obresti + rente.</li>\n<li><b>Nominalni</b> = tekoče cene; <b>realni</b> = stalne cene; <b>potencialni</b> = max ob stabilnih cenah; <b>dejanski</b> = v danih razmerah.</li>\n<li><b>NDP = BDP − amortizacija</b>; <b>neto naložbe = bruto naložbe − amortizacija</b>.</li>\n<li><b>IPC</b> meri strošek stalne košarice dobrin povprečnega potrošnika.</li>\n<li><b>Poslovni cikel</b>: odstopanja dejanskega od potencialnega BDP — recesija (padec v vsaj 2 trimesečjih) in ekspanzija.</li>\n</ul>\n</div>\n\n<h2>3 · AD–AS, multiplikator in poslovni cikli</h2>\n<div class=\"note-card\">\n<h3>Agregatno povpraševanje in ponudba</h3>\n<ul>\n<li><b>AD = C + I + G + NX</b>; krivulja je padajoča (nižje cene → višja realna ponudba denarja → nižje obrestne mere → več investicij).</li>\n<li><b>AS</b> kratkoročno naraščajoča (lepljive cene/mezde), <b>dolgoročno navpična</b> (vsi stroški se prilagodijo).</li>\n<li><b>Stagflacija</b> = upočasnjena rast + visoka inflacija (premik AS).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Multiplikator</h3>\n<ul>\n<li><b>Multiplikator</b>: za koliko se poveča BDP ob enoti povečanja AD. Predpostavka: neizrabljene zmogljivosti, fiksne cene/mezde.</li>\n<li>Investicijski / državnih izdatkov: <b>1/MNV = 1/(1−MNP)</b>.</li>\n<li><b>Davčni multiplikator je nižji</b> od multiplikatorja državnih izdatkov (del dohodka se prelije v varčevanje).</li>\n<li><b>Paradoks varčevanja</b>: pretirano varčevanje zmanjša AD, dohodek in na koncu tudi samo varčevanje.</li>\n</ul>\n</div>\n\n<h2>4 · Denar in monetarna politika</h2>\n<div class=\"note-card\">\n<h3>Denar</h3>\n<ul>\n<li><b>5 funkcij</b>: menjalno, plačilno sredstvo, merilec, hranilec vrednosti, svetovni denar.</li>\n<li><b>Agregati</b>: M1 (transakcijski: gotovina + knjižni), M2 (+ hranilni računi), M3 (+ dolgoročni depoziti), M4 (+ tuj denar).</li>\n<li><b>Transakcijsko</b> povpraševanje (LT) je odvisno od dohodka; <b>špekulativno</b> (LŠ) od obrestne mere (padajoče).</li>\n<li><b>Denarni multiplikator = 1 / stopnja obveznih rezerv.</b></li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Centralna banka</h3>\n<ul>\n<li>Instrumenti: diskontna stopnja, politika odprtega trga (nakup/prodaja VP), obvezne rezerve.</li>\n<li><b>Restriktivna</b> MP (ob inflaciji): manj denarja → višje obrestne mere → nižji AD, I, BDP. <b>Ekspanzivna</b>: obratno.</li>\n<li><b>Kvantitativna teorija</b>: M·V = P·Q.</li>\n</ul>\n</div>\n\n<h2>5 · Javne finance in fiskalna politika</h2>\n<div class=\"note-card\">\n<h3>Davki</h3>\n<ul>\n<li><b>Neposredni</b> (dohodnina, davek na dobiček) — ni prevaljevanja; <b>posredni</b> (DDV, trošarine) — možno prevaljevanje.</li>\n<li><b>Progresivni</b>: MDS &gt; PDS (dohodnina); <b>sorazmerni</b>: MDS = PDS; <b>regresivni</b>: MDS &lt; PDS.</li>\n<li><b>Lafferjeva krivulja</b>: obrnjena U; pri 0 % in 100 % so prihodki 0.</li>\n<li><b>Ramseyevo pravilo</b>: obdavči cenovno neelastične dobrine (cigareti, alkohol, nafta).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Proračun in dolg</h3>\n<ul>\n<li><b>Deficit T &lt; G</b>, <b>suficit T &gt; G</b>, uravnotežen T = G.</li>\n<li><b>Avtomatski stabilizatorji</b>: nadomestila za brezposelnost, progresivni davki — blažijo cikel.</li>\n<li><b>Učinek izrinjanja</b> (crowding-out): strukturni deficit dvigne obrestne mere in izrine zasebne naložbe; ne deluje v recesiji (tam <b>akceleracija</b>).</li>\n<li><b>Javni dolg</b>: notranji (državljanom) in zunanji (tujcem).</li>\n</ul>\n</div>\n\n<h2>6 · Odprto gospodarstvo in devizni tečaji</h2>\n<div class=\"note-card\">\n<h3>Plačilna bilanca</h3>\n<ul>\n<li>Vsota: tekoči račun + kapitalsko-finančni račun + statistična napaka = 0.</li>\n<li><b>Tekoči račun</b>: blago, storitve, dohodki, tekoči transferji.</li>\n<li><b>Komparativna prednost</b>: država proizvaja, kjer ima relativno nižje stroške; <b>absolutna</b> = absolutno nižji stroški.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Tečaji</h3>\n<ul>\n<li>Drseči (trg) / stalni (vlada določi) / nadzorovano drsenje.</li>\n<li><b>Apreciacija/depreciacija</b>: pri drsečem tečaju (trg). <b>Devalvacija/revalvacija</b>: pri stalnem tečaju (uradna odločitev).</li>\n<li><b>Pariteta kupne moči</b>: tečaji sledijo razliki v inflaciji med državami.</li>\n<li><b>Carine</b>: prohibitivna (prepreči ves uvoz) / neprohibitivna; <b>kvota</b> omeji količino uvoza.</li>\n</ul>\n</div>\n\n<h2>7 · Ekonomske šole, brezposelnost, inflacija, rast</h2>\n<div class=\"note-card\">\n<h3>Šole in IS-LM</h3>\n<ul>\n<li><b>Klasiki / Sayev zakon</b>: ponudba ustvarja lastno povpraševanje; AS navpična.</li>\n<li><b>Keynes</b>: uravnavanje AD prek fiskalne politike; cene/mezde lepljive. <b>Monetarizem</b> (Friedman): inflacija je denarni pojav.</li>\n<li><b>IS</b> = ravnovesje trga blaga (S = I), <b>LM</b> = ravnovesje trga denarja (M = L).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Brezposelnost in inflacija</h3>\n<ul>\n<li><b>Okunov zakon</b>: ~2 % padca BDP pod potencialom → +1 odstotna točka brezposelnosti.</li>\n<li>Vrste: <b>frikcijska</b> (menjava služb, prvi vstop), <b>strukturna</b> (neusklajenost), <b>ciklična</b> (recesija).</li>\n<li><b>Phillipsova krivulja</b>: kratkoročno inverzna povezava inflacija–brezposelnost; dolgoročno navpična (LSUR/NAIRU ~5,8–5,9 % v SLO).</li>\n<li>Inflacija: <b>povpraševanja</b> (premik AD) vs <b>stroškovna</b> (premik AS); hiperinflacija &gt; 50 %/mesec.</li>\n<li><b>Štiri kolesa rasti</b>: zemlja, naravni viri, kapital, tehnologija.</li>\n</ul>\n</div>\n"}]},{"id":"ov","name":"Organizacijsko vedenje","tier":"A","parts":[{"id":"izpit","name":"Izpit","type":"izpit","decks":[{"id":"ov1","name":"Uvod v OV","questions":[{"q":"Kako je opredeljeno organizacijsko vedenje?","options":["Veja računovodstva, ki meri stroške dela v podjetju","Raziskovalno področje o vplivih posameznikov, skupin in strukture na vedenje","Pravni okvir, ki ureja pogodbe med delodajalci in zaposlenimi","Tehnika trženja, usmerjena v vedenje potrošnikov na trgu"],"correct":1,"explanation":"OV je samostojno, multidisciplinarno področje o vplivih posameznikov, skupin in strukture na vedenje v organizacijah."},{"q":"Kateri je pravilni vrstni red managementa, temelječega na dokazih?","options":["Uporabi dokaze, nato zastavi vprašanje in poišči vire","Zastavi vprašanje, poišči najboljše dokaze, jih uporabi","Najprej intuicija, nato odločitev in šele potem analiza","Poišči dokaze, oblikuj modno muho in nato odločitev"],"correct":1,"explanation":"Znanstveni pristop: zastaviti vprašanje, poiskati najboljše obstoječe dokaze in jih uporabiti v študiji primera."},{"q":"Katero NI eno od petih sider organizacijskega vedenja?","options":["Sidro multidisciplinarnosti in sistematičnega raziskovanja","Situacijsko sidro o odvisnosti učinkov od razmer","Sidro maksimiranja kratkoročnega dobička podjetja","Sidro večnivojskosti in sidro odprtega sistema"],"correct":2,"explanation":"Sidra so multidisciplinarnost, sistematično raziskovanje, situacijsko, večnivojskost in odprti sistem. Maksimiranje dobička ni sidro."},{"q":"Po Katzu prevladujejo pri vrhnjem managementu predvsem:","options":["Tehnične spretnosti","Konceptualne spretnosti","Rutinske administrativne naloge","Operativne ročne veščine"],"correct":1,"explanation":"Po Katzu vrhnji management najbolj potrebuje konceptualne spretnosti, nižji pa tehnične; medosebne so pomembne na vseh ravneh."},{"q":"Katera od štirih aktivnosti managerjev (Luthans) pomeni motivacijo, discipliniranje in obvladovanje konfliktov?","options":["Tradicionalni management odločanja","Komuniciranje in papirologija","Ravnanje z ljudmi pri delu","Gradnja socialne mreže"],"correct":2,"explanation":"Ravnanje z ljudmi zajema motivacijo, discipliniranje, obvladovanje konfliktov, kadrovanje in usposabljanje."},{"q":"Kaj je organizacijsko državljanstvo (OCB)?","options":["Vedenje, ki krši pomembne organizacijske norme","Formalna obveznost iz opisa delovnega mesta","Diskrecijsko vedenje izven opisa dela, ki koristi organizaciji","Prostovoljni trajni umik posameznika iz organizacije"],"correct":2,"explanation":"OCB je diskrecijsko vedenje, ki ni del formalnega opisa dela, a prispeva k uspešnosti organizacije."},{"q":"Kaj označuje odklonsko vedenje na delovnem mestu?","options":["Prostovoljno vedenje, ki krši pomembne organizacijske norme","Vsako ustvarjalno odstopanje od ustaljenih postopkov","Diskrecijsko pomaganje sodelavcem izven obveznosti","Splošno merilo učinkovitosti in uspešnosti delavca"],"correct":0,"explanation":"Odklonsko (kontraproduktivno) vedenje je prostovoljno vedenje, ki krši norme in ogroža organizacijo ter njene člane."},{"q":"Kateri par opisuje zgolj odvisne spremenljivke v OV?","options":["Plača in delovni čas","Produktivnost in absentizem","Kultura in struktura","Sidra in metode"],"correct":1,"explanation":"Med najbolj preučevane odvisne spremenljivke sodijo produktivnost, zadovoljstvo, absentizem, odhod, odklonsko vedenje in OCB."},{"q":"Katera trditev o raznolikosti delovne sile drži?","options":["Vedno zmanjša ustvarjalnost in hitrost odločanja","Prinaša koristi in tudi izzive, kot so konflikti","Nima nobenega vpliva na uspešnost organizacije","Je pomembna le pri mednarodnih korporacijah"],"correct":1,"explanation":"Raznolikost prinaša koristi (talenti, ustvarjalnost, reševanje problemov) in izzive (odpor, manko kohezivnosti, konflikti, daljše odločanje)."},{"q":"Katera metoda raziskovanja v OV pomeni nadzorovano manipulacijo spremenljivk?","options":["Terenska študija","Meta-analiza","Laboratorijski eksperiment","Intervju"],"correct":2,"explanation":"Laboratorijski eksperiment omogoča nadzorovano manipulacijo; metode so še meta-analize, terenske študije, vprašalniki, intervjuji, študije primerov."}]},{"id":"ov2","name":"Skupine, norme in timi","questions":[{"q":"Kako je opredeljena skupina?","options":["Naključna množica ljudi na istem mestu ob istem času","Dva ali več soodvisnih posameznikov v interakciji s skupnim ciljem","Vsak oddelek, ki je vpisan v organizacijsko shemo","Skupek posameznikov brez vsakršne medsebojne povezave"],"correct":1,"explanation":"Skupina so dva ali več posameznikov, ki delujejo skupaj, so soodvisni in v interakciji za skupne cilje."},{"q":"Po čem se neformalna skupina razlikuje od formalne?","options":["Določena je z organizacijsko strukturo podjetja","Vedno je večja in bolj produktivna od formalne","Nastane iz potreb po socialnih stikih, ne iz strukture","Obstaja izključno v proizvodnih obratih"],"correct":2,"explanation":"Neformalna skupina ni organizacijsko določena; oblikuje se kot odgovor na potrebe po socialnih stikih."},{"q":"Kateri je pravilni vrstni red faz po Tuckmanu?","options":["Viharna faza, oblikovanje, pravila, izvajanje, zaključek","Oblikovanje, viharna faza, oblikovanje pravil, izvajanje, zaključevanje","Pravila, oblikovanje, izvajanje, viharna faza, zaključek","Izvajanje, oblikovanje, pravila, viharna faza, zaključek"],"correct":1,"explanation":"Tuckman (1965): oblikovanje, viharna faza, oblikovanje pravil, izvajanje, zaključevanje."},{"q":"Katera vrsta soodvisnosti pri nalogah zahteva najvišjo koordinacijo?","options":["Združevalna","Sekvenčna","Recipročna","Popolna"],"correct":3,"explanation":"Popolna (poglobljena) soodvisnost predvideva najvišjo stopnjo interakcije in koordinacije med člani.","more":"Poznamo štiri vrste soodvisnosti pri nalogah, od najnižje do najvišje koordinacije: (1) združevalna — člani delajo bolj ali manj ločeno, potrebna je minimalna koordinacija; (2) sekvenčna — naloge si sledijo po določenem vrstnem redu, člani se specializirajo; (3) recipročna — člani se specializirajo in si izmenjujejo vmesne rezultate; (4) popolna/poglobljena — najvišja stopnja interakcije in koordinacije. Poleg soodvisnosti pri nalogah ločimo še soodvisnost pri ciljih (skupna vizija ciljev) in pri rezultatih (povezanost prek povratnih informacij in posledic)."},{"q":"Kaj je pokazala Aschova študija?","options":["Da so timi vedno uspešnejši od posameznikov","Da denar najmočneje določa rezultate dela","Da pritisk skupine vodi v konformizem kljub napaki","Da kohezivnost vedno škoduje produktivnosti"],"correct":2,"explanation":"Asch je prikazal vplivnost pritiskov skupine in posledični konformizem kljub zavedanju nepravilnega odgovora."},{"q":"Kaj je pokazala Hawthorne študija glede norm?","options":["Denar je najpomembnejši dejavnik outputa zaposlenih","Norme skupine pomembno vplivajo na individualno vedenje","Fizični pogoji povsem določajo storilnost delavcev","Neformalne skupine ne vplivajo na vedenje članov"],"correct":1,"explanation":"Norme skupine in pripadnost so se izkazale za pomembnejše od denarja in fizičnih pogojev."},{"q":"Kaj opisuje pojem družbenega izmikanja (social loafing)?","options":["Večji trud posameznika v skupini kot pri samostojnem delu","Manjši vloženi trud posameznika pri skupinskem delu","Konflikt med nasprotujočimi pričakovanji vlog","Visoka kohezivnost in zadovoljstvo članov tima"],"correct":1,"explanation":"Ringelmann je pokazal, da posamezniki pri skupinskem delu vlagajo manj truda kot pri individualnem."},{"q":"Kateri ukrep NE povečuje kohezivnosti skupine?","options":["Oblikovanje manjših skupin in več skupnega časa","Spodbujanje tekmovanja z drugimi skupinami","Nagrajevanje skupine namesto posameznika","Sproščanje vstopnih kriterijev in nižanje statusa"],"correct":3,"explanation":"Kohezivnost krepijo manjše skupine, skupni cilji, več skupnega časa, višji status z ostrejšimi kriteriji, tekmovanje z drugimi in nagrajevanje skupine."},{"q":"V čem je ključna razlika med timom in skupino (Katzenbach)?","options":["Tim deluje povsem brez kakršnega koli vodje","Tim ima vzajemno odgovornost in kolektivni rezultat","Skupina je vedno bolj uspešna od tima","Med njima v praksi ni nobene razlike"],"correct":1,"explanation":"Pri timu je odgovornost individualna in vzajemna, vodenje se deli, rezultat je kolektiven; optimalna velikost 5–9."},{"q":"Katera Belbinova vloga je opisana kot ustvarjalna in rešuje zahtevne probleme?","options":["Proizvajalec (Plant)","Koordinator","Dovrševalec","Timski delavec"],"correct":0,"explanation":"Proizvajalec (Plant) je ustvarjalen in rešuje zahtevne probleme; dovoljena slabost je spregledovanje podrobnosti."},{"q":"Kateri so štirje vedenjski vzorci po Adizesu/Lipičniku (PAEI)?","options":["Vizionar, realist, kritik, optimist","Proizvajalec, administrator, podjetnik, integrator","Vodja, sledilec, opazovalec, izvajalec","Modrec, pogumnež, humanist, pravičnik"],"correct":1,"explanation":"PAEI: proizvajalec, administrator, podjetnik (entrepreneur) in integrator."}]},{"id":"ov3","name":"Motivacija in delo","questions":[{"q":"Iz katerih treh sestavin je sestavljena motivacija?","options":["Cilj, nagrada in kazen","Smer, intenzivnost in vztrajnost","Vhod, proces in izhod","Plača, status in moč"],"correct":1,"explanation":"Motivacija je skupek procesov, ki vzbudijo (smer), usmerijo (intenzivnost) in uravnavajo (vztrajnost) vedenje."},{"q":"Kaj je značilno za intrinzične dejavnike motivacije?","options":["Plačilo, bonusi in napredovanje","Ugodnosti, varnost in prosti čas","Uživanje, razvoj spretnosti in dosežki","Pohvala in odsotnost disciplinskih postopkov"],"correct":2,"explanation":"Intrinzični dejavniki izhajajo iz dela samega: uživanje, zanimivost, dosežki, razvoj spretnosti; ekstrinzični so plačilo, status ipd."},{"q":"Kaj je po Csikszentmihalyiju ključni pogoj za zanos (flow)?","options":["Čim višja denarna nagrada","Stalni nadzor nadrejenega","Ravnotežje med spretnostmi in izzivi","Popolna odsotnost vsakršnih ciljev"],"correct":2,"explanation":"Zanos nastopi ob ravnotežju med spretnostmi in izzivi; premalo izzivov vodi v dolgčas, preveč pa v tesnobo."},{"q":"Katera NI dimenzija značilnosti dela po Hackmanu in Oldhamu?","options":["Avtonomija","Pomen naloge","Identiteta naloge","Višina osnovne plače"],"correct":3,"explanation":"Dimenzije so raznolikost zmožnosti, identiteta naloge, pomen naloge, avtonomija in povratne informacije; plača ni med njimi.","more":"Model značilnosti dela (Hackman & Oldham) ima pet dimenzij: raznolikost zmožnosti, identiteta naloge, pomen naloge, avtonomija in povratne informacije. Prve tri vplivajo na doživljanje pomembnosti, avtonomija na doživljanje odgovornosti, povratne informacije pa na poznavanje rezultatov. Iz njih izračunamo oceno motivacijskega potenciala: OMP = ((raznolikost + identiteta + pomen) / 3) × avtonomija × povratne informacije."},{"q":"Kaj pomeni samoiniciativno preoblikovanje dela (job crafting)?","options":["Da nadrejeni na novo predpiše opis delovnega mesta","Da zaposleni sam prilagodi naloge, odnose in dojemanje dela","Da kadrovska služba prerazporedi vse zaposlene","Da se delovno mesto ukine zaradi digitalizacije"],"correct":1,"explanation":"Job crafting je samoiniciativno preoblikovanje nalog, odnosov in dojemanja dela s strani zaposlenega (Wrzesniewski & Dutton)."},{"q":"Kaj je osnovna premisa Lockejeve teorije postavljanja ciljev?","options":["Najboljši cilj je vedno 'naredi po svojih najboljših močeh'","Cilji ne vplivajo na delovno uspešnost posameznika","Konkretni in težki cilji s povratnimi informacijami dvignejo uspešnost","Cilji morajo biti čim bolj splošni in nezahtevni"],"correct":2,"explanation":"Konkretni in zahtevni cilji ter povratne informacije vodijo k višji uspešnosti; odnos je odvisen od zavezanosti cilju."},{"q":"Kaj NE sodi med sestavne dele uspešnega MBO (vodenje s cilji)?","options":["Jasnost ciljev","Participacija pri odločanju","Določen časovni okvir","Odsotnost povratnih informacij"],"correct":3,"explanation":"MBO temelji na jasnosti ciljev, participaciji, časovnem okviru in povratnih informacijah; odsotnost povratnih informacij vodi v neuspeh."},{"q":"Na čem temelji Adamsova teorija pravičnosti?","options":["Na hierarhiji petih ravni potreb","Na primerjavi lastnih vložkov in rezultatov z drugimi","Na dveh faktorjih, higienikih in motivatorjih","Na postavljanju konkretnih in težkih ciljev"],"correct":1,"explanation":"Posameznik primerja razmerje svojih vložkov in rezultatov z referenco in se odziva na zaznano (ne)pravičnost."},{"q":"Katera strategija je odziv na zaznano nepravičnost po Adamsu?","options":["Povečanje hierarhije potreb","Sprememba vloženega inputa ali outputa","Postavitev SMART ciljev","Uvedba modela zanosa"],"correct":1,"explanation":"Med strategije sodijo sprememba inputov/outputov, popačenje zaznave sebe ali drugih, menjava reference in odhod iz podjetja."},{"q":"Kako Maslow razdeli potrebe nižjega in višjega reda?","options":["Nižje so zadovoljene interno, višje eksterno","Nižje so fiziološke in varnost, zadovoljene eksterno","Vse potrebe so vedno zadovoljene hkrati in enako","Med redoma potreb v teoriji ni nobene razlike"],"correct":1,"explanation":"Nižji red (fiziološke, varnost) se zadovolji eksterno; višji red (pripadnost, ugled, samopotrjevanje) interno."}]},{"id":"ov4","name":"Stališča, čustva, zaznave","questions":[{"q":"Kaj pravi teorija razširitve in izgradnje (broaden-and-build)?","options":["Negativna čustva širijo pozornost in gradijo vire","Pozitivna čustva širijo pozornost in gradijo vire","Čustva nimajo vpliva na razmišljanje in dejanja","Le denar dolgoročno gradi psihološko trdoživost"],"correct":1,"explanation":"Pozitivna čustva (Fredrickson) razširijo spekter pozornosti in gradijo fizične, intelektualne in socialne vire ter trdoživost."},{"q":"Kako 'pita sreče' razdeli vpliv na doživljanje sreče?","options":["50 % okoliščine, 40 % genetika, 10 % dejanja","50 % genetika, 40 % namerna dejanja, 10 % okoliščine","40 % genetika, 40 % dejanja, 20 % okoliščine","10 % genetika, 50 % dejanja, 40 % okoliščine"],"correct":1,"explanation":"Po modelu: ~50 % genetika, ~40 % namerna dejanja in ~10 % življenjske okoliščine."},{"q":"Kaj opisuje halo učinek?","options":["Pripisovanje lastnih značilnosti drugim ljudem","Splošni vtis o osebi na osnovi ene značilnosti","Selektivno opažanje le določenih dražljajev","Vpliv nedavnih primerjav na oceno značilnosti"],"correct":1,"explanation":"Halo učinek je oblikovanje celostnega vtisa o posamezniku na podlagi ene same značilnosti.","more":"Med napake v procesu zaznavanja sodijo še: učinek kontrasta (oceno popači nedavna primerjava z drugimi), stereotipiziranje (posplošene značilnosti skupine pripišemo posamezniku), projeciranje (lastne značilnosti pripisujemo drugim), selektivno zaznavanje (videno interpretiramo glede na lastne izkušnje in interese) in napaka prvega vtisa (presoje gradimo na predhodnem vtisu)."},{"q":"Kaj je temeljna napaka pripisovanja?","options":["Precenjevanje zunanjih in podcenjevanje notranjih vzrokov","Podcenjevanje zunanjih in precenjevanje notranjih vzrokov","Pripisovanje vsega vedenja zgolj naključju","Popolno zanikanje vzrokov tujega vedenja"],"correct":1,"explanation":"Pri presojanju vedenja drugih podcenjujemo vpliv zunanjih (situacijskih) in precenjujemo vpliv notranjih dejavnikov."},{"q":"Katere tri dimenzije uporablja Kelleyjeva teorija pripisovanja?","options":["Vizija, tveganje, karizma","Razločevalnost, konsenzualnost, doslednost","Smer, intenzivnost, vztrajnost","Halo, kontrast, projekcija"],"correct":1,"explanation":"Kelley presoja vzroke vedenja glede na razločevalnost, konsenzualnost in doslednost."},{"q":"Kaj je samouresničujoča se prerokba v različici Pygmalion?","options":["Nizka pričakovanja zvišajo uspešnost","Visoka pričakovanja zvišajo uspešnost","Pričakovanja nimajo učinka na uspešnost","Uspešnost je odvisna le od plačila"],"correct":1,"explanation":"Pygmalion: visoka pričakovanja nadrejenega dvignejo uspešnost; Golem: nizka pričakovanja jo znižajo."},{"q":"Kaj je kognitivna disonanca (Festinger)?","options":["Skladje med plačo in vloženim trudom","Neskladje med stališči ali med vedenjem in stališči","Sinonim za visoko organizacijsko pripadnost","Vrsta situacijske teorije vodenja"],"correct":1,"explanation":"Disonanca je neskladje med stališči ali med vedenjem in stališči; posameznik stremi k njenemu zmanjšanju."},{"q":"V čem se emocije razlikujejo od razpoloženja?","options":["Emocije so šibke in brez konkretnega sprožilca","Emocije so usmerjene in intenzivne, razpoloženja šibkejša","Razpoloženja so vedno negativna in kratkotrajna","Med emocijami in razpoloženji ni razlike"],"correct":1,"explanation":"Emocije so močne, usmerjene in kratke; razpoloženja so manj intenzivna, daljša in brez situacijskega sprožilca."},{"q":"Kaj je površinsko igranje pri emocionalnem delu?","options":["Iskreno izražanje dejansko občutenih čustev","Sprememba notranjih občutij, da se ujamejo z izrazom","Izražanje zahtevanih čustev, ki jih oseba ne občuti","Popolno prikrivanje vseh čustev pred strankami"],"correct":2,"explanation":"Površinsko igranje je izražanje zahtevanih emocij, ki jih oseba notranje ne čuti; globinsko spremeni tudi občutja."},{"q":"Šest temeljnih čustev po Ekmanu so:","options":["jeza, gnus, strah, sreča, žalost, presenečenje","veselje, zaupanje, pričakovanje, jeza, strah, gnus","ljubezen, ponos, sram, krivda, upanje, zavist","navdušenje, dolgčas, nervoza, umirjenost, jeza, strah"],"correct":0,"explanation":"Ekman navaja šest temeljnih čustev: jezo, gnus, strah, srečo, žalost in presenečenje."},{"q":"Kaj predvideva teorija afektivnih dogodkov (AET)?","options":["Da čustva nimajo zveze z delovno uspešnostjo","Da dogodki pri delu sprožajo čustva, ki vplivajo na uspešnost","Da je zadovoljstvo odvisno le od plače","Da osebnost ne vpliva na intenzivnost čustev"],"correct":1,"explanation":"AET: dogodki v delovnem okolju sprožajo pozitivne/negativne emocije, te pa vplivajo na zadovoljstvo in uspešnost."},{"q":"Kaj je organizacijska pripadnost?","options":["Diskrecijska pomoč sodelavcem izven obveznosti","Identifikacija z organizacijo in želja ostati član","Splošna mera produktivnosti zaposlenega","Nasprotujoča pričakovanja dveh različnih vlog"],"correct":1,"explanation":"Pripadnost je identifikacija s cilji organizacije in želja po ohranjanju članstva; pogosto boljši napovedovalec posledic kot zadovoljstvo."}]},{"id":"ov5","name":"Etika in vrednote","questions":[{"q":"Kako Rokeach deli vrednote?","options":["Na hedonske in na potenčne vrednote","Na terminalne (cilje) in instrumentalne (načine)","Na notranje in na zunanje vrednote","Na pozitivne in na negativne vrednote"],"correct":1,"explanation":"Rokeach loči terminalne vrednote (zaželena končna stanja) in instrumentalne (načini doseganja terminalnih)."},{"q":"Katera delitev vrednot je značilna za Muska?","options":["Terminalne in instrumentalne","Odprtost, ohranitev, samopreseganje","Hedonske, potenčne, moralne, izpolnitvene","Legitimne, prisilne, referenčne"],"correct":2,"explanation":"Muskova delitev (po starostnih razlikah): hedonske, potenčne, moralne in izpolnitvene vrednote."},{"q":"Kaj je etična dilema?","options":["Vsaka kršitev zakonodaje v podjetju","Izbira med dvema ali več etično neugodnimi možnostmi","Sinonim za pravno odgovornost organizacije","Tehnika vodenja s pomočjo nagrad"],"correct":1,"explanation":"Etična dilema vključuje izbiranje med dvema ali več etično neugodnimi alternativnimi scenariji."},{"q":"Kateri je pravilni vrstni red stopenj po Kohlbergu?","options":["Konvencionalna, prekonvencionalna, postkonvencionalna","Prekonvencionalna, konvencionalna, postkonvencionalna","Postkonvencionalna, konvencionalna, prekonvencionalna","Vse tri stopnje nastopijo hkrati"],"correct":1,"explanation":"Kohlberg: prekonvencionalna (posledice zame), konvencionalna (pričakovanja družbe), postkonvencionalna (notranja načela)."},{"q":"Kaj trdi etični relativizem?","options":["Etika matične države velja povsod po svetu","Etika ene kulture ni boljša od etike druge","Etika sploh ne obstaja kot pojav","Etika je vedno enaka pravu"],"correct":1,"explanation":"Etični relativizem trdi, da nobena kultura ni etično boljša od druge; nasprotje je etični imperializem."},{"q":"Kaj pomeni ugašanje etičnosti (ethical fading)?","options":["Krepitev etične zavesti skozi usposabljanja","Postopno bledenje etične komponente odločitve","Uvedba etičnega kodeksa v organizaciji","Anonimna prijava kršitev po etični liniji"],"correct":1,"explanation":"Ethical fading je proces, v katerem etična perspektiva postopoma zbledi, kar poveča nezavedno neetično vedenje."},{"q":"Kaj je etična linija?","options":["Najvišja stopnja moralnega presojanja","Kanal za anonimno prijavo kršitev etičnih načel","Mejna vrednost dobička podjetja","Vrsta konsekvenčne etične teorije"],"correct":1,"explanation":"Etična linija je telefonska ali spletna pot za anonimno sporočanje kršitev etičnih načel v organizaciji."},{"q":"Kateri par opisuje obe veji raziskovanja poslovne etike?","options":["Terminalna in instrumentalna","Preskriptivna in deskriptivna","Notranja in zunanja","Afektivna in kognitivna"],"correct":1,"explanation":"Preskriptivna veja preučuje, kako bi se ljudje morali vesti; deskriptivna pa, kako se dejansko vedejo."},{"q":"Kaj je značilno za postkonvencionalno stopnjo moralnega presojanja?","options":["Presoja po posledicah dejanj zame","Presoja po pričakovanjih družine in družbe","Presoja po lastnih, jasno opredeljenih načelih","Odsotnost vsakršne moralne presoje"],"correct":2,"explanation":"Na postkonvencionalni stopnji se moralnost presoja po notranjih, natančno opredeljenih načelih (pravice, pravičnost)."}]},{"id":"ov6","name":"Stres","questions":[{"q":"Kako se razlikujeta stres in stresor?","options":["Sta popolna sinonima v vsakdanji rabi","Stres je odgovor, stresor je sprožilec stresa","Stresor je odgovor, stres je njegov sprožilec","Oba pomenita izključno fizično bolezen"],"correct":1,"explanation":"Stres je adaptivni odgovor posameznika; stresor je oseba ali dogodek, ki sproži stresni odziv."},{"q":"Kaj sta eustres in distres?","options":["Dve obliki konflikta vlog","Eustres je pozitiven, distres negativen stres","Eustres je hujša oblika izgorelosti","Oba sta sopomenki za naučeno nemoč"],"correct":1,"explanation":"Eustres spremlja pozitivne dogodke (pozitiven stres), distres prinaša neugodne posledice (negativen stres)."},{"q":"Kaj je naučena nemoč (Seligman)?","options":["Pomanjkanje strokovnih spretnosti za nalogo","Občutek izgube kontrole ob neizogibnem dogodku","Vrsta intrinzične motivacije za delo","Visoka stopnja kohezivnosti v skupini"],"correct":1,"explanation":"Naučena nemoč je občutek izgube kontrole, ko posameznik zazna, da neugodnemu dogodku ne more ubežati."},{"q":"Kaj je konflikt oseba-vloga?","options":["Nasprotujoča pričakovanja dveh različnih vlog","Zahteva po vedenju, ki ni skladno z vrednotami osebe","Premalo nalog in aktivnosti pri delu","Nejasnost o tem, kaj se od osebe pričakuje"],"correct":1,"explanation":"Konflikt oseba-vloga nastopi, ko se od posameznika zahteva vedenje, ki ni skladno z njegovimi vrednotami ali prepričanji."},{"q":"Kaj je dvoumnost vloge?","options":["Nasprotujoča pričakovanja med dvema vlogama","Nejasnost, kaj se od osebe pričakuje in kako je ocenjena","Prevelika količina dodeljenih nalog","Konflikt med delom in družino"],"correct":1,"explanation":"Dvoumnost vloge pomeni, da posameznik ne ve, kaj se od njega pri delu pričakuje in kako bo ocenjen."},{"q":"Katere tri komponente sestavljajo izgorelost?","options":["Tesnoba, depresija, napetost","Izčrpanost, depersonalizacija, malo osebnih uspehov","Smer, intenzivnost, vztrajnost","Halo, kontrast, projekcija"],"correct":1,"explanation":"Izgorelost sestavljajo fizična/čustvena izčrpanost, depersonalizacija (ciničen odnos) in občutek malo osebnih uspehov."},{"q":"Kaj predpostavlja Karasekov model zahteve-nadzor?","options":["Stres je odvisen le od osebnosti zaposlenega","Stres je funkcija zahtev dela in stopnje nadzora","Stres izvira izključno iz zunanjega okolja","Stres ni povezan z doživljanjem kontrole"],"correct":1,"explanation":"Po Karaseku je stres najintenzivnejši, ko so zahteve visoke, nadzor nad delom pa nizek."},{"q":"Kakšna je razlika med izzivnimi in zavirajočimi stresorji?","options":["Izzivni vedno škodujejo, zavirajoči koristijo","Izzivne zaznavamo kot priložnost, zavirajoče kot oviro","Zavirajoči stresorji vedno prinašajo eustres","Med njima ni nobene pomembne razlike"],"correct":1,"explanation":"Izzivne stresorje zaznavamo kot priložnosti za rast, zavirajoče kot ovire pri doseganju ciljev."},{"q":"Kateri pogled na stres je povezan s Cannonom?","options":["Kognitivna ocena dražljaja","Homeostaza in odziv beg-ali-boj","Skladnost med osebo in okoljem (P-E fit)","Psihoanalitični ego-ideal"],"correct":1,"explanation":"Cannon: homeostaza in odziv 'fight-or-flight'; stres nastopi, ko zunanje zahteve porušijo naravno ravnotežje."},{"q":"Kam sodi 'osredotočenost na problem' v strategijah obvladovanja stresa (Latack, Havlovic)?","options":["K odpravljanju samega vira stresa","K nadziranju zgolj stresnih čustev","K popolnemu izogibanju situaciji","K psihoanalitičnemu ego-idealu"],"correct":0,"explanation":"Na problem osredotočene strategije ciljajo neposredno na vir stresa; na čustva osredotočene pa na obvladovanje občutkov."}]},{"id":"ov7","name":"Vodenje","questions":[{"q":"Kako je opredeljeno vodenje?","options":["Računovodsko spremljanje uspešnosti zaposlenih","Zmožnost vplivanja na skupino v smeri ciljev","Pravica do kaznovanja podrejenih delavcev","Tehnično načrtovanje delovnih postopkov"],"correct":1,"explanation":"Vodenje je zmožnost vplivanja na skupino k doseganju ciljev; je proces usmerjanja vedenja ljudi pri delu."},{"q":"Katere štiri sestavine zajema čustvena inteligentnost po Golemanu?","options":["Vizija, tveganje, karizma, ocena razmer","Samozavedanje, samoobvladovanje, družbeno zavedanje, obvladovanje odnosov","Smer, intenzivnost, vztrajnost, cilj","Legitimnost, prisila, nagrada, informacija"],"correct":1,"explanation":"Goleman: samozavedanje, samoobvladovanje (osebne kompetence), družbeno zavedanje in obvladovanje odnosov (socialne kompetence)."},{"q":"Kaj loči vedenjske teorije Univerze Ohio?","options":["Notranji in zunanji lokus kontrole","Vzpostavitev strukture in vzpostavitev odnosov","Eustres in distres","Terminalne in instrumentalne vrednote"],"correct":1,"explanation":"Ohio: 'initiating structure' (strukturiranje vlog za cilje) in 'consideration' (zaupanje, spoštovanje, upoštevanje čustev)."},{"q":"Kaj predpostavlja Fiedlerjev kontingenčni model?","options":["Da je vodstveni stil zelo prilagodljiv","Da je vodstveni stil fiksen in mora ustrezati situaciji","Da karizma sama določa uspeh vodenja","Da vodenja sploh ni mogoče preučevati"],"correct":1,"explanation":"Fiedler: stil je fiksen izraz osebnosti; vodjo je treba uskladiti s situacijo (odnos vodja–člani, definiranost naloge, moč vodje)."},{"q":"Kaj je značilno za transformacijskega vodjo?","options":["Vodi izključno z nagradami za dosežene cilje","Doseže sprejetje skupne vizije in delo prek lastnih interesov","Posreduje le, kadar pride do odklonov","Se izogiba odgovornosti in odločitvam"],"correct":1,"explanation":"Transformacijski vodja preseže delovne zahteve in doseže sprejetje vizije; transakcijski vodi z nagradami in mng. z izjemami."},{"q":"Kateri element NE sodi k transakcijskemu vodenju?","options":["Nagrade za dosežene cilje","Management z izjemami","Brezvladje (laissez-faire)","Idealiziran vpliv (karizma)"],"correct":3,"explanation":"Transakcijsko: nagrade, mng. z izjemami, laissez-faire. Idealiziran vpliv je sestavina transformacijskega vodenja."},{"q":"Kaj opisuje teorija LMX (izmenjava vodja-sledilec)?","options":["Vse sledilce vodja obravnava povsem enako","Vodja oblikuje priljubljeno 'in' in 'out' skupino","Vodstveni stil je vedno fiksen","Moč izvira le iz položaja v hierarhiji"],"correct":1,"explanation":"LMX: vodja izbere priljubljene sledilce ('in'), s katerimi ima kakovostnejše izmenjave (boljše ocene, manj fluktuacije)."},{"q":"Kaj označuje makiavelizem kot osebnostno potezo?","options":["Visoko empatijo in skrb za druge","Prepričanje, da cilj opravičuje sredstva","Osrednjo željo po služenju drugim","Naravno nagnjenost k timskemu delu"],"correct":1,"explanation":"Makiavelizem je stopnja, do katere je posameznik pragmatičen, ohranja distanco in verjame, da cilj opravičuje sredstva."},{"q":"Kaj je osrednja motivacija pri uslužnostnem (servant) vodenju?","options":["Maksimiranje osebnega ugleda vodje","Želja najprej služiti drugim","Stroga kontrola in nadzor podrejenih","Tekmovanje med oddelki podjetja"],"correct":1,"explanation":"Uslužnostno vodenje izhaja iz naravne želje najprej služiti; z vidika moralnosti je med najbolj etičnimi pristopi."},{"q":"Kaj je 'stekleni previs' (glass cliff)?","options":["Najvišja raven hierarhične lestvice","Verjetnost napredovanja žensk v kriznih obdobjih","Meja pri horizontalnem premeščanju","Sinonim za steklen strop"],"correct":1,"explanation":"Stekleni previs: ženske z večjo verjetnostjo napredujejo na vodilne položaje v kriznih obdobjih z visokim tveganjem neuspeha."},{"q":"Katera omejitev velja za teorije osebnih značilnosti vodenja?","options":["Lastnosti popolnoma določajo uspeh v vseh situacijah","Ni univerzalnih lastnosti za vse situacije vodenja","Vodenja se da povsem naučiti z urjenjem","Karizma je edina pomembna lastnost vodje"],"correct":1,"explanation":"Teorije potez nimajo univerzalnih lastnosti za vse situacije in so boljši napovedovalec vznika kot uspešnosti vodij."}]},{"id":"ov8","name":"Osebnost, moč, konflikt","questions":[{"q":"Kateri so deli osebnosti po Freudovi teoriji?","options":["Ekstravertiranost, čutenje, presojanje","Id, ego in superego","Telo, um in duša","Moč, status in vpliv"],"correct":1,"explanation":"Freud: id (vir impulzov), superego ('vest', vrednote) in ego (obvladovanje konflikta, kompromisi)."},{"q":"Kaj pomeni notranji lokus kontrole?","options":["Prepričanje, da dogodke določa sreča","Prepričanje, da posameznik sam vpliva na dogajanje","Naklonjenost strogo strukturiranemu delu","Odvisnost od potrjevanja s strani drugih"],"correct":1,"explanation":"Pri notranjem lokusu posameznik verjame, da sam vpliva na dogajanje; povezano je z višjo motivacijo in zadovoljstvom."},{"q":"Kaj je značilno za fokus na preprečevanje (prevention)?","options":["Hitro delo in mnogo alternativ","Previdnost, natančnost in priprava na najslabše","Optimizem in iskanje pozitivne povratne informacije","Načrtovanje le scenarija najboljšega izida"],"correct":1,"explanation":"Fokus na preprečevanje pomeni počasnejše, natančno delo, pripravo na najslabše in cilje kot odgovornosti; fokus na napredovanje je nasproten."},{"q":"Katere so štiri sestavine psihološkega kapitala?","options":["Moč, status, vpliv, avtoriteta","Samozaupanje, upanje, optimizem, trdoživost","Smer, intenzivnost, vztrajnost, cilj","Id, ego, superego, sebstvo"],"correct":1,"explanation":"Psihološki kapital: samozaupanje (samoučinkovitost), upanje, optimizem in trdoživost."},{"q":"Katera moč sodi med osebne vire moči po French in Ravnu?","options":["Legitimna moč","Moč nagrajevanja","Referenčna moč","Moč prisile"],"correct":2,"explanation":"Osebna moč: ekspertna in referenčna. Legitimna, nagrajevanja, prisile in informacij so moč položaja.","more":"French in Raven ločita šest virov moči. Moč položaja: legitimna (izhaja iz položaja v hierarhiji), moč nagrajevanja, moč prisile (zastraševanje/kaznovanje) in moč informacij (dostop do podatkov). Osebna moč: ekspertna (znanje in spretnosti) in referenčna (identifikacija ter spoštovanje do osebe); k osebni pogosto prištevamo še karizmo."},{"q":"Kateri trije dejavniki povečujejo odvisnost in s tem moč?","options":["Pomen, redkost, nenadomestljivost","Vizija, tveganje, karizma","Smer, intenzivnost, vztrajnost","Halo, kontrast, projekcija"],"correct":0,"explanation":"Odvisnost raste, če je vir pomemben, redek in nenadomestljiv; večja kot je odvisnost B od A, večja je moč A."},{"q":"Kaj je pokazal Milgramov eksperiment o ubogljivosti?","options":["Da ljudje dosledno zavračajo avtoriteto","Da je ~65 % sledilo avtoriteti do najvišjega sunka","Da denar najmočneje določa vedenje","Da je konflikt vedno škodljiv"],"correct":1,"explanation":"V Milgramovem poskusu je ~65 % udeležencev sledilo pozivom avtoritete do najvišje stopnje električnega sunka."},{"q":"Katero pravilo prepričevanja po Cialdiniju temelji na 'dajanju z namenom prejemanja'?","options":["Redkost","Recipročnost","Avtoriteta","Konsenz"],"correct":1,"explanation":"Recipročnost: dajanje z namenom prejemanja. Cialdinijevih šest: recipročnost, redkost, avtoriteta, skladnost, všečnost, konsenz.","more":"Cialdinijevih šest pravil prepričevanja: recipročnost (dajanje z namenom prejemanja), redkost (časovno ali količinsko omejene ponudbe), avtoriteta (sledenje mnenju strokovnjakov), skladnost (moč danih obljub in doslednosti), všečnost (raje ugodimo tistim, ki so nam všeč) in konsenz (sledenje vedenju drugih)."},{"q":"Kaj je asertivna komunikacija?","options":["Poudarjanje izključno lastnih potreb","Neposredno, a spoštljivo izražanje stališč","Popolna podreditev potrebam drugih","Izogibanje vsakršni komunikaciji"],"correct":1,"explanation":"Asertivnost je samozavestno in spoštljivo izražanje stališč; leži na presečišču agresivnega in pasivnega sloga."},{"q":"Kateri tip konflikta izvira iz osebnostnih razlik in napetosti med ljudmi?","options":["Vsebinski konflikt","Čustveni konflikt","Procesni konflikt","Funkcionalni konflikt"],"correct":1,"explanation":"Čustveni konflikt je posledica osebnostnih razlik in medosebnih napetosti; vsebinski se nanaša na odločitve, procesni na način dela."},{"q":"Kaj je značilno za moderni (in ne tradicionalni) pogled na konflikt?","options":["Konflikt je vedno slab in ga je treba iztrebiti","Konflikt je lahko koristen in se mu ni mogoče izogniti","Konflikt nastane le zaradi motenj v komunikaciji","Konflikt vedno znižuje uspešnost skupine"],"correct":1,"explanation":"Moderni pogled: konflikt je lahko koristen (funkcionalen) in neizogiben; tradicionalni ga vidi kot nekaj slabega."},{"q":"Kaj meri samoučinkovitost v zvezi z določeno nalogo?","options":["Splošen občutek lastne vrednosti","Prepričanje, da je posameznik zmožen opraviti nalogo","Prepričanje o nadzoru nad zunanjimi dogodki","Stopnjo čustvene stabilnosti osebe"],"correct":1,"explanation":"Samoučinkovitost je prepričanje o zmožnosti opraviti določeno nalogo; samozavest je širši občutek lastne vrednosti."}]},{"id":"ov-izpit2021","name":"Pretekli izpit (2. rok 2021)","questions":[{"q":"Po Kordi je eden od simbolov moči tudi opremljenost pisarn vodilnih managerjev (masivno pohištvo, razpored prostora).","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Korda med simbole moči (status) uvršča izgled pisarne — npr. velike, masivne mize in razporeditev prostora."},{"q":"Za makiaveliste je značilno, da so v odnosih očarljivi, empatični in z ljudmi ne manipulirajo.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. Makiavelisti ravno nasprotno: zlahka lažejo in manipulirajo, kažejo malo empatije, cilj jim opravičuje sredstva."},{"q":"Instrumentalno pogojevanje predvideva, da ima nenagrajeno vedenje manjšo verjetnost ponovitve.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Pri instrumentalnem (operantnem) pogojevanju nagrajeno vedenje pogosteje ponovimo, nenagrajeno pa redkeje."},{"q":"Selektivno zaznavanje je proces, v katerem posameznik išče in identificira le določene dražljaje v okolici.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. To je opredelitev selektivnega zaznavanja (vpliv osebnih značilnosti, interesov, izkušenj)."},{"q":"Motivacija je ena od podedovanih osebnih lastnosti.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. Motivacija ni podedovana lastnost, ampak skupek procesov (smer, intenzivnost, vztrajnost); je multifacetna in ljudi ne motivira le denar.","more":"Ključ izpita je bil tu negotov ('Pravilno???'). Pravilno je 'Ne drži': motivacija je stanje/proces, ne dedna poteza osebnosti."},{"q":"McClellandova teorija loči med potrebo po dosežkih, potrebo po moči in potrebo po varnosti.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. McClelland loči potrebo po dosežkih, po moči in po POVEZANOSTI (pripadnosti) — ne po varnosti."},{"q":"Manager z modernim pogledom na konflikte meni, da se jim je treba izogibati in nesoglasja 'pomesti pod preprogo'.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. To je tradicionalni pogled. Moderni pogled vidi konflikt kot (lahko) koristen in neizogiben."},{"q":"Podjetje Starbucks smo obravnavali kot primer avtentične organizacijske kulture.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. Starbucks ni bil obravnavan kot tak primer (primer kulture svobode in odgovornosti je bil Netflix)."},{"q":"Logotip, prevladujoče barve, razporeditev prostorov in arhitektura sodijo med artefakte organizacijske kulture.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Artefakti so vidni, otipljivi izrazi kulture (Schein): logo, barve, prostori, arhitektura, obleka itd."},{"q":"Etični vodje se zavzemajo za pozitivne spremembe, a sami včasih ne ravnajo v skladu z etičnimi standardi.","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. Etični vodje so vzorniki in DOSLEDNO ravnajo skladno z etiko (standardi, nagrade)."},{"q":"Inkubacija je faza ustvarjalnega razmišljanja, v kateri posameznik 'odloži' problem, da bi kasneje prišlo do uvida.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Faze ustvarjalnega procesa: priprava → inkubacija → iluminacija (uvid) → verifikacija."},{"q":"Sprejemalec, posredovalec in zastopnik so primeri informacijskih managerskih vlog po Mintzbergu.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Mintzbergove vloge: medosebne, INFORMACIJSKE (sprejemalec, posredovalec, zastopnik/govorec) in odločitvene."},{"q":"Zastonjkarstvo je pojav, pri katerem posamezniki pri skupinskem delu vlagajo manj truda kot pri individualnem.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. To je družbeno izmikanje (social loafing), ki ga je nakazal že Ringelmannov poskus."},{"q":"Kohezivnost povečamo s spodbujanjem tekmovanja z drugimi skupinami in tako, da člani več časa preživijo skupaj.","options":["Drži","Ne drži"],"correct":0,"explanation":"Drži. Med ukrepi za kohezivnost so tudi tekmovanje z drugimi skupinami, več skupnega časa, manjše skupine in nagrajevanje skupine."},{"q":"Za govorice v podjetju je značilno, da so neformalne in da jih vrhnji management nadzoruje (kontrolira).","options":["Drži","Ne drži"],"correct":1,"explanation":"Ne drži. Govorice so neformalna komunikacija, ki je management NE nadzoruje."},{"q":"Pfeffer (osebne kvalitete za pridobivanje moči): katere kvalitete spadajo v dimenzijo 'Zmožnosti'?","options":["Empatija, toleriranje konflikta, samospoznavanje, samozaupanje","Samozavest, samozavedanje, proaktivnost, makiavelizem","Ambicije, fokus, energija","Energija, empatija, toleriranje konflikta, fokus","Samospoznavanje, inteligentnost, ambicije, fokus"],"correct":0,"explanation":"Pfeffer loči VOLJO (ambicije, energija, fokus) in ZMOŽNOSTI (toleriranje konflikta, empatija, samospoznavanje, samozaupanje)."},{"q":"Če zaposleni vodjo občudujejo zaradi osebnih lastnosti in se z njim identificirajo, vodja izkazuje ___.","options":["Ekspertno moč","Karakterno moč","Referenčno moč","Legitimno moč","Moč vpliva"],"correct":2,"explanation":"Referenčna moč izvira iz identifikacije sodelavcev z vodjo ter iz ugleda in spoštovanja do njega."},{"q":"Pojav v timih, ko norma konsenza prevlada nad realistično oceno (z iluzijo enotnosti), imenujemo ___.","options":["Kohezivnost","Projeciranje","Pripisovanje","Polarizacija","Enoumje"],"correct":4,"explanation":"Enoumje (groupthink): težnja po dogovoru prevlada nad kritično presojo; člani mislijo, da vsi mislijo enako.","more":"Ključ izpita je tu napačno navajal 'polarizacijo' (D). Opis (norma konsenza, iluzija enotnosti) je značilen za enoumje (E)."},{"q":"Katera trditev o Zimbardovi študiji zaporniških vlog je NAPAČNA?","options":["Študijo so predčasno prekinili, ker je situacija postala neobvladljiva","Uporabljena metoda je bil eksperiment v kontroliranem okolju","Vloge so dodelili glede na osebnost (agresivni so bili paziči)","Pokazala je, kako se ljudje prilagodijo vlogam in pričakovanjem","Vprašanje je bilo, kaj se zgodi, ko 'dober' človek pride v 'zlobno okolje'"],"correct":2,"explanation":"Napačna je trditev c: vloge so dodelili NAKLJUČNO, predhodno testiranje pa je služilo izločitvi k agresiji nagnjenih oseb."},{"q":"Katero stališče opisuje: identifikacija z organizacijo in njenimi cilji ter želja po ohranjanju članstva?","options":["Afektivno stališče","Organizacijska pripadnost","Organizacijsko državljanstvo","Zavzetost","Zadovoljstvo z organizacijo"],"correct":1,"explanation":"To je opredelitev organizacijske pripadnosti."},{"q":"Mateja nadrejenemu pove le tisto, za kar misli, da želi slišati. Kaj je značilno za njeno komuniciranje?","options":["Selektivno zaznavanje","Filtriranje","Zaznavna obramba","Govorice","Žargon"],"correct":1,"explanation":"Filtriranje je namerno prirejanje informacije, da je za prejemnika ugodnejša/zaželena."},{"q":"Katera trditev o emocijah in razpoloženjih je NEPRAVILNA?","options":["Na intenzivnost izražanja emocij vplivajo organizacijski dejavniki in nacionalna kultura","Pozitiven afekt je razpoloženje iz specifičnih pozitivnih emocij","Po teoriji afektivnih dogodkov na zadovoljstvo vplivajo trenutne in pretekle emocije","Razpoloženja trajajo dlje kot emocije in jih povzročajo konkretni dogodki","Raziskave kažejo, da slabo vreme ne vpliva na razpoloženje"],"correct":3,"explanation":"Nepravilna je d: razpoloženja nimajo jasnega/konkretnega sprožilca — to (konkreten dogodek) je značilno za emocije."},{"q":"Na avdiciji ste dobili nižjo oceno, ker je imel kandidat tik pred vami odlične reference. Za kakšno napako gre?","options":["Temeljna napaka pripisovanja","Halo učinek","Učinek kontrasta","Učinek opitosti","Učinek nepravičnosti"],"correct":2,"explanation":"Učinek kontrasta: na oceno vpliva nedavna primerjava z drugim (boljšim) kandidatom."},{"q":"Katera trditev NI Buzanova?","options":["Možgani niso genetsko oblikovani, temveč se oblikujejo z aktivnostjo","Če vodite druge, jim pomagate oblikovati asociativne zveze","Učenje pomeni vzpostavljanje asociativnih zvez","Proces učenja se ob ustrezni aktivnosti odvija celo življenje","Propadanje retencije se imenuje pozabljanje"],"correct":4,"explanation":"Po Buzanu 'pozabljanja ni' — obstaja le brisanje asociativnih zvez, zato je trditev e v nasprotju z njegovim naukom."},{"q":"Za kateri pogled na stres je značilno, da nastopi, ko zahteve iz okolja porušijo naravno ravnotežje?","options":["Psihoanalitski pristop","Homeostatični pristop","Yerkes-Dodsonov zakon","Pristop kognitivne ocene","Pristop skladnosti oseba-okolje"],"correct":1,"explanation":"Homeostatični pristop (Cannon): stres nastopi, ko zunanje zahteve porušijo posameznikovo naravno ravnotežje (homeostazo)."},{"q":"Konflikt delo-družina teoretično opredeljujemo kot ___.","options":["Konflikt oseba-vloga","Konflikt znotraj vloge","Konflikt zaznave vloge","Konflikt med vlogami","Konflikt psihološke pogodbe"],"correct":3,"explanation":"Konflikt delo-družina je oblika konflikta MED vlogami: zahteve dela ovirajo izpolnitev družinske vloge."},{"q":"Katera teorija pojasnjuje verjetnosti trud→uspešnost in uspešnost→nagrade ter vrednost nagrad (instrumentalnost, valenca, pričakovanje)?","options":["Adamsova teorija","Vroomova teorija","Teorija postavljanja ciljev","Alderferjeva teorija","Herzbergova teorija"],"correct":1,"explanation":"To je Vroomova teorija pričakovanj: motivacija = pričakovanje × instrumentalnost × valenca."},{"q":"Katera lastnost se je v raziskavah občudovanih vodij (Kouzes & Posner) vselej uvrstila na prvo mesto?","options":["Inteligentnost","Odločanje","Poštenost","Navdihovanje","Kompetentnost"],"correct":2,"explanation":"Na prvem mestu je bila poštenost (npr. 88 % anketiranih jo je izbralo)."},{"q":"Vodja si izbere pet 'favoritov' ('dream team'), preostalih sedem potisne na obrobje. Katera teorija to pojasnjuje?","options":["Fiedlerjev model","Teorija izmenjave sodelavec-vodja (LMX)","Teorija etičnega vodenja","Hersey-Blanchardova teorija","Raziskave Univerze v Ohiu"],"correct":1,"explanation":"LMX teorija predpostavlja 'in' (priljubljene) in 'out' sodelavce; izmenjave z 'in' so kakovostnejše."},{"q":"Profesor je podvomil v eno metrijsko lastnost metode in raziskavo ponovil. Katero lastnost je preverjal?","options":["Objektivnost","Nobeno od navedenih","Zanesljivost","Občutljivost","Veljavnost"],"correct":2,"explanation":"S ponovitvijo (test-retest) preverjamo zanesljivost — doslednost in ponovljivost rezultatov metode.","more":"Ključ izpita je bil tu negotov ('A???'). Ponovljivost meritve je vidik zanesljivosti (C), ne objektivnosti."},{"q":"Kako imenujemo proces, v katerem se posamezniki prilagodijo organizacijski kulturi podjetja?","options":["Usposabljanje","Sodelovanje","Mentoriranje","Socializacija","Institucionalizacija"],"correct":3,"explanation":"Organizacijska socializacija je proces, skozi katerega novi zaposleni prevzamejo vrednote in norme kulture podjetja."},{"q":"Marko popusti partnerki in se odpove svojim željam, da ohrani harmonijo (ona 'zmaga'). Katero strategijo je uporabil?","options":["Izogibanje","Reševanje problemov","Izglajevanje","Pospeševanje","Emocionalno taktiziranje"],"correct":2,"explanation":"Izglajevanje (prilagajanje): nizka skrb zase, visoka skrb za drugega — popuščanje za ohranitev odnosa.","more":"Ključ izpita je navajal 'izogibanje' (A), a Marko se konfliktu ni izognil — popustil je, kar je izglajevanje (C)."},{"q":"Schefferville: na podlagi katerih kategorij sklepamo o 1) uspešnosti tima in 2) najboljšega posameznika?","options":["Povprečna individualna napaka in napaka tima","Napaka tima in največja individualna napaka","Povprečna in največja individualna napaka","Povprečna in najmanjša individualna napaka","Napaka tima in najmanjša individualna napaka"],"correct":4,"explanation":"Uspešnost tima merimo z napako tima, najboljšega posameznika pa z najmanjšo individualno napako (najmanjši odklon od pravilne razvrstitve)."},{"q":"Katere vrednote izhajajo iz Rokeacheve teorije?","options":["Terminalne / instrumentalne","Tekmovalne / komplementarne","Nacionalne / individualne","Prevzete / ponotranjene","Vrednote X / vrednote Y"],"correct":0,"explanation":"Rokeach loči terminalne (cilji) in instrumentalne (načini doseganja) vrednote."},{"q":"Katere so dimenzije teorije Velikih 5?","options":["Čustvena stabilnost, odprtost, narcisizem, samonadzor, samozavest","Čustvena inteligentnost, makiavelizem, odprtost, vestnost, sprejemljivost","Ekstravertiranost, vestnost, samoučinkovitost, pripadnost, narcisizem","Ekstravertiranost, makiavelizem, proaktivnost, samozavest, tveganje","Ekstravertiranost, sprejemljivost, vestnost, čustvena stabilnost, odprtost"],"correct":4,"explanation":"Velikih 5: ekstravertiranost, sprejemljivost, vestnost, čustvena stabilnost (nevroticizem) in odprtost za izkušnje."},{"q":"Mateja meni, da je uspeh na izpitu odvisen predvsem od sreče in razpoloženja profesorja. Kaj je zanjo značilno?","options":["Makiavelizem","Osebni lokus kontrole","Notranji lokus kontrole","Zunanji lokus kontrole","Temeljni lokus kontrole"],"correct":3,"explanation":"Zunanji lokus kontrole: prepričanje, da dogodke določajo zunanje sile (sreča, drugi), ne posameznik sam."},{"q":"Za katero generacijo so značilne vrednote: ambicije, dosežki, upiranje avtoriteti, prizadevanje za uspeh, lojalnost karieri?","options":["Ljudje v srednjih letih","Baby-Boom generacija","Facebook generacija","Generacija X","Generacija Y"],"correct":1,"explanation":"To so vrednote Baby-Boom generacije (1945–1964)."},{"q":"Katera trditev o organizacijskem vedenju kot znanosti je NAPAČNA?","options":["Uporablja izsledke različnih disciplin (psihologija, sociologija)","Pojave proučuje sistematično z različnimi raziskovalnimi metodami","Po sidru večnivojskosti preučuje raven posameznika, skupine in nacionalno raven","Priznava, da so učinki dejavnosti odvisni tudi od situacije","Priznava, da so organizacije odprti sistemi"],"correct":2,"explanation":"Napačna je c: večnivojskost zajema posameznika, skupino in ORGANIZACIJO — ne 'nacionalne ravni'."},{"q":"Katero vedenje vodje je v skladu s teorijo Y (McGregor)?","options":["Vodja dnevno nadzira delo podrejenih","Vodja natančno pove, kako morajo delati","Vodja zaposlene vključuje v reševanje problemov","Vodja postavi jasna pravila za delo","Vodja zaposlene motivira predvsem z denarjem"],"correct":2,"explanation":"Teorija Y predpostavlja, da zaposleni radi delajo in sprejemajo odgovornost — vodja jih vključuje v reševanje problemov.","more":"Ključ izpita je bil tu negotov ('D???'). Nadzor in jasna pravila ustrezajo teoriji X; vključevanje zaposlenih (C) je značilno za teorijo Y."},{"q":"Iz katere znanstvene discipline organizacijsko vedenje povzema dognanja o primerjavi stališč in vrednot med kulturami?","options":["Psihologije","Sociologije","Antropologije","Političnih znanosti","Socialne psihologije"],"correct":2,"explanation":"Antropologija prispeva primerjalno preučevanje kultur, vrednot in stališč med družbami."}]},{"id":"ov-poudarki","name":"Poudarki pred izpitom","questions":[{"q":"Katera stopnja soodvisnosti pri nalogah je značilna za time v podjetju IDEO?","options":["Soodvisnost pri rezultatih","Recipročna soodvisnost","Poglobljena (popolna) soodvisnost","Združevalna soodvisnost","Funkcionalna soodvisnost"],"correct":2,"explanation":"Pri IDEO gre za poglobljeno (popolno) soodvisnost — najvišjo stopnjo interakcije in koordinacije med člani."},{"q":"Tuckmanov model predvideva, da skupina med opravljanjem nalog SOČASNO oblikuje tudi norme in pričakovanja.","options":["Pravilno","Napačno"],"correct":1,"explanation":"Napačno. Tuckman je stopenjski model (oblikovanje → viharna faza → oblikovanje pravil → izvajanje → zaključevanje); norme so ločena faza, ne sočasna."},{"q":"Nadrejeni razmišlja, ali zaposleni zamuja tudi pri projektih, rokih in odmorih — torej o njegovem vedenju v RAZLIČNIH situacijah. Kateri kriterij Kelleyjeve teorije je to?","options":["Razločevalnost","Konsenzualnost","Doslednost","Primerljivost","Kontrast"],"correct":0,"explanation":"Razločevalnost: ali se oseba v različnih situacijah vede različno ali enako."},{"q":"Kaj je značilno za učinek medenega meseca pri zadovoljstvu z delom?","options":["Ob menjavi službe zaradi nezadovoljstva zadovoljstvo v prvih mesecih na novem mestu močno naraste","Posameznik kljub nezadovoljstvu ostane zaradi navezanosti na podjetje","Posameznik s podobnimi vrednotami kot podjetje ne kaže deviantnega vedenja","Različni zaposleni imajo različno stopnjo zadovoljstva","Pred odpustitvijo preverimo, kdaj je bil zaposleni najbolj zadovoljen"],"correct":0,"explanation":"Učinek medenega meseca: na novem delovnem mestu zadovoljstvo začasno močno naraste (sledi mu lahko 'učinek mačka' — kasnejša prilagoditev)."},{"q":"Če bi bile zaznave le odsev dražljajev, bi vsi ljudje zaznavali enako.","options":["Pravilno","Napačno"],"correct":0,"explanation":"Pravilno. Ravno zato, ker zaznave niso le odsev dražljajev (vplivajo izkušnje, motivi, osebnost), ljudje isto situacijo zaznavajo različno."},{"q":"Če želimo povečati zadovoljstvo pri delu, moramo oblikovati delovna mesta, ki zaposlenim ponujajo izzive.","options":["Pravilno","Napačno"],"correct":0,"explanation":"Pravilno. Med ukrepi za zadovoljstvo je oblikovanje delovnih mest z izzivi (poleg pravičnega plačila, kompetentnih nadrejenih, opolnomočenja)."},{"q":"Dispozicijski model predvideva, da je zadovoljstvo pri delu relativno stabilna, trajna značilnost posameznika.","options":["Pravilno","Napačno"],"correct":0,"explanation":"Pravilno. Po dispozicijskem modelu posameznik zadovoljstvo doživlja podobno v različnih situacijah (stabilna značilnost)."},{"q":"Karasekov model stresa — katera trditev je NAPAČNA?","options":["Model obravnava stres glede na delovne zahteve in stopnjo nadzora","Nizke zahteve in malo nadzora vodijo v pasivnost","Visok nadzor ob visokih zahtevah povzroči preobremenitev","Visok nadzor ob visokih zahtevah lahko vodi v aktivnost (eustres)"],"correct":2,"explanation":"Napačna je c: visok nadzor ob visokih zahtevah = aktivnost/eustres. Preobremenitev (distres) nastopi pri visokih zahtevah in NIZKEM nadzoru."},{"q":"Ustanavljaš dobrodelno društvo in želiš pri kandidatih oceniti dobrohotnost. Katero teorijo vrednot je najbolj smiselno preučiti?","options":["Schwartzovo teorijo individualnih vrednot, predvsem vrednote samopreseganja","Schwartzovo teorijo nacionalnih vrednot, predvsem samopreseganje","Muskovo teorijo vrednot, predvsem potenčne vrednote","Vrednotni sistem podjetja Zappos, predvsem vrednoto WOW"],"correct":0,"explanation":"Dobrohotnost (benevolenca) sodi med vrednote samopreseganja v Schwartzovi teoriji individualnih vrednot."},{"q":"Individualne vrednote so posplošeni motivacijski cilji, zato jih posamezniki spreminjajo vsakih nekaj mesecev.","options":["Pravilno","Napačno"],"correct":1,"explanation":"Napačno. Vrednote so relativno stabilne in trajne; ne spreminjajo se vsakih nekaj mesecev."},{"q":"Andrej je usmerjen v rezultate, vodi z delegiranjem; oddelek je uspešen, zaposleni nekoliko manj zadovoljni. Katera vedenjska vloga (Lipičnik) prevladuje?","options":["Proizvajalec","Administrator","Podjetnik","Integrator"],"correct":0,"explanation":"Proizvajalec: usmerjen v rezultate in učinkovitost, dela prek delegiranja — visoka uspešnost, manj poudarka na zadovoljstvu ljudi."},{"q":"Podjetnik Darjan odhaja; naslednika izbirajo znotraj podjetja. Katera vedenjska vloga je najprimernejša?","options":["Integrator — pozna zaposlene, jih povezuje in ima dobre odnose","Administrator — vodi s pravili in postopki","Proizvajalec — usmerjen v rezultate","Nihče od obstoječih ni primeren"],"correct":0,"explanation":"Najprimernejši je integrator: usmerjen k ljudem, ceni harmonijo, povezuje zaposlene in ima vzpostavljene odnose, kar olajša prevzem vodenja."}]}],"notes":"\n<h2>★ Poudarki za izpit</h2>\n<div class=\"note-card\">\n<h3>Profesoričini poudarki (ni uradni seznam)</h3>\n<ul>\n<li><b>Skupine/timi</b>: Tuckmanov model; <b>Belbin</b> (9 timskih vlog — uspešen tim ne potrebuje 9 ljudi, ena oseba lahko opravlja več vlog); <b>Lipičnikovi vedenjski vzorci</b> (PAEI) + raziskava EF (slo. študenti ≈ paEi).</li>\n<li><b>Primer vodij (14. sklop)</b> — prepoznaj dominantno vlogo: Andrej = <b>proizvajalec</b> (rezultati, delegiranje; oddelek uspešen, ljudje manj zadovoljni); Brane = <b>integrator</b> (motiviranje, povezovanje; manj uspešen, bolj zadovoljni); Cetinski = <b>administrator</b> (pravila, postopki); Darjan = <b>podjetnik</b>. Naslednik znotraj podjetja → najprimernejši <b>integrator</b>.</li>\n<li><b>Vrednote</b>: teorija delovnih vrednot; <b>Schwartz</b> (krog) — osnovna struktura vrednot je univerzalna, hierarhija se med kulturami razlikuje.</li>\n<li><b>Velikih 5</b> in povezave z uspešnostjo — pri timskem delu je dober napovednik predvsem <b>sprejemljivost (prijetnost)</b>. Pregledati tudi kompetence.</li>\n<li><b>Hawthorne</b>: pomen socialnih in medosebnih odnosov za vedenje in uspešnost.</li>\n<li><b>MARS model</b> uspešnosti: odvisna spremenljivka = vedenje/rezultati; dejavniki = <b>m</b>otivacija, <b>a</b>bilities (sposobnosti), <b>r</b>ole perception (zaznava vloge), <b>s</b>ituacijski dejavniki. Znati uporabiti na primeru, ne le našteti.</li>\n<li><b>Fredrickson</b> (razširitev in izgradnja pozitivnih čustev); <b>Zappos</b> (poveži z organizacijsko kulturo/organiziranjem); <b>Cialdini</b> (pravila prepričevanja, ~str. 200).</li>\n</ul>\n</div>\n\n<h2>1 · Uvod v organizacijsko vedenje</h2>\n<div class=\"note-card\">\n<h3>Kaj je OV</h3>\n<ul>\n<li><b>Organizacijsko vedenje (OB)</b>: samostojno raziskovalno področje, ki preučuje vplive posameznikov, skupin in strukture na vedenje v organizacijah, z namenom povečevanja uspešnosti. Multidisciplinarno (psihologija dela, sociologija dela, industrijska razmerja, organizacijska analiza).</li>\n<li><b>Management, temelječ na dokazih</b>: zastaviti vprašanje → poiskati najboljše obstoječe dokaze → uporabiti relevantne dokaze. Ob tem se zavedamo modnih muh in pasti intuicije.</li>\n<li><b>Gradniki uspeha</b>: na dokazih temelječe izobraževanje, na dokazih temelječ management, uspešnost.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Spretnosti, sidra, metode</h3>\n<ul>\n<li><b>Katz</b>: konceptualne (vrhnji mng.), medosebne, tehnične (nižji mng.) spretnosti. <b>Luthans</b>: učinkoviti vs. hitro-napredujoči managerji — 4 aktivnosti: tradicionalni management, komuniciranje, ravnanje z ljudmi, gradnja socialne mreže.</li>\n<li><b>5 sider OV</b>: multidisciplinarnost, sistematično raziskovanje, situacijsko, večnivojskost, odprti sistem.</li>\n<li><b>Metode</b>: meta-analize, terenske študije, vprašalniki, intervjuji, študije primerov, laboratorijski eksperiment.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Izzivi in odvisne spremenljivke</h3>\n<ul>\n<li><b>Izzivi</b>: globalizacija (medkulturna občutljivost), spremembe pri delu (digitalizacija, UI, negotovost), raznolika delovna sila, etika in odgovornost.</li>\n<li><b>Raznolikost</b> — koristi: privablja talente, spodbuja ustvarjalnost, boljše reševanje problemov; problemi: odpor, manko kohezivnosti, konflikti, daljše odločanje.</li>\n<li><b>Najbolj preučevane odvisne spremenljivke</b>: produktivnost, zadovoljstvo pri delu, absentizem, odhod iz podjetja, <b>odklonsko vedenje</b> (krši norme), <b>OCB / organizacijsko državljanstvo</b> (diskrecijsko, izven opisa dela).</li>\n</ul>\n</div>\n\n<h2>2 · Skupine, norme in timi</h2>\n<div class=\"note-card\">\n<h3>Skupine</h3>\n<ul>\n<li><b>Skupina</b>: dva ali več soodvisnih posameznikov v interakciji s skupnim ciljem. Formalna (določena s strukturo) vs neformalna (iz potrebe po stikih).</li>\n<li><b>Tipologije</b>: usmerjevalna, delovna, interesna, prijateljska. Razlogi za vključitev: identiteta, podobnost, razločevalnost, status, zmanjšanje negotovosti.</li>\n<li><b>Tuckman</b>: oblikovanje → viharna faza → oblikovanje pravil → izvajanje → zaključevanje. Model periodičnega ravnotežja: skupina ob polovici naredi preobrat.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Soodvisnost, vloge, norme</h3>\n<ul>\n<li><b>Soodvisnost pri nalogah</b>: združevalna → sekvenčna → recipročna → popolna (najvišja koordinacija). Tudi soodvisnost pri ciljih in pri rezultatih.</li>\n<li><b>Vloge</b>: zaznava vloge, pričakovanja vloge, psihološka pogodba, konflikt vlog. <b>Zimbardo</b>: prilagoditev vlogam.</li>\n<li><b>Norme</b>: sprejeti standardi vedenja. <b>Hawthorne</b>: norme in pripadnost vplivajo bolj kot denar. <b>Konformizem</b>, referenčna skupina, <b>Asch</b> (pritisk skupine).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Velikost, kohezivnost, timi</h3>\n<ul>\n<li><b>Družbeno izmikanje</b> (Ringelmann): manj truda v skupini. Optimalna skupina 5–7 (timi 5–9).</li>\n<li><b>Status</b>: visok status → manj omejen z normami, bolj asertiven. <b>Kohezivnost</b>: manjše skupine, skupni cilji, več skupnega časa, tekmovanje z drugimi, nagrajevanje skupine.</li>\n<li><b>Skupine vs timi</b> (Katzenbach): tim ima vzajemno odgovornost, deljeno vodenje, kolektivni rezultat. <b>Belbin</b> vloge; <b>Adizes/Lipičnik</b> PAEI: proizvajalec, administrator, podjetnik, integrator.</li>\n</ul>\n</div>\n\n<h2>3 · Motivacija in oblikovanje dela</h2>\n<div class=\"note-card\">\n<h3>Osnove in zanos</h3>\n<ul>\n<li>Motivacija = <b>smer → intenzivnost → vztrajnost</b>. Vsebinske (Maslow, Alderfer, Herzberg, McClelland) vs procesne teorije. Ekstrinzično (plačilo, status) vs intrinzično (uživanje, razvoj).</li>\n<li><b>Zanos</b> (Csikszentmihalyi): popolna vpetost; ključno ravnotežje med spretnostmi in izzivi (premalo izzivov → dolgčas, preveč → tesnoba).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Oblikovanje dela in teorije</h3>\n<ul>\n<li><b>Značilnosti dela</b> (Hackman & Oldham): raznolikost zmožnosti, identiteta naloge, pomen naloge, avtonomija, povratne informacije. OMP = ((raznolikost+identiteta+pomen)/3) × avtonomija × povratne info.</li>\n<li><b>Job crafting</b>: preoblikovanje nalog, odnosov, dojemanja (Wrzesniewski); iskanje virov/izzivov, zmanjšanje zahtev (Petrou).</li>\n<li><b>Locke</b>: konkretni in težki cilji + povratne info → višja uspešnost (odvisno od zavezanosti). SMART(ER). <b>MBO</b>. <b>Adams</b> (pravičnost): primerjava vložkov/rezultatov; strategije: sprememba inputov/outputov, popačenje zaznave, menjava reference, odhod.</li>\n</ul>\n</div>\n\n<h2>4 · Stališča, čustva in zaznavanje</h2>\n<div class=\"note-card\">\n<h3>Sreča in zaznavanje</h3>\n<ul>\n<li><b>Broaden-and-build</b> (Fredrickson): pozitivna čustva širijo pozornost in gradijo vire ter trdoživost. Pita sreče: ~50 % genetika, ~40 % namerna dejanja, ~10 % okoliščine.</li>\n<li><b>Napake zaznavanja</b>: učinek kontrasta, stereotipiziranje, projeciranje, halo učinek, selektivno zaznavanje, prvi vtis. Model: zaznavalec – tarča – situacija.</li>\n<li><b>Samouresničujoča prerokba</b>: Pygmalion (visoka pričakovanja dvignejo uspešnost) vs Golem (nizka znižajo).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Pripisovanje in stališča</h3>\n<ul>\n<li><b>Pripisovanje</b> (Heider): notranji/zunanji vzroki. <b>Temeljna napaka pripisovanja</b>: precenjamo notranje, podcenjamo zunanje. <b>Kelley</b>: razločevalnost, konsenzualnost, doslednost.</li>\n<li>Stališča: afektivna, kognitivna, vedenjska komponenta. <b>Kognitivna disonanca</b> (Festinger): neskladje → težnja k skladnosti.</li>\n<li><b>Zadovoljstvo pri delu</b>; učinek medenega meseca / mačka. <b>Pripadnost</b>: afektivna, normativna, kalkulativna; pogosto boljši napovedovalec posledic kot zadovoljstvo. Odzivi na nezadovoljstvo: glas, odhod, zvestoba, zanemarjanje.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Čustva</h3>\n<ul>\n<li><b>Afekt</b> = emocije (močne, usmerjene, kratke) + razpoloženje (šibkejše, brez sprožilca, dlje). <b>Ekman</b>: 6 čustev; <b>Plutchik</b>: 4 pari.</li>\n<li><b>Emocionalno delo</b>: površinsko (le izraz) vs globinsko igranje (sprememba občutij). Emocionalna disonanca; emocionalna okužba. <b>Teorija afektivnih dogodkov</b> (AET).</li>\n</ul>\n</div>\n\n<h2>5 · Etika in vrednote</h2>\n<div class=\"note-card\">\n<ul>\n<li><b>Vrednote</b>: prepričanja o zaželenih končnih stanjih, urejena po pomembnosti. <b>Rokeach</b>: terminalne (cilji) vs instrumentalne (načini). <b>Musek</b>: hedonske, potenčne, moralne, izpolnitvene. <b>Schwartz</b>: krožni model.</li>\n<li><b>Etika</b>: standardi vedenja; <b>moralni problem</b>, <b>etična dilema</b> (izbira med slabimi možnostmi). Veji: preskriptivna in deskriptivna.</li>\n<li><b>Kohlberg</b>: prekonvencionalna → konvencionalna → postkonvencionalna stopnja. <b>Rest</b>: prepoznava problema → presoja → namera → vedenje.</li>\n<li><b>Relativizem</b> (nobena kultura ni boljša) vs <b>imperializem</b> (standardi matične države). <b>Ugašanje etičnosti</b>; etična linija; etični kodeks.</li>\n</ul>\n</div>\n\n<h2>6 · Stres</h2>\n<div class=\"note-card\">\n<ul>\n<li><b>Stres</b>: adaptivni odgovor na prekomerne zahteve; <b>stresor</b> = sprožilec. <b>Izzivni</b> (priložnost) vs <b>zavirajoči</b>; <b>eustres</b> vs <b>distres</b>.</li>\n<li>Posledice: fiziološke, psihološke, vedenjske; <b>izgorelost</b> (izčrpanost, depersonalizacija, malo osebnih uspehov).</li>\n<li>Pogledi: Cannon (homeostaza, fight-or-flight), Lazarus (kognitivna ocena), Kahn (P-E fit), Levinson (psihoanalitični). <b>Naučena nemoč</b> (Seligman); model <b>zahteve-nadzor</b> (Karasek).</li>\n<li>Konflikt vlog: med vlogami (delo-družina), znotraj vloge, oseba-vloga; dvoumnost vloge; pre-/podobremenjenost. Obvladovanje: čuječnost, spanec, gibanje; osredotočeno na problem vs na čustva (Latack, Havlovic).</li>\n</ul>\n</div>\n\n<h2>7 · Vodenje</h2>\n<div class=\"note-card\">\n<h3>Pristopi in slogi</h3>\n<ul>\n<li><b>Vodenje</b>: zmožnost vplivanja na skupino k ciljem. <b>Čustvena inteligentnost</b> (Goleman): samozavedanje, samoobvladovanje, družbeno zavedanje, obvladovanje odnosov.</li>\n<li><b>Karizmatično</b>: vizija, osebno tveganje, ocena razmer, dovzetnost za potrebe, nekonvencionalno vedenje. Temni vidiki: <b>makiavelizem</b> (cilj opravičuje sredstva), <b>narcisizem</b>.</li>\n<li><b>Etično</b> (Brown), <b>uslužnostno</b> (servant — najprej služiti), <b>LMX</b> (in/out skupina).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Teorije vodenja</h3>\n<ul>\n<li><b>Osebnostne</b> (trait): omejitev — ni univerzalnih lastnosti. Spol: <b>stekleni strop</b> (navzgor), <b>steklena stena</b> (horizontalno), <b>stekleni previs</b> (vodenje v krizi).</li>\n<li><b>Vedenjske</b>: Ohio (initiating structure vs consideration), Michigan (k ljudem vs k nalogam).</li>\n<li><b>Situacijske</b>: Fiedler (stil fiksen; odnos vodja–člani, definiranost naloge, moč vodje). <b>Transakcijsko</b> (nagrade, mng. z izjemami, laissez-faire) vs <b>transformacijsko</b> (idealiziran vpliv, inspiracija, intelektualna stimulacija, upoštevanje posameznika).</li>\n</ul>\n</div>\n\n<h2>8 · Osebnost, moč in konflikt</h2>\n<div class=\"note-card\">\n<h3>Osebnost</h3>\n<ul>\n<li>Teorije: dispozicijska (poteze), psihodinamska (Freud: id, ego, superego), humanistična (Rogers: samoaktualizacija), integrativni pristop.</li>\n<li><b>Velikih 5</b>: ekstravertiranost, sprejemljivost, vestnost, čustvena stabilnost, odprtost. <b>MBTI</b>: E/I, S/N, T/F, J/P.</li>\n<li><b>Lokus kontrole</b> (notranji/zunanji); <b>motivacijski fokus</b> (napredovanje/preprečevanje); <b>psihološki kapital</b> (samozaupanje, upanje, optimizem, trdoživost); samoučinkovitost vs samozavest.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Moč, vpliv, konflikt</h3>\n<ul>\n<li><b>Moč</b>: zmožnost vplivati na vedenje drugih; avtoriteta = vir moči; politika. <b>Odvisnost</b> raste s pomenom, redkostjo, nenadomestljivostjo. McClelland: osebna (JAZ) vs družbena (MI) moč.</li>\n<li><b>French & Raven</b> — položaj: legitimna, prisile, nagrajevanja, informacij; oseba: ekspertna, referenčna (+ karizma). <b>Milgram</b>: ~65 % sledilo avtoriteti.</li>\n<li><b>Cialdini</b>: recipročnost, redkost, avtoriteta, skladnost, všečnost, konsenz. <b>Asertivna komunikacija</b> (presek agresivnega in pasivnega). Konflikt: tradicionalni vs moderni pogled; tipi: vsebinski, čustveni, procesni.</li>\n</ul>\n</div>\n\n<h2>9 · Dodatne teme (managment, kultura, komunikacija, učenje)</h2>\n<div class=\"note-card\">\n<h3>Managerske vloge in kultura</h3>\n<ul>\n<li><b>Mintzbergove vloge</b>: medosebne (predstavnik, vodja, povezovalec), <b>informacijske</b> (sprejemalec, posredovalec, zastopnik/govorec) in odločitvene (podjetnik, reševalec motenj, razporejevalec virov, pogajalec).</li>\n<li><b>Organizacijska kultura</b> (Schein): artefakti (vidno — logo, barve, prostori, arhitektura) → izražene vrednote → temeljne predpostavke (nezavedno). \"Pogledati je treba pod površino artefaktov.\"</li>\n<li><b>Socializacija</b>: proces, skozi katerega novi zaposleni prevzamejo vrednote in norme kulture.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Komunikacija, učenje, ustvarjalnost</h3>\n<ul>\n<li><b>Ovire v komunikaciji</b>: filtriranje (prirejanje sporočila prejemniku v prid), selektivno zaznavanje, zaznavna obramba, <b>govorice</b> (neformalne, nenadzorovane), žargon.</li>\n<li><b>Učenje</b>: relativno trajna sprememba vedenja iz izkušenj. Klasično pogojevanje (Pavlov) vs <b>instrumentalno/operantno</b> (nagrajeno vedenje pogosteje ponovimo, nenagrajeno redkeje). <b>Buzan</b> (žarčno učenje): učenje = asociativne zveze; \"pozabljanja ni\", le brisanje asociacij.</li>\n<li><b>Ustvarjalni proces</b>: priprava → <b>inkubacija</b> → iluminacija (uvid) → verifikacija. Skupinske tehnike: nevihta možganov, 6-3-5, Philips 66, Delfi.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Motivacija (dodatno), X/Y, merske lastnosti</h3>\n<ul>\n<li><b>Vroomova teorija pričakovanj</b>: motivacija = pričakovanje (trud→uspešnost) × instrumentalnost (uspešnost→nagrada) × valenca (vrednost nagrade).</li>\n<li><b>McClelland</b>: potreba po dosežkih, po moči in po <b>povezanosti</b> (ne po varnosti).</li>\n<li><b>McGregor</b> — teorija X (ljudje se izogibajo delu in odgovornosti → nadzor) vs teorija Y (delo je naravno, sprejemajo odgovornost → vključevanje v odločanje).</li>\n<li><b>Metrijske lastnosti metode</b>: objektivnost, <b>zanesljivost</b> (doslednost/ponovljivost), veljavnost, občutljivost.</li>\n<li><b>Enoumje (groupthink)</b>: norma konsenza prevlada nad realistično presojo (iluzija enotnosti).</li>\n</ul>\n</div>\n","flashcards":[{"id":"fc-ov1","name":"Uvod v OV","cards":[{"front":"Organizacijsko vedenje (OB)","back":"Področje o vplivih posameznikov, skupin in strukture na vedenje v organizacijah, za večjo uspešnost."},{"front":"5 sider OV","back":"Multidisciplinarnost, sistematično raziskovanje, situacijsko, večnivojskost, odprti sistem."},{"front":"Management na dokazih","back":"Zastavi vprašanje → poišči najboljše dokaze → uporabi jih."},{"front":"Katzove spretnosti","back":"Konceptualne (vrh), medosebne, tehnične (nižji management)."},{"front":"Luthans — 4 aktivnosti","back":"Tradicionalni management, komuniciranje, ravnanje z ljudmi, gradnja socialne mreže."},{"front":"OCB (organizacijsko državljanstvo)","back":"Diskrecijsko vedenje izven opisa dela, ki koristi organizaciji."},{"front":"Odklonsko vedenje","back":"Prostovoljno vedenje, ki krši pomembne organizacijske norme."}]},{"id":"fc-ov2","name":"Skupine, norme in timi","cards":[{"front":"Skupina","back":"Dva ali več soodvisnih posameznikov v interakciji s skupnim ciljem."},{"front":"Tuckmanove faze","back":"Oblikovanje → viharna faza → oblikovanje pravil → izvajanje → zaključevanje."},{"front":"Soodvisnost pri nalogah","back":"Združevalna → sekvenčna → recipročna → popolna (najvišja koordinacija)."},{"front":"Zimbardo / Asch","back":"Zimbardo: prilagoditev vlogam; Asch: pritisk skupine → konformizem."},{"front":"Družbeno izmikanje","back":"Ringelmann: posameznik v skupini vloži manj truda."},{"front":"Skupina vs tim (Katzenbach)","back":"Tim: vzajemna odgovornost, deljeno vodenje, kolektivni rezultat; optimalno 5–9."},{"front":"Adizes/Lipičnik PAEI","back":"Proizvajalec, administrator, podjetnik, integrator."}]},{"id":"fc-ov3","name":"Motivacija in delo","cards":[{"front":"Katere 3 sestavine ima motivacija?","back":"Smer (kam usmerimo trud), intenzivnost (koliko truda) in vztrajnost (kako dolgo)."},{"front":"Vsebinske vs procesne teorije motivacije","back":"Vsebinske preučujejo POTREBE, ki motivirajo (Maslow, Herzberg, McClelland); procesne preučujejo MISELNE PROCESE (Locke, Adams)."},{"front":"Maslowova hierarhija potreb","back":"Pet ravni od spodaj navzgor: fiziološke → varnost → pripadnost → ugled → samopotrjevanje. Nižji red (fiziološke, varnost) se zadovolji eksterno, višji red interno.","svg":"<svg viewBox=\"0 0 240 150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-height:150px\">\n        <polygon points=\"120,8 150,40 90,40\" fill=\"var(--terra)\"/>\n        <polygon points=\"88,42 152,42 168,72 72,72\" fill=\"var(--teal)\" opacity=\"0.85\"/>\n        <polygon points=\"70,74 170,74 186,104 54,104\" fill=\"var(--ink2)\" opacity=\"0.55\"/>\n        <polygon points=\"52,106 188,106 204,136 36,136\" fill=\"var(--ink2)\" opacity=\"0.35\"/>\n        <text x=\"120\" y=\"30\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\">Samopotrj.</text>\n        <text x=\"120\" y=\"61\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\">Ugled</text>\n        <text x=\"120\" y=\"93\" font-size=\"8\" fill=\"var(--ink)\" text-anchor=\"middle\">Pripadnost</text>\n        <text x=\"120\" y=\"124\" font-size=\"8\" fill=\"var(--ink)\" text-anchor=\"middle\">Varnost / fiziološke</text>\n      </svg>"},{"front":"Herzbergova dvofaktorska teorija","back":"Higieniki (plača, pogoji, nadzor) le preprečijo nezadovoljstvo; motivatorji (dosežki, priznanje, rast) ustvarjajo zadovoljstvo."},{"front":"Zanos (flow) — kdaj nastopi?","back":"Ko sta spretnost in izziv v ravnotežju. Premalo izziva → dolgčas; preveč izziva → tesnoba; usklajeno → zanos.","svg":"<svg viewBox=\"0 0 200 150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-height:150px\">\n        <line x1=\"30\" y1=\"130\" x2=\"190\" y2=\"130\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n        <line x1=\"30\" y1=\"130\" x2=\"30\" y2=\"15\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n        <polygon points=\"30,130 190,15 150,15 30,110\" fill=\"var(--teal)\" opacity=\"0.3\"/>\n        <line x1=\"30\" y1=\"130\" x2=\"190\" y2=\"15\" stroke=\"var(--teal)\" stroke-width=\"2\"/>\n        <text x=\"95\" y=\"55\" font-size=\"9\" fill=\"var(--ink)\" transform=\"rotate(-32 95 55)\">ZANOS</text>\n        <text x=\"70\" y=\"35\" font-size=\"8\" fill=\"var(--red)\">Tesnoba</text>\n        <text x=\"120\" y=\"118\" font-size=\"8\" fill=\"var(--ink2)\">Dolgčas</text>\n        <text x=\"100\" y=\"146\" font-size=\"8\" fill=\"var(--ink2)\" text-anchor=\"middle\">Spretnost →</text>\n        <text x=\"14\" y=\"80\" font-size=\"8\" fill=\"var(--ink2)\" transform=\"rotate(-90 14 80)\">Izziv →</text>\n      </svg>"},{"front":"Značilnosti dela (Hackman & Oldham)","back":"5 dimenzij: raznolikost zmožnosti, identiteta naloge, pomen naloge, avtonomija, povratne info. OMP = ((razn.+ident.+pomen)/3) × avtonomija × povratne info."},{"front":"Lockejeva teorija ciljev","back":"Konkretni in zahtevni cilji + povratne informacije → višja uspešnost (odvisno od zavezanosti cilju). Cilji naj bodo SMART."},{"front":"Adamsova teorija pravičnosti","back":"Posameznik primerja razmerje vložki/rezultati z referenco. Ob zaznani nepravičnosti: spremeni vložke/rezultate, popači zaznavo, zamenja referenco ali odide."}]},{"id":"fc-ov4","name":"Stališča, čustva, zaznave","cards":[{"front":"Broaden-and-build","back":"Pozitivna čustva širijo pozornost in gradijo vire ter trdoživost."},{"front":"Halo učinek","back":"Splošni vtis o osebi na osnovi ene same značilnosti."},{"front":"Temeljna napaka pripisovanja","back":"Precenjamo notranje in podcenjamo zunanje vzroke tujega vedenja."},{"front":"Kelley — pripisovanje","back":"Razločevalnost, konsenzualnost, doslednost."},{"front":"Kognitivna disonanca (Festinger)","back":"Neskladje stališč/vedenja → težnja k skladnosti."},{"front":"Emocije vs razpoloženje","back":"Emocije: močne, usmerjene, kratke; razpoloženje: šibko, brez sprožilca, daljše."},{"front":"Površinsko vs globinsko igranje","back":"Površinsko = le izraz; globinsko = sprememba notranjih občutij."},{"front":"Organizacijska pripadnost","back":"Identifikacija z organizacijo in želja ostati član."}]},{"id":"fc-ov5","name":"Etika in vrednote","cards":[{"front":"Rokeach","back":"Terminalne vrednote (cilji) vs instrumentalne (načini)."},{"front":"Musek","back":"Hedonske, potenčne, moralne, izpolnitvene vrednote."},{"front":"Etična dilema","back":"Izbira med dvema ali več etično neugodnimi možnostmi."},{"front":"Kohlberg","back":"Prekonvencionalna → konvencionalna → postkonvencionalna stopnja."},{"front":"Relativizem vs imperializem","back":"Relativizem: nobena kultura ni boljša; imperializem: standardi matične države."},{"front":"Ugašanje etičnosti","back":"Etična komponenta odločitve postopoma zbledi (ethical fading)."}]},{"id":"fc-ov6","name":"Stres","cards":[{"front":"Stres vs stresor","back":"Stres = adaptivni odgovor; stresor = sprožilec."},{"front":"Eustres vs distres","back":"Eustres = pozitiven; distres = negativen stres."},{"front":"Izzivni vs zavirajoči stresorji","back":"Izzivni = priložnost za rast; zavirajoči = ovira za cilje."},{"front":"Naučena nemoč (Seligman)","back":"Občutek izgube kontrole ob neizogibnem negativnem dogodku."},{"front":"Izgorelost — 3 komponente","back":"Izčrpanost, depersonalizacija, malo osebnih uspehov."},{"front":"Karasekov model (zahteve-nadzor)","back":"Stres je funkcija zahtev dela in nadzora nad delom. Najbolj obremenjujoče (distres) je pri VISOKIH zahtevah in NIZKEM nadzoru.","svg":"<svg viewBox=\"0 0 220 150\" xmlns=\"http://www.w3.org/2000/svg\" style=\"width:100%;max-height:150px\">\n        <rect x=\"55\" y=\"20\" width=\"65\" height=\"50\" fill=\"var(--teal)\" opacity=\"0.25\"/>\n        <rect x=\"120\" y=\"20\" width=\"65\" height=\"50\" fill=\"var(--teal)\" opacity=\"0.5\"/>\n        <rect x=\"55\" y=\"70\" width=\"65\" height=\"50\" fill=\"var(--ink2)\" opacity=\"0.25\"/>\n        <rect x=\"120\" y=\"70\" width=\"65\" height=\"50\" fill=\"var(--red)\" opacity=\"0.45\"/>\n        <text x=\"87\" y=\"48\" font-size=\"7.5\" fill=\"var(--ink)\" text-anchor=\"middle\">Nizka obrem.</text>\n        <text x=\"152\" y=\"44\" font-size=\"7.5\" fill=\"var(--ink)\" text-anchor=\"middle\">Aktivnost</text>\n        <text x=\"152\" y=\"54\" font-size=\"7\" fill=\"var(--ink2)\" text-anchor=\"middle\">(eustres)</text>\n        <text x=\"87\" y=\"98\" font-size=\"7.5\" fill=\"var(--ink)\" text-anchor=\"middle\">Pasivnost</text>\n        <text x=\"152\" y=\"94\" font-size=\"7.5\" fill=\"var(--ink)\" text-anchor=\"middle\">Preobrem.</text>\n        <text x=\"152\" y=\"104\" font-size=\"7\" fill=\"var(--ink2)\" text-anchor=\"middle\">(distres)</text>\n        <text x=\"120\" y=\"138\" font-size=\"8\" fill=\"var(--ink2)\" text-anchor=\"middle\">Zahteve dela →</text>\n        <text x=\"14\" y=\"72\" font-size=\"8\" fill=\"var(--ink2)\" transform=\"rotate(-90 14 72)\">Nadzor →</text>\n      </svg>"},{"front":"Konflikt oseba-vloga","back":"Zahteva po vedenju, ki ni skladno z vrednotami osebe."}]},{"id":"fc-ov7","name":"Vodenje","cards":[{"front":"Vodenje","back":"Zmožnost vplivanja na skupino v smeri ciljev."},{"front":"Goleman — čustvena inteligentnost","back":"Samozavedanje, samoobvladovanje, družbeno zavedanje, obvladovanje odnosov."},{"front":"Karizmatično vodenje","back":"Vizija, osebno tveganje, ocena razmer, dovzetnost za potrebe, nekonvencionalnost."},{"front":"Ohio vs Michigan","back":"Ohio: struktura vs odnosi; Michigan: usmerjenost k ljudem vs k nalogam."},{"front":"Fiedler","back":"Stil je fiksen; uskladi vodjo s situacijo (odnos, naloga, moč)."},{"front":"Transakcijsko vs transformacijsko","back":"Transakcijsko: nagrade/izjeme; transformacijsko: vizija, inspiracija, intel. stimulacija, upoštevanje."},{"front":"Steklene ovire pri napredovanju žensk","back":"Stekleni STROP = nevidna meja pri napredovanju navzgor; steklena STENA = meja pri horizontalnem premeščanju; stekleni PREVIS = ženske pogosteje napredujejo v krizah z visokim tveganjem neuspeha."}]},{"id":"fc-ov8","name":"Osebnost, moč, konflikt","cards":[{"front":"Freud","back":"Id (impulzi), superego (vest/vrednote), ego (kompromisi)."},{"front":"Velikih 5","back":"Ekstravertiranost, sprejemljivost, vestnost, čustvena stabilnost, odprtost."},{"front":"Lokus kontrole","back":"Notranji (sam vplivam) vs zunanji (zunaj moje kontrole)."},{"front":"Motivacijski fokus","back":"Napredovanje (nagrade, hitrost) vs preprečevanje (previdnost, najslabše)."},{"front":"Psihološki kapital","back":"Samozaupanje, upanje, optimizem, trdoživost."},{"front":"French & Raven","back":"Položaj: legitimna, prisile, nagrajevanja, informacij; oseba: ekspertna, referenčna."},{"front":"Odvisnost (vir moči)","back":"Raste s pomenom, redkostjo in nenadomestljivostjo vira."},{"front":"Milgramov eksperiment (ubogljivost)","back":"Vprašanje: kako daleč gre človek, ko mu avtoriteta ukaže škoditi drugemu? Udeleženec ('učitelj') je ob napaki 'učenca' pritiskal gumb za vse močnejši (navidezni) sunek. Rezultat: ~65 % je sledilo avtoriteti do najvišje stopnje."},{"front":"Cialdinijevih 6 pravil prepričevanja","back":"Recipročnost (dajanje za prejemanje), redkost (omejene ponudbe), avtoriteta (sledenje strokovnjakom), skladnost (moč obljub), všečnost (raje ugodimo všečnim) in konsenz (sledenje drugim)."},{"front":"Tipi konflikta","back":"Vsebinski (različni pogledi na odločitev), čustveni (osebnostne razlike in napetosti), procesni (nesoglasja o tem, kako naj skupina dela)."}]},{"id":"fc-ov-dodatni","name":"Dodatni pojmi (izpit)","cards":[{"front":"Mintzbergove managerske vloge","back":"Tri skupine: medosebne (predstavnik, vodja, povezovalec), INFORMACIJSKE (sprejemalec, posredovalec, zastopnik/govorec) in odločitvene (podjetnik, reševalec motenj, razporejevalec virov, pogajalec)."},{"front":"Organizacijska kultura in artefakti (Schein)","back":"Kulturo razumemo skozi ravni: artefakti (vidno — logo, barve, prostori, arhitektura), izražene vrednote in temeljne predpostavke (nezavedno). 'Pogledati je treba pod površino artefaktov.'"},{"front":"Socializacija","back":"Proces, skozi katerega novi zaposleni prevzamejo vrednote, norme in vedenje organizacijske kulture."},{"front":"Komunikacijske ovire","back":"Filtriranje (prirejanje sporočila prejemniku v prid), selektivno zaznavanje, zaznavna obramba, govorice (neformalne, nenadzorovane) in žargon."},{"front":"Klasično vs instrumentalno pogojevanje","back":"Klasično (Pavlov): povezovanje dražljajev. Instrumentalno/operantno: nagrajeno vedenje pogosteje ponovimo, nenagrajeno redkeje."},{"front":"Žarčno učenje (Buzan)","back":"Učenje = vzpostavljanje asociativnih zvez; možgani se oblikujejo z aktivnostjo; 'pozabljanja ni' — obstaja le brisanje asociacij. Orodje: miselni vzorci."},{"front":"Faze ustvarjalnega procesa","back":"Priprava → inkubacija ('odložiš' problem) → iluminacija (uvid) → verifikacija (preverjanje rešitve)."},{"front":"Vroomova teorija pričakovanj","back":"Motivacija = pričakovanje (trud→uspešnost) × instrumentalnost (uspešnost→nagrada) × valenca (vrednost nagrade)."},{"front":"McClellandove tri potrebe","back":"Potreba po dosežkih, po moči in po POVEZANOSTI (pripadnosti). Pozor: NE po varnosti."},{"front":"Teoriji X in Y (McGregor)","back":"Teorija X: ljudje ne marajo dela, se izogibajo odgovornosti → nadzor in pravila. Teorija Y: delo je naravno, sprejemajo odgovornost → vključevanje v odločanje."},{"front":"Metrijske lastnosti metode","back":"Objektivnost (neodvisnost od ocenjevalca), zanesljivost (doslednost/ponovljivost), veljavnost (meri, kar naj bi) in občutljivost (loči med posamezniki)."},{"front":"Enoumje (groupthink)","back":"Norma konsenza prevlada nad realistično oceno; iluzija enotnosti, pritisk na drugače misleče. Zmanjša kakovost odločitev."},{"front":"Strategije ravnanja v konfliktu","back":"Glede na skrb zase in za drugega: reševanje problemov (visoko/visoko), izglajevanje (nizko/visoko), kompromis (srednje), izogibanje (nizko/nizko), pospeševanje/prevladovanje (visoko/nizko)."}]}]}]},{"id":"rac","name":"Uvod v računovodstvo","tier":"B","parts":[{"id":"izpit","name":"Izpit","type":"izpit","decks":[{"id":"rk1","name":"Kviz 1 — Temelji in izkazi","questions":[{"q":"Metodo dvostavnega knjigovodstva so iznašli:","options":["Babilonci okoli leta 3600 pr. n. št.","italijanski trgovci v srednjem veku (12.–13. stoletje)","angleški industrialci v 19. stoletju","rimski trgovci v času menjalne trgovine"],"correct":1,"explanation":"Dvostavno knjigovodstvo so razvili italijanski trgovci v srednjem veku (12.–13. stoletje). Stroškovno računovodstvo se je razvilo precej kasneje, v 19. stoletju z industrijsko revolucijo."},{"q":"Katera trditev o razliki med podjetji in zavodi je pravilna?","options":["Podjetja delujejo na področju negospodarstva, zavodi pa na gospodarskem področju.","Tako podjetja kot zavodi imajo za glavni cilj doseganje dobička.","Podjetja poslujejo v razmerah tveganja z bistvenim ciljem dobička, zavodi pa zadovoljujejo širše družbene potrebe.","Zavodi poslujejo v razmerah tveganja, podjetja pa ne."],"correct":2,"explanation":"Podjetja so na gospodarskem področju delujoče organizacije, ki poslujejo v razmerah tveganja – bistven pomen imata dobiček in skrb za razvoj. Zavodi delujejo na področju negospodarstva, njihov cilj je zadovoljevanje širših družbenih potreb in ne dobiček."},{"q":"Računovodstvo je del:","options":["izvajalnega poslovnega sistema","odločevalnega poslovnega sistema","informacijskega sistema","nabavne funkcije podjetja"],"correct":2,"explanation":"Računovodstvo je del informacijskega sistema podjetja – je dejavnost vrednostnega spremljanja in proučevanja pojavov, povezanih s poslovanjem poslovnega sistema."},{"q":"Katera od naštetih NI temeljna računovodska funkcija?","options":["knjigovodstvo","računovodsko predračunavanje","računovodsko analiziranje","računovodsko oglaševanje"],"correct":3,"explanation":"Temeljne računovodske funkcije so štiri: knjigovodstvo, računovodsko predračunavanje, računovodsko nadziranje in računovodsko analiziranje. »Računovodsko oglaševanje« ne obstaja."},{"q":"Katera računovodska funkcija se ukvarja s podatki o prihodnosti?","options":["knjigovodstvo","računovodsko predračunavanje","računovodsko nadziranje","računovodsko analiziranje"],"correct":1,"explanation":"Knjigovodstvo spremlja preteklost (pretekle poslovne dogodke). Računovodsko predračunavanje pa se ukvarja s prihodnostjo – z načrtovanimi poslovnimi procesi in stanji."},{"q":"Kakšno je razmerje med pojmoma knjigovodstvo in računovodstvo?","options":["Knjigovodstvo je širši pojem in vsebuje računovodstvo.","Računovodstvo je širši pojem; poleg knjigovodstva vsebuje še predračunavanje, nadziranje in analiziranje.","Knjigovodstvo vključuje tudi predračunavanje in analiziranje.","Knjigovodstvo in računovodstvo sta sopomenki."],"correct":1,"explanation":"Računovodstvo je širši pojem – poleg knjigovodstva vsebuje še tri računovodske funkcije (predračunavanje, nadziranje, analiziranje). Knjigovodstvo se ukvarja le s spremljanjem podatkov o preteklem poslovanju."},{"q":"Kateri od naštetih je NOTRANJI uporabnik računovodskih informacij?","options":["posojilodajalci (banke)","država","poslovodstvo","dobavitelji"],"correct":2,"explanation":"Notranji uporabniki so poslovodstvo, lastniki z aktivno pravico odločanja in zaposleni. Posojilodajalci, država, dobavitelji, kupci in konkurenti so zunanji uporabniki."},{"q":"Poročanje zunanjim uporabnikom računovodskih informacij je osnovni namen:","options":["stroškovnega računovodstva","poslovodnega računovodstva","finančnega računovodstva","računovodskega nadziranja"],"correct":2,"explanation":"Finančno računovodstvo zbira in poroča podatke o poslovanju podjetja zunanjim uporabnikom (sredstva, obveznosti do virov, poslovni izid)."},{"q":"Katera trditev o stroškovnem računovodstvu drži?","options":["Pripravlja računovodske izkaze za zunanje poročanje.","Spremlja in proučuje notranje poslovanje podjetja ter daje analitične podatke.","Namenjeno je izključno državi in davčni upravi.","Za delovanje finančnega računovodstva ni potrebno."],"correct":1,"explanation":"Stroškovno računovodstvo spremlja in proučuje notranje poslovanje podjetja (poslovni izid po enotah, poslovni učinki, stroški prvin). Daje analitične podatke, ki so ključni za finančno in poslovodno računovodstvo."},{"q":"Po katerih standardih praviloma vodijo računovodstvo majhna in srednja slovenska podjetja, ki ne kotirajo na borzi?","options":["SRS – Slovenski računovodski standardi","MSRP – Mednarodni standardi računovodskega poročanja","ameriški standardi US GAAP","samo po ZGD, brez računovodskih standardov"],"correct":0,"explanation":"SRS sprejema Slovenski inštitut za revizijo; uporabljajo jih majhna in srednja podjetja. MSRP (sprejema Odbor za mednarodne računovodske standarde) uporabljajo velika podjetja oz. tista, ki kotirajo na borzi."},{"q":"Kaj glede računovodskih standardov določa Zakon o gospodarskih družbah (ZGD)?","options":["Da slovenske računovodske standarde sprejema Agencija za trg vrednostnih papirjev.","Da morajo vsa podjetja obvezno uporabljati mednarodne standarde.","Da lahko slovenska podjetja za zunanje poročanje uporabljajo SRS ali MSRP.","Da morajo banke in zavarovalnice obvezno uporabljati SRS."],"correct":2,"explanation":"ZGD določa, da lahko slovenska podjetja za zunanje računovodsko poročanje uporabljajo bodisi slovenske računovodske standarde bodisi mednarodne standarde računovodskega poročanja."},{"q":"Temeljni notranji akt, ki ureja delovanje računovodstva v posameznem podjetju, se imenuje:","options":["statut o računovodstvu","pravilnik o računovodstvu","kontni načrt","letno poročilo"],"correct":1,"explanation":"Pravilnik o računovodstvu je temeljni notranji akt, ki ureja delovanje računovodstva v posameznem podjetju."},{"q":"Kateri sta temeljni računovodski predpostavki, na katerih temelji računovodstvo?","options":["razumljivost in primerljivost","upoštevanje nastanka poslovnih dogodkov in časovna neomejenost delovanja","zanesljivost in ustreznost","natančnost informacij in pogostost poročanja"],"correct":1,"explanation":"Temeljni računovodski predpostavki sta upoštevanje nastanka poslovnih dogodkov (dogodki se zabeležijo ob nastanku, ne ob plačilu) in upoštevanje časovne neomejenosti delovanja (podjetje obravnavamo kot delujoče, ki bo poslovalo tudi v prihodnosti)."},{"q":"Upoštevanje nastanka poslovnega dogodka pomeni, da se prihodki, odhodki in stroški:","options":["zabeležijo šele takrat, ko podjetje prejme oziroma plača denar","zabeležijo takoj ob njihovem nastanku, ne glede na povezane denarne tokove","prikažejo na razumljiv, ustrezen in primerljiv način","pojavijo le, če podjetje namerava ustaviti poslovanje"],"correct":1,"explanation":"Po tej predpostavki se poslovni dogodki zabeležijo takoj ob nastanku in ne šele, ko nastanejo z njimi povezani denarni tokovi – torej ne upoštevamo načela denarnih tokov."},{"q":"Katera od naštetih NI kakovostna značilnost računovodskih informacij?","options":["razumljivost","zanesljivost","dobičkonosnost","primerljivost"],"correct":2,"explanation":"Kakovostne značilnosti računovodskih informacij so štiri: razumljivost, ustreznost, zanesljivost in primerljivost. Dobičkonosnost mednje ne sodi."},{"q":"Katera trditev o poslovodnem računovodstvu v primerjavi s finančnim drži?","options":["Poslovodno računovodstvo je strogo predpisano z zakonom in standardi.","Poslovodno računovodstvo poroča letno, finančno pa dnevno.","Poslovodno računovodstvo je namenjeno notranjim uporabnikom in pogosteje poroča.","Finančno računovodstvo je namenjeno notranjim uporabnikom."],"correct":2,"explanation":"Poslovodno računovodstvo pripravlja informacije za notranje uporabnike, poroča pogosteje (mesečno, tedensko ali celo dnevno), način priprave pa ni nujno predpisan. Finančno računovodstvo je namenjeno zunanjim uporabnikom, poroča letno in upošteva računovodske standarde."},{"q":"Bilanca stanja je računovodski izkaz, ki prikazuje:","options":["prihodke in odhodke podjetja v obdobju","premoženjsko in finančno stanje podjetja na določen dan","denarne tokove podjetja v obdobju","gibanje kapitala med poslovnim letom"],"correct":1,"explanation":"Bilanca stanja je temeljni računovodski izkaz, ki prikazuje višino in strukturo sredstev ter obveznosti do virov sredstev podjetja na določen dan – torej premoženjski in finančni položaj."},{"q":"Bilanca stanja je:","options":["dinamičen izkaz, ki se nanaša na obdobje","statičen in kumulativen izkaz, ki kaže stanje na določen dan","izkaz, ki prikazuje izključno poslovni izid","izkaz denarnih tokov pri poslovanju"],"correct":1,"explanation":"Bilanca stanja je statična (kaže stanje določenega dne) in kumulativna (v njej so vidne posledice vseh preteklih poslovnih odločitev podjetja)."},{"q":"Premoženjsko stanje podjetja v bilanci stanja predstavlja:","options":["višina in struktura obveznosti do virov sredstev","višina in struktura sredstev","višina kapitala podjetja","dosežen poslovni izid"],"correct":1,"explanation":"Premoženjsko stanje je višina in struktura sredstev (dolgoročnih in kratkoročnih), ki omogočajo izvajanje dejavnosti. Finančno stanje pa je struktura obveznosti do virov sredstev – kako podjetje financira svoja sredstva."},{"q":"Sredstva so v bilanci stanja razvrščena po načelu:","options":["naraščajoče zapadlosti","naraščajoče likvidnosti","padajoče likvidnosti","abecednega vrstnega reda"],"correct":1,"explanation":"Sredstva so razvrščena po načelu naraščajoče likvidnosti – na vrhu so sredstva, najbolj oddaljena od likvidnih (dolgoročna sredstva), nato sledijo kratkoročna sredstva."},{"q":"Obveznosti do virov sredstev so v bilanci stanja razvrščene po načelu:","options":["naraščajoče zapadlosti","naraščajoče likvidnosti","padajoče zapadlosti","velikosti zneska postavke"],"correct":0,"explanation":"Obveznosti do virov sredstev so razvrščene po načelu naraščajoče zapadlosti – najprej je zapisan kapital, sledijo dolgoročne in nazadnje kratkoročne obveznosti."},{"q":"Izkaz poslovnega izida je računovodski izkaz, ki:","options":["prikazuje stanje sredstev podjetja na določen dan","prikazuje prihodke in odhodke ter poslovni izid v določenem obdobju","prikazuje prihodke in odhodke podjetja na določen dan","prikazuje izključno denarne tokove podjetja"],"correct":1,"explanation":"Izkaz poslovnega izida je dinamičen izkaz, ki prikazuje poslovnoizidne tokove (prihodke in odhodke) v določenem obdobju ter dosežen poslovni izid kot razliko med njimi."},{"q":"Trditev »Izkaz poslovnega izida prikazuje prihodke in odhodke podjetja na določen dan« je:","options":["pravilna","napačna – izkaz poslovnega izida se nanaša na obdobje, ne na določen dan","pravilna le za proizvajalna podjetja","pravilna le za trgovinska podjetja"],"correct":1,"explanation":"Trditev je napačna. Izkaz poslovnega izida je dinamičen izkaz in se nanaša na obdobje. Na določen dan se nanaša bilanca stanja (statičen izkaz)."},{"q":"Prihodki pomenijo:","options":["povečanje gospodarskih koristi podjetja v obračunskem obdobju","zmanjšanje gospodarskih koristi podjetja","povečanje denarnih sredstev na transakcijskem računu","vrednostni izraz potroškov prvin poslovnega procesa"],"correct":0,"explanation":"Prihodki so povečanja gospodarskih koristi podjetja v obliki povečanj sredstev ali zmanjšanj dolgov. Tvorijo poslovnoizidni tok in se ugotavljajo po načelu fakturirane prodaje."},{"q":"Odhodki pomenijo:","options":["povečanje gospodarskih koristi podjetja","zmanjšanje gospodarskih koristi podjetja","zmanjšanje denarja v blagajni podjetja","povečanje poslovnega izida podjetja"],"correct":1,"explanation":"Odhodki so zmanjšanja gospodarskih koristi podjetja v obliki zmanjšanj sredstev ali povečanj dolgov. Vplivajo na poslovnoizidni tok in zmanjšujejo velikost kapitala."},{"q":"Prihodki se ugotavljajo po načelu:","options":["denarnega toka – ob prejemu plačila","fakturirane prodaje – ob izstavitvi računa","naraščajoče likvidnosti","previdnosti"],"correct":1,"explanation":"Prihodki se ugotavljajo po načelu fakturirane prodaje – torej ob izstavitvi računa kupcu in ne šele ob prejemu plačila."},{"q":"Kaj predstavlja povezavo med bilanco stanja in izkazom poslovnega izida?","options":["stanje denarnih sredstev na transakcijskem računu","dosežen poslovni izid","vrednost zalog materiala","nabavna vrednost opreme"],"correct":1,"explanation":"Povezava med izkazoma je dosežen poslovni izid – prikazan je v izkazu poslovnega izida, hkrati pa povečuje (dobiček) ali zmanjšuje (izguba) kapital, izkazan v bilanci stanja ob koncu obdobja."},{"q":"Izkazan čisti dobiček ob koncu poslovnega leta:","options":["poveča vrednost kapitala v bilanci stanja","poveča vrednost denarnih sredstev v bilanci stanja","poveča dolgoročne rezervacije","zmanjša vrednost osnovnega kapitala"],"correct":0,"explanation":"Izkazan čisti dobiček poveča vrednost kapitala v bilanci stanja ob koncu leta. Ne poveča pa nujno denarnih sredstev – poslovni izid je poslovnoizidni in ne denarni tok."},{"q":"Izguba za podjetje pomeni:","options":["povečanje obveznosti do države","zmanjšanje denarnih sredstev podjetja","zmanjšanje kapitala podjetja","zmanjšanje vsote sredstev v bilanci stanja"],"correct":2,"explanation":"Izguba pomeni zmanjšanje kapitala podjetja. Pokrije se s preostalimi postavkami kapitala – ne pa z osnovnim kapitalom."},{"q":"Trditev »Izkazan pozitivni čisti poslovni izid (dobiček) poveča stanje denarnih sredstev podjetja« je:","options":["pravilna – dobiček vedno pomeni več denarja","napačna – poslovni izid je poslovnoizidni in ne denarni tok","pravilna le pri gotovinski prodaji","pravilna le za trgovinska podjetja"],"correct":1,"explanation":"Trditev je napačna. Poslovni izid je poslovnoizidni tok (razlika med prihodki in odhodki), ne denarni tok. S poslovnim izidom ne odgovarjamo za denarna sredstva v obdobju – dobiček torej ne pomeni nujno več denarja."},{"type":"match","q":"Poveži računovodski standard / akt z njegovo vlogo.","pairs":[{"term":"SRS","def":"Slovenski računovodski standardi — majhna in srednja podjetja, ki ne kotirajo na borzi"},{"term":"MSRP","def":"Mednarodni standardi — podjetja, ki kotirajo na borzi, banke, zavarovalnice (obvezno)"},{"term":"ZGD","def":"Zakon o gospodarskih družbah — zakonski okvir poročanja in izbire standardov"},{"term":"Pravilnik o računovodstvu","def":"Temeljni notranji akt, ki ureja računovodstvo v podjetju"},{"term":"AJPES","def":"Agencija, ki sprejema in javno objavlja letna poročila"}],"explanation":"SRS sprejema Slovenski inštitut za revizijo, MSRP pa Odbor za mednarodne standarde. Sklep o uporabi SRS/MSRP (kjer je izbira mogoča) sprejmejo lastniki."},{"type":"match","q":"Poveži temeljni računovodski izkaz z njegovo vsebino.","pairs":[{"term":"Bilanca stanja","def":"Premoženjsko stanje (sredstva = obveznosti do virov) na določen dan"},{"term":"Izkaz poslovnega izida","def":"Prihodki in odhodki v obdobju → poslovni izid (dobiček/izguba)"},{"term":"Izkaz denarnih tokov","def":"Prejemki in izdatki po treh dejavnostih (poslovanje, naložbenje, financiranje)"}],"explanation":"Bilanca stanja je trenutek (na dan), izkaz poslovnega izida in denarnih tokov pa obdobji."},{"type":"match","q":"Poveži vrsto računovodstva z njegovo značilnostjo.","pairs":[{"term":"Finančno računovodstvo","def":"Poroča zunanjim uporabnikom (sredstva, obveznosti, poslovni izid)"},{"term":"Stroškovno računovodstvo","def":"Spremlja notranje poslovanje, daje analitične podatke"},{"term":"Poslovodno računovodstvo","def":"Podpira odločanje poslovodstva, vključuje podatke o prihodnosti"}],"explanation":"Finančno je usmerjeno navzven (zunanji uporabniki), stroškovno in poslovodno navznoter (notranji uporabniki)."},{"q":"Katera podjetja morajo OBVEZNO uporabljati MSRP?","options":["Vsa slovenska podjetja","Podjetja, ki kotirajo na borzi, ter banke in zavarovalnice","Samo majhna in mikro podjetja","Samo samostojni podjetniki","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"MSRP morajo obvezno uporabljati podjetja, katerih vrednostni papirji so na organiziranem trgu (borzi), ter banke in zavarovalnice; prav tako skupine, ki sestavljajo konsolidirane izkaze. Druga podjetja se lahko odločijo za MSRP (sklep sprejmejo lastniki, nato vsaj 5 let)."},{"q":"Kdo v podjetju sprejme sklep o uporabi SRS oz. MSRP (kjer je izbira mogoča)?","options":["Poslovodstvo","Lastniki podjetja","Revizor","AJPES","Slovenski inštitut za revizijo"],"correct":1,"explanation":"Sklep o uporabi računovodskih standardov (SRS/MSRP) sprejmejo lastniki podjetja; po sprejetju MSRP jih morajo uporabljati vsaj pet let."},{"q":"Po katerih merilih ZGD razvršča družbe na mikro, majhne, srednje in velike?","options":["Po pravni obliki in sedežu","Po povprečnem številu zaposlenih, prihodkih od prodaje in vrednosti sredstev","Po višini osnovnega kapitala in številu lastnikov","Po dejavnosti (SKD) in starosti družbe","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"ZGD razvršča družbe glede na povprečno število zaposlenih, čiste prihodke od prodaje in vrednost sredstev ob koncu poslovnega leta. Razvrstitev vpliva na obseg LP, zahtevane izkaze in obveznost revidiranja."},{"q":"V okviru katere postavke podjetje izkazuje zgradbo/zemljišče, ki ga daje v najem zaradi pridobivanja prihodkov ali pričakovanega povečanja vrednosti?","options":["Opredmetena osnovna sredstva","Naložbene nepremičnine","Zaloge","Sredstva za prodajo","Neopredmetena sredstva"],"correct":1,"explanation":"Nepremičnina za lastno dejavnost = OOS; nepremičnina, dana v najem ali za povečanje vrednosti = naložbena nepremičnina; nepremičnina, predvidena za prodajo v 12 mesecih = sredstvo za prodajo (kratkoročno)."},{"q":"Kosmati donos iz poslovanja je:","options":["Razlika med prihodki od prodaje in proizvajalnimi stroški prodanih proizvodov","Razlika med poslovnimi prihodki in poslovnimi odhodki","Prihodki od prodaje, prilagojeni za povečanje/zmanjšanje zalog dokončanih in nedokončanih proizvodov","Razlika med celotnimi prihodki in celotnimi odhodki","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Kosmati donos iz poslovanja so prihodki od prodaje, prilagojeni za spremembo vrednosti zalog proizvodov in nedokončane proizvodnje (po potrebi + drugi poslovni prihodki) — izhodišče različice I (nemške oblike) IPI."}]},{"id":"rk2","name":"Kviz 2 — Knjigovodstvo in kategorije","questions":[{"q":"Poslovni dogodek je:","options":["vsako dogajanje, ki vpliva na spremembo (vsaj dveh) gospodarskih kategorij","pisno pričevanje o spremembi sredstev podjetja","vsak zapis, vnesen v glavno knjigo","letno poročilo, ki ga podjetje odda AJPES-u"],"correct":0,"explanation":"Poslovni dogodek je vsako dogajanje, ki vpliva na spremembo (vsaj dveh) gospodarskih kategorij. Pisno pričevanje o njem je knjigovodska listina."},{"q":"Knjigovodska listina je:","options":["podatkovna zbirka za urejanje in obdelovanje podatkov","pisno pričevanje o nastanku poslovnega dogodka","seznam vseh kontov, ki jih podjetje uporablja","temeljni računovodski izkaz"],"correct":1,"explanation":"Knjigovodska listina je pisno pričevanje o nastanku poslovnega dogodka in podlaga za vnašanje podatkov v poslovne knjige. Brez listine poslovni dogodek za knjigovodstvo ne obstaja."},{"q":"Po čem se glavna knjiga razlikuje od pomožnih knjig?","options":["Glavna knjiga vsebuje samo vrednostne podatke, pomožne knjige tudi količinske.","Glavna knjiga vsebuje tudi količinske podatke, pomožne knjige le vrednostne.","Glavna knjiga se vodi po enostavnem, pomožne knjige po dvostavnem načelu.","Med glavno in pomožnimi knjigami ni vsebinske razlike."],"correct":0,"explanation":"Glavna knjiga vsebuje samo vrednostne podatke (zgoščene gospodarske kategorije, dvostavna zasnova). Pomožne knjige vsebujejo tudi količinske in podrobnejše analitične podatke (enostavna zasnova)."},{"q":"Knjigovodski dokument, ki je nalog za knjiženje poslovnega dogodka v poslovne knjige, se imenuje:","options":["konto","temeljnica","bilanca stanja","kontni načrt"],"correct":1,"explanation":"Nalog za knjiženje je temeljnica – listina, na podlagi katere se poslovni dogodek vnese v poslovne knjige."},{"q":"Likvidiranje (prejetih) računov pomeni:","options":["plačilo prejetih računov","shranjevanje prejetih računov","kontrolo prejetih računov","digitalizacijo prejetih računov"],"correct":2,"explanation":"Likvidiranje računov je kontroliranje prejetih računov – preverjanje pravilnosti listine. Ne pomeni plačila računa."},{"q":"Konto ima debetno in kreditno stran. Debetna stran je:","options":["desna stran konta","leva stran konta","spodnji del konta","stran, na katero nikoli ne knjižimo"],"correct":1,"explanation":"Konto ima levo (debetno) in desno (kreditno) stran. Poslovni dogodki se po dvostavnem knjigovodstvu spremljajo na obeh straneh kontov."},{"q":"V katerih kontnih razredih spremljamo sredstva?","options":["v razredih 4 in 7","v razredih 2 in 9","v razredih 0, 1, 3 in 6","v razredih 5, 8 in 9"],"correct":2,"explanation":"Sredstva spremljamo v kontnih razredih 0, 1, 3 in 6. Razreda 2 in 9 sta za obveznosti do virov sredstev, 4 za stroške, 7 za odhodke in prihodke, 8 za poslovni izid."},{"q":"V katerem kontnem razredu knjižimo kapital?","options":["v kontnem razredu 2","v kontnem razredu 3","v kontnem razredu 7","v kontnem razredu 9"],"correct":3,"explanation":"Kapital je obveznost do virov sredstev in ga knjižimo v kontnem razredu 9. V razredu 2 so kratkoročne obveznosti do virov sredstev."},{"q":"V katerem kontnem razredu spremljamo stroške?","options":["v kontnem razredu 4","v kontnem razredu 6","v kontnem razredu 7","v kontnem razredu 9"],"correct":0,"explanation":"Stroške spremljamo v kontnem razredu 4. Razred 7 je za odhodke in prihodke, razred 8 pa za poslovni izid."},{"q":"Prva številka konta se nanaša na ___, druga opredeljuje ___, tretja pa ___.","options":["kontni razred · kontno skupino · sintetični konto","sintetični konto · kontno skupino · kontni razred","kontno skupino · kontni razred · analitični konto","glavno knjigo · pomožno knjigo · temeljnico"],"correct":0,"explanation":"Prva številka konta označuje kontni razred, druga kontno skupino, tretja pa sintetični konto."},{"q":"Osnovno načelo dvostavnega knjigovodstva pravi, da:","options":["vsak poslovni dogodek knjižimo samo na enem kontu","je treba vsak poslovni dogodek knjižiti na vsaj dveh kontih, vsota debetnih knjižb pa je enaka vsoti kreditnih","podjetje vodi dvoje ločenih knjigovodstev – eno za notranje, drugo za davčne potrebe","knjižimo le tiste dogodke, ki vplivajo na denarna sredstva"],"correct":1,"explanation":"Osnovno načelo dvostavnega knjigovodstva: vsak poslovni dogodek je treba knjižiti na vsaj dveh kontih, pri čemer je vsota debetnih knjižb enaka vsoti kreditnih knjižb."},{"q":"Kaj od navedenega NI temeljna bilančna knjižba?","options":["povečanju sredstev sledi povečanje obveznosti do virov sredstev","povečanju ene vrste sredstev sledi zmanjšanje druge vrste sredstev","zmanjšanju obveznosti do virov sredstev sledi povečanje odhodkov","zmanjšanju sredstev sledi zmanjšanje obveznosti do virov sredstev"],"correct":2,"explanation":"Temeljne bilančne knjižbe vključujejo le sredstva in obveznosti do virov sredstev. Knjižba, kjer nastopijo odhodki (ali prihodki), spada med izvedene bilančne knjižbe, ne med temeljne."},{"q":"Nabavna vrednost opredmetenega osnovnega sredstva zajema:","options":["samo nakupno ceno dobavitelja","nakupno ceno (brez DDV) ter odvisne stroške nabave in stroške usposobitve za uporabo","nakupno ceno z vključenim DDV","nakupno ceno, zmanjšano za ocenjeno preostalo vrednost"],"correct":1,"explanation":"Nabavna vrednost = nakupna cena dobavitelja (brez DDV) + odvisni stroški nabave + stroški usposobitve za uporabo (prevoz, montaža ...). Je osnova za izračun amortizacije."},{"q":"Amortizacija se začne obračunavati:","options":["na dan nakupa osnovnega sredstva","prvi dan naslednjega meseca po tem, ko je sredstvo usposobljeno za uporabo","prvi dan naslednjega poslovnega leta","šele takrat, ko je sredstvo v celoti odpisano"],"correct":1,"explanation":"Amortizacija se prične obračunavati prvi dan v mesecu, ki sledi mesecu, v katerem je bilo osnovno sredstvo usposobljeno za uporabo."},{"q":"Amortizacijska osnova (amortizirljivi znesek) je enaka:","options":["nabavni vrednosti sredstva","nabavni vrednosti, zmanjšani za ocenjeno preostalo vrednost","nabavni vrednosti, zmanjšani za odpisano vrednost","neodpisani vrednosti sredstva"],"correct":1,"explanation":"Amortizacijska osnova = nabavna vrednost − ocenjena preostala vrednost. (Nabavna vrednost − odpisana vrednost da neodpisano vrednost, kar ni isto.)"},{"q":"Neodpisana (knjigovodska) vrednost osnovnega sredstva je enaka:","options":["nabavni vrednosti, zmanjšani za odpisano vrednost (popravek vrednosti)","nabavni vrednosti, zmanjšani za preostalo vrednost","seštevku nabavne vrednosti in obračunane amortizacije","letnemu znesku amortizacije"],"correct":0,"explanation":"Neodpisana vrednost = nabavna vrednost − odpisana vrednost. V bilanci stanja so opredmetena osnovna sredstva izkazana prav po neodpisani vrednosti."},{"q":"Obračun amortizacije ___ vrednost opredmetenega osnovnega sredstva.","options":["povečuje nabavno","povečuje odpisano","povečuje neodpisano","povečuje preostalo"],"correct":1,"explanation":"Amortizacija povečuje odpisano vrednost (popravek vrednosti) – torej del nabavne vrednosti, ki je že prenesen med odhodke. Hkrati zmanjšuje neodpisano vrednost; nabavna vrednost ostane nespremenjena."},{"q":"Katera metoda zmanjševanja vrednosti zalog od leta 2006 ni več dovoljena?","options":["metoda FIFO (zaporednih cen)","metoda drsečih povprečnih cen","metoda LIFO (povratnih cen)","metoda tehtanih povprečnih cen"],"correct":2,"explanation":"Metoda LIFO (povratnih cen), pri kateri se oddaja obračuna po zadnjih cenah, od leta 2006 ni več dovoljena. SRS in MSRP priporočajo metodo FIFO."},{"q":"Pri metodi FIFO se:","options":["oddaja iz zaloge obračuna po zadnjih cenah, končna zaloga po prvih","oddaja iz zaloge obračuna po prvih cenah, končna zaloga ostane po zadnjih","ob vsaki oddaji izračuna nova povprečna cena","vse enote vrednotijo po isti, vnaprej določeni ceni"],"correct":1,"explanation":"FIFO (first in, first out): oddaja se obračuna po prvih (najstarejših) cenah, končna zaloga pa ostane ovrednotena po zadnjih (najnovejših) cenah."},{"q":"Cene materiala naraščajo. Če podjetje pri vrednotenju zalog uporablja metodo drsečih povprečnih cen namesto metode FIFO, izkazuje:","options":["višji poslovni izid kot pri metodi FIFO","nižji poslovni izid kot pri metodi FIFO","enak poslovni izid kot pri metodi FIFO","poslovnega izida v tem primeru ni mogoče primerjati"],"correct":1,"explanation":"Ob rastočih cenah FIFO pusti v zalogi najnovejše (najvišje) cene, odda pa najstarejše (najnižje) – nižji stroški, višji izid. Drseče povprečne cene dajo višje stroške oddaje in zato nižji poslovni izid kot FIFO."},{"q":"Izbira metode vrednotenja zalog (FIFO, drseče povprečne cene):","options":["vpliva na poslovnoizidne tokove, ne pa na denarne tokove","vpliva na denarne tokove, ne pa na poslovnoizidne tokove","ne vpliva ne na poslovnoizidne ne na denarne tokove","vpliva popolnoma enako na poslovnoizidne in denarne tokove"],"correct":0,"explanation":"Z metodami vrednotenja zalog vplivamo na poslovnoizidne tokove (vrednost stroškov in odhodkov ter s tem na poslovni izid), ne vplivamo pa na denarne tokove."},{"q":"Stroški so:","options":["denarni tok, ki zmanjšuje denarna sredstva podjetja","vrednostni izraz potroškov prvin poslovnega procesa","vsa zmanjšanja gospodarskih koristi podjetja v obdobju","obveznost podjetja do države"],"correct":1,"explanation":"Stroški so vrednostni izraz potroškov delovnih sredstev, predmetov dela, storitev in delovne sile. Za njihov nastanek je nujno trošenje prvin poslovnega procesa."},{"q":"Delitev stroškov na stroške materiala, stroške dela, stroške amortizacije in stroške storitev je delitev stroškov po:","options":["poslovnih funkcijah","naravnih vrstah","nositeljih stroškov","stroškovnih mestih"],"correct":1,"explanation":"To je delitev stroškov po naravnih vrstah – stroški materiala, dela, amortizacije, storitev (in drugi stroški)."},{"q":"Stroški opravljenega študentskega dela se v podjetju knjigovodsko izkazujejo med:","options":["stroški materiala","stroški dela","stroški storitev","drugimi stroški"],"correct":2,"explanation":"Stroški študentskega dela se izkazujejo med stroški storitev, ne med stroški dela – študent namreč ni zaposlen v podjetju."},{"q":"Stroškovna cena proizvoda je najvišja, če podjetje za vrednotenje poslovnih učinkov uporablja metodo:","options":["proizvajalnih stroškov","spremenljivih proizvajalnih stroškov","zožene lastne cene","nabavne vrednosti"],"correct":2,"explanation":"Pri metodi zožene lastne cene v vrednost učinka vključimo največ stroškov (vse neposredne in posredne, razen neposrednih stroškov prodaje in stroškov financiranja), zato je stroškovna cena najvišja."},{"q":"Pri metodi vrednotenja proizvodov s proizvajalnimi stroški (priporoča jo MSRP) so proizvodi vrednoteni:","options":["z vsemi stroški, razen neposrednih stroškov prodaje in financiranja","z neposrednimi stroški ter posrednimi proizvajalnimi stroški","samo s spremenljivim delom posrednih proizvajalnih stroškov","po pričakovani prodajni ceni"],"correct":1,"explanation":"Pri metodi proizvajalnih stroškov v vrednost učinka vključimo neposredne stroške materiala, storitev, amortizacije in dela ter posredne proizvajalne stroške."},{"q":"Najetje (prejem) bančnega posojila je za podjetje primer:","options":["prihodka","prejemka, ki ni prihodek","odhodka","izdatka"],"correct":1,"explanation":"Najetje posojila pomeni povečanje denarnih sredstev (prejemek), ne pomeni pa povečanja gospodarskih koristi – torej ni prihodek. Prejemki in prihodki niso nujno povezani."},{"q":"Obračunan izstopni DDV pri prodaji blaga za podjetje pomeni:","options":["povečanje prihodkov od prodaje","obveznost do države","terjatev do države","povečanje poslovnih odhodkov"],"correct":1,"explanation":"Izstopni DDV, ki ga podjetje zaračuna kupcu, ne povečuje prihodkov, ampak pomeni obveznost do države. DDV vpliva na denarne tokove, ne pa neposredno na poslovnoizidne tokove."},{"q":"Pri obračunu DDV velja: če je vstopni DDV večji od izstopnega, ima podjetje:","options":["obveznost do države iz DDV","terjatev do države iz DDV","dodatni prihodek iz naslova DDV","dodatni odhodek iz naslova DDV"],"correct":1,"explanation":"Če je vstopni DDV večji od izstopnega, ima podjetje terjatev do države iz DDV (razliko dobi povrnjeno). Če je izstopni DDV večji od vstopnega, ima obveznost do države."},{"q":"Stroški plač z vidika podjetja (stroški dela) zajemajo:","options":["samo neto plače, izplačane zaposlenim","bruto plače ter prispevke in davke, obračunane na plače","samo prispevke, ki jih plača delodajalec","plače zaposlenih in stroške študentskega dela"],"correct":1,"explanation":"Stroški dela zajemajo bruto plače zaposlenih ter prispevke in davke, obračunane na plače. Z vidika podjetja je celoten strošek dela večji od neto izplačila zaposlenim."},{"type":"match","q":"Poveži kontni razred z vsebino, ki jo v njem spremljamo.","pairs":[{"term":"Razred 4","def":"Stroški (po naravnih vrstah)"},{"term":"Razred 7","def":"Odhodki in prihodki"},{"term":"Razred 8","def":"Poslovni izid"},{"term":"Razred 9","def":"Kapital (dolgoročne obveznosti do virov sredstev)"},{"term":"Razred 2","def":"Kratkoročne obveznosti do virov sredstev"}],"explanation":"Sredstva so v razredih 0, 1, 3 in 6; obveznosti do virov v 2 in 9; stroški v 4; odhodki in prihodki v 7; poslovni izid v 8."},{"type":"match","q":"Poveži vrsto zaloge oz. metodo z načinom vrednotenja.","pairs":[{"term":"Zaloga materiala in trgovskega blaga","def":"Po nabavni vrednosti (nakupna cena + nevračljive dajatve + stroški nabave)"},{"term":"Zaloga proizvodov in nedokončane proizvodnje","def":"Po stroških nastajanja (nabavna vrednost ne obstaja)"},{"term":"FIFO","def":"Oddaja po prvih (najstarejših) cenah; zaloga ostane po zadnjih"},{"term":"Drseče tehtane povprečne cene","def":"Oddaja po sproti preračunanem povprečju cen"}],"explanation":"Kupljene zaloge (material, blago) vrednotimo po nabavni vrednosti, lastne (proizvodi) po stroških nastajanja. LIFO od 2006 ni dovoljen."},{"type":"match","q":"Poveži poslovni dogodek z vrsto izvedene bilančne knjižbe.","pairs":[{"term":"Prodaja proizvodov na up","def":"↑ sredstev (terjatve) in ↑ prihodkov"},{"term":"Stroški prodanih proizvodov","def":"↓ sredstev (zaloge) in ↑ odhodkov"},{"term":"Prejet obračun obresti za posojilo","def":"↑ obveznosti in ↑ odhodkov"},{"term":"Naknadno znižanje obveznosti do dobavitelja","def":"↓ obveznosti in ↑ prihodkov"}],"explanation":"Izvedene bilančne knjižbe vplivajo na BS posredno — prek poslovnega izida (prihodki/odhodki). Štiri temeljne knjižbe pa vplivajo le na sredstva in obveznosti do virov."},{"q":"Stroški dela z vidika podjetja (skupni strošek plače) zajemajo:","options":["Samo neto plačo zaposlenega","Bruto plačo in prispevke delodajalca","Samo bruto plačo","Bruto plačo, zmanjšano za dohodnino","Neto plačo in dohodnino"],"correct":1,"explanation":"Strošek dela za podjetje = bruto plača + prispevki delodajalca (16,1 %). Prispevki delojemalca (22,1 %) in akontacija dohodnine se odbijejo od bruto plače pri izračunu neto (čiste) plače zaposlenega."},{"q":"Podjetje proda osnovno sredstvo po ceni, VIŠJI od neodpisane vrednosti. Razliko izkaže med:","options":["Drugimi poslovnimi prihodki (dobiček)","Drugimi poslovnimi odhodki (izguba)","Finančnimi odhodki","Zalogami","Prihodki od prodaje"],"correct":0,"explanation":"Prodajna cena > neodpisana vrednost → dobiček pri prodaji = drugi poslovni prihodki. Če je cena < neodpisana vrednost, nastane izguba = drugi poslovni odhodki; če sta enaki, ni izida."},{"q":"Podjetje proda osnovno sredstvo po ceni, NIŽJI od neodpisane vrednosti. Razliko izkaže med:","options":["Drugimi poslovnimi prihodki","Drugimi poslovnimi odhodki (izguba)","Stroški amortizacije","Finančnimi prihodki","Popravkom vrednosti"],"correct":1,"explanation":"Prodajna cena < neodpisana (knjigovodska) vrednost → izguba pri prodaji = drugi poslovni odhodki."},{"q":"Amortizacijska osnova (amortizirljivi znesek) opredmetenega osnovnega sredstva je:","options":["Nabavna vrednost","Nabavna vrednost − ocenjena preostala vrednost","Neodpisana vrednost + popravek vrednosti","Nabavna vrednost + DDV","Tržna vrednost ob koncu dobe koristnosti"],"correct":1,"explanation":"Amortizacijska osnova = nabavna vrednost − ocenjena preostala vrednost. Mesečni strošek amortizacije = amort. osnova / (doba koristnosti v letih × 12); amortizirati začnemo mesec po usposobitvi za uporabo."},{"q":"Ob katerem od naštetih poslovnih dogodkov se pojavijo STROŠKI?","options":["Prejem računa za osebni računalnik","Prejem računa za montažo stroja","Plačilo dobaviteljevega računa za material","Poraba materiala v proizvodnji","Nakup materiala na zalogo"],"correct":3,"explanation":"Stroški nastanejo ob (u)porabi prvin poslovnega procesa — npr. poraba materiala v proizvodnji. Nakup/prejem računa za sredstvo poveča sredstva (ne stroškov), plačilo računa je le denarni tok."},{"q":"Stroškovna cena proizvoda je NAJVIŠJA, če podjetje uporablja metodo:","options":["Zožene lastne cene","Proizvajalnih stroškov","Spremenljivih proizvajalnih stroškov","Nabavne vrednosti","FIFO"],"correct":0,"explanation":"Pri zoženi lastni ceni v zalogo prenesemo VSE stroške obdobja → najvišja stroškovna cena. Pri proizvajalnih stroških le proizvajalne, pri spremenljivih proizvajalnih le spremenljive → najnižja."},{"q":"Zaloge nedokončane proizvodnje in dokončanih proizvodov vrednotimo:","options":["Po nabavni vrednosti","Po stroških, povezanih z njihovim nastajanjem","Po prodajni ceni","Po tržni vrednosti","Po nominalni vrednosti"],"correct":1,"explanation":"Lastni proizvodi nimajo nabavne vrednosti, zato jih vrednotimo po stroških nastajanja (proizvajalni stroški oz. zožena lastna cena ali spremenljivi proizvajalni stroški). Material in trgovsko blago pa po nabavni vrednosti."}]},{"id":"rk3","name":"Kviz 3 — Izkazi in analiza","questions":[{"q":"Letno poročilo o poslovanju podjetja:","options":["morajo pripraviti vsa podjetja, njegov obseg pa je odvisen od velikosti podjetja","pripravijo le velika podjetja in podjetja, ki kotirajo na borzi","ni obvezno – pripravi se le na zahtevo lastnikov","pripravi in objavi davčna uprava"],"correct":0,"explanation":"Letno poročilo morajo v skladu z zakonodajo pripraviti vsa podjetja; obseg je odvisen od velikosti podjetja (majhna podjetja: bilanca stanja, izkaz poslovnega izida in priloga s pojasnili)."},{"q":"Letno poročilo je sestavljeno iz dveh delov, in sicer iz:","options":["bilance stanja in izkaza poslovnega izida","poslovnega poročila in računovodskega poročila","davčnega obračuna in revizijskega poročila","glavne knjige in pomožnih knjig"],"correct":1,"explanation":"Letno poročilo sestavljata poslovno poročilo (uspešnost poslovanja, kazalniki, načrti) in računovodsko poročilo (letni računovodski izkazi s prilogami s pojasnili)."},{"q":"Kaj je treba opraviti pred sestavljanjem letnega poročila?","options":["revizijo vseh poslovnih dogodkov leta","inventuro (popis) sredstev, da se ugotovi razlika med knjigovodskim in dejanskim stanjem","izplačilo dividend lastnikom","obračun DDV za celotno leto"],"correct":1,"explanation":"Pred sestavljanjem letnega poročila je potrebna inventura sredstev, da se ugotovi morebitna razlika med knjigovodskim in dejanskim stanjem vrst sredstev."},{"q":"Letni računovodski izkazi v računovodskem poročilu obsegajo:","options":["samo bilanco stanja in izkaz poslovnega izida","bilanco stanja, izkaz poslovnega izida, izkaz denarnih tokov in izkaz gibanja kapitala","bilanco stanja in davčni obračun","poslovno poročilo in revizijsko mnenje"],"correct":1,"explanation":"Letni računovodski izkazi obsegajo bilanco stanja, izkaz poslovnega izida, izkaz denarnih tokov in izkaz gibanja kapitala (poleg prilog s pojasnili)."},{"q":"Poslovni izid iz poslovanja označujemo tudi s kratico:","options":["EBITDA","EBIT","ROE","EPS"],"correct":1,"explanation":"Poslovni izid iz poslovanja je EBIT – izkazuje uspešnost poslovanja podjetja pri njegovi osnovni poslovni dejavnosti."},{"q":"EBITDA dobimo tako, da poslovnemu izidu iz poslovanja prištejemo:","options":["finančne prihodke obdobja","amortizacijo opredmetenih osnovnih sredstev in neopredmetenih dolgoročnih sredstev","davek od dobička","druge (izredne) prihodke"],"correct":1,"explanation":"EBITDA = poslovni izid iz poslovanja + amortizacija opredmetenih osnovnih sredstev + amortizacija neopredmetenih dolgoročnih sredstev."},{"q":"Pri angloameriški obliki izkaza poslovnega izida so poslovni odhodki prikazani:","options":["po naravnih vrstah stroškov","po poslovnih funkcijah","po kontnih razredih","po datumu nastanka"],"correct":1,"explanation":"Pri angloameriški obliki so poslovni odhodki prikazani po poslovnih funkcijah in neposredno. Pri nemški obliki pa po naravnih vrstah stroškov."},{"q":"Kosmati poslovni izid od prodaje pri proizvajalnem podjetju je razlika med:","options":["poslovnimi prihodki in poslovnimi odhodki","čistimi prihodki od prodaje in proizvajalnimi stroški prodanih proizvodov","prihodki od prodaje in vsemi stroški poslovanja v obdobju","prihodki od prodaje in finančnimi odhodki"],"correct":1,"explanation":"Kosmati poslovni izid od prodaje (angloameriška oblika izkaza) je razlika med čistimi prihodki od prodaje in proizvajalnimi stroški prodanih proizvodov."},{"q":"Katera trditev o nemški in angloameriški obliki izkaza poslovnega izida drži?","options":["obe obliki dasta enak poslovni izid iz poslovanja","nemška oblika da vedno višji poslovni izid","obliki je treba uporabljati izmenično vsako leto","angloameriška oblika ne upošteva finančnih prihodkov"],"correct":0,"explanation":"Podjetje samo izbere obliko prikaza poslovnega izida; SRS priporočajo angloameriško različico, pri obeh različicah pa dobimo enak poslovni izid iz poslovanja."},{"q":"Davek od dobička je z vidika gospodarskih kategorij:","options":["strošek podjetja","poslovni odhodek","obveznost do države, ki zmanjšuje čisti dobiček in ni ne strošek ne odhodek","finančni prihodek"],"correct":2,"explanation":"Davek od dobička je obveznost do države, ki zmanjšuje čisti dobiček. Z vidika gospodarskih kategorij ni ne strošek ne odhodek; ob poravnavi obveznosti pa nastane izdatek."},{"q":"O razporeditvi katerega dobička odloča skupščina lastnikov?","options":["čistega dobička","bilančnega dobička","kosmatega dobička od prodaje","poslovnega izida iz poslovanja"],"correct":1,"explanation":"Lastniki neposredno ne odločajo o razporeditvi čistega dobička, ampak o razporeditvi bilančnega dobička."},{"q":"Bilančni dobiček je:","options":["vedno enak čistemu dobičku obdobja","čisti dobiček, povečan za preneseni dobiček iz preteklih let","sestavni del bilance stanja","del osnovnega kapitala podjetja"],"correct":1,"explanation":"Bilančni dobiček je širša kategorija – čisti dobiček + preneseni dobiček iz preteklih let. Ni neposredno izkazan v nobenem računovodskem izkazu, je izračunljiva kategorija."},{"q":"Izguba podjetja se pokrije:","options":["izključno z osnovnim kapitalom","s preostalimi postavkami kapitala, ne pa z osnovnim kapitalom","s posojilom banke","z obveznostmi do dobaviteljev"],"correct":1,"explanation":"Izguba se pokrije s preostalimi postavkami kapitala; ne sme se pokriti z osnovnim kapitalom."},{"q":"Izkaz denarnih tokov:","options":["prikazuje stanje vseh sredstev podjetja na določen dan","prikazuje spremembe denarnih sredstev v obdobju in je orodje za spremljanje plačilne sposobnosti","prikazuje izključno poslovni izid obdobja","se sestavlja enkrat na pet let"],"correct":1,"explanation":"Izkaz denarnih tokov prikazuje prejemke in izdatke ter spremembe denarnih sredstev v obdobju; je orodje za spremljanje plačilne sposobnosti podjetja."},{"q":"Računovodski standardi denarne tokove ločeno prikazujejo za tri vrste dejavnosti, in sicer za:","options":["nabavo, proizvodnjo in prodajo","poslovanje, naložbenje (investiranje) in financiranje","preteklost, sedanjost in prihodnost","material, delo in storitve"],"correct":1,"explanation":"Denarne tokove prikazujemo ločeno za denarne tokove pri poslovanju, pri naložbenju (investiranju) in pri financiranju."},{"q":"Pri kateri metodi izdelave izkaza denarnih tokov so prejemki in izdatki pri poslovanju prikazani po posameznih vrstah (priporočajo jo SRS)?","options":["posredna metoda","neposredna metoda","metoda strukturnih deležev","metoda drsečih povprečnih cen"],"correct":1,"explanation":"Pri neposredni metodi (priporočajo jo SRS) se denarni tokovi pri poslovanju prikažejo po posameznih vrstah prejemkov in izdatkov. Pri posredni metodi se ugotovijo posredno iz poslovnih prihodkov in odhodkov."},{"q":"Osnovni namen revidiranja računovodskih izkazov je:","options":["izračunati davek od dobička","povečati stopnjo zaupanja uporabnikov v računovodske izkaze","sestaviti kontni načrt podjetja","določiti višino dividend lastnikom"],"correct":1,"explanation":"Revidiranje se izvaja z namenom, da bi povečali stopnjo zaupanja predvidenih uporabnikov v računovodske izkaze."},{"q":"Če revizor oceni, da računovodski izkazi resnično in pošteno prikazujejo finančni položaj in poslovni izid podjetja, poda:","options":["mnenje brez pridržkov","mnenje s pridržki","odklonilno mnenje","zavrnitev izdelave mnenja"],"correct":0,"explanation":"Mnenje brez pridržkov pomeni, da računovodski izkazi resnično in pošteno prikazujejo finančno stanje in poslovni izid podjetja."},{"q":"S časovnimi razmejitvami podjetje razmejuje:","options":["prejemke in izdatke","prihodke in stroške","sredstva in obveznosti do virov sredstev","prejemke in prihodke"],"correct":1,"explanation":"S časovnimi razmejitvami podjetje razmejuje prihodke in stroške – razporeja jih v obdobja, na katera se dejansko nanašajo."},{"q":"Odloženi stroški so po vsebini:","options":["aktivne časovne razmejitve","pasivne časovne razmejitve","rezervacije","obveznosti do dobaviteljev"],"correct":0,"explanation":"Odloženi stroški so po vsebini aktivne časovne razmejitve. Kratkoročne aktivne časovne razmejitve vključujejo odložene stroške in prehodno nezaračunane prihodke."},{"q":"Vnaprej vračunane odpravnine zaposlenim ob upokojitvi in jubilejne nagrade se računovodsko izkazujejo v okviru:","options":["aktivnih časovnih razmejitev","pasivnih časovnih razmejitev","rezervacij","osnovnega kapitala"],"correct":2,"explanation":"Vnaprej vračunane odpravnine ob upokojitvi in vnaprej vračunane jubilejne nagrade se računovodsko izkazujejo v okviru rezervacij."},{"q":"Kratkoročne pasivne časovne razmejitve vključujejo:","options":["odložene stroške in prehodno nezaračunane prihodke","vnaprej vračunane stroške in kratkoročno odložene prihodke","dolgoročne finančne naložbe","zaloge proizvodov in materiala"],"correct":1,"explanation":"Kratkoročne pasivne časovne razmejitve vključujejo vnaprej vračunane stroške in kratkoročno odložene prihodke. (Odloženi stroški in nezaračunani prihodki sodijo med aktivne časovne razmejitve.)"},{"q":"Analiza, pri kateri ugotavljamo, kako se posamezne postavke računovodskih izkazov spreminjajo med obdobji, se imenuje:","options":["vodoravna analiza","navpična analiza","analiza s kazalniki","inventura"],"correct":0,"explanation":"Vodoravna analiza (analiza računovodskih postavk v času) ugotavlja, kako se posamezne postavke spreminjajo med obdobji; izražamo jo z vrednostnimi razlikami in indeksi."},{"q":"Pri navpični analizi računovodskih izkazov:","options":["primerjamo iste postavke med različnimi obdobji","ugotavljamo strukturne deleže postavk glede na izbrano celoto","izračunavamo davek od dobička","popisujemo dejansko stanje sredstev"],"correct":1,"explanation":"Navpična analiza (analiza strukturnih deležev) ugotavlja deleže posameznih gospodarskih kategorij glede na izbrano celoto – najpogosteje glede na bilančno vsoto."},{"q":"Katera prednost je značilna za analizo strukturnih deležev (navpično analizo)?","options":["omogoča primerjavo med različno velikimi podjetji","natančno napove prihodnji dobiček podjetja","nadomesti revizijo računovodskih izkazov","odpravi vpliv inflacije na izkaze"],"correct":0,"explanation":"Ker navpična analiza uporablja relativne deleže, omogoča primerjavo med različno velikimi podjetji."},{"q":"Najbolj razširjena metoda za analiziranje računovodskih izkazov je:","options":["analiza z relativnimi števili (kazalniki)","inventura sredstev","revidiranje izkazov","dvostavno knjigovodstvo"],"correct":0,"explanation":"Analiza računovodskih izkazov s kazalniki – relativnimi števili (stopnje, indeksi, koeficienti) – je najbolj razširjena metoda; pomembno je pravilno razlaganje kazalnikov."},{"q":"Kazalnik, ki primerja dva raznovrstna, a med seboj primerljiva podatka, je:","options":["stopnja udeležbe","indeks","koeficient","strukturni delež"],"correct":2,"explanation":"Koeficient primerja dva raznovrstna podatka, ki sta med seboj primerljiva. Stopnja udeležbe primerja istovrstni kategoriji (del/celota), indeks pa podatek z izhodiščno velikostjo."},{"q":"Stopnja udeležbe je relativno število, ki:","options":["primerja podatek z istovrstno izhodiščno velikostjo","izraža razmerje med dvema istovrstnima kategorijama, od katerih se prva nanaša na del, druga na celoto","primerja dva povsem raznovrstna podatka","meri plačilno sposobnost podjetja"],"correct":1,"explanation":"Stopnja udeležbe je razmerje med dvema istovrstnima kategorijama, pri čemer se prva nanaša na del in druga na celoto."},{"q":"S katerimi primerjalnimi podatki (standardi) primerjamo informacije iz računovodskih izkazov?","options":["samo s podatki konkurenčnih podjetij","s podatki preteklega poslovanja, s podatki drugih podjetij v panogi in s podatki o načrtovanem poslovanju","izključno s podatki o načrtovanem poslovanju","s podatki o gibanju tečajev na borzi"],"correct":1,"explanation":"Pridobljene informacije primerjamo s podatki preteklega poslovanja, s podatki drugih (najboljših) podjetij v panogi in s podatki o načrtovanem poslovanju."},{"q":"Pri vodoravni analizi pogosto uporabljamo indekse, ki jih izračunamo kot razmerje med:","options":["delom in celoto iste postavke","podatkom proučevanega obdobja in istovrstnim podatkom prejšnjega (izhodiščnega) obdobja","dvema raznovrstnima kategorijama","prihodki in odhodki obdobja"],"correct":1,"explanation":"Pri vodoravni analizi so postavke prejšnjega obdobja osnova za primerjavo; indeks dobimo kot razmerje med podatkom proučevanega obdobja in podatkom prejšnjega obdobja."},{"type":"match","q":"Poveži pojem iz izkaza poslovnega izida z opisom.","pairs":[{"term":"EBIT","def":"Poslovni izid iz poslovanja (pred obrestmi in davki)"},{"term":"EBITDA","def":"EBIT + amortizacija opredmetenih in neopredmetenih sredstev"},{"term":"Angloameriška oblika (II.)","def":"PRIHODKI − ODHODKI; odhodki po poslovnih funkcijah"},{"term":"Nemška oblika (I.)","def":"PRIHODKI − STROŠKI (prilagojeni za spremembo zalog)"}],"explanation":"Ne glede na obliko je poslovni izid ENAK. SRS dajejo prednost različici II (anglo-ameriški)."},{"type":"match","q":"Poveži vrsto časovne razmejitve z opisom.","pairs":[{"term":"AČR — odloženi stroški","def":"Vnaprej plačan/prejet račun za daljše obdobje (npr. celoletno zavarovanje)"},{"term":"AČR — nezaračunani prihodki","def":"Storitev opravljena, račun še ni izdan (prihodek zaslužen)"},{"term":"PČR — odloženi prihodki","def":"Vnaprej prejeto plačilo za prihodnje obdobje (npr. naročnina vnaprej)"},{"term":"PČR — vnaprej vračunani stroški","def":"Strošek nastaja sproti, račun prejmemo kasneje (npr. najemnina na koncu)"}],"explanation":"Aktivne ČR so na strani sredstev, pasivne na strani obveznosti do virov. Razmejujemo prihodke in stroške, da pripadejo pravemu obdobju."},{"type":"match","q":"Poveži pojem iz analize računovodskih izkazov z opisom.","pairs":[{"term":"Vodoravna analiza","def":"Spreminjanje postavk med obdobji (indeksi)"},{"term":"Navpična analiza","def":"Strukturni deleži postavk glede na izbrano celoto"},{"term":"Kazalec","def":"Absolutno število (npr. dobiček, prihodki)"},{"term":"Kazalnik","def":"Relativno število — razmerje dveh podatkov (npr. stopnja udeležbe, indeks)"}],"explanation":"Vodoravna = v času, navpična = struktura. Kazalec je absoluten, kazalnik relativen (delež/indeks/koeficient)."},{"q":"Pri različici I (nemški obliki) IPI velja, da so poslovni odhodki enaki:","options":["Vsi stroški + povečanje zaloge proizvodov in nedokončane proizvodnje","Vsi stroški − povečanje zaloge proizvodov in nedokončane proizvodnje","Vsi stroški (brez prilagoditve)","Samo stroški prodanih proizvodov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Odhodki = stroški, prilagojeni za spremembo zalog: če se zaloga proizvodov POVEČA, odhodke dobimo tako, da stroške ZMANJŠAMO za povečanje; če se zaloga zmanjša, stroške povečamo. Tako je izid po obeh različicah enak."},{"q":"Kateri obliki izkaza poslovnega izida dajejo SRS prednost?","options":["Različici I (nemški obliki)","Različici II (anglo-ameriški obliki)","Obema enakovredno","Obliki za trgovinska podjetja","Nobeni — obliko predpiše AJPES"],"correct":1,"explanation":"SRS dajejo prednost različici II (anglo-ameriški obliki: PRIHODKI − ODHODKI), podjetje pa izbere obliko, ki mu bolj ustreza. Izračunani poslovni izid je v vsakem primeru enak."},{"q":"Letni računovodski izkazi v računovodskem poročilu obsegajo:","options":["Samo bilanco stanja in izkaz poslovnega izida","Bilanco stanja, izkaz poslovnega izida, izkaz denarnih tokov, izkaz vseobsegajočega donosa in izkaz gibanja kapitala","Bilanco stanja in poslovno poročilo","Izkaz poslovnega izida in poročilo revizorja","Samo izkaz denarnih tokov"],"correct":1,"explanation":"Letni računovodski izkazi: bilanca stanja, izkaz poslovnega izida, izkaz denarnih tokov, izkaz vseobsegajočega donosa in izkaz gibanja kapitala. Računovodsko poročilo poleg izkazov vsebuje še priloge s pojasnili in (če je podjetje zavezano) poročilo revizorja."},{"q":"Letno poročilo je treba sestaviti v koliko mesecih po koncu poslovnega leta (ZGD)?","options":["V enem mesecu","V dveh mesecih","V treh mesecih (konsolidirano v štirih)","V šestih mesecih","Do konca naslednjega poslovnega leta"],"correct":2,"explanation":"Po 54. členu ZGD je treba letno poročilo sestaviti v treh mesecih po koncu poslovnega leta; konsolidirano letno poročilo pa v štirih mesecih."},{"q":"Pri dvotirnem sistemu upravljanja letno poročilo:","options":["Pripravi in sprejme upravni odbor","Pripravi uprava, sprejme pa nadzorni svet","Pripravi in sprejme skupščina lastnikov","Pripravi revizor, sprejme uprava","Pripravi AJPES"],"correct":1,"explanation":"Pri dvotirnem sistemu (uprava + nadzorni svet) letno poročilo pripravi uprava, sprejme pa nadzorni svet. Pri enotirnem sistemu ga pripravi in sprejme upravni odbor."},{"q":"Katera od naštetih NI skupina kazalnikov pri analiziranju računovodskih izkazov?","options":["Kazalniki financiranja","Kazalniki investiranja","Kazalniki plačilne sposobnosti","Kazalniki obračanja","Kazalniki amortiziranja"],"correct":4,"explanation":"Skupine kazalnikov: financiranja, investiranja, plačilne sposobnosti, obračanja, gospodarnosti in donosnosti. »Kazalniki amortiziranja« ne obstajajo kot skupina."},{"q":"Po čem se rezervacije in dolgoročne PČR razlikujejo od kratkoročnih PČR?","options":["Nanašajo se na obdobje, daljše od enega leta","Knjižijo se med sredstva","Vključujejo samo prihodke","Se ne pojavljajo v bilanci stanja","Nanašajo se na obdobje, krajše od enega meseca"],"correct":0,"explanation":"Rezervacije in dolgoročne PČR so vsebinsko sorodne kratkoročnim PČR, le da se nanašajo na obdobje, daljše od enega leta (vnaprej vračunani stroški/obveznosti, ki bodo nastale čez več kot leto dni)."},{"q":"Kosmati poslovni izid od prodaje pri proizvajalnem podjetju je razlika med:","options":["Prihodki od prodaje in proizvajalnimi stroški prodanih proizvodov","Poslovnimi prihodki in poslovnimi odhodki","Celotnimi prihodki in celotnimi odhodki","Prihodki od prodaje in nabavno vrednostjo prodanega blaga","Prihodki in stroški dela"],"correct":0,"explanation":"Kosmati poslovni izid od prodaje (proizvajalno podjetje) = prihodki od prodaje − proizvajalni stroški prodanih proizvodov. (V trgovinskem podjetju = prihodki od prodaje − nabavna vrednost prodanega blaga = razlika v ceni.)"}]},{"id":"rac-knjizbe","name":"Knjiženje poslovnih dogodkov","questions":[{"q":"Podjetje je kupilo material z odloženim rokom plačila. Kako se knjiži?","options":["Poveča se zaloga materiala in obveznosti do dobaviteljev","Povečajo se stroški materiala in obveznosti do dobaviteljev","Poveča se zaloga materiala, zmanjša se TRR","Zmanjša se zaloga materiala, povečajo se obveznosti do dobaviteljev"],"correct":0,"explanation":"Nakup na <b>zalogo</b> (ne poraba) → <b>zaloga materiala ↑ = debet</b>. Odloženo plačilo (račun, ne denar) → <b>obveznosti do dobaviteljev ↑ = kredit</b>. Material preide v stroške šele ob porabi.","htmlExpl":true},{"q":"Nabavljen material se porablja v proizvodnji. Kako se knjiži?","options":["Povečajo se stroški materiala, zmanjša se zaloga materiala","Poveča se zaloga materiala in obveznosti do dobaviteljev","Povečajo se stroški materiala, zmanjša se TRR","Zmanjšajo se stroški materiala, poveča se zaloga"],"correct":0,"explanation":"<b>Poraba</b> prvine → <b>stroški materiala ↑ = debet</b>; hkrati se <b>zaloga materiala ↓ = kredit</b> (porabljeni del odide iz zaloge). Razlikuj: nakup → zaloga; poraba → stroški.","htmlExpl":true},{"q":"Blagajnik prenese denar iz blagajne na transakcijski račun (TRR). Kako se knjiži?","options":["Poveča se TRR, zmanjša se blagajna","Poveča se blagajna, zmanjša se TRR","Poveča se TRR in blagajna","Poveča se TRR, zmanjšajo se obveznosti"],"correct":0,"explanation":"Oba sta denarni <b>sredstvi</b>. TRR ↑ = <b>debet</b>, blagajna ↓ = <b>kredit</b>. Bilančna vsota se ne spremeni (premik znotraj sredstev) — primer temeljne bilančne knjižbe.","htmlExpl":true},{"q":"V plačilo je zapadel dobaviteljev račun in je bil plačan iz TRR. Kako se knjiži?","options":["Zmanjšata se TRR in obveznosti do dobaviteljev","Zmanjša se TRR, povečajo se stroški","Zmanjša se TRR, zmanjša se kratkoročno posojilo","Poveča se TRR, zmanjšajo se obveznosti do dobaviteljev"],"correct":0,"explanation":"Plačilo poravna obveznost: <b>obveznosti do dobaviteljev ↓ = debet</b>, <b>TRR ↓ = kredit</b>. Strošek je nastal že prej (ob prejemu/porabi), tu je le denarni tok.","htmlExpl":true},{"q":"Podjetje je najelo kratkoročno posojilo, denar je prejelo na TRR. Kako se knjiži?","options":["Poveča se TRR in kratkoročno posojilo (kratkoročne finančne obveznosti)","Poveča se TRR in prihodki od prodaje","Poveča se TRR in osnovni kapital","Zmanjša se TRR, poveča se kratkoročno posojilo"],"correct":0,"explanation":"Prejem posojila: <b>TRR ↑ = debet</b>, <b>kratkoročno posojilo ↑ = kredit</b>. <b>Posojilo NI prihodek</b> — gre za prejemek, ki poveča obveznost, ne gospodarske koristi.","htmlExpl":true},{"q":"Podjetje je vrnilo (odplačalo) kratkoročno posojilo iz TRR. Kako se knjiži?","options":["Zmanjšata se TRR in kratkoročno posojilo","Zmanjšata se TRR in obveznosti do dobaviteljev","Zmanjša se TRR, povečajo se finančni odhodki","Zmanjša se TRR, zmanjša se dolgoročno posojilo"],"correct":0,"explanation":"Vračilo posojila: <b>kratkoročno posojilo ↓ = debet</b>, <b>TRR ↓ = kredit</b>. Pozor: zmanjša se <i>posojilo</i>, ne obveznosti do dobaviteljev (to so dolgovi za nabave, ne za posojila).","htmlExpl":true},{"q":"Podjetje se je dokapitaliziralo z izdajo delnic; denar je prejelo na TRR. Kako se knjiži?","options":["Poveča se TRR in osnovni kapital","Poveča se TRR in prihodki","Poveča se TRR in kratkoročno posojilo","Poveča se TRR in obveznosti do dobaviteljev"],"correct":0,"explanation":"Vplačilo kapitala: <b>TRR ↑ = debet</b>, <b>osnovni kapital ↑ = kredit</b>. Kapital je obveznost do virov sredstev (lastniški vir), ne prihodek.","htmlExpl":true},{"q":"Banka je odobrila spremembo dolgoročnega posojila v kratkoročno (rok zapadlosti ≤ 1 leto). Kako se knjiži?","options":["Zmanjša se dolgoročno posojilo, poveča se kratkoročno posojilo","Poveča se dolgoročno posojilo, zmanjša se kratkoročno","Zmanjša se TRR, poveča se kratkoročno posojilo","Poveča se TRR, zmanjša se dolgoročno posojilo"],"correct":0,"explanation":"Reklasifikacija znotraj obveznosti do virov: <b>dolgoročno posojilo ↓ = debet</b>, <b>kratkoročno posojilo ↑ = kredit</b>. Denar se ne giblje, bilančna vsota ostane enaka (temeljna bilančna knjižba).","htmlExpl":true},{"q":"Z denarjem iz TRR so kupili obveznice, ki jih nameravajo držati dolgoročno. Kako se knjiži?","options":["Zmanjša se TRR, povečajo se dolgoročne finančne naložbe","Zmanjša se TRR, povečajo se kratkoročne finančne naložbe","Poveča se TRR, povečajo se finančne naložbe","Zmanjša se TRR, povečajo se finančni odhodki"],"correct":0,"explanation":"Premik znotraj sredstev: <b>dolgoročne finančne naložbe ↑ = debet</b>, <b>TRR ↓ = kredit</b>. Namen držanja (dolgoročno) določa, ali so naložbe dolgoročne ali kratkoročne.","htmlExpl":true},{"q":"Obračunani so stroški dela (delavec je opravil delo, plača še ni izplačana). Kako se knjiži?","options":["Povečajo se stroški dela in obveznosti do zaposlenih","Povečajo se stroški dela, zmanjša se TRR","Povečajo se obveznosti do zaposlenih, zmanjša se TRR","Povečajo se stroški dela in obveznosti do dobaviteljev"],"correct":0,"explanation":"Nastanek stroška ob opravljenem delu: <b>stroški dela ↑ = debet</b>, <b>obveznosti do zaposlenih ↑ = kredit</b>. Izplačilo (↓ TRR, ↓ obveznosti do zaposlenih) je ločen, kasnejši dogodek.","htmlExpl":true},{"q":"Obračunane so plače z dohodnino in prispevki. Kako se knjiži?","options":["Povečajo se stroški dela; povečajo se obveznosti do zaposlenih (neto) in obveznosti do države (dohodnina, prispevki)","Povečajo se stroški dela in obveznosti do zaposlenih (vse skupaj)","Povečajo se stroški dela, zmanjša se TRR","Povečajo se stroški dela in obveznosti do dobaviteljev"],"correct":0,"explanation":"<b>Stroški dela ↑ = debet</b> (bruto + prispevki delodajalca). Na strani kredita: <b>obveznosti do zaposlenih</b> (neto plača) in <b>obveznosti do države</b> (dohodnina in prispevki). Strošek dela podjetja vključuje tudi prispevke delodajalca (16,1 %).","htmlExpl":true},{"q":"Prejet je obračun obresti za bančno posojilo (obresti še niso plačane). Kako se knjiži?","options":["Povečajo se finančni odhodki in obveznosti za obresti","Povečajo se finančni odhodki, zmanjša se TRR","Povečajo se finančni prihodki in obveznosti za obresti","Povečajo se stroški storitev in obveznosti za obresti"],"correct":0,"explanation":"Obresti od najetega posojila so <b>finančni odhodki ↑ = debet</b>; ker še niso plačane → <b>obveznosti za obresti ↑ = kredit</b>. Obresti niso strošek storitev, temveč finančni odhodek.","htmlExpl":true},{"q":"Podjetje je plačalo obresti od najetega posojila iz TRR. Kako se knjiži?","options":["Povečajo se finančni odhodki, zmanjša se TRR","Povečata se TRR in finančni prihodki","Zmanjša se TRR, povečajo se finančni prihodki","Zmanjša se TRR, zmanjša se posojilo"],"correct":0,"explanation":"Plačane obresti od <b>lastnega</b> posojila: <b>finančni odhodki ↑ = debet</b>, <b>TRR ↓ = kredit</b>. (Če bi obresti PREJELI za dano posojilo, bi šlo za finančne prihodke in ↑ TRR.)","htmlExpl":true},{"q":"Podjetje, ki je v preteklem letu dalo posojilo, je prejelo obresti na TRR. Kako se knjiži?","options":["Poveča se TRR, povečajo se finančni prihodki","Zmanjša se TRR, povečajo se finančni odhodki","Poveča se TRR, povečajo se finančni odhodki","Poveča se TRR, zmanjšajo se finančne naložbe"],"correct":0,"explanation":"Prejete obresti za <b>dano</b> posojilo so <b>finančni prihodki ↑ = kredit</b>; <b>TRR ↑ = debet</b>. Nasprotje plačila obresti od lastnega dolga.","htmlExpl":true},{"q":"Podjetje je prodalo proizvode na up (izdalo račun). Kako se knjiži PRIHODKOVNI del?","options":["Povečajo se terjatve do kupcev in prihodki od prodaje","Poveča se TRR in prihodki od prodaje","Povečajo se terjatve do kupcev, zmanjša se zaloga proizvodov","Povečajo se terjatve do kupcev in obveznosti do države"],"correct":0,"explanation":"Prodaja na up: <b>terjatve do kupcev ↑ = debet</b>, <b>prihodki od prodaje ↑ = kredit</b>. Prihodek nastane ob izdaji računa (ne ob plačilu). Plačilo kupca je kasnejši dogodek (↑ TRR, ↓ terjatve).","htmlExpl":true},{"q":"Ob prodaji proizvodov nastanejo stroški prodanih proizvodov. Kako se knjiži ODHODKOVNI del?","options":["Povečajo se poslovni odhodki (stroški prodanih proizvodov), zmanjša se zaloga proizvodov","Povečajo se prihodki, zmanjša se zaloga proizvodov","Povečajo se poslovni odhodki, poveča se zaloga proizvodov","Povečajo se stroški materiala, zmanjša se zaloga"],"correct":0,"explanation":"Prodani proizvodi odidejo iz zaloge v odhodke: <b>poslovni odhodki (stroški prodanih proizvodov) ↑ = debet</b>, <b>zaloga proizvodov ↓ = kredit</b>. To je odhodkovna stran prodaje (ločeno od prihodkovne).","htmlExpl":true},{"q":"Podjetje je plačalo najemnino za poslovni prostor iz TRR. Kako se knjiži?","options":["Povečajo se stroški storitev, zmanjša se TRR","Poveča se zaloga, zmanjša se TRR","Povečajo se stroški storitev in obveznosti do dobaviteljev","Povečajo se stroški materiala, zmanjša se TRR"],"correct":0,"explanation":"Najemnina je <b>storitev</b>: <b>stroški storitev ↑ = debet</b>, <b>TRR ↓ = kredit</b> (plačano takoj). Če bi prejeli le račun (brez plačila), bi namesto TRR rasle obveznosti do dobaviteljev.","htmlExpl":true},{"q":"Podjetje je najelo kombi in prejelo račun za enomesečno najemnino (še ni plačano). Kako se knjiži?","options":["Povečajo se stroški storitev in obveznosti do dobaviteljev","Povečajo se stroški storitev, zmanjša se TRR","Poveča se zaloga in obveznosti do dobaviteljev","Povečajo se stroški materiala in obveznosti do dobaviteljev"],"correct":0,"explanation":"Najem je storitev, prejet račun (ne plačilo): <b>stroški storitev ↑ = debet</b>, <b>obveznosti do dobaviteljev ↑ = kredit</b>.","htmlExpl":true},{"q":"Kupec je plačal že izstavljeni račun za opravljeno storitev. Kako se knjiži?","options":["Poveča se TRR, zmanjšajo se terjatve do kupcev","Poveča se TRR, povečajo se prihodki od prodaje","Zmanjša se TRR, zmanjšajo se terjatve","Poveča se TRR, zmanjšajo se obveznosti"],"correct":0,"explanation":"Plačilo terjatve: <b>TRR ↑ = debet</b>, <b>terjatve do kupcev ↓ = kredit</b>. Prihodek je bil pripoznan že ob izdaji računa, zato ga tu NE knjižimo znova (sicer bi bil dvojno upoštevan).","htmlExpl":true},{"q":"Podjetje je opravilo storitev in izdalo račun (plačilo še ni prejeto). Kako se knjiži?","options":["Povečajo se terjatve do kupcev in prihodki od prodaje","Poveča se TRR in prihodki od prodaje","Povečajo se terjatve do kupcev, zmanjša se zaloga","Povečajo se prihodki, zmanjša se TRR"],"correct":0,"explanation":"Opravljena storitev z računom: <b>terjatve do kupcev ↑ = debet</b>, <b>prihodki od prodaje ↑ = kredit</b>. Prihodek pripoznamo ob opravljeni storitvi/izdaji računa (načelo nastanka).","htmlExpl":true},{"q":"Podjetje je prodalo finančne naložbe (delnice) po višji ceni od nabavne; denar prejelo na TRR. Kako se knjiži?","options":["Poveča se TRR, zmanjšajo se finančne naložbe, povečajo se finančni prihodki","Poveča se TRR, zmanjšajo se finančne naložbe","Poveča se TRR, povečajo se finančni odhodki","Zmanjša se TRR, povečajo se finančne naložbe"],"correct":0,"explanation":"Prodaja z dobičkom: <b>TRR ↑ = debet</b>, <b>finančne naložbe ↓ = kredit</b> (po nabavni vrednosti), razlika (dobiček) = <b>finančni prihodki ↑ = kredit</b>.","htmlExpl":true},{"q":"V postopku prisilne poravnave so se zmanjšale obveznosti do dobaviteljev. Kako se knjiži?","options":["Zmanjšajo se obveznosti do dobaviteljev, povečajo se drugi prihodki","Zmanjšajo se obveznosti do dobaviteljev, poveča se TRR","Zmanjšajo se obveznosti do dobaviteljev in odhodki","Povečajo se obveznosti do dobaviteljev in prihodki"],"correct":0,"explanation":"Odpis dela dolga je gospodarska korist: <b>obveznosti do dobaviteljev ↓ = debet</b>, <b>drugi prihodki ↑ = kredit</b>.","htmlExpl":true},{"q":"Podjetje je nabavilo material po ceni z 22 % DDV (na odloženo plačilo). Kako se knjiži?","options":["Poveča se zaloga materiala (brez DDV), terjatve do države (vstopni DDV) in obveznosti do dobaviteljev (z DDV)","Poveča se zaloga materiala (z DDV) in obveznosti do dobaviteljev","Poveča se zaloga materiala in obveznosti do države","Povečajo se stroški materiala (z DDV) in obveznosti do dobaviteljev"],"correct":0,"explanation":"DDV pri nabavi: <b>zaloga materiala ↑</b> (vrednost brez DDV, debet), <b>terjatve do države za vstopni DDV ↑</b> (debet — DDV bomo poračunali), <b>obveznosti do dobaviteljev ↑</b> (celoten znesek z DDV, kredit). Vstopni DDV ni strošek.","htmlExpl":true},{"q":"Podjetje je prodalo proizvode po ceni z 22 % DDV (na up). Kako se knjiži prihodkovni del z DDV?","options":["Povečajo se terjatve do kupcev (z DDV), prihodki od prodaje (brez DDV) in obveznosti do države (izstopni DDV)","Povečajo se terjatve do kupcev in prihodki od prodaje (z DDV)","Povečajo se terjatve do kupcev (z DDV) in prihodki od prodaje (z DDV)","Povečajo se terjatve do kupcev in terjatve do države"],"correct":0,"explanation":"DDV pri prodaji: <b>terjatve do kupcev ↑</b> (z DDV, debet), <b>prihodki od prodaje ↑</b> (brez DDV, kredit — DDV ni prihodek), <b>obveznosti do države za izstopni DDV ↑</b> (kredit).","htmlExpl":true}]}],"notes":"<h2>Uvod v računovodstvo · povzetek snovi</h2>\n<div class=\"note-card\">\n<h3>1. Temelji računovodstva</h3>\n<ul><li><b>Računovodstvo</b> je del informacijskega sistema podjetja; spremlja gospodarske kategorije (sredstva, obveznosti, stroške, prihodke, odhodke, poslovni izid).</li><li><b>Vrste</b>: <b>finančno</b> (za zunanje uporabnike), <b>stroškovno</b> (notranje poslovanje, analitika), <b>poslovodno</b> (odločanje, prihodnost).</li><li><b>Uporabniki</b>: notranji (poslovodstvo, lastniki z aktivno pravico, zaposleni) in zunanji (posojilodajalci, država, dobavitelji, kupci, konkurenti).</li><li><b>Knjigovodstvo</b> je del računovodstva (evidentiranje); računovodstvo je širši pojem (še analiziranje, načrtovanje, nadziranje).</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>2. Zakonski okvir in predpostavki</h3>\n<ul><li><b>ZGD</b> (8. poglavje) ureja poslovne knjige in letno poročilo; podrobnosti določajo <b>standardi</b>.</li><li><b>SRS</b> (Slov. inštitut za revizijo) — majhna/srednja; <b>MSRP</b> (IFRS) — obvezno za borzna podjetja, banke, zavarovalnice in konsolidacije. Sklep o izbiri sprejmejo <b>lastniki</b> (nato vsaj 5 let). ZDA: <b>US GAAP</b>.</li><li>Družbe (po št. zaposlenih, prihodkih, sredstvih): mikro, majhne, srednje, velike → vpliva na obseg LP in obvezno revizijo.</li><li><b>Dve predpostavki</b>: (1) <b>nastanek poslovnih dogodkov</b> (accrual — beležimo ob nastanku, ne ob plačilu), (2) <b>časovna neomejenost delovanja</b> (going-concern).</li><li><b>Pravilnik o računovodstvu</b> = temeljni notranji akt podjetja.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>3. Bilanca stanja in knjižbe</h3>\n<ul><li><b>Bilanca stanja</b>: SREDSTVA = OBVEZNOSTI DO VIROV SREDSTEV (na določen <i>dan</i>). Sredstva po likvidnosti, obveznosti po zapadlosti.</li><li><b>Konto</b>: debet (leva) / kredit (desna). Prva številka = kontni <b>razred</b>, druga = <b>skupina</b>, tretja = <b>sintetični konto</b>.</li><li><b>Kontni razredi</b>: sredstva 0,1,3,6; obveznosti do virov 2 (kratkoročne) in 9 (kapital/dolgoročne); stroški 4; odhodki in prihodki 7; poslovni izid 8.</li><li><b>4 temeljne knjižbe</b> (le BS): ↑S↑OVS, ↓S↓OVS, ↑S↓S, ↑OVS↓OVS.</li><li><b>4 izvedene knjižbe</b> (prek poslovnega izida): ↑S↑prihodkov, ↓S↑odhodkov, ↓OVS↑prihodkov, ↑OVS↑odhodkov.</li><li><b>Stroški</b> nastanejo ob porabi prvin (≠ izdatek, ≠ odhodek). <b>Naravne vrste</b>: material, dela, amortizacije, storitev.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>4. Osnovna sredstva in zaloge</h3>\n<ul><li><b>OOS</b>: nabavna − popravek = <b>neodpisana</b> (knjigovodska) vrednost. <b>Amort. osnova</b> = nabavna − preostala vrednost; mesečni strošek = AO/(leta×12); začnemo <b>mesec po usposobitvi</b>.</li><li><b>Prodaja OOS</b> vs neodpisana vrednost: cena = NV → ni izida; cena &gt; NV → drugi poslovni <b>prihodki</b>; cena &lt; NV → drugi poslovni <b>odhodki</b>.</li><li><b>Vrednotenje zalog</b>: material in blago po <b>nabavni vrednosti</b>; proizvodi in nedok. proizvodnja po <b>stroških nastajanja</b>.</li><li><b>Metode vrednotenja proizvodov</b>: zožena lastna cena (vsi stroški → najvišja cena), proizvajalni stroški (priporoča MSRP/SRS), spremenljivi proizvajalni stroški (najnižja cena).</li><li><b>Zmanjševanje vrednosti zalog</b>: FIFO, drseče tehtane povprečne cene. LIFO od 2006 ni dovoljen. Ob rastočih cenah FIFO → nižji stroški, višji izid.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>5. Časovne razmejitve</h3>\n<ul><li>Razmejujemo <b>prihodke in stroške</b>, da pripadejo pravemu obdobju (en račun za daljše obdobje).</li><li><b>AČR</b>: odloženi stroški (vnaprej plačano), nezaračunani prihodki (storitev opravljena, račun še ne izdan).</li><li><b>PČR</b>: odloženi prihodki (vnaprej prejeto plačilo), vnaprej vračunani stroški (strošek nastaja, račun kasneje).</li><li><b>Rezervacije in dolgoročne PČR</b>: enako kot kratkoročne, a za obdobje &gt; 1 leto.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>6. IPI, denarni tokovi, davek</h3>\n<ul><li><b>IPI</b>: I. različica (nemška) PRIHODKI − STROŠKI (prilagojeni za spremembo zalog); II. različica (anglo-ameriška) PRIHODKI − ODHODKI. Izid je <b>enak</b>; SRS dajejo prednost <b>II</b>.</li><li>Odhodki = stroški ± sprememba zalog (zaloga ↑ → odhodki = stroški − povečanje; zaloga ↓ → odhodki = stroški + zmanjšanje).</li><li><b>EBIT</b> = poslovni izid iz poslovanja; <b>EBITDA</b> = EBIT + amortizacija. <b>DDPO</b> = davek od dohodkov pravnih oseb.</li><li><b>Kosmati poslovni izid od prodaje</b> = prihodki od prodaje − proizvajalni stroški prodanih proizvodov (trgovina: − nabavna vrednost prodanega blaga = RVC).</li><li><b>Izkaz denarnih tokov</b>: prejemki/izdatki za 3 dejavnosti — poslovanje, naložbenje (investiranje), financiranje. Prejemki ≠ prihodki. Neposredna metoda (SRS) vs posredna.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>7. Letno poročilo, revidiranje, analiza</h3>\n<ul><li><b>Letno poročilo</b> = poslovno poročilo + računovodsko poročilo. Računovodsko = letni izkazi + priloge s pojasnili + (po potrebi) poročilo revizorja.</li><li><b>5 računovodskih izkazov</b>: BS, IPI, IDT, izkaz vseobsegajočega donosa, izkaz gibanja kapitala.</li><li>Rok za LP: <b>3 mesece</b> (konsolidirano 4) po koncu poslovnega leta (ZGD 54). Sprejem: dvotirni (uprava pripravi, nadzorni svet sprejme) / enotirni (upravni odbor). Objava prek <b>AJPES</b>.</li><li><b>Revidiranje</b>: poveča zaupanje uporabnikov v izkaze → revizorjevo mnenje.</li><li><b>Analiza</b>: vodoravna (v času, indeksi) in navpična (strukturni deleži). <b>Kazalec</b> = absoluten, <b>kazalnik</b> = relativen. Skupine kazalnikov: financiranja, investiranja, plačilne sposobnosti, obračanja, gospodarnosti, donosnosti.</li></ul>\n</div>"}]},{"id":"stat","name":"Osnove statistike","tier":"B","parts":[{"id":"k1","name":"1. kolokvij (teme 1–4)","type":"kolokvij","decks":[{"id":"st-t12","name":"Uvod, zgodovina in podatki (teme 1–2)","questions":[{"q":"Kateri razvijalec statistike je dal ime znani statistični krivulji normalne porazdelitve?","options":["Karl Pearson","William Gosset","Florence Nightingale","Carl Friedrich Gauss","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Carl Friedrich Gauss je opisal normalno porazdelitev, ki jo pogosto imenujemo Gaussova krivulja."},{"q":"Kdo je zahteval popis nepremičnin, drobnice in prebivalcev v Angliji v 11. stoletju?","options":["William I. the Conqueror","Florence Nightingale","Karl Pearson","Carl Friedrich Gauss","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Osvajalec William I. the Conqueror je zahteval popis nepremičnin, drobnice in prebivalcev, kar velja za enega prvih sistematičnih popisov v Evropi."},{"q":"Katera od navedenih je metoda PRIMARNEGA zbiranja podatkov?","options":["Branje tiskanih publikacij","Anketa med potrošniki","Iskanje podatkov v podatkovnih bazah","Pregled spletnih portalov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Anketa je klasična metoda primarnega zbiranja podatkov — podatke zbiramo neposredno sami."},{"q":"Finančni in časovni prihranki ter hitra razpoložljivost so prednosti:","options":["Primarnih podatkov pred sekundarnimi","Sekundarnih podatkov pred primarnimi","Eksperimenta pred anketo","Intervjuja pred vprašalnikom","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Finančni in časovni prihranki, hitra razpoložljivost in regularnost objav so glavne prednosti sekundarnih podatkov."},{"q":"Katera je tipična omejitev sekundarnih podatkov?","options":["Visoki stroški zbiranja","Zastarelost podatkov in neustreznost definicij","Potreba po lastni anketni mreži","Nezmožnost objave na spletu","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Sekundarni podatki so pogosto zastareli, temeljijo na definicijah, ki ne ustrezajo našemu namenu, in imajo lahko prekinite časovne serije."},{"q":"Intervju je opredeljen kot:","options":["Sistematično opazovanje enot v naravnih razmerah","Pogovor z določenim namenom","Statistično testiranje hipotez o vzorcih","Analiza spletnih strani in forumov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Intervju je pogovor z določenim namenom; delimo ga na osebni (ena na ena) in skupinski (fokusne skupine)."},{"q":"Kateri od navedenih je primer opazovalne študije?","options":["Telefonska anketa o zadovoljstvu strank","Navidezno nakupovanje — skriti kupec","Skupinski intervju s fokusno skupino","Poštna anketa o porabi gospodinjstev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Navidezno nakupovanje (skriti kupec) je tipičen primer opazovalne študije, kjer so enote opazovane v naravnih razmerah."},{"q":"POPIS (census) v statistiki pomeni:","options":["Opazovanje izbranega dela enot populacije","Ocenjevanje parametrov iz vzorčnih podatkov","Opazovanje vseh posamičnih enot populacije","Zbiranje primarnih podatkov z anketo","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Popis (census) pomeni opazovanje vseh enot, ki sestavljajo populacijo — ne le vzorca."},{"q":"Statistični parameter je:","options":["Vrednost, ki se od enote do enote spreminja","Konstanta, ki numerično izraža značilnosti populacije","Del vzorčnih podatkov, pridobljenih z anketo","Skupina spremenljivk v frekvenčni porazdelitvi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Parameter je konstanta, ki numerično izraža količinske in kakovostne značilnosti populacije — za vse enote je enak."},{"q":"Sklepna statistična analiza se ukvarja z:","options":["Opisovanjem parametrov celotne populacije","Posploševanjem in ocenjevanjem na osnovi vzorčnih podatkov","Grafičnim prikazom frekvenčnih porazdelitev","Zbiranjem primarnih podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Sklepna statistika posplošuje, napoveduje in ocenjuje povezave med spremenljivkami na osnovi nepopolnih (vzorčnih) podatkov."},{"q":"PRS je kratica za:","options":["Poslovni register Slovenije","Pokrajinski register skupnosti","Področni register storitev","Primarni register statistike","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"PRS je Poslovni register Slovenije — eden najpomembnejših slovenskih registrov, ki vsebuje podatke o poslovnih subjektih."},{"q":"RTE je kratica za:","options":["Register teritorialnih enot","Register tujih enot","Register tržnih ekvivalentov","Register tehničnih evidenc","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"RTE je Register teritorialnih enot — register, ki vsebuje podatke o geografski razdelitvi države."},{"q":"Kaj je konstruktivni register?","options":["Register, ki ga vodi računalniški sistem brez človeških posegov","Register, pri katerem enota z vpisom pridobi lastnost, ki je prej ni imela","Register, ki temelji na izvirnih podatkih formalnih dokumentov","Register, ki je dostopen le pooblaščenim institucijam","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri konstruktivnem registru enota z vpisom pridobi določeno lastnost, ki je prej ni imela (npr. pravno osebnost z vpisom v sodni register)."},{"q":"Katera razpredelnica ima enote opazovanja v vrsticah in spremenljivke v stolpcih?","options":["Razpredelnica surovih podatkov (podatkovna matrika)","Frekvenčna tabela","Kontingenčna tabela","Strukturna tabela","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Razpredelnica surovih podatkov (podatkovna matrika) ima v vrsticah enote opazovanja, v stolpcih pa spremenljivke — logika Excela in SPSS. Frekvenčna tabela prikazuje frekvenčno porazdelitev, kontingenčna pa dve opisni spremenljivki hkrati (v vrsticah in stolpcih).","wrong":{"Frekvenčna tabela":"Frekvenčna tabela prikazuje frekvenčno porazdelitev vrednosti spremenljivke, ne surovih enot v vrsticah.","Kontingenčna tabela":"Kontingenčna tabela razvršča enote po dveh opisnih spremenljivkah (v vrsticah in stolpcih), ne enot opazovanja v vrsticah.","Strukturna tabela":"Strukturna tabela prikazuje deleže (strukturo) celote, ne surovih podatkov."}},{"q":"Kateri od navedenih opisuje STVARNO opredelitev statističnih množic?","options":["Opredelitev geografskega območja preučevane populacije","Opredelitev časovnega obdobja opazovanja","Opredelitev vsebinskih lastnosti, ki jih enota mora izpolnjevati","Opredelitev skupnega števila enot v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stvarna opredelitev statističnih množic opisuje vsebinske lastnosti enot (npr. \"redni\" v: \"redni študent EF UL\")."},{"q":"Kvantitativni podatki se delijo na:","options":["Nominalne in ordinalne","Diskretne (celoštevilske) in zvezne (kontinuirane)","Primarne in sekundarne","Absolutne in relativne","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Kvantitativni (številski) podatki se delijo na diskretne (celoštevilske) in zvezne (kontinuirane)."},{"q":"Porterjev model petih silnic spada med orodja za:","options":["Analizo notranjega okolja podjetja","Analizo privlačnosti panoge","Merjenje demografskih sprememb trga","Zbiranje primarnih podatkov o potrošnikih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Porterjev model petih silnic je orodje za oceno privlačnosti panoge na osnovi petih elementov (rivalstvo, substituti, dobavitelji, kupci, vstopne ovire)."},{"q":"Kolikšna je bila stopnja anketne brezposelnosti v Q4 2025?","options":["2,8 %","4,1 %","4,9 %","6,2 %","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja anketne brezposelnosti v Q4 2025 je znašala 4,1 % (vir: SURS)."},{"q":"Kateri od načinov zbiranja podatkov je primeren za oceno stanja v točno določenem trenutku (ne intervalu)?","options":["Anketna metoda z letnim vzorcem","Popis (census), ki zajame vse enote v točno določenem datumu","Panelna anketa z mesečnim sledenjem","Administrativni register z letnimi posodobitvami","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za oceno stanja v točno določenem trenutku je najprimernejši popis (census), ki zajame vse enote na točno določen datum."},{"q":"Katera od trditev o vzorčni oceni parametra je pravilna?","options":["Vzorčna ocena je vedno enaka pravi vrednosti parametra","Vzorčna ocena je rezultat vzorčenja in se od prave vrednosti parametra razlikuje za vzorčno napako","Vzorčna ocena je natančnejša od popisa","Vzorčna ocena je vedno nezanesljiva in neuporabna","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Vzorčna ocena je rezultat vzorčenja. Razlikuje se od prave vrednosti parametra za vzorčno napako, ki jo je mogoče statistično oceniti."},{"q":"Katera trditev o neenakosti med stopnjo registrirane in anketne brezposelnosti je pravilna?","options":["Stopnja registrirane brezposelnosti je vedno višja","Razlika nastane, ker imata različne definicije brezposelnih oseb","Obe merita isti pojav z enako metodologijo","Anketna brezposelnost vedno podcenjuje dejansko stanje","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Razlika med stopnjama nastane zaradi različnih definicij: registrirana brezposelnost temelji na registraciji pri ZRSZ, anketna pa na standardih ILO."}]},{"id":"st-t34-1","name":"Lestvice, prikaz in opisne mere (teme 3–4) (1/2)","questions":[{"type":"match","q":"Poveži mersko lestvico z njeno značilnostjo.","pairs":[{"term":"Imenska (nominalna)","def":"Le razvrščanje v kategorije brez vrstnega reda (npr. spol)"},{"term":"Ordinalna","def":"Kategorije z vrstnim redom, a brez enakih razmikov (npr. ocena)"},{"term":"Intervalna","def":"Enaki razmiki, a brez absolutne ničle (npr. °C)"},{"term":"Razmernostna","def":"Enaki razmiki in absolutna ničla (npr. dohodek)"}],"explanation":"Lestvice si sledijo od najnižje (imenska) do najvišje (razmernostna)."},{"type":"match","q":"Poveži srednjo vrednost z njeno opredelitvijo.","pairs":[{"term":"Aritmetična sredina","def":"Vsota vseh vrednosti, deljena s številom enot"},{"term":"Mediana","def":"Vrednost, ki razdeli urejeni niz na dva enaka dela"},{"term":"Modus","def":"Najpogostejša vrednost v nizu"},{"term":"Geometrijska sredina","def":"Primerna za povprečenje stopenj rasti in indeksov"}],"explanation":"Aritmetična sredina je občutljiva na osamelce, mediana in modus pa ne."},{"type":"match","q":"Poveži mero razpršenosti z njeno opredelitvijo.","pairs":[{"term":"Variacijski razmik","def":"Razlika med največjo in najmanjšo vrednostjo"},{"term":"Varianca","def":"Povprečje kvadratov odklonov od aritmetične sredine"},{"term":"Standardni odklon","def":"Koren variance; razpršenost v izvirnih enotah"},{"term":"Koeficient variacije","def":"Relativna razpršenost glede na povprečje (v %)"}],"explanation":"Koeficient variacije = (std. odklon / AS) × 100 omogoča primerjavo razpršenosti različnih pojavov."},{"q":"Zakon o državni statistiki je bil v Sloveniji sprejet leta:","options":["1991","1995","2001","2004","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Zakon o državni statistiki je bil sprejet leta 1995 in določa pravne okvire za delovanje državne statistike v Sloveniji."},{"q":"Nominalna spremenljivka je tista, pri kateri:","options":["Vrednosti uredimo od najmanjše do največje","Primerjamo razlike med vrednostmi","Vrednosti le razlikujemo med seboj","Primerjamo razmerja med vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Pri nominalnih spremenljivkah vrednosti le razlikujemo med seboj (ugotavljamo enakost ali neenakost). Primeri: spol, zakonski stan, naslov."},{"q":"Ordinalna spremenljivka je tista, pri kateri:","options":["Vrednosti le razlikujemo med seboj","Vrednosti uredimo od najmanjše do največje","Primerjamo razlike med vrednostmi","Primerjamo razmerja med vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri ordinalnih spremenljivkah vrednosti uredimo po velikosti (razvrstimo), ne moremo pa meriti razdalj med njimi. Primeri: izobrazba, ocena."},{"q":"Katera spremenljivka ima lastnosti INTERVALNE merske lestvice?","options":["Spol zaposlenega","Zakonski stan","Temperatura v stopinjah Celzija","Višina mesečne plače v EUR","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Temperatura v stopinjah Celzija je intervalna spremenljivka: primerjamo razlike med vrednostmi, ni pa smiselnega absolutnega izhodišča (0 °C ni odsotnost temperature)."},{"q":"Katera spremenljivka ima lastnosti RAZMERNOSTNE merske lestvice?","options":["Letnik študija","Inteligenčni kvocient (IQ)","Temperatura v Celziusih","Mesečna plača v EUR","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Mesečna plača v EUR je razmernostna spremenljivka: primerjamo razmerja (npr. ena plača je dvakrat večja od druge), absolutno izhodišče (0 EUR = brez dohodka) je smiselno."},{"q":"Spol je primer spremenljivke z mersko lestvico:","options":["Ordinalno","Intervalno","Nominalno","Razmernostno","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Spol je nominalna spremenljivka — vrednosti (moški, ženski) so le kategorije brez naravnega vrstnega reda."},{"q":"Izobrazba zaposlenega (osnovna, srednja, višja, visoka) je primer:","options":["Nominalne spremenljivke","Ordinalne spremenljivke","Intervalne spremenljivke","Razmernostne spremenljivke","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Izobrazba je ordinalna spremenljivka — vrednosti imajo naravni vrstni red (od najnižje do najvišje), razdalje med njimi pa niso enakovredne."},{"q":"Celoštevilska (diskretna) spremenljivka zavzame:","options":["Vse realne vrednosti v nekem intervalu","Le cela (diskontinuirana) števila","Samo vrednosti med 0 in 1","Izključno negativne vrednosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Celoštevilska oz. diskretna spremenljivka zavzame le cela števila (npr. število zaposlenih, število otrok, izpitna ocena)."},{"q":"Vzorec je:","options":["Celotna populacija preučevanega pojava","Del populacije, ki obsega izbrane enote","Vrednost parametra za celotno populacijo","Spremenljivka z nominalnimi vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Vzorec je del populacije, ki ga opazujemo z namenom, da iz vzorčnih podatkov izračunamo ocene parametrov za celotno populacijo."},{"q":"Spremenljivka v statistiki je:","options":["Konstanta, ki opisuje populacijo kot celoto","Značilnost, ki jo vključimo v statistično analizo","Vrednost parametra za celotno populacijo","Posamezna enota preučevane populacije","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Spremenljivka je značilnost enote, ki smo jo vključili v statistično analizo. Vrednost spremenljivke se od enote do enote razlikuje."},{"q":"Promil (‰) se uporablja, ko je celota enaka:","options":["1","100","1000","10.000","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni odtisoček ali promil (‰) se uporablja pri demografskih kazalcih, kjer je celota 1000."},{"q":"Indeks I a/b = 125 pomeni, da je v a za koliko % VEČ kot v b?","options":["125 %","12,5 %","25 %","1,25 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Iz indeksa 125 odštejemo bazno vrednost 100 in dobimo 25 %. V a je torej 25 % več kot v b."},{"q":"Indeks I a/b = 80 pomeni, da je v a za koliko % MANJ kot v b?","options":["80 %","8 %","20 %","0,80 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"100 – 80 = 20. V a je 20 % manj kot v b."},{"q":"SWOT (PSPN) analiza preučuje:","options":["Samo prednosti podjetja v primerjavi s konkurenco","Prednosti, slabosti, priložnosti in nevarnosti","Politično, socialno, ekonomsko in tehnološko okolje","Stopnjo rivalstva med obstoječimi podjetji v panogi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"SWOT analiza (v slovenščini PSPN) preučuje prednosti, slabosti, priložnosti in nevarnosti — namen je pomoč pri strateških odločitvah."},{"q":"Makro statistični sistemi so:","options":["Del poslovnih informacijskih sistemov","Istovetni z računovodskimi sistemi podjetij","Samostojni in od podjetja neodvisni statistični sistemi","Registri na ravni posameznih občin","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Makro statistični sistemi so samostojni in od podjetja neodvisni statistični sistemi (npr. ESS, SSS)."},{"q":"Katera vrsta analize preučuje odnos med DVEMA spremenljivkama?","options":["Univariantna analiza","Bivariatna analiza","Multivariatna analiza","Deskriptivna analiza","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Bivariatna analiza preučuje odnos med dvema spremenljivkama. Univariatna preučuje eno, multivariatna pa tri ali več."},{"q":"Katera od navedenih velja za INTERVALNO spremenljivko?","options":["Število zaposlenih v podjetju","Stopnja izobrazbe zaposlenega","Mesečna bruto plača v EUR","Temperatura zraka v stopinjah Celzija","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Temperatura v °C je intervalna — razlike so smiselne (20 °C – 10 °C = 10 °C), ni pa smiselnega absolutnega izhodišča."},{"q":"Katera od navedenih trditev o APRS je pravilna?","options":["Vsebuje le aktivne poslovne subjekte z več kot 5 zaposlenimi","Vsebuje vse registrirane poslovne subjekte ne glede na aktivnost","Individualni podatki so dostopni samo akademskim institucijam","Vsebuje izključno podjetja s statusom pravne osebe","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"APRS vsebuje vse registrirane poslovne subjekte, ne glede na to, ali so aktivni ali ne."},{"q":"V čem se SPRS razlikuje od APRS?","options":["SPRS vsebuje manj enot in je dostopnejši javnosti","SPRS temelji na APRS, dodaja pa ažuriranje spremenljivk in ni javno dostopen","SPRS ne vključuje podružnic tujih podjetij","SPRS vsebuje izključno mikro podjetja","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"SPRS temelji na APRS, a so enote tekoče ažurirane. Za razliko od APRS individualni podatki iz SPRS niso javno dostopni."},{"q":"Katera od navedenih trditev o CRP je pravilna?","options":["CRP vsebuje podatke o poslovnih subjektih in podružnicah","CRP vsebuje EMŠO in osebne podatke o osebah s stalnim ali začasnim prebiv.","CRP je dostopen le sodiščem in policiji","CRP vsebuje le podatke o davčnih zavezancih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"CRP (Centralni register prebivalstva) vsebuje za vsako osebo: EMŠO, kraj rojstva, ime, priimek, državljanstvo, prebivališče, zakonski stan idr."}]},{"id":"st-t34-2","name":"Lestvice, prikaz in opisne mere (teme 3–4) (2/2)","questions":[{"q":"Stopnja brezposelnosti se izračuna kot:","options":["Brezposelni / delovno sposobno prebiv. × 100","Brezposelni / skupno prebiv. × 100","Brezposelni / aktivno prebiv. × 100","Brezposelni / delovno aktivno prebiv. × 100","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stopnja brezposelnosti = brezposelne osebe / aktivno prebivalstvo × 100. Aktivno prebivalstvo = zaposleni + brezposelni."},{"q":"Stopnja delovne aktivnosti se izračuna kot:","options":["Brezposelni / aktivno prebiv. × 100","Delovno aktivno prebiv. / delovno sposobno prebiv. × 100","Aktivno prebiv. / skupno prebiv. × 100","Zaposleni / skupno prebiv. × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja delovne aktivnosti = delovno aktivno prebivalstvo / delovno sposobno prebivalstvo × 100."},{"q":"Katera vrsta tabel ima vrednosti opisnih spremenljivk v VRSTICAH in STOLPCIH?","options":["Frekvenčna tabela","Analitična tabela","Kontingenčna tabela","Razpredelnica surovih podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Kontingenčna tabela ima vrednosti opisnih spremenljivk v vrsticah in stolpcih ter prikazuje frekvenčno porazdelitev za dve opisni spremenljivki.","wrong":{"Razpredelnica surovih podatkov":"Razpredelnica surovih podatkov (podatkovna matrika) ima v vrsticah enote opazovanja, v stolpcih pa spremenljivke (logika Excela) — ne razvršča dveh opisnih spremenljivk v obeh dimenzijah.","Frekvenčna tabela":"Frekvenčna tabela prikazuje porazdelitev frekvenc ene spremenljivke, ne dveh hkrati.","Analitična tabela":"Analitična tabela je splošen izraz za tabelo z izračuni; ne opisuje razporeditve dveh opisnih spremenljivk v vrsticah in stolpcih."}},{"q":"Outlier (ubežnik) je statistični pojem, ki označuje:","options":["Vrednost, ki je znotraj pričakovanega razpona","Vrednost, ki je numerično oddaljena od ostalih podatkov","Spremenljivko z nominalnimi vrednostmi","Vzorčno oceno parametra populacije","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Outlier (ubežnik) je vrednost, ki je numerično oddaljena od ostalih podatkov (zunaj skupnosti vrednosti)."},{"q":"Katera od navedenih NI načelo delovanja slovenske državne statistike?","options":["Nevtralnost in objektivnost","Strokovna neodvisnost","Statistična zaupnost","Pridobitnost in tržna usmerjenost","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Načela delovanja slovenske državne statistike so: nevtralnost, objektivnost, strokovna neodvisnost, racionalnost, statistična zaupnost in preglednost. Pridobitnost ni med njimi."},{"q":"Kateri je tipičen primer zvezne (kontinuirane) spremenljivke?","options":["Število zaposlenih v podjetju","Izpitna ocena pri predmetu","Mesečna višina štipendije v EUR","Število otrok v gospodinjstvu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Mesečna višina štipendije je zvezna (kontinuirana) spremenljivka — lahko zavzame katerokoli vrednost v nekem intervalu (npr. 350,75 EUR).","wrong":{"Število zaposlenih v podjetju":"Število zaposlenih je diskretna (števna) spremenljivka — zavzame le cela števila, ne poljubnih vmesnih vrednosti.","Izpitna ocena pri predmetu":"Izpitna ocena je urejenostna (ordinalna) spremenljivka — kategorije z vrstnim redom, ne zvezna.","Število otrok v gospodinjstvu":"Število otrok je diskretna spremenljivka (le cela števila)."}},{"q":"Enostavni količinski indeks se izračuna kot:","options":["pt / po × 100","qt / qo × 100","Pt × qt / Po × qo × 100","yt / yo × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Enostavni količinski indeks = qt / qo × 100, kjer je qt količina v tekočem in qo količina v baznem obdobju."},{"q":"Splošna stopnja fertilnosti (f) ima v imenovalcu:","options":["Srednje število celotnega prebiv.","Srednje število žensk v rodni dobi (15–49 let)","Število živorojenih v enem letu","Srednje število vseh žensk v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"f = N / V30.6,f,15 × 1000, kjer je V30.6,f,15 srednje število žensk v rodni dobi 15–49 let."},{"q":"Kateri od navedenih je primer diskretne (celoštevilske) spremenljivke?","options":["Mesečna plača v EUR","Temperatura v °C","Število zaposlenih v podjetju","Dolžina letnega dopusta v dnevih","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Število zaposlenih je diskretna spremenljivka — zavzame le cela nenegatavna števila. Dolžina dopusta je diskretna (celi dnevi), plača in temperatura pa sta zvezni."},{"q":"Kolikšna je bila stopnja registrirane brezposelnosti v Sloveniji februarja 2026?","options":["3,2 %","4,1 %","4,9 %","5,8 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stopnja registrirane brezposelnosti v Sloveniji februarja 2026 je znašala 4,9 % (vir: ZRSZ)."},{"q":"Kolikšna je bila mesečna stopnja inflacije (april 2026 / marec 2026)?","options":["0,5 %","1,9 %","3,0 %","3,1 %","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Mesečna stopnja inflacije (april 2026/marec 2026) je znašala 1,9 % (vir: SURS)."},{"q":"Kolikšna je bila stopnja naravnega prirastka v Sloveniji v letu 2024?","options":["-4,1 ‰","-2,2 ‰","0,5 ‰","5,4 ‰","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja naravnega prirastka je bila -2,2 ‰, kar pomeni negativno naravno gibanje (vir: SURS)."},{"q":"Katera trditev o APRS in europski uredbi o statističnih poslovnih registrih je pravilna?","options":["APRS v celoti izpolnjuje vse zahteve evropske uredbe","APRS ne vključuje vseh spremenljivk, ki jih zahteva evropska uredba","APRS vsebuje le aktivne poslovne subjekte","APRS ne vsebuje podatkov o pravnoorganizacijski obliki","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"APRS ne vključuje nekaterih spremenljivk, ki jih zahteva evropska uredba o statističnih poslovnih registrih za podjetja."},{"q":"Združevanje indeksnih vrst na NOVI osnovi izvedemo tako, da:","options":["Vsak člen stare vrste pomnožimo s stičnim členom","Vsak člen stare vrste delimo s stičnim členom in množimo s prvim členom nove vrste","Vsak člen nove vrste delimo z zadnjim členom stare vrste","Obe vrsti seštejemo in delimo z 2","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Združevanje na novi osnovi: vsak člen stare vrste delimo s stičnim členom stare vrste in množimo s prvim členom nove vrste (konstanta 100)."},{"q":"Katera trditev o spreminjanju indeksne osnove je pravilna?","options":["Osnovo spremenimo z množenjem vsakega člena z novim baznim letom","Osnovo spremenimo z deljenjem vsakega člena z vrednostjo novega baznega leta","Osnova se samodejno izračuna brez posegov","Osnove indeksnih vrst ni mogoče spremeniti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Da spremenimo osnovo indeksne vrste z j na 0, delimo vsak člen vrste z vrednostjo tistega člena, ki ustreza novemu baznemu letu (to je konstanta)."},{"q":"Kateri od navedenih je primer TRENUTNE (momentne) statistične množice?","options":["Sklenitve zakonskih zvez v letu 2024","Rojeni v SLO v prvem polletju 2024","Umrli za covidom v letu 2023","Stalno prebiv. SLO na dan 1. januarja 2025","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Trenutne množice so opredeljene za točno določen trenutek. Stanje stalnega prebiv. na dan 1. januarja je momentna množica."},{"q":"Kateri od navedenih je primer RAZMIČNE (intervalne) statistične množice?","options":["Prebiv. SLO na dan 1. julija 2025","Podjetja v APRS na dan 31. decembra 2024","Ločitve v SLO v letu 2024","Delovno aktivni v SLO na dan 30. junija 2025","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Razmične (intervalne) množice so opredeljene z obdobjem (intervalom). Ločitve v določenem letu so tipičen primer."},{"q":"Katera od navedenih je pravilna razlaga indeksa I a/b = 80?","options":["V a je 80 % več kot v b","V a je 20 % manj kot v b","V a je 0,80 krat več kot v b","V a je 1,25 krat več kot v b","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"I a/b = 80 → a ima 20 % manj kot b (100 − 80 = 20 %). V a je 0,80-krat toliko kot v b (ne 0,80 krat VEČ)."},{"q":"Kateri od navedenih opisuje pravilno zaporedje: urejanje, analiza, interpretacija?","options":["Zbiranje → urejanje → prikaz → analiza → interpretacija","Urejanje → zbiranje → analiza → prikaz → interpretacija","Prikaz → analiza → zbiranje → urejanje → interpretacija","Interpretacija → zbiranje → analiza → urejanje → prikaz","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Statistični proces: zbiranje podatkov → urejanje (čiščenje, kodiranje) → prikaz (tabele, grafikoni) → analiza → interpretacija rezultatov."},{"q":"Kateri od navedenih nadomestnih kazalcev za obseg proizvodnje je najustreznejši za primerjave med panogami?","options":["Bruto prihodek od prodaje","Skupna vrednost zalog","Neto dodana vrednost","Skupni stroški dela","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Neto dodana vrednost je najprimernejša mera za medpanožne primerjave obsega proizvodnje, ker eliminira vmesno porabo in obrabo."},{"q":"Indeks je:","options":["Absolutno število z mersko enoto","Relativno (neimenovano) število za primerjavo istovrstnih podatkov","Aritmetična sredina dveh vrednosti","Vsota vrednosti spremenljivke v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Indeks je relativno (neimenovano) število, s katerim primerjamo dvoje ali več istovrstnih podatkov."},{"q":"Indeks s STALNO osnovo se izračuna tako, da:","options":["Za vsak indeks v vrsti vzamemo predhodno obdobje kot osnovo","Za vse indekse v vrsti vzamemo isto bazno obdobje","Za osnovo vzamemo povprečje celotnega opazovanega niza","Indekse zaporedno množimo med seboj","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri indeksih s stalno osnovo je za vse člene v vrsti osnova primerjave enako (isto) bazno obdobje."}]}],"notes":"\n<h2>1–4 · Osnove statistike</h2>\n<div class=\"note-card\">\n<h3>Temeljni pojmi in podatki</h3>\n<ul>\n<li><b>Statistika</b>: zbiranje, urejanje, prikaz in analiza množičnih podatkov. <b>Populacija</b> (vse enote) vs <b>vzorec</b> (del populacije).</li>\n<li><b>Merske lestvice (Stevens)</b>: imenska (kategorije), ordinalna (vrstni red), intervalna (enaki razmiki, brez prave ničle), razmernostna (prava ničla). Višja lestvica = več dovoljenih operacij.</li>\n<li><b>Vrste podatkov</b>: kvalitativni (opisni) vs kvantitativni (številski); <b>primarni</b> (anketa, intervju, opazovanje) vs <b>sekundarni</b> (npr. SURS SI-STAT).</li>\n<li><b>PEST</b> = analiza zunanjega okolja; <b>SWOT</b> = prednosti/slabosti.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Srednje vrednosti in razpršenost</h3>\n<ul>\n<li><b>Aritmetična sredina</b> (občutljiva na osamelce), <b>mediana</b> (razdeli niz na pol, odporna na osamelce), <b>modus</b> (najpogostejša vrednost), <b>geometrijska sredina</b> (za stopnje rasti).</li>\n<li><b>Razpršenost</b>: variacijski razmik, <b>varianca</b>, <b>standardni odklon</b> (koren variance), <b>koeficient variacije</b> = (σ/AS)×100.</li>\n<li><b>Strukture</b> (delež ×100; vsota 100 %) in <b>koeficienti</b> (razmerje dveh vsebinsko povezanih absolutnih števil).</li>\n</ul>\n</div>\n\n<h2>Prikazi podatkov (tabele in grafikoni)</h2>\n<div class=\"note-card\">\n<h3>Tabele</h3>\n<p><b>Razpredelnica surovih podatkov</b> (podatkovna matrika): enote v vrsticah, spremenljivke v stolpcih (logika Excela/SPSS).</p>\n<p><b>Frekvenčna tabela</b> — porazdelitev frekvenc ene spremenljivke:</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px;text-align:left\">Ocena</th><th style=\"border:1px solid var(--line);padding:4px 10px\">f</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">3</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">7</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">8</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">8</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">12</td></tr>\n</table>\n<p><b>Kontingenčna (dvorazsežna) tabela</b> — dve opisni spremenljivki hkrati (v vrsticah in stolpcih):</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px\"></th><th style=\"border:1px solid var(--line);padding:4px 10px\">M</th><th style=\"border:1px solid var(--line);padding:4px 10px\">Ž</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Da</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">14</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">9</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Ne</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">11</td></tr>\n</table>\n</div>\n<div class=\"note-card\">\n<h3>Grafikoni — kateri za kaj</h3>\n<div style=\"display:flex;flex-wrap:wrap;gap:18px;align-items:flex-start\">\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"28\" y=\"92\" width=\"32\" height=\"23\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"60\" y=\"68\" width=\"32\" height=\"47\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"92\" y=\"40\" width=\"32\" height=\"75\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"124\" y=\"30\" width=\"32\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"156\" y=\"62\" width=\"32\" height=\"53\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"188\" y=\"95\" width=\"32\" height=\"20\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Histogram</b> — frekvenčna porazdelitev <i>zvezne</i> spremenljivke (stolpci se stikajo).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 120 120\" style=\"width:100%;max-height:120px\">\n      <!-- 0° pri ura 3 (desno); koti naraščajo v nasprotni smeri urinega kazalca (matematična smer); izseki od največjega -->\n      <path d=\"M60,60 L100,60 A40,40 0 0,0 20,60 Z\" fill=\"var(--terra)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L20,60 A40,40 0 0,0 72.36,98.04 Z\" fill=\"var(--teal)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L72.36,98.04 A40,40 0 0,0 100,60 Z\" fill=\"var(--ink2)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <line x1=\"100\" y1=\"60\" x2=\"112\" y2=\"60\" stroke=\"var(--ink)\" stroke-width=\"1.6\"/>\n      <text x=\"103\" y=\"54\" font-size=\"9\" fill=\"var(--ink2)\">0°</text>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Strukturni krog (tortni)</b> — <i>struktura (deleži)</i> celote. Začnemo pri <b>0° (desno, ura 3)</b> in izseke nizamo po velikosti od največjega, v nasprotni smeri urinega kazalca (matematična smer kotov).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <polyline points=\"34,95 74,72 114,82 154,45 194,58 220,32\" fill=\"none\" stroke=\"var(--teal)\" stroke-width=\"2.5\"/>\n      <g fill=\"var(--teal)\"><circle cx=\"34\" cy=\"95\" r=\"2.5\"/><circle cx=\"74\" cy=\"72\" r=\"2.5\"/><circle cx=\"114\" cy=\"82\" r=\"2.5\"/><circle cx=\"154\" cy=\"45\" r=\"2.5\"/><circle cx=\"194\" cy=\"58\" r=\"2.5\"/><circle cx=\"220\" cy=\"32\" r=\"2.5\"/></g>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Linijski grafikon</b> — <i>kronološko</i> gibanje pojava (časovna vrsta).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"42\" y=\"45\" width=\"30\" height=\"70\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"92\" y=\"70\" width=\"30\" height=\"45\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"142\" y=\"30\" width=\"30\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"192\" y=\"78\" width=\"30\" height=\"37\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Stolpčni grafikon</b> — primerjava <i>opisnih</i> kategorij (stolpci so ločeni).</figcaption>\n  </figure>\n</div>\n</div>\n\n<h2>5–8 · Relativna števila in indeksi</h2>\n<div class=\"note-card\">\n<h3>Enostavni indeksi</h3>\n<ul>\n<li><b>Enostavni indeks</b>: i = (y₁/y₀)×100. Razlaga: <b>I − 100</b> (za koliko %), <b>I : 100</b> (kolikokrat).</li>\n<li><b>Časovni</b> (dve obdobji), <b>krajevni</b> (dva kraja), <b>stvarni</b> (dva pojava). <b>Bazni</b> (stalna osnova) vs <b>verižni</b> (s predhodnim).</li>\n<li><b>Deflacioniranje</b>: realna vrednost = (nominalna / indeks cen)×100. Indeks vrednosti = indeks cen × indeks količin / 100.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Skupinski (agregatni in srednji) indeksi</h3>\n<ul>\n<li><b>Laspeyres</b> (uteži = bazne količine q₀), <b>Paasche</b> (uteži = tekoče količine q₁), <b>Fisher</b> = √(L·P).</li>\n<li><b>Srednji</b>: TAS = agregatni Laspeyres; THS = agregatni Paasche.</li>\n<li><b>Stalna struktura</b> (uteži baznega obdobja) vs <b>spremenljiva struktura</b> (indeks povprečne cene). <b>Strukturni premiki</b> = I(spremenljiva)/I(stalna)×100.</li>\n<li><b>Relacija (vedno „križ\")</b>: Iᵥ = Iₚ(Laspeyres)·I_q(Paasche)/100. Strukturni premiki zavrejo rast cen, ko je IᴾL &gt; IᴾP.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Agregatni vs srednji indeksi — prednosti in slabosti</h3>\n<p style=\"margin:0 0 6px\"><b>Agregatni indeksi</b> (Laspeyres, Paasche, Fisher) — iz vsot vrednosti Σ(p·q):</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: neposredna ekonomska interpretacija (primerjamo dejanske <i>skupne vrednosti</i> košarice); natančni, ker temeljijo na dejanskih cenah <i>in</i> količinah; omogočajo razčlenitev vrednostnega indeksa na cenovni in količinski del (Iᵥ = IᴾL·I_qP/100).</li>\n<li><b>Slabosti</b>: zahtevajo <i>popolne</i> podatke o cenah in količinah za vse postavke v obeh obdobjih (podatkovno zahtevni); izbira obdobja uteži premakne rezultat — <b>Laspeyres</b> (bazne uteži) navzgor precenjuje, <b>Paasche</b> (tekoče uteži) navzdol podcenjuje rast cen; težavni ob spremembi nabora postavk.</li>\n</ul>\n<p style=\"margin:8px 0 6px\"><b>Srednji indeksi</b> (tehtana sredina enostavnih indeksov): <b>TAS</b> tehtana z baznimi vrednostmi p₀q₀ = agregatni Laspeyres; <b>THS</b> tehtana s tekočimi vrednostmi p₁q₁ = agregatni Paasche.</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: izračunljivi že iz <i>posameznih (enostavnih) indeksov</i> in vrednostnih uteži — ni potrebna cela matrika q in p; primerni, ko poznamo strukturo izdatkov/vrednosti, ne pa posameznih količin (tako se v praksi računa npr. indeks cen življenjskih potrebščin); prožni pri izbiri uteži.</li>\n<li><b>Slabosti</b>: rezultat je odvisen od <i>izbire uteži in tipa sredine</i> — napačna sredina (aritmetična namesto harmonične ali obratno) ali napačne uteži dajo pristranski indeks; manj neposredno ekonomsko interpretabilni kot agregati.</li>\n</ul>\n<p style=\"margin:8px 0 0\"><b>Ključno</b>: <b>TAS = Laspeyres</b> in <b>THS = Paasche</b> — ob pravilnih utežeh dasta agregatni in srednji pristop <i>enak</i> rezultat. Razlika ni v vrednosti, ampak v tem, <i>katere podatke imamo na voljo</i>.</p>\n</div>\n\n<h2>9–12 · Klasifikacije, prebivalstvo, ekon. aktivnost</h2>\n<div class=\"note-card\">\n<h3>Statistični sistem in klasifikacije</h3>\n<ul>\n<li><b>ESS</b>: na vrhu <b>Eurostat</b>; v Sloveniji glavni izvajalec <b>SURS</b>.</li>\n<li><b>Klasifikacije</b>: NACE (EU)/SKD (SLO) — dejavnosti; <b>ISIC</b> (ZN) — osnova za NACE; <b>HS</b> — blago/carina; <b>PRODCOM</b> — industrijski proizvodi; CPA — proizvodi po dejavnosti.</li>\n<li><b>Enote</b>: pravna, <b>lokalna</b> (po lokaciji), <b>EED</b> (enovrstna dejavnost). <b>Glavna dejavnost</b> = dejavnost z <b>največ zaposlenimi</b>; pri več hierarhičnih ravneh po <b>top-down metodi</b> (seštevamo navzgor po ravneh, ne izberemo kar največjega razreda). <b>Metapodatki</b> = podatki o podatkih.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Statistične enote — natančno razvrščanje (s primerom)</h3>\n<p style=\"margin:0 0 6px\">Iste podatke o podjetju razvrstimo v <b>štiri vrste enot</b>, vsako po svojem kriteriju:</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> (institucionalna/pravna enota): <b>1</b> na pravni subjekt. Kriterij: pravni status. <i>Primer:</i> Galeb = 1 podjetje.</li>\n<li><b>Lokalna enota (LE)</b>: podjetje ali del podjetja na <b>enem naslovu/lokaciji</b>. Število = <b>število različnih lokacij</b>. Kriterij: <i>geografija</i>. Na enem naslovu je vedno <b>ena</b> LE, tudi če tam tečeta dve dejavnosti.</li>\n<li><b>Enota enovrstne dejavnosti (EED)</b>: del podjetja, ki opravlja <b>eno vrsto dejavnosti</b> (eno šifro), <i>ne glede na lokacijo</i>. Število = <b>število različnih šifer dejavnosti</b>. Kriterij: <i>dejavnost</i>.</li>\n<li><b>Lokalna enota enovrstne dejavnosti (LEVED)</b>: <b>ena dejavnost na eni lokaciji</b>. Število = število <b>dejansko obstoječih kombinacij lokacija–šifra</b>. Kriterij: <i>lokacija IN dejavnost hkrati</i>.</li>\n</ul>\n<p style=\"margin:8px 0 4px\"><b>Pozor:</b> LEVED <b>ni</b> produkt lokacij × šifer. Šteješ samo kombinacije, ki res obstajajo.</p>\n<p style=\"margin:6px 0 4px\"><b>Primer (Galeb):</b> Brnik (62.10), Lesce (62.20), Portorož (62.20 in 63.30).</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> = 1.</li>\n<li><b>LE</b> = 3 (Brnik, Lesce, Portorož).</li>\n<li><b>EED</b> = 3 (tri različne šifre: 62.10, 62.20, 63.30 — čeprav 62.20 nastopa dvakrat, je <i>ena</i> dejavnost).</li>\n<li><b>LEVED</b> = 4 (Brnik–62.10, Lesce–62.20, Portorož–62.20, Portorož–63.30; <i>ne</i> 3×3 = 9).</li>\n<li><b>Skupaj</b> = 1 + 3 + 3 + 4 = <b>11 enot</b>.</li>\n</ul>\n<p style=\"margin:6px 0 0;font-size:13px;color:var(--ink2)\">Mini-pravilo: LE šteje <i>naslove</i>, EED šteje <i>šifre</i>, LEVED šteje <i>pare (naslov, šifra)</i>.</p>\n</div>\n<div class=\"note-card\">\n<h3>Prebivalstvo in ekonomska aktivnost</h3>\n<ul>\n<li><b>Skupni prirastek</b> = naravni prirastek (živorojeni − umrli) + selitveni saldo (priseljeni − odseljeni).</li>\n<li><b>SSN</b> = živorojeni / srednje št. <b>vseh</b> preb. ×1000; <b>SSR</b> = živorojeni / ženske 15–49 ×1000 (SSR &gt; SSN).</li>\n<li><b>Koef. maskulinitete</b> ≈1050; <b>koef. starostne odvisnosti</b> = (0–14 + 65+)/(15–64)×100; <b>indeks staranja</b> = (65+ / 0–14)×100.</li>\n<li><b>Napovedovanje</b>: linearno (konst. absolutni prirastek) vs geometrijsko (konst. stopnja rasti; pri r&gt;0 višja napoved). <b>Produktivnost</b> in <b>intenzivnost</b> = 1/produktivnost. PKM (Big Mac index).</li>\n</ul>\n</div>\n"},{"id":"k2","name":"2. kolokvij (teme 4–8)","type":"kolokvij","decks":[{"id":"st-t5-1","name":"Strukture in koeficienti (tema 5) (1/2)","questions":[{"q":"Kaj je relativno število strukture?","options":["Razmerje med dvema absolutnima številoma iz različnih skupin","Delež posamezne kategorije v celoti, izražen v odstotkih (%)","Razmerje med vrednostmi iz dveh zaporednih časovnih obdobij","Razmerje med vrednostmi iz različnih geografskih enot","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Relativno število strukture = (vrednost kategorije / skupna vrednost) × 100. Pove, koliko odstotkov celote predstavlja posamezna kategorija. Vsota vseh relativnih števil strukture mora biti 100 %."},{"q":"Koliko mora znašati vsota vseh relativnih števil strukture?","options":["0","50","100","Odvisno od podatkov","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Vsota vseh relativnih števil strukture vedno znaša natanko 100 %, ker vsaka kategorija predstavlja delež celote, vse deleže pa seštejemo v celoto."},{"q":"Kateri od nastetih koeficientov je smiseln?","options":["BDP Nemčije / število zaposlenih v kmetijstvu Španije","Promet podjetja A v 2023 / število zaposlenih v podjetju B v 2020","Pridelek hmelja v Nemčiji / površina hmeljišč v Nemčiji v istem letu","Število rojstev v Sloveniji / BDP Kitajske","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Koeficient je smiseln, ko sta števec in imenovalec vsebinsko logično povezana, nanašata se na isto enoto preučevanja in isto časovno obdobje. Pridelek / površina = hektarski pridelek — logična zveza, ista zemlja, isto leto."},{"q":"Kaj je stolpčna pogojna struktura v dvorazsežni tabeli?","options":["Delež vsake celice glede na skupni seštevek celotne tabele","Delež vsake celice glede na vsoto njenega stolpca","Vsota absolutnih vrednosti v posameznem stolpcu","Razmerje med vrsticami tabele","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Stolpčna pogojna struktura prikazuje, kako se vrednosti razporedijo ZNOTRAJ vsakega stolpca — vsaka celica se deli z vsoto svojega stolpca × 100. Vsota vrednosti v vsakem stolpcu je tako 100 %."},{"q":"Florence Nightingale je v statistiki znana po tem, da je razvila:","options":["Temelje opisne statistike s prikazom umrljivosti vojakov","Gaussovo krivuljo normalne porazdelitve","Korelacijski koeficient za merjenje odvisnosti","Metodo vzorčenja pri nadzoru kakovosti piva","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Florence Nightingale je z analizo skupin umrlih vojakov v Turčiji in Krimu postavila temelje opisne statistike."},{"q":"Karl Pearson je v statistiki razvil:","options":["Metodo linearne ekstrapolacije","Korelacijski koeficient","Normalno porazdelitev (Gaussovo krivuljo)","Top-down metodo razvrščanja dejavnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Karl Pearson je razvil korelacijski koeficient, ki meri stopnjo linearne odvisnosti med dvema spremenljivkama."},{"q":"Netnografija je metoda, ki preučuje:","options":["Odzive potrošnikov v fizičnih prodajalnah","Spletne strani in skupnosti na internetu","Demografsko strukturo prebivalstva","Primerjave indeksov cen med državami","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Spletna etnografija (netnografija) je analiza spletnih strani, forumov in skupnosti — oblika opazovalne študije na internetu."},{"q":"Meta podatki so:","options":["Statistični podatki o tujih državah","Podatki o podatkih (vsebina, struktura, kakovost)","Vzorčni podatki, pridobljeni z anketo","Administrativni podatki iz registrov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Meta podatki vsebujejo podatke o podatkih; obsegajo informacije o vsebini, strukturi, kakovosti, lastništvu in distribuciji podatkov."},{"q":"SKD je:","options":["Standardna klasifikacija dejavnosti v Sloveniji","Skupni koeficient demografije","Statistični kazalec dejanske aktivnosti","Sistem kratkih definicij","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"SKD je Standardna klasifikacija dejavnosti — slovenska različica NACE, s katero je do ravni razredov praktično identična."},{"q":"Strukturni odstotek se izračuna, ko je celota enaka:","options":["1","100","1000","10.000","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Strukturni odstotek je izražen v %, kjer je celota 100. Strukturni delež ima celoto 1, strukturni odtisoček (promil) pa 1000."},{"q":"Strukturni delež se izračuna, ko je celota enaka:","options":["100","1000","1","10","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni delež je izražen kot decimalno število med 0 in 1, kjer je celota 1 (100 %)."},{"q":"Strukturni krog (tortni grafikon) se najpogosteje uporablja za prikazovanje:","options":["Kronološke spremembe pojava","Frekvenčne porazdelitve zvezne spremenljivke","Strukture (deležev) celote","Razpršenosti podatkov v vzorcu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni krog je analitični grafikon, namenjen prikazovanju struktur — razčlembi celote na dele.","wrong":{"Kronološke spremembe pojava":"Časovne (kronološke) spremembe prikažemo z linijskim grafikonom, ne s strukturnim krogom.","Frekvenčne porazdelitve zvezne spremenljivke":"Frekvenčno porazdelitev zvezne spremenljivke prikažemo s histogramom.","Razpršenosti podatkov v vzorcu":"Razpršenost prikazujemo npr. s škatlo z brki (boxplot), ne s tortnim grafikonom."}},{"q":"Histogram se najpogosteje uporablja za prikazovanje:","options":["Strukture populacije po skupinah","Frekvenčne porazdelitve zvezne spremenljivke","Kronoloških sprememb indeksov","Korelacije med dvema spremenljivkama","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Histogram prikazuje frekvenčno porazdelitev zvezne (kontinuirane) spremenljivke, razvrščene v razrede."},{"q":"Koeficient je smiseln le, kadar sta podatka v števcu in imenovalcu:","options":["Izražena v različnih merskih enotah","Vsebinsko, prostorsko in časovno usklajena","Iz različnih populacij in različnih obdobij","Izračunana kot absolutni vrednosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient je smiseln le, kadar sta podatka v števcu in imenovalcu vsebinsko, prostorsko in časovno usklajena."},{"q":"PEST analiza je orodje za sistematično preučevanje dejavnikov:","options":["Notranjega okolja podjetja (prednosti in slabosti)","Zunanjega okolja (politično, ekonomsko, socialno, tehnološko)","Primerjalnih prednosti pred konkurenco","Demografske strukture ciljnih kupcev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"PEST analiza preučuje zunanje dejavnike poslovnega okolja: politične, ekonomske, socialne in tehnološke."},{"q":"Kateri od kazalcev SODI med koeficiente?","options":["Absolutni naravni prirastek","Indeks staranja","Splošna stopnja natalitete","Število živorojenih v enem letu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Splošna stopnja natalitete je koeficient — razmerje med številom živorojenih in srednim številom prebivalcev, izraženo v promilih."},{"q":"Enorazsežna struktura pomeni razčlenitev:","options":["Po dveh spremenljivkah hkrati","Po treh ali več spremenljivkah","Po eni spremenljivki","Po nominalnih spremenljivkah","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Enorazsežna struktura je razčlenitev po eni spremenljivki. Dvorazsežna je po dveh, večrazsežna pa po treh ali več."},{"q":"Izhodišče prvega krogovega izseka v strukturnem krogu je:","options":["Pri 90 stopinjah (ura 12.00)","Pri 180 stopinjah (ura 9.00)","Pri 0 stopinjah (ura 15.00)","Pri 270 stopinjah (ura 6.00)","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Izhodišče prvega krogovega izseka je pri 0 stopinjah (ura 15.00), krogove izseke pa nizamo v nasprotni smeri urinega kazalca."},{"q":"Krogove izseke v strukturnem krogu nanašamo:","options":["Naključno, brez posebnega vrstnega reda","Po velikosti od najmanjšega do največjega","Po abecednem redu kategorij","Po velikosti od največjega do najmanjšega","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Krogove izseke v strukturnem krogu nizamo v nasprotni smeri urinega kazalca po velikosti od največjega do najmanjšega."}]},{"id":"st-t5-2","name":"Strukture in koeficienti (tema 5) (2/2)","questions":[{"q":"Katero od navedenih pojasnuje, kaj je »Para podatek«?","options":["Podatek, ki opisuje vsebino in strukturo zbirke podatkov","Opis procesa zbiranja primarnih podatkov, ki omogoča razumevanje nastanka podatkov","Podatek, zbran vzporedno s primarnim za namen preverjanja","Sintetični kazalec na osnovi več spremenljivk","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Para podatki opisujejo proces interpretacije in ustvarjanja podatkov, ki omogoča razumevanje njihovega nastanka in evaluacijo."},{"q":"Koeficient po PREMI shemi (v) meri:","options":["Koliko delovnih ur je potrebnih za enoto producta","Koliko enot proizvoda nastane na enoto porabljenega dela","Koliko delovnih ur je opravljenih na zaposlenega","Koliko denarnih enot prihodka ustvari zaposleni","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient produktivnosti dela po premi shemi (v) = Q/T — pove, koliko enot proizvoda nastane na enoto porabljenega dela."},{"q":"Katera vrsta podatkov je primerna za izračun koeficienta, ki meri produktivnost na zaposlenega?","options":["Nominalni in ordinalni podatki","Samo diskretni (celoštevilski) podatki","Kvantitativni podatki (vrednostni ali naturalni)","Samo primarne podatke iz anket","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient produktivnosti dela zahteva kvantitativne podatke: mere obsega proizvodnje (Q) in potroška dela (T)."},{"q":"Katera vrsta grafičnega prikaza je primerna za prikazovanje koeficientov?","options":["Strukturni krog","Pravokotniki z enako ali različno širino","Starostna piramida","Razsevni diagram (XY)","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za prikazovanje koeficientov so primerni pravokotniki (stolpčni grafikon) z enako ali različno širino."},{"q":"Kateri kazalec meri razmerje med celotnim vzdrževanim delom populacije in delovno aktivnim delom?","options":["Indeks staranja","Stopnja aktivnosti","Koeficient starostne odvisnosti","Stopnja mortalitete","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient starostne odvisnosti = (osebe do 15 let + osebe 65+) / osebe 15–64 let × 100."},{"q":"Kolikšen je bil koeficient starostne odvisnosti v 2. polletju 2025?","options":["48,3","53,7","58,1","63,4","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient starostne odvisnosti je v 2. polletju 2025 znašal 58,1 (vir: SURS)."},{"q":"Kolikšen je bil delež bruto domačih izdatkov za R&R v BDP leta 2024?","options":["1,07 %","1,68 %","2,14 %","2,89 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež bruto domačih izdatkov za R&R v BDP je znašal 2,14 % v letu 2024 (vir: SURS)."},{"q":"Kolikšen je bil delež dnevnih ali skoraj dnevnih uporabnikov interneta (16–74 let) v letu 2025?","options":["72 %","81 %","88 %","94 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež oseb, ki vsak dan ali skoraj vsak dan uporabljajo internet, je bil 88 % v letu 2025 (vir: SURS)."},{"q":"Kolikšen je bil delež e-kupcev (16–74 let) v letu 2025?","options":["52,0 %","59,5 %","67,0 %","74,3 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež e-kupcev je znašal 67,0 % v letu 2025 (vir: SURS)."},{"q":"Katera nadomestna mera za obseg proizvodnje NI primerna za izračun produktivnosti?","options":["Naturalne mere (npr. tone, kosi)","Vrednostne mere (EUR, dodana vrednost)","Pogojno naturalne mere (standardizirane enote)","Število zaposlenih v podjetju","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Število zaposlenih je mera potroška dela (T), ne obsega proizvodnje (Q). Nadomestne mere za Q so: naturalne, pogojno naturalne in vrednostne."},{"q":"Pri izračunu koeficienta, ki meri pridelek hmelja na hektar, je v imenovalcu:","options":["Število zaposlenih v hmeljogojstvu","Površina hmeljišč v hektarjih","Vrednost izvoženega hmelja v EUR","Število porabljenih ur pri pridelavi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pridelek hmelja / hmeljske površine (ha) je smiseln koeficient — meri donos na površinsko enoto. Imenovalec so hmeljske površine."},{"q":"Katera trditev o izvedenih demografskih kazalcih je pravilna?","options":["Absolutni naravni prirastek je izvedeni kazalec","Stopnja naravnega prirastka sodi med absolutne kazalce","Splošna stopnja mortalitete je izvedeni kazalec, ki sodi med koeficiente","Število umrlih v enem letu je relativni kazalec","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Splošna stopnja mortalitete (m) je izvedeni kazalec, ki sodi med koeficiente (razmerje med absolutnimi kazalci)."},{"q":"Katera od trditev o analitičnem prikazu podatkov s strukturnim krogom je NAPAČNA?","options":["Izseke nizamo v smeri urinega kazalca","Izseke nizamo po velikosti od največjega do najmanjšega","Izhodišče prvega izseka je pri 0 stopinjah (ura 15, desno)","3D strukturni krog je manj informativen kot 2D","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Napačna trditev je »v smeri urinega kazalca«: izseke nizamo v NASPROTNI smeri urinega kazalca (matematična smer), z izhodiščem pri 0° (ura 15, desno), po velikosti od največjega do najmanjšega. Ostale tri trditve so pravilne.","wrong":{"Izseke nizamo po velikosti od največjega do najmanjšega":"Ta trditev je PRAVILNA — izseke res nizamo od največjega do najmanjšega, zato ni iskana napačna trditev.","Izhodišče prvega izseka je pri 0 stopinjah (ura 15, desno)":"Ta trditev je PRAVILNA — izhodišče je pri 0° (ura 15, desno), zato ni iskana napačna trditev.","3D strukturni krog je manj informativen kot 2D":"Ta trditev je PRAVILNA — 3D popači zaznavo deležev in je manj informativen, zato ni iskana napačna trditev."}},{"q":"Kateri od navedenih ni predpogoj za smiselnost koeficienta?","options":["Vsebinska usklajenost podatkov v števcu in imenovalcu","Prostorska usklajenost podatkov v števcu in imenovalcu","Časovna usklajenost podatkov v števcu in imenovalcu","Enaka merska enota v števcu in imenovalcu","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Koeficient zahteva vsebinsko, prostorsko in časovno usklajenost — ni pa nujno, da sta merski enoti enaki (npr. kg / ha)."},{"q":"Katera je pravilna opredelitev staranja prebivalstva?","options":["Porast absolutnega števila oseb, starejših od 65 let","Naraščanje deleža starega prebiv. in padanje deleža mladega prebiv. v skupnem prebiv.","Porast koeficienta starostne odvisnosti brez spremembe indeksa staranja","Padanje stopnje natalitete ob hkratnem naraščanju mortalitete","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Demografsko staranje je proces, pri katerem narašča delež starega in pada delež mladega prebiv. v skupnem prebiv."},{"q":"Katera od navedenih je pravilna razlaga koeficienta produktivnosti dela po premi shemi v = Q/T = 5?","options":["Za enoto proizvoda je potrebnih 5 ur dela","Na enoto porabljenega dela nastane 5 enot proizvoda","Delavec zasluži 5 EUR na uro dela","Podjetje porabi 5 enot materiala na enoto proizvoda","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"v = Q/T = 5 pomeni: na enoto porabljenega dela (T) nastane 5 enot proizvoda (Q). Recipročna shema t = T/Q bi dala koliko dela je na enoto proizvoda.","wrong":{"Za enoto proizvoda je potrebnih 5 ur dela":"To opisuje INTENZIVNOST dela (t = T/Q), torej recipročno vrednost produktivnosti — koliko dela je potrebnega na enoto proizvoda, ne obratno.","Delavec zasluži 5 EUR na uro dela":"To je urna postavka oz. plača, ne koeficient produktivnosti dela.","Podjetje porabi 5 enot materiala na enoto proizvoda":"To je tehnični/materialni koeficient porabe materiala, ne produktivnost dela."}},{"q":"Kako imenujemo razliko med vrednostjo vzorčne ocene in pravo vrednostjo parametra?","options":["Standardni odklon","Koeficient variabilnosti","Vzorčna napaka","Mediana","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Razlika med vzorčno oceno in pravo vrednostjo parametra se imenuje vzorčna napaka (sampling error)."},{"q":"Katera od navedenih je pravilna opredelitev para podatka?","options":["Podatek o podatku (vsebina, struktura, kakovost)","Opis procesa zbiranja prim. podatkov, ki omogoča razumevanje nastanka","Vzporedno zbrani podatek za namene preverjanja","Sekundarni podatek iz javno dostopnih registrov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Para podatek opisuje proces interpretacije in ustvarjanja podatkov — dokumentira, kako in zakaj so bili zbrani."}]},{"id":"st-t6","name":"Enostavni indeksi in deflacioniranje (tema 6)","questions":[{"type":"match","q":"Poveži vrsto indeksa z opredelitvijo.","pairs":[{"term":"Časovni indeks","def":"Primerja isti pojav v dveh časovnih obdobjih"},{"term":"Krajevni (prostorski) indeks","def":"Primerja isti pojav v dveh krajih ob istem času"},{"term":"Stvarni indeks","def":"Primerja dva različna pojava ob istem času in kraju"}],"explanation":"Pri časovnem se spreminja čas, pri krajevnem kraj, pri stvarnem pa preučevani pojav."},{"q":"Kaj pomeni bazni enostavni indeks It/0 = 120?","options":["Vrednost se je zmanjšala za 120 enot","Vrednost je v tekočem obdobju za 20 % višja kot v baznem","Vrednost je v baznem obdobju za 20 % višja kot v tekočem","Vrednost je narasla za 120 enot","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Bazni indeks 120 pomeni, da je tekoča vrednost 120 % bazne vrednosti — torej za 20 % višja od bazne. Formula: It/0 = (yt / y0) × 100 = 120 → yt je za 20 % večji od y0."},{"q":"Kaj je verižni indeks?","options":["Indeks, ki primerja tekoče obdobje z enim fiksnim baznim obdobjem","Indeks, ki primerja vrednosti iz dveh različnih krajev ob istem času","Indeks, ki primerja vsako obdobje s prejšnjim (neposredno predhodnim) obdobjem","Produkt vseh baznih indeksov v obravnavanem obdobju","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Verižni indeks (Vt/t-1) primerja vsako obdobje s prejšnjim: Vt/t-1 = (yt / yt-1) × 100. Produkt vseh verižnih indeksov (deljenih s 100) pa da bazni indeks celotnega obdobja."},{"q":"Kaj je deflacioniranje?","options":["Množenje nominalne vrednosti s cenovnim indeksom","Pretvorba nominalnih vrednosti v realne z deljenjem s cenovnim indeksom × 100","Odštevanje stopnje inflacije od nominalne vrednosti","Izračun povprečne cene v baznem letu","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Deflacioniranje: realna vrednost = (nominalna vrednost / indeks cen) × 100. S tem 'izločimo' vpliv cen in dobimo realno spremembo količine oz. obsega. Deliš, ne množiš!"},{"q":"Kaj je prostorski (krajevni) indeks?","options":["Indeks, ki primerja vrednosti iz dveh zaporednih časovnih obdobij","Indeks, ki primerja vrednost istega pojava v dveh različnih krajih v istem časovnem obdobju","Indeks spremembe cen na različnih ravneh ekonomije","Verižni indeks za geografska območja","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Prostorski oz. krajevni indeks: I_A/B = (y_A / y_B) × 100. Primerja ISTO spremenljivko v dveh različnih krajih (državah, regijah...) ob ISTEM časovnem obdobju. Npr. BDP na preb. Avstrije glede na Slovenijo."},{"q":"Verižni indeksi so indeksi, pri katerih je osnova primerjave:","options":["Vedno isto bazno leto","Vedno predhodno obdobje v nizu","Povprečje celotnega opazovanega niza","Vrednost iz naslednjega obdobja","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za verižne indekse je značilno, da je osnova primerjave vedno predhodno obdobje v nizu zaporednih obdobij."},{"q":"Tehnika imputacije pri urejanju podatkov se uporablja za:","options":["Razvrščanje enot v razrede frekvenčne porazdelitve","Obravnavo manjkajočih vrednosti","Preračun verižnih indeksov na stalno osnovo","Tehtanje podatkov pri izračunu skupinskih indeksov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Tehnika imputacije je postopek za obravnavo manjkajočih vrednosti pri urejanju podatkov."},{"q":"Enostavni indeks cen se izračuna kot:","options":["qt / qo × 100","Pt × qt / Po × qo × 100","pt / po × 100","(pt + po) / 2 × 100","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Enostavni indeks cen = pt / po × 100, kjer je pt cena v tekočem in po cena v baznem obdobju."},{"q":"Pri preračunu verižnih indeksov na stalno osnovo (0) delimo vsak člen indeksne vrste z:","options":["Prvim členom indeksne vrste","Zadnjim členom indeksne vrste","Stičnim členom × konstanta 100","Celotno indeksno vrsto z baznim indeksom","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Verižne indekse preračunamo na stalno osnovo tako, da vsak člen delimo s prvim členom indeksne vrste (ki je konstanta 100), oz. se izračuna kumulativno z množenjem."},{"q":"Kako dobimo vrednost pojava za celotno obdobje iz vrste verižnih indeksov?","options":["Z deljenjem zadnjega člena z baznim letom","S kumulativnim množenjem verižnih indeksov","Z računanjem aritmetične sredine vseh členov","Z deljenjem zadnjega člena z vsoto vseh členov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Kumulativno množenje verižnih indeksov pove, kako se je pojav spremenil v celotnem obdobju od prvega do zadnjega opazovanega período."}]},{"id":"st-t7","name":"Skupinski indeksi: Laspeyres in Paasche (tema 7)","questions":[{"type":"match","q":"Poveži indeks z načinom tehtanja oz. opredelitvijo.","pairs":[{"term":"Laspeyresov indeks","def":"Tehtanje z baznimi količinami (q₀)"},{"term":"Paaschejev indeks","def":"Tehtanje s tekočimi količinami (q₁)"},{"term":"Fisherjev indeks","def":"Geometrijska sredina Laspeyresovega in Paaschejevega"},{"term":"Deflator","def":"Indeks cen za pretvorbo nominalne vrednosti v realno"},{"term":"Verižni indeks","def":"Primerja vsako obdobje z neposredno predhodnim"}],"explanation":"Laspeyres uporablja bazne, Paasche tekoče uteži; Fisher je njuna geometrijska sredina."},{"q":"Kaj meri Laspeyresov indeks cen (IᴾL)?","options":["Za koliko so se spremenile cene, tehtane s tekočimi količinami (q₁)","Za koliko so se spremenile količine, tehtane z baznimi cenami (p₀)","Za koliko so se spremenile cene, tehtane z baznimi količinami (q₀)","Za koliko se je spremenila skupna vrednost","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IᴾL = Σ(q₀·p₁) / Σ(q₀·p₀) × 100. Meri spremembo cen, pri čemer kot uteži (ponderi) uporablja BAZNE količine (q₀). Ker uteži ostanejo enake, sprememba odraža samo vpliv cen."},{"q":"Kateri ponderi se uporabijo pri Paaschejevem indeksu cen (IᴾP)?","options":["Bazne cene (p₀)","Tekoče količine (q₁)","Bazne količine (q₀)","Tekoče cene (p₁)","Pravilna rešitev ni navedena"],"correct":1,"explanation":"IᴾP = Σ(q₁·p₁) / Σ(q₁·p₀) × 100. Paaschejev indeks cen kot uteži uporablja TEKOČE količine (q₁) — tiste iz tekočega, ne baznega obdobja. Zato je manjši od Laspeyresovega, kadar se kupuje relativno manj dragih stvari."},{"q":"Kdaj so strukturni premiki zavrli rast cen?","options":["Ko je IᴾL = IᴾP (enaka vrednost)","Ko je IᴾL < IᴾP (Paasche višji)","Ko je IᴾL > IᴾP (Laspeyres višji)","Ko je indeks vrednosti večji od 100","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IᴾL > IᴾP → strukturni premiki so zavrli rast cen. To pomeni, da so se v tekočem obdobju relativno povečale nakupljene količine cenejših vrst blaga. Posledično tekoče uteži (Paasche) dajejo nižji rezultat od baznih (Laspeyres)."},{"q":"Katera relacija med skupinskimi indeksi je pravilna?","options":["IV = IᴾL × IQL / 100","IV = IᴾL × IQP / 100","IV = IᴾP × IQP / 100","IV = IᴾL + IQP − 100","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Pravilni relaciji sta: IV = IᴾL × IQP / 100 in IV = IᴾP × IQL / 100. Vedno 'križi' — Laspeyresov cenovni × Paaschejev količinski (ali obratno). Nikoli L×L ali P×P!"},{"q":"Tehnika tehtanja pri urejanju podatkov se uporablja za:","options":["Izračun ponderiranih indeksov cen","Naknadno uskladitev strukture vzorca s strukturo populacije","Preverbo logičnih napak v podatkih","Razvrščanje ordinalnnih spremenljivk","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Tehnika tehtanja (weighting) se uporablja za naknadno uskladitev strukture vzorca s strukturo populacije."},{"q":"Kateri od koeficientov produktivnosti meri, koliko delovnega časa je potrebnega za enoto proizvoda?","options":["Koeficient po premi shemi (v = Q/T)","Koeficient po recipročni shemi (t = T/Q)","Skupinski indeks po Laspeyresu","Enostavni indeks cen","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient po recipročni shemi t = T/Q meri, koliko delovnega časa (T) je potrebnega za enoto proizvoda (Q)."},{"q":"Laspeyresov skupinski indeks cen se izračuna z:","options":["Ponderji iz tekočega (t) obdobja","Ponderji iz baznega (0) obdobja","Geometrijsko sredino Laspeyresovega in Paaschejevega","Aritmetično sredino cen brez ponderjev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Laspeyresov obrazec uporablja pondere iz baznega (0) obdobja — tistega, ki je v imenovalcu indeksa."},{"q":"Paaschejev skupinski indeks cen se izračuna z:","options":["Ponderji iz baznega (0) obdobja","Ponderji iz tekočega (t) obdobja","Geometrijsko sredino vseh cen v seriji","Aritmetično sredino Laspeyresovega in Paaschejevega","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Paaschejev obrazec uporablja pondere iz tekočega (t) obdobja — tistega, ki je v števcu indeksa."},{"q":"Katera od navedenih velja za skupinske indekse?","options":["Skupinski indeksi so enaki enostavnim indeksom pri eni dobri","Skupinski indeksi se delijo na agregatne in srednje indekse","Skupinski indeksi se vedno izračunavajo brez ponderjev","Skupinski indeksi so vedno Laspeyresovi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Skupinske indekse delimo glede na postopek izračuna na agregatne (Laspeyres, Paasche, Fisher) in srednje indekse."}]},{"id":"st-t8","name":"Skupinski indeksi: Fisher, strukturni premiki (tema 8)","questions":[{"type":"match","q":"Poveži skupinski indeks z njegovo lastnostjo.","pairs":[{"term":"Tehtana aritmetična sredina (TAS)","def":"Da enak rezultat kot agregatni Laspeyresov indeks"},{"term":"Tehtana harmonična sredina (THS)","def":"Da enak rezultat kot agregatni Paaschejev indeks"},{"term":"Indeks s stalno strukturo","def":"Uteži iz baznega obdobja; izhodišče za strukturne premike"},{"term":"Indeks s spremenljivo strukturo","def":"Indeks povprečne (srednje) cene homogenega proizvoda"}],"explanation":"TAS = agregatni Laspeyres, THS = agregatni Paasche. Indeks strukturnih premikov = razmerje obeh × 100."},{"q":"Kaj je Fisherjev idealni indeks?","options":["Aritmetična sredina Laspeyresovega in Paaschejevega indeksa","Harmonična sredina Laspeyresovega in Paaschejevega indeksa","Geometrijska sredina Laspeyresovega in Paaschejevega indeksa","Produkt vseh agregatnih indeksov / 100","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IF = √(IᴾL × IᴾP). Fisherjev indeks je geometrijska sredina Laspeyresovega in Paaschejevega indeksa. Velja za 'idealnega', ker nima sistematične naprave ne navzgor ne navzdol."},{"q":"Kaj pomeni IV = 95?","options":["Skupna vrednost je narasla za 95 %","Skupna vrednost je padla za 5 %","Skupna vrednost je narasla za 5 %","Cene so padle za 5 %","Pravilna rešitev ni navedena"],"correct":1,"explanation":"IV = 95 pomeni, da je tekoča skupna vrednost (Σq₁p₁) enaka 95 % bazne skupne vrednosti (Σq₀p₀) — torej se je skupna vrednost zmanjšala za 5 %."},{"q":"Fisherjevo idealno indeksno število je:","options":["Aritmetična sredina Laspeyresovega in Paaschejevega","Geometrijska sredina Laspeyresovega in Paaschejevega","Harmonična sredina Laspeyresovega in Paaschejevega","Razlika med Laspeyresovim in Paaschejevim","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Fisherjevo idealno indeksno število je geometrijska sredina Laspeyresovega in Paaschejevega skupinskega indeksa."},{"q":"Indeks strukturnih premikov se izračuna kot:","options":["Enostavni indeks cen / skupinski indeks cen × 100","Indeks cen s spremenljivo strukturo / indeks cen s stalno strukturo × 100","Laspeyresov indeks / Paaschejev indeks × 100","Skupinski indeks / enostavni indeks × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Indeks strukturnih premikov = indeks cen s spremenljivo strukturo / indeks cen s stalno strukturo × 100."},{"q":"Indeks povprečne (srednje) cene se izračuna kot:","options":["Povprečna cena za tekoče / bazno obdobje × 100","Vsota cen tekočega / vsota cen baznega obdobja × 100","(Cena tekočega – cena baznega) / cena baznega × 100","Skupinski indeks cen / enostavni indeks cen × 100","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Indeks povprečne (srednje) cene = Pt / Po × 100, kjer je Pt povprečna cena v tekočem in Po povprečna cena v baznem obdobju."}]},{"id":"st-nal58","name":"Računske naloge · teme 5–8","calc":true,"questions":[{"q":"Naloga 1 · Struktura naložbenega portfelja","hint":"Relativno število strukture = (vrednost enote / skupna vrednost) × 100. Vsota vseh strukturnih deležev = 100 %.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Tvoj portfelj na koncu leta 2023 je sestavljen iz treh vrst sredstev. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Sredstvo</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Delnice (S&P 500 ETF)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">15.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Obveznice (US Treasury)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">9.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Denar in ekvivalenti</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">6.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\"><b>SKUPAJ</b></td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\"><b>30.000 EUR</b></td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Strukturni delež delnic je 50 %.</div><div style=\"font-size:13.5px\"><b>b)</b> Strukturni delež obveznic je 25 %.</div><div style=\"font-size:13.5px\"><b>c)</b> Strukturni delež denarja je 20 %.</div><div style=\"font-size:13.5px\"><b>d)</b> Vsota vseh treh deležev je 100 %.</div></div>","options":["a + b","a + c + d","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Delnice 15.000/30.000×100 = <b>50 %</b> (a ✓). Obveznice 9.000/30.000×100 = <b>30 %</b>, ne 25 % (b ✗). Denar 6.000/30.000×100 = <b>20 %</b> (c ✓). Vsota 50+30+20 = <b>100 %</b> (d ✓). → pravilno <b>a + c + d</b>."},{"q":"Naloga 2 · Smiselnost koeficientov","hint":"Koeficient je smiseln, kadar sta števec in imenovalec vsebinsko povezana, se nanašata na isto enoto/območje in na isto (ali zaporedno) časovno obdobje.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Kateri koeficienti so smiselni?</div><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Dnevni promet NQ futures (USD, 2023) / št. trading dni na NQ (2023).</div><div style=\"font-size:13.5px\"><b>b)</b> BDP Japonske (USD, 2023) / promet NYSE (EUR, 2023).</div><div style=\"font-size:13.5px\"><b>c)</b> Neto dobiček sklada (EUR) / povpr. št. zaposlenih v skladu (2023).</div><div style=\"font-size:13.5px\"><b>d)</b> Prodane opcije na S&P 500 (okt. 2023) / AUM vseh hedge skladov (USD, 2019).</div></div>","options":["a","c","a + c","b + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"a) povprečni dnevni promet — isti pojav, isto obdobje → <b>smiseln</b>. c) dobiček na zaposlenega — vsebinsko povezano, isto obdobje → <b>smiseln</b>. b) različni valuti in nepovezana pojava → ne. d) različni obdobji (2023 vs 2019) in nesorazmerna agregata → ne. → <b>a + c</b>."},{"q":"Naloga 3 · Povprečni enostavni indeks — delniški portfelj","hint":"Enostavni indeks: i = (p₁/p₀)×100. Povprečni enostavni indeks = (Σi)/n. i < 100 = padec, i > 100 = rast.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Slediš štirim delnicam (bazno 2022 = 100, tekoče 2023). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Delnica</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀ (2022)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁ (2023)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">i</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">AAPL</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">150</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">180</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">120,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">MSFT</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">250</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">300</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">120,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">GOOGL</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">90</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">90,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">AMZN</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">210</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">105,0</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Povprečni enostavni indeks vseh štirih je 108,75.</div><div style=\"font-size:13.5px\"><b>b)</b> GOOGL je edina, ki je v 2023 izgubila vrednost.</div><div style=\"font-size:13.5px\"><b>c)</b> V povprečju so delnice zrasle za 8,75 %.</div><div style=\"font-size:13.5px\"><b>d)</b> Povprečni enostavni indeks je enak vrednostnemu indeksu portfelja.</div></div>","options":["a + b","a + b + c","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Povprečje indeksov = (120+120+90+105)/4 = 435/4 = <b>108,75</b> (a ✓). Le GOOGL ima i < 100 (b ✓). 108,75 − 100 = <b>+8,75 %</b> (c ✓). d ✗: vrednostni indeks tehta s količinami/vrednostmi posameznih delnic — enak bi bil le, če bi imel v vsako vloženo enako; tega tu ne vemo. → <b>a + b + c</b>."},{"q":"Naloga 4 · Deflacioniranje — realna vrednost S&P 500","hint":"Realna vrednost = (nominalna / indeks cen) × 100. Bazni indeks: Iₜ/₀ = (yₜ/y₀)×100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Podana je vrednost S&P 500 in CPI (osnova 2020 = 100). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Leto</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">S&P 500 (nom.)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">CPI</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">S&P 500 (realno)</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2020</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.756</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.756</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2021</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.766</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">107,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.454</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2022</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.840</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">117,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.282</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2023</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.769</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">122,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">?</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Realna vrednost 2023 (po cenah 2020) ≈ 3.909.</div><div style=\"font-size:13.5px\"><b>b)</b> S&P 500 je 2022 nominalno padel glede na 2021.</div><div style=\"font-size:13.5px\"><b>c)</b> S&P 500 je 2023 realno presegel raven iz 2021.</div><div style=\"font-size:13.5px\"><b>d)</b> Bazni indeks nominalne vrednosti 2023 (2020 = 100) ≈ 127,0.</div></div>","options":["a + b","a + c","b + c + d","a + b + d","Pravilna rešitev ni navedena"],"correct":3,"htmlExpl":true,"explanation":"Realno 2023 = 4.769/122×100 = <b>3.909</b> (a ✓). Nominalno 3.840 < 4.766 → padec (b ✓). Realno: 3.909 (2023) < 4.454 (2021) → <b>ni</b> presegel (c ✗). Bazni indeks 4.769/3.756×100 = <b>126,97 ≈ 127</b> (d ✓). → <b>a + b + d</b>."},{"q":"Naloga 5 · Laspeyresov in Paaschejev indeks — futures","hint":"Σ(q₀p₀)=bazna vrednost. Σ(q₁p₀)=tek. količine × bazne cene. Σ(q₀p₁)=bazne količine × tek. cene. Σ(q₁p₁)=tek. vrednost. IᴾL=Σ(q₀p₁)/Σ(q₀p₀)×100; IQL=Σ(q₁p₀)/Σ(q₀p₀)×100; IᴾP=Σ(q₁p₁)/Σ(q₁p₀)×100; IV=Σ(q₁p₁)/Σ(q₀p₀)×100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Brokerska hiša je aprila (0) in maja (1) 2023 sklenila futures pogodbe. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Pogodba</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₁</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">NQ mini</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">50</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">20,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">60</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">22,00</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">ES mini</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">10,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">80</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">12,00</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Laspeyresov indeks cen IᴾL = 115.</div><div style=\"font-size:13.5px\"><b>b)</b> Laspeyresov indeks količin IQL = 100.</div><div style=\"font-size:13.5px\"><b>c)</b> Paaschejev indeks cen IᴾP = 114.</div><div style=\"font-size:13.5px\"><b>d)</b> Indeks vrednosti IV = 120.</div></div>","options":["a + b","a + b + c","a + b + c + d","a + c","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Σ(q₀p₀)=1000+1000=<b>2000</b>; Σ(q₀p₁)=1100+1200=<b>2300</b>; Σ(q₁p₀)=1200+800=<b>2000</b>; Σ(q₁p₁)=1320+960=<b>2280</b>. IᴾL=2300/2000×100=<b>115</b> (a ✓). IQL=2000/2000×100=<b>100</b> (b ✓). IᴾP=2280/2000×100=<b>114</b> (c ✓). IV=2280/2000×100=<b>114</b>, ne 120 (d ✗). → <b>a + b + c</b>."},{"q":"Naloga 6 · Skupinski indeksi — investicijski skladi","hint":"Izračunaj vse štiri vsote Σ(q₀p₀), Σ(q₁p₀), Σ(q₀p₁), Σ(q₁p₁), nato vstavi v formule (kot pri Nalogi 5).","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Podjetje prodaja dve vrsti skladov (bazno jan 2023, tekoče jul 2023). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Sklad</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₁</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">ETF skladi</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">30,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">250</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">33,00</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Obvezniški</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">300</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">20,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">22,00</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Laspeyresov indeks cen IᴾL = 110.</div><div style=\"font-size:13.5px\"><b>b)</b> Laspeyresov indeks količin IQL ≈ 95,8.</div><div style=\"font-size:13.5px\"><b>c)</b> Paaschejev indeks cen je večji (IᴾP > IᴾL).</div><div style=\"font-size:13.5px\"><b>d)</b> Skupna vrednost prodaje se je zmanjšala (IV < 100).</div></div>","options":["a","a + b","a + b + c","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Σ(q₀p₀)=6000+6000=<b>12000</b>; Σ(q₀p₁)=6600+6600=<b>13200</b>; Σ(q₁p₀)=7500+4000=<b>11500</b>; Σ(q₁p₁)=8250+4400=<b>12650</b>. IᴾL=13200/12000×100=<b>110</b> (a ✓). IQL=11500/12000×100=<b>95,8</b> (b ✓). IᴾP=12650/11500×100=<b>110</b> → ni večji od IᴾL (c ✗). IV=12650/12000×100=<b>105,4</b> > 100 → vrednost zrasla (d ✗). → <b>a + b</b>."},{"q":"Naloga 7 · Fisherjev indeks in strukturni premiki — futures","hint":"IF = √(IᴾL × IᴾP). Relacija: IV = IᴾP × IQL/100 = IᴾL × IQP/100 (IQP = Paaschejev indeks količin). IᴾL > IᴾP → strukturni premiki zavrli rast cen.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Za par futures pogodb (NQ + ES) so že izračunani naslednji skupinski indeksi. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Skupinski indeks</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, cene (IᴾL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">115</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, količine (IQL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Paasche, cene (IᴾP)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">114</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Vrednostni (IV)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">114</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Fisherjev indeks cen ≈ 114,5.</div><div style=\"font-size:13.5px\"><b>b)</b> Ker je IᴾL > IᴾP (115 > 114), so strukturni premiki zavrli rast cen.</div><div style=\"font-size:13.5px\"><b>c)</b> Relacija IV = IᴾL × IQL/100 drži (115×100/100 = 115 = IV).</div><div style=\"font-size:13.5px\"><b>d)</b> Relacija IV = IᴾP × IQL/100 drži (114×100/100 = 114 = IV).</div></div>","options":["a + b","a + b + c","a + b + d","b + c + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"IF = √(115×114) = √13110 = <b>114,5</b> (a ✓). IᴾL > IᴾP → premiki zavrli rast cen (b ✓). c ✗: 115×100/100 = 115 ≠ IV (=114) — napačno sparjeno (IᴾL gre z IQP, ne IQL). d ✓: IᴾP×IQL/100 = 114×100/100 = 114 = IV. → <b>a + b + d</b>."},{"q":"Naloga 8 · Relacije med indeksi — skladi","hint":"IQP = Paaschejev indeks količin = Σ(q₁p₁)/Σ(q₀p₁)×100. Relacija: IV = IᴾL × IQP/100 = IᴾP × IQL/100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Za par investicijskih skladov so že izračunani naslednji indeksi. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Skupinski indeks</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, cene (IᴾL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">110</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Paasche, cene (IᴾP)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">110</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, količine (IQL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">≈ 95,8</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Vrednostni (IV)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">≈ 105,4</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Fisherjev indeks cen = 110.</div><div style=\"font-size:13.5px\"><b>b)</b> Ker je IᴾL = IᴾP = 110, strukturni premiki niso vplivali na rast cen.</div><div style=\"font-size:13.5px\"><b>c)</b> Relacija IV = IᴾL × IQP/100 drži, pri čemer je IQP ≈ 95,8.</div><div style=\"font-size:13.5px\"><b>d)</b> Ker je IV (≈105,4) manjši od IᴾL (110), se je vrednost prodaje zmanjšala.</div></div>","options":["a + b","a + b + c","b + c + d","a + b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"IF = √(110×110) = <b>110</b> (a ✓). IᴾL = IᴾP → strukturnih premikov ni (b ✓). Z IQP ≈ 95,8 (Paaschejev količinski indeks): IV = IᴾL × IQP/100 = 110×95,8/100 = <b>105,4</b> ✓ (c ✓). d ✗: IV = 105,4 > 100 → vrednost je <b>zrasla</b> za 5,4 %; to, da je IV < IᴾL, ne pomeni padca. → <b>a + b + c</b>."}]}],"notes":"\n<h2>1–4 · Osnove statistike</h2>\n<div class=\"note-card\">\n<h3>Temeljni pojmi in podatki</h3>\n<ul>\n<li><b>Statistika</b>: zbiranje, urejanje, prikaz in analiza množičnih podatkov. <b>Populacija</b> (vse enote) vs <b>vzorec</b> (del populacije).</li>\n<li><b>Merske lestvice (Stevens)</b>: imenska (kategorije), ordinalna (vrstni red), intervalna (enaki razmiki, brez prave ničle), razmernostna (prava ničla). Višja lestvica = več dovoljenih operacij.</li>\n<li><b>Vrste podatkov</b>: kvalitativni (opisni) vs kvantitativni (številski); <b>primarni</b> (anketa, intervju, opazovanje) vs <b>sekundarni</b> (npr. SURS SI-STAT).</li>\n<li><b>PEST</b> = analiza zunanjega okolja; <b>SWOT</b> = prednosti/slabosti.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Srednje vrednosti in razpršenost</h3>\n<ul>\n<li><b>Aritmetična sredina</b> (občutljiva na osamelce), <b>mediana</b> (razdeli niz na pol, odporna na osamelce), <b>modus</b> (najpogostejša vrednost), <b>geometrijska sredina</b> (za stopnje rasti).</li>\n<li><b>Razpršenost</b>: variacijski razmik, <b>varianca</b>, <b>standardni odklon</b> (koren variance), <b>koeficient variacije</b> = (σ/AS)×100.</li>\n<li><b>Strukture</b> (delež ×100; vsota 100 %) in <b>koeficienti</b> (razmerje dveh vsebinsko povezanih absolutnih števil).</li>\n</ul>\n</div>\n\n<h2>Prikazi podatkov (tabele in grafikoni)</h2>\n<div class=\"note-card\">\n<h3>Tabele</h3>\n<p><b>Razpredelnica surovih podatkov</b> (podatkovna matrika): enote v vrsticah, spremenljivke v stolpcih (logika Excela/SPSS).</p>\n<p><b>Frekvenčna tabela</b> — porazdelitev frekvenc ene spremenljivke:</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px;text-align:left\">Ocena</th><th style=\"border:1px solid var(--line);padding:4px 10px\">f</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">3</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">7</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">8</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">8</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">12</td></tr>\n</table>\n<p><b>Kontingenčna (dvorazsežna) tabela</b> — dve opisni spremenljivki hkrati (v vrsticah in stolpcih):</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px\"></th><th style=\"border:1px solid var(--line);padding:4px 10px\">M</th><th style=\"border:1px solid var(--line);padding:4px 10px\">Ž</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Da</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">14</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">9</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Ne</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">11</td></tr>\n</table>\n</div>\n<div class=\"note-card\">\n<h3>Grafikoni — kateri za kaj</h3>\n<div style=\"display:flex;flex-wrap:wrap;gap:18px;align-items:flex-start\">\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"28\" y=\"92\" width=\"32\" height=\"23\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"60\" y=\"68\" width=\"32\" height=\"47\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"92\" y=\"40\" width=\"32\" height=\"75\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"124\" y=\"30\" width=\"32\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"156\" y=\"62\" width=\"32\" height=\"53\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"188\" y=\"95\" width=\"32\" height=\"20\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Histogram</b> — frekvenčna porazdelitev <i>zvezne</i> spremenljivke (stolpci se stikajo).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 120 120\" style=\"width:100%;max-height:120px\">\n      <!-- 0° pri ura 3 (desno); koti naraščajo v nasprotni smeri urinega kazalca (matematična smer); izseki od največjega -->\n      <path d=\"M60,60 L100,60 A40,40 0 0,0 20,60 Z\" fill=\"var(--terra)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L20,60 A40,40 0 0,0 72.36,98.04 Z\" fill=\"var(--teal)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L72.36,98.04 A40,40 0 0,0 100,60 Z\" fill=\"var(--ink2)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <line x1=\"100\" y1=\"60\" x2=\"112\" y2=\"60\" stroke=\"var(--ink)\" stroke-width=\"1.6\"/>\n      <text x=\"103\" y=\"54\" font-size=\"9\" fill=\"var(--ink2)\">0°</text>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Strukturni krog (tortni)</b> — <i>struktura (deleži)</i> celote. Začnemo pri <b>0° (desno, ura 3)</b> in izseke nizamo po velikosti od največjega, v nasprotni smeri urinega kazalca (matematična smer kotov).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <polyline points=\"34,95 74,72 114,82 154,45 194,58 220,32\" fill=\"none\" stroke=\"var(--teal)\" stroke-width=\"2.5\"/>\n      <g fill=\"var(--teal)\"><circle cx=\"34\" cy=\"95\" r=\"2.5\"/><circle cx=\"74\" cy=\"72\" r=\"2.5\"/><circle cx=\"114\" cy=\"82\" r=\"2.5\"/><circle cx=\"154\" cy=\"45\" r=\"2.5\"/><circle cx=\"194\" cy=\"58\" r=\"2.5\"/><circle cx=\"220\" cy=\"32\" r=\"2.5\"/></g>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Linijski grafikon</b> — <i>kronološko</i> gibanje pojava (časovna vrsta).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"42\" y=\"45\" width=\"30\" height=\"70\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"92\" y=\"70\" width=\"30\" height=\"45\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"142\" y=\"30\" width=\"30\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"192\" y=\"78\" width=\"30\" height=\"37\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Stolpčni grafikon</b> — primerjava <i>opisnih</i> kategorij (stolpci so ločeni).</figcaption>\n  </figure>\n</div>\n</div>\n\n<h2>5–8 · Relativna števila in indeksi</h2>\n<div class=\"note-card\">\n<h3>Enostavni indeksi</h3>\n<ul>\n<li><b>Enostavni indeks</b>: i = (y₁/y₀)×100. Razlaga: <b>I − 100</b> (za koliko %), <b>I : 100</b> (kolikokrat).</li>\n<li><b>Časovni</b> (dve obdobji), <b>krajevni</b> (dva kraja), <b>stvarni</b> (dva pojava). <b>Bazni</b> (stalna osnova) vs <b>verižni</b> (s predhodnim).</li>\n<li><b>Deflacioniranje</b>: realna vrednost = (nominalna / indeks cen)×100. Indeks vrednosti = indeks cen × indeks količin / 100.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Skupinski (agregatni in srednji) indeksi</h3>\n<ul>\n<li><b>Laspeyres</b> (uteži = bazne količine q₀), <b>Paasche</b> (uteži = tekoče količine q₁), <b>Fisher</b> = √(L·P).</li>\n<li><b>Srednji</b>: TAS = agregatni Laspeyres; THS = agregatni Paasche.</li>\n<li><b>Stalna struktura</b> (uteži baznega obdobja) vs <b>spremenljiva struktura</b> (indeks povprečne cene). <b>Strukturni premiki</b> = I(spremenljiva)/I(stalna)×100.</li>\n<li><b>Relacija (vedno „križ\")</b>: Iᵥ = Iₚ(Laspeyres)·I_q(Paasche)/100. Strukturni premiki zavrejo rast cen, ko je IᴾL &gt; IᴾP.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Agregatni vs srednji indeksi — prednosti in slabosti</h3>\n<p style=\"margin:0 0 6px\"><b>Agregatni indeksi</b> (Laspeyres, Paasche, Fisher) — iz vsot vrednosti Σ(p·q):</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: neposredna ekonomska interpretacija (primerjamo dejanske <i>skupne vrednosti</i> košarice); natančni, ker temeljijo na dejanskih cenah <i>in</i> količinah; omogočajo razčlenitev vrednostnega indeksa na cenovni in količinski del (Iᵥ = IᴾL·I_qP/100).</li>\n<li><b>Slabosti</b>: zahtevajo <i>popolne</i> podatke o cenah in količinah za vse postavke v obeh obdobjih (podatkovno zahtevni); izbira obdobja uteži premakne rezultat — <b>Laspeyres</b> (bazne uteži) navzgor precenjuje, <b>Paasche</b> (tekoče uteži) navzdol podcenjuje rast cen; težavni ob spremembi nabora postavk.</li>\n</ul>\n<p style=\"margin:8px 0 6px\"><b>Srednji indeksi</b> (tehtana sredina enostavnih indeksov): <b>TAS</b> tehtana z baznimi vrednostmi p₀q₀ = agregatni Laspeyres; <b>THS</b> tehtana s tekočimi vrednostmi p₁q₁ = agregatni Paasche.</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: izračunljivi že iz <i>posameznih (enostavnih) indeksov</i> in vrednostnih uteži — ni potrebna cela matrika q in p; primerni, ko poznamo strukturo izdatkov/vrednosti, ne pa posameznih količin (tako se v praksi računa npr. indeks cen življenjskih potrebščin); prožni pri izbiri uteži.</li>\n<li><b>Slabosti</b>: rezultat je odvisen od <i>izbire uteži in tipa sredine</i> — napačna sredina (aritmetična namesto harmonične ali obratno) ali napačne uteži dajo pristranski indeks; manj neposredno ekonomsko interpretabilni kot agregati.</li>\n</ul>\n<p style=\"margin:8px 0 0\"><b>Ključno</b>: <b>TAS = Laspeyres</b> in <b>THS = Paasche</b> — ob pravilnih utežeh dasta agregatni in srednji pristop <i>enak</i> rezultat. Razlika ni v vrednosti, ampak v tem, <i>katere podatke imamo na voljo</i>.</p>\n</div>\n\n<h2>9–12 · Klasifikacije, prebivalstvo, ekon. aktivnost</h2>\n<div class=\"note-card\">\n<h3>Statistični sistem in klasifikacije</h3>\n<ul>\n<li><b>ESS</b>: na vrhu <b>Eurostat</b>; v Sloveniji glavni izvajalec <b>SURS</b>.</li>\n<li><b>Klasifikacije</b>: NACE (EU)/SKD (SLO) — dejavnosti; <b>ISIC</b> (ZN) — osnova za NACE; <b>HS</b> — blago/carina; <b>PRODCOM</b> — industrijski proizvodi; CPA — proizvodi po dejavnosti.</li>\n<li><b>Enote</b>: pravna, <b>lokalna</b> (po lokaciji), <b>EED</b> (enovrstna dejavnost). <b>Glavna dejavnost</b> = dejavnost z <b>največ zaposlenimi</b>; pri več hierarhičnih ravneh po <b>top-down metodi</b> (seštevamo navzgor po ravneh, ne izberemo kar največjega razreda). <b>Metapodatki</b> = podatki o podatkih.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Statistične enote — natančno razvrščanje (s primerom)</h3>\n<p style=\"margin:0 0 6px\">Iste podatke o podjetju razvrstimo v <b>štiri vrste enot</b>, vsako po svojem kriteriju:</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> (institucionalna/pravna enota): <b>1</b> na pravni subjekt. Kriterij: pravni status. <i>Primer:</i> Galeb = 1 podjetje.</li>\n<li><b>Lokalna enota (LE)</b>: podjetje ali del podjetja na <b>enem naslovu/lokaciji</b>. Število = <b>število različnih lokacij</b>. Kriterij: <i>geografija</i>. Na enem naslovu je vedno <b>ena</b> LE, tudi če tam tečeta dve dejavnosti.</li>\n<li><b>Enota enovrstne dejavnosti (EED)</b>: del podjetja, ki opravlja <b>eno vrsto dejavnosti</b> (eno šifro), <i>ne glede na lokacijo</i>. Število = <b>število različnih šifer dejavnosti</b>. Kriterij: <i>dejavnost</i>.</li>\n<li><b>Lokalna enota enovrstne dejavnosti (LEVED)</b>: <b>ena dejavnost na eni lokaciji</b>. Število = število <b>dejansko obstoječih kombinacij lokacija–šifra</b>. Kriterij: <i>lokacija IN dejavnost hkrati</i>.</li>\n</ul>\n<p style=\"margin:8px 0 4px\"><b>Pozor:</b> LEVED <b>ni</b> produkt lokacij × šifer. Šteješ samo kombinacije, ki res obstajajo.</p>\n<p style=\"margin:6px 0 4px\"><b>Primer (Galeb):</b> Brnik (62.10), Lesce (62.20), Portorož (62.20 in 63.30).</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> = 1.</li>\n<li><b>LE</b> = 3 (Brnik, Lesce, Portorož).</li>\n<li><b>EED</b> = 3 (tri različne šifre: 62.10, 62.20, 63.30 — čeprav 62.20 nastopa dvakrat, je <i>ena</i> dejavnost).</li>\n<li><b>LEVED</b> = 4 (Brnik–62.10, Lesce–62.20, Portorož–62.20, Portorož–63.30; <i>ne</i> 3×3 = 9).</li>\n<li><b>Skupaj</b> = 1 + 3 + 3 + 4 = <b>11 enot</b>.</li>\n</ul>\n<p style=\"margin:6px 0 0;font-size:13px;color:var(--ink2)\">Mini-pravilo: LE šteje <i>naslove</i>, EED šteje <i>šifre</i>, LEVED šteje <i>pare (naslov, šifra)</i>.</p>\n</div>\n<div class=\"note-card\">\n<h3>Prebivalstvo in ekonomska aktivnost</h3>\n<ul>\n<li><b>Skupni prirastek</b> = naravni prirastek (živorojeni − umrli) + selitveni saldo (priseljeni − odseljeni).</li>\n<li><b>SSN</b> = živorojeni / srednje št. <b>vseh</b> preb. ×1000; <b>SSR</b> = živorojeni / ženske 15–49 ×1000 (SSR &gt; SSN).</li>\n<li><b>Koef. maskulinitete</b> ≈1050; <b>koef. starostne odvisnosti</b> = (0–14 + 65+)/(15–64)×100; <b>indeks staranja</b> = (65+ / 0–14)×100.</li>\n<li><b>Napovedovanje</b>: linearno (konst. absolutni prirastek) vs geometrijsko (konst. stopnja rasti; pri r&gt;0 višja napoved). <b>Produktivnost</b> in <b>intenzivnost</b> = 1/produktivnost. PKM (Big Mac index).</li>\n</ul>\n</div>\n"},{"id":"izpit","name":"Izpit (vse teme)","type":"izpit","decks":[{"id":"st-t12","name":"Uvod, zgodovina in podatki (teme 1–2)","questions":[{"q":"Kateri razvijalec statistike je dal ime znani statistični krivulji normalne porazdelitve?","options":["Karl Pearson","William Gosset","Florence Nightingale","Carl Friedrich Gauss","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Carl Friedrich Gauss je opisal normalno porazdelitev, ki jo pogosto imenujemo Gaussova krivulja."},{"q":"Kdo je zahteval popis nepremičnin, drobnice in prebivalcev v Angliji v 11. stoletju?","options":["William I. the Conqueror","Florence Nightingale","Karl Pearson","Carl Friedrich Gauss","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Osvajalec William I. the Conqueror je zahteval popis nepremičnin, drobnice in prebivalcev, kar velja za enega prvih sistematičnih popisov v Evropi."},{"q":"Katera od navedenih je metoda PRIMARNEGA zbiranja podatkov?","options":["Branje tiskanih publikacij","Anketa med potrošniki","Iskanje podatkov v podatkovnih bazah","Pregled spletnih portalov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Anketa je klasična metoda primarnega zbiranja podatkov — podatke zbiramo neposredno sami."},{"q":"Finančni in časovni prihranki ter hitra razpoložljivost so prednosti:","options":["Primarnih podatkov pred sekundarnimi","Sekundarnih podatkov pred primarnimi","Eksperimenta pred anketo","Intervjuja pred vprašalnikom","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Finančni in časovni prihranki, hitra razpoložljivost in regularnost objav so glavne prednosti sekundarnih podatkov."},{"q":"Katera je tipična omejitev sekundarnih podatkov?","options":["Visoki stroški zbiranja","Zastarelost podatkov in neustreznost definicij","Potreba po lastni anketni mreži","Nezmožnost objave na spletu","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Sekundarni podatki so pogosto zastareli, temeljijo na definicijah, ki ne ustrezajo našemu namenu, in imajo lahko prekinite časovne serije."},{"q":"Intervju je opredeljen kot:","options":["Sistematično opazovanje enot v naravnih razmerah","Pogovor z določenim namenom","Statistično testiranje hipotez o vzorcih","Analiza spletnih strani in forumov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Intervju je pogovor z določenim namenom; delimo ga na osebni (ena na ena) in skupinski (fokusne skupine)."},{"q":"Kateri od navedenih je primer opazovalne študije?","options":["Telefonska anketa o zadovoljstvu strank","Navidezno nakupovanje — skriti kupec","Skupinski intervju s fokusno skupino","Poštna anketa o porabi gospodinjstev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Navidezno nakupovanje (skriti kupec) je tipičen primer opazovalne študije, kjer so enote opazovane v naravnih razmerah."},{"q":"POPIS (census) v statistiki pomeni:","options":["Opazovanje izbranega dela enot populacije","Ocenjevanje parametrov iz vzorčnih podatkov","Opazovanje vseh posamičnih enot populacije","Zbiranje primarnih podatkov z anketo","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Popis (census) pomeni opazovanje vseh enot, ki sestavljajo populacijo — ne le vzorca."},{"q":"Statistični parameter je:","options":["Vrednost, ki se od enote do enote spreminja","Konstanta, ki numerično izraža značilnosti populacije","Del vzorčnih podatkov, pridobljenih z anketo","Skupina spremenljivk v frekvenčni porazdelitvi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Parameter je konstanta, ki numerično izraža količinske in kakovostne značilnosti populacije — za vse enote je enak."},{"q":"Sklepna statistična analiza se ukvarja z:","options":["Opisovanjem parametrov celotne populacije","Posploševanjem in ocenjevanjem na osnovi vzorčnih podatkov","Grafičnim prikazom frekvenčnih porazdelitev","Zbiranjem primarnih podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Sklepna statistika posplošuje, napoveduje in ocenjuje povezave med spremenljivkami na osnovi nepopolnih (vzorčnih) podatkov."},{"q":"PRS je kratica za:","options":["Poslovni register Slovenije","Pokrajinski register skupnosti","Področni register storitev","Primarni register statistike","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"PRS je Poslovni register Slovenije — eden najpomembnejših slovenskih registrov, ki vsebuje podatke o poslovnih subjektih."},{"q":"RTE je kratica za:","options":["Register teritorialnih enot","Register tujih enot","Register tržnih ekvivalentov","Register tehničnih evidenc","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"RTE je Register teritorialnih enot — register, ki vsebuje podatke o geografski razdelitvi države."},{"q":"Kaj je konstruktivni register?","options":["Register, ki ga vodi računalniški sistem brez človeških posegov","Register, pri katerem enota z vpisom pridobi lastnost, ki je prej ni imela","Register, ki temelji na izvirnih podatkih formalnih dokumentov","Register, ki je dostopen le pooblaščenim institucijam","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri konstruktivnem registru enota z vpisom pridobi določeno lastnost, ki je prej ni imela (npr. pravno osebnost z vpisom v sodni register)."},{"q":"Katera razpredelnica ima enote opazovanja v vrsticah in spremenljivke v stolpcih?","options":["Razpredelnica surovih podatkov (podatkovna matrika)","Frekvenčna tabela","Kontingenčna tabela","Strukturna tabela","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Razpredelnica surovih podatkov (podatkovna matrika) ima v vrsticah enote opazovanja, v stolpcih pa spremenljivke — logika Excela in SPSS. Frekvenčna tabela prikazuje frekvenčno porazdelitev, kontingenčna pa dve opisni spremenljivki hkrati (v vrsticah in stolpcih).","wrong":{"Frekvenčna tabela":"Frekvenčna tabela prikazuje frekvenčno porazdelitev vrednosti spremenljivke, ne surovih enot v vrsticah.","Kontingenčna tabela":"Kontingenčna tabela razvršča enote po dveh opisnih spremenljivkah (v vrsticah in stolpcih), ne enot opazovanja v vrsticah.","Strukturna tabela":"Strukturna tabela prikazuje deleže (strukturo) celote, ne surovih podatkov."}},{"q":"Kateri od navedenih opisuje STVARNO opredelitev statističnih množic?","options":["Opredelitev geografskega območja preučevane populacije","Opredelitev časovnega obdobja opazovanja","Opredelitev vsebinskih lastnosti, ki jih enota mora izpolnjevati","Opredelitev skupnega števila enot v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stvarna opredelitev statističnih množic opisuje vsebinske lastnosti enot (npr. \"redni\" v: \"redni študent EF UL\")."},{"q":"Kvantitativni podatki se delijo na:","options":["Nominalne in ordinalne","Diskretne (celoštevilske) in zvezne (kontinuirane)","Primarne in sekundarne","Absolutne in relativne","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Kvantitativni (številski) podatki se delijo na diskretne (celoštevilske) in zvezne (kontinuirane)."},{"q":"Porterjev model petih silnic spada med orodja za:","options":["Analizo notranjega okolja podjetja","Analizo privlačnosti panoge","Merjenje demografskih sprememb trga","Zbiranje primarnih podatkov o potrošnikih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Porterjev model petih silnic je orodje za oceno privlačnosti panoge na osnovi petih elementov (rivalstvo, substituti, dobavitelji, kupci, vstopne ovire)."},{"q":"Kolikšna je bila stopnja anketne brezposelnosti v Q4 2025?","options":["2,8 %","4,1 %","4,9 %","6,2 %","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja anketne brezposelnosti v Q4 2025 je znašala 4,1 % (vir: SURS)."},{"q":"Kateri od načinov zbiranja podatkov je primeren za oceno stanja v točno določenem trenutku (ne intervalu)?","options":["Anketna metoda z letnim vzorcem","Popis (census), ki zajame vse enote v točno določenem datumu","Panelna anketa z mesečnim sledenjem","Administrativni register z letnimi posodobitvami","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za oceno stanja v točno določenem trenutku je najprimernejši popis (census), ki zajame vse enote na točno določen datum."},{"q":"Katera od trditev o vzorčni oceni parametra je pravilna?","options":["Vzorčna ocena je vedno enaka pravi vrednosti parametra","Vzorčna ocena je rezultat vzorčenja in se od prave vrednosti parametra razlikuje za vzorčno napako","Vzorčna ocena je natančnejša od popisa","Vzorčna ocena je vedno nezanesljiva in neuporabna","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Vzorčna ocena je rezultat vzorčenja. Razlikuje se od prave vrednosti parametra za vzorčno napako, ki jo je mogoče statistično oceniti."},{"q":"Katera trditev o neenakosti med stopnjo registrirane in anketne brezposelnosti je pravilna?","options":["Stopnja registrirane brezposelnosti je vedno višja","Razlika nastane, ker imata različne definicije brezposelnih oseb","Obe merita isti pojav z enako metodologijo","Anketna brezposelnost vedno podcenjuje dejansko stanje","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Razlika med stopnjama nastane zaradi različnih definicij: registrirana brezposelnost temelji na registraciji pri ZRSZ, anketna pa na standardih ILO."}]},{"id":"st-t34-1","name":"Lestvice, prikaz in opisne mere (teme 3–4) (1/2)","questions":[{"type":"match","q":"Poveži mersko lestvico z njeno značilnostjo.","pairs":[{"term":"Imenska (nominalna)","def":"Le razvrščanje v kategorije brez vrstnega reda (npr. spol)"},{"term":"Ordinalna","def":"Kategorije z vrstnim redom, a brez enakih razmikov (npr. ocena)"},{"term":"Intervalna","def":"Enaki razmiki, a brez absolutne ničle (npr. °C)"},{"term":"Razmernostna","def":"Enaki razmiki in absolutna ničla (npr. dohodek)"}],"explanation":"Lestvice si sledijo od najnižje (imenska) do najvišje (razmernostna)."},{"type":"match","q":"Poveži srednjo vrednost z njeno opredelitvijo.","pairs":[{"term":"Aritmetična sredina","def":"Vsota vseh vrednosti, deljena s številom enot"},{"term":"Mediana","def":"Vrednost, ki razdeli urejeni niz na dva enaka dela"},{"term":"Modus","def":"Najpogostejša vrednost v nizu"},{"term":"Geometrijska sredina","def":"Primerna za povprečenje stopenj rasti in indeksov"}],"explanation":"Aritmetična sredina je občutljiva na osamelce, mediana in modus pa ne."},{"type":"match","q":"Poveži mero razpršenosti z njeno opredelitvijo.","pairs":[{"term":"Variacijski razmik","def":"Razlika med največjo in najmanjšo vrednostjo"},{"term":"Varianca","def":"Povprečje kvadratov odklonov od aritmetične sredine"},{"term":"Standardni odklon","def":"Koren variance; razpršenost v izvirnih enotah"},{"term":"Koeficient variacije","def":"Relativna razpršenost glede na povprečje (v %)"}],"explanation":"Koeficient variacije = (std. odklon / AS) × 100 omogoča primerjavo razpršenosti različnih pojavov."},{"q":"Zakon o državni statistiki je bil v Sloveniji sprejet leta:","options":["1991","1995","2001","2004","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Zakon o državni statistiki je bil sprejet leta 1995 in določa pravne okvire za delovanje državne statistike v Sloveniji."},{"q":"Nominalna spremenljivka je tista, pri kateri:","options":["Vrednosti uredimo od najmanjše do največje","Primerjamo razlike med vrednostmi","Vrednosti le razlikujemo med seboj","Primerjamo razmerja med vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Pri nominalnih spremenljivkah vrednosti le razlikujemo med seboj (ugotavljamo enakost ali neenakost). Primeri: spol, zakonski stan, naslov."},{"q":"Ordinalna spremenljivka je tista, pri kateri:","options":["Vrednosti le razlikujemo med seboj","Vrednosti uredimo od najmanjše do največje","Primerjamo razlike med vrednostmi","Primerjamo razmerja med vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri ordinalnih spremenljivkah vrednosti uredimo po velikosti (razvrstimo), ne moremo pa meriti razdalj med njimi. Primeri: izobrazba, ocena."},{"q":"Katera spremenljivka ima lastnosti INTERVALNE merske lestvice?","options":["Spol zaposlenega","Zakonski stan","Temperatura v stopinjah Celzija","Višina mesečne plače v EUR","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Temperatura v stopinjah Celzija je intervalna spremenljivka: primerjamo razlike med vrednostmi, ni pa smiselnega absolutnega izhodišča (0 °C ni odsotnost temperature)."},{"q":"Katera spremenljivka ima lastnosti RAZMERNOSTNE merske lestvice?","options":["Letnik študija","Inteligenčni kvocient (IQ)","Temperatura v Celziusih","Mesečna plača v EUR","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Mesečna plača v EUR je razmernostna spremenljivka: primerjamo razmerja (npr. ena plača je dvakrat večja od druge), absolutno izhodišče (0 EUR = brez dohodka) je smiselno."},{"q":"Spol je primer spremenljivke z mersko lestvico:","options":["Ordinalno","Intervalno","Nominalno","Razmernostno","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Spol je nominalna spremenljivka — vrednosti (moški, ženski) so le kategorije brez naravnega vrstnega reda."},{"q":"Izobrazba zaposlenega (osnovna, srednja, višja, visoka) je primer:","options":["Nominalne spremenljivke","Ordinalne spremenljivke","Intervalne spremenljivke","Razmernostne spremenljivke","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Izobrazba je ordinalna spremenljivka — vrednosti imajo naravni vrstni red (od najnižje do najvišje), razdalje med njimi pa niso enakovredne."},{"q":"Celoštevilska (diskretna) spremenljivka zavzame:","options":["Vse realne vrednosti v nekem intervalu","Le cela (diskontinuirana) števila","Samo vrednosti med 0 in 1","Izključno negativne vrednosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Celoštevilska oz. diskretna spremenljivka zavzame le cela števila (npr. število zaposlenih, število otrok, izpitna ocena)."},{"q":"Vzorec je:","options":["Celotna populacija preučevanega pojava","Del populacije, ki obsega izbrane enote","Vrednost parametra za celotno populacijo","Spremenljivka z nominalnimi vrednostmi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Vzorec je del populacije, ki ga opazujemo z namenom, da iz vzorčnih podatkov izračunamo ocene parametrov za celotno populacijo."},{"q":"Spremenljivka v statistiki je:","options":["Konstanta, ki opisuje populacijo kot celoto","Značilnost, ki jo vključimo v statistično analizo","Vrednost parametra za celotno populacijo","Posamezna enota preučevane populacije","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Spremenljivka je značilnost enote, ki smo jo vključili v statistično analizo. Vrednost spremenljivke se od enote do enote razlikuje."},{"q":"Promil (‰) se uporablja, ko je celota enaka:","options":["1","100","1000","10.000","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni odtisoček ali promil (‰) se uporablja pri demografskih kazalcih, kjer je celota 1000."},{"q":"Indeks I a/b = 125 pomeni, da je v a za koliko % VEČ kot v b?","options":["125 %","12,5 %","25 %","1,25 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Iz indeksa 125 odštejemo bazno vrednost 100 in dobimo 25 %. V a je torej 25 % več kot v b."},{"q":"Indeks I a/b = 80 pomeni, da je v a za koliko % MANJ kot v b?","options":["80 %","8 %","20 %","0,80 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"100 – 80 = 20. V a je 20 % manj kot v b."},{"q":"SWOT (PSPN) analiza preučuje:","options":["Samo prednosti podjetja v primerjavi s konkurenco","Prednosti, slabosti, priložnosti in nevarnosti","Politično, socialno, ekonomsko in tehnološko okolje","Stopnjo rivalstva med obstoječimi podjetji v panogi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"SWOT analiza (v slovenščini PSPN) preučuje prednosti, slabosti, priložnosti in nevarnosti — namen je pomoč pri strateških odločitvah."},{"q":"Makro statistični sistemi so:","options":["Del poslovnih informacijskih sistemov","Istovetni z računovodskimi sistemi podjetij","Samostojni in od podjetja neodvisni statistični sistemi","Registri na ravni posameznih občin","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Makro statistični sistemi so samostojni in od podjetja neodvisni statistični sistemi (npr. ESS, SSS)."},{"q":"Katera vrsta analize preučuje odnos med DVEMA spremenljivkama?","options":["Univariantna analiza","Bivariatna analiza","Multivariatna analiza","Deskriptivna analiza","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Bivariatna analiza preučuje odnos med dvema spremenljivkama. Univariatna preučuje eno, multivariatna pa tri ali več."},{"q":"Katera od navedenih velja za INTERVALNO spremenljivko?","options":["Število zaposlenih v podjetju","Stopnja izobrazbe zaposlenega","Mesečna bruto plača v EUR","Temperatura zraka v stopinjah Celzija","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Temperatura v °C je intervalna — razlike so smiselne (20 °C – 10 °C = 10 °C), ni pa smiselnega absolutnega izhodišča."},{"q":"Katera od navedenih trditev o APRS je pravilna?","options":["Vsebuje le aktivne poslovne subjekte z več kot 5 zaposlenimi","Vsebuje vse registrirane poslovne subjekte ne glede na aktivnost","Individualni podatki so dostopni samo akademskim institucijam","Vsebuje izključno podjetja s statusom pravne osebe","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"APRS vsebuje vse registrirane poslovne subjekte, ne glede na to, ali so aktivni ali ne."},{"q":"V čem se SPRS razlikuje od APRS?","options":["SPRS vsebuje manj enot in je dostopnejši javnosti","SPRS temelji na APRS, dodaja pa ažuriranje spremenljivk in ni javno dostopen","SPRS ne vključuje podružnic tujih podjetij","SPRS vsebuje izključno mikro podjetja","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"SPRS temelji na APRS, a so enote tekoče ažurirane. Za razliko od APRS individualni podatki iz SPRS niso javno dostopni."},{"q":"Katera od navedenih trditev o CRP je pravilna?","options":["CRP vsebuje podatke o poslovnih subjektih in podružnicah","CRP vsebuje EMŠO in osebne podatke o osebah s stalnim ali začasnim prebiv.","CRP je dostopen le sodiščem in policiji","CRP vsebuje le podatke o davčnih zavezancih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"CRP (Centralni register prebivalstva) vsebuje za vsako osebo: EMŠO, kraj rojstva, ime, priimek, državljanstvo, prebivališče, zakonski stan idr."}]},{"id":"st-t34-2","name":"Lestvice, prikaz in opisne mere (teme 3–4) (2/2)","questions":[{"q":"Stopnja brezposelnosti se izračuna kot:","options":["Brezposelni / delovno sposobno prebiv. × 100","Brezposelni / skupno prebiv. × 100","Brezposelni / aktivno prebiv. × 100","Brezposelni / delovno aktivno prebiv. × 100","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stopnja brezposelnosti = brezposelne osebe / aktivno prebivalstvo × 100. Aktivno prebivalstvo = zaposleni + brezposelni."},{"q":"Stopnja delovne aktivnosti se izračuna kot:","options":["Brezposelni / aktivno prebiv. × 100","Delovno aktivno prebiv. / delovno sposobno prebiv. × 100","Aktivno prebiv. / skupno prebiv. × 100","Zaposleni / skupno prebiv. × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja delovne aktivnosti = delovno aktivno prebivalstvo / delovno sposobno prebivalstvo × 100."},{"q":"Katera vrsta tabel ima vrednosti opisnih spremenljivk v VRSTICAH in STOLPCIH?","options":["Frekvenčna tabela","Analitična tabela","Kontingenčna tabela","Razpredelnica surovih podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Kontingenčna tabela ima vrednosti opisnih spremenljivk v vrsticah in stolpcih ter prikazuje frekvenčno porazdelitev za dve opisni spremenljivki.","wrong":{"Razpredelnica surovih podatkov":"Razpredelnica surovih podatkov (podatkovna matrika) ima v vrsticah enote opazovanja, v stolpcih pa spremenljivke (logika Excela) — ne razvršča dveh opisnih spremenljivk v obeh dimenzijah.","Frekvenčna tabela":"Frekvenčna tabela prikazuje porazdelitev frekvenc ene spremenljivke, ne dveh hkrati.","Analitična tabela":"Analitična tabela je splošen izraz za tabelo z izračuni; ne opisuje razporeditve dveh opisnih spremenljivk v vrsticah in stolpcih."}},{"q":"Outlier (ubežnik) je statistični pojem, ki označuje:","options":["Vrednost, ki je znotraj pričakovanega razpona","Vrednost, ki je numerično oddaljena od ostalih podatkov","Spremenljivko z nominalnimi vrednostmi","Vzorčno oceno parametra populacije","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Outlier (ubežnik) je vrednost, ki je numerično oddaljena od ostalih podatkov (zunaj skupnosti vrednosti)."},{"q":"Katera od navedenih NI načelo delovanja slovenske državne statistike?","options":["Nevtralnost in objektivnost","Strokovna neodvisnost","Statistična zaupnost","Pridobitnost in tržna usmerjenost","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Načela delovanja slovenske državne statistike so: nevtralnost, objektivnost, strokovna neodvisnost, racionalnost, statistična zaupnost in preglednost. Pridobitnost ni med njimi."},{"q":"Kateri je tipičen primer zvezne (kontinuirane) spremenljivke?","options":["Število zaposlenih v podjetju","Izpitna ocena pri predmetu","Mesečna višina štipendije v EUR","Število otrok v gospodinjstvu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Mesečna višina štipendije je zvezna (kontinuirana) spremenljivka — lahko zavzame katerokoli vrednost v nekem intervalu (npr. 350,75 EUR).","wrong":{"Število zaposlenih v podjetju":"Število zaposlenih je diskretna (števna) spremenljivka — zavzame le cela števila, ne poljubnih vmesnih vrednosti.","Izpitna ocena pri predmetu":"Izpitna ocena je urejenostna (ordinalna) spremenljivka — kategorije z vrstnim redom, ne zvezna.","Število otrok v gospodinjstvu":"Število otrok je diskretna spremenljivka (le cela števila)."}},{"q":"Enostavni količinski indeks se izračuna kot:","options":["pt / po × 100","qt / qo × 100","Pt × qt / Po × qo × 100","yt / yo × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Enostavni količinski indeks = qt / qo × 100, kjer je qt količina v tekočem in qo količina v baznem obdobju."},{"q":"Splošna stopnja fertilnosti (f) ima v imenovalcu:","options":["Srednje število celotnega prebiv.","Srednje število žensk v rodni dobi (15–49 let)","Število živorojenih v enem letu","Srednje število vseh žensk v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"f = N / V30.6,f,15 × 1000, kjer je V30.6,f,15 srednje število žensk v rodni dobi 15–49 let."},{"q":"Kateri od navedenih je primer diskretne (celoštevilske) spremenljivke?","options":["Mesečna plača v EUR","Temperatura v °C","Število zaposlenih v podjetju","Dolžina letnega dopusta v dnevih","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Število zaposlenih je diskretna spremenljivka — zavzame le cela nenegatavna števila. Dolžina dopusta je diskretna (celi dnevi), plača in temperatura pa sta zvezni."},{"q":"Kolikšna je bila stopnja registrirane brezposelnosti v Sloveniji februarja 2026?","options":["3,2 %","4,1 %","4,9 %","5,8 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stopnja registrirane brezposelnosti v Sloveniji februarja 2026 je znašala 4,9 % (vir: ZRSZ)."},{"q":"Kolikšna je bila mesečna stopnja inflacije (april 2026 / marec 2026)?","options":["0,5 %","1,9 %","3,0 %","3,1 %","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Mesečna stopnja inflacije (april 2026/marec 2026) je znašala 1,9 % (vir: SURS)."},{"q":"Kolikšna je bila stopnja naravnega prirastka v Sloveniji v letu 2024?","options":["-4,1 ‰","-2,2 ‰","0,5 ‰","5,4 ‰","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja naravnega prirastka je bila -2,2 ‰, kar pomeni negativno naravno gibanje (vir: SURS)."},{"q":"Katera trditev o APRS in europski uredbi o statističnih poslovnih registrih je pravilna?","options":["APRS v celoti izpolnjuje vse zahteve evropske uredbe","APRS ne vključuje vseh spremenljivk, ki jih zahteva evropska uredba","APRS vsebuje le aktivne poslovne subjekte","APRS ne vsebuje podatkov o pravnoorganizacijski obliki","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"APRS ne vključuje nekaterih spremenljivk, ki jih zahteva evropska uredba o statističnih poslovnih registrih za podjetja."},{"q":"Združevanje indeksnih vrst na NOVI osnovi izvedemo tako, da:","options":["Vsak člen stare vrste pomnožimo s stičnim členom","Vsak člen stare vrste delimo s stičnim členom in množimo s prvim členom nove vrste","Vsak člen nove vrste delimo z zadnjim členom stare vrste","Obe vrsti seštejemo in delimo z 2","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Združevanje na novi osnovi: vsak člen stare vrste delimo s stičnim členom stare vrste in množimo s prvim členom nove vrste (konstanta 100)."},{"q":"Katera trditev o spreminjanju indeksne osnove je pravilna?","options":["Osnovo spremenimo z množenjem vsakega člena z novim baznim letom","Osnovo spremenimo z deljenjem vsakega člena z vrednostjo novega baznega leta","Osnova se samodejno izračuna brez posegov","Osnove indeksnih vrst ni mogoče spremeniti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Da spremenimo osnovo indeksne vrste z j na 0, delimo vsak člen vrste z vrednostjo tistega člena, ki ustreza novemu baznemu letu (to je konstanta)."},{"q":"Kateri od navedenih je primer TRENUTNE (momentne) statistične množice?","options":["Sklenitve zakonskih zvez v letu 2024","Rojeni v SLO v prvem polletju 2024","Umrli za covidom v letu 2023","Stalno prebiv. SLO na dan 1. januarja 2025","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Trenutne množice so opredeljene za točno določen trenutek. Stanje stalnega prebiv. na dan 1. januarja je momentna množica."},{"q":"Kateri od navedenih je primer RAZMIČNE (intervalne) statistične množice?","options":["Prebiv. SLO na dan 1. julija 2025","Podjetja v APRS na dan 31. decembra 2024","Ločitve v SLO v letu 2024","Delovno aktivni v SLO na dan 30. junija 2025","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Razmične (intervalne) množice so opredeljene z obdobjem (intervalom). Ločitve v določenem letu so tipičen primer."},{"q":"Katera od navedenih je pravilna razlaga indeksa I a/b = 80?","options":["V a je 80 % več kot v b","V a je 20 % manj kot v b","V a je 0,80 krat več kot v b","V a je 1,25 krat več kot v b","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"I a/b = 80 → a ima 20 % manj kot b (100 − 80 = 20 %). V a je 0,80-krat toliko kot v b (ne 0,80 krat VEČ)."},{"q":"Kateri od navedenih opisuje pravilno zaporedje: urejanje, analiza, interpretacija?","options":["Zbiranje → urejanje → prikaz → analiza → interpretacija","Urejanje → zbiranje → analiza → prikaz → interpretacija","Prikaz → analiza → zbiranje → urejanje → interpretacija","Interpretacija → zbiranje → analiza → urejanje → prikaz","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Statistični proces: zbiranje podatkov → urejanje (čiščenje, kodiranje) → prikaz (tabele, grafikoni) → analiza → interpretacija rezultatov."},{"q":"Kateri od navedenih nadomestnih kazalcev za obseg proizvodnje je najustreznejši za primerjave med panogami?","options":["Bruto prihodek od prodaje","Skupna vrednost zalog","Neto dodana vrednost","Skupni stroški dela","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Neto dodana vrednost je najprimernejša mera za medpanožne primerjave obsega proizvodnje, ker eliminira vmesno porabo in obrabo."},{"q":"Indeks je:","options":["Absolutno število z mersko enoto","Relativno (neimenovano) število za primerjavo istovrstnih podatkov","Aritmetična sredina dveh vrednosti","Vsota vrednosti spremenljivke v populaciji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Indeks je relativno (neimenovano) število, s katerim primerjamo dvoje ali več istovrstnih podatkov."},{"q":"Indeks s STALNO osnovo se izračuna tako, da:","options":["Za vsak indeks v vrsti vzamemo predhodno obdobje kot osnovo","Za vse indekse v vrsti vzamemo isto bazno obdobje","Za osnovo vzamemo povprečje celotnega opazovanega niza","Indekse zaporedno množimo med seboj","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri indeksih s stalno osnovo je za vse člene v vrsti osnova primerjave enako (isto) bazno obdobje."}]},{"id":"st-t5-1","name":"Strukture in koeficienti (tema 5) (1/2)","questions":[{"q":"Kaj je relativno število strukture?","options":["Razmerje med dvema absolutnima številoma iz različnih skupin","Delež posamezne kategorije v celoti, izražen v odstotkih (%)","Razmerje med vrednostmi iz dveh zaporednih časovnih obdobij","Razmerje med vrednostmi iz različnih geografskih enot","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Relativno število strukture = (vrednost kategorije / skupna vrednost) × 100. Pove, koliko odstotkov celote predstavlja posamezna kategorija. Vsota vseh relativnih števil strukture mora biti 100 %."},{"q":"Koliko mora znašati vsota vseh relativnih števil strukture?","options":["0","50","100","Odvisno od podatkov","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Vsota vseh relativnih števil strukture vedno znaša natanko 100 %, ker vsaka kategorija predstavlja delež celote, vse deleže pa seštejemo v celoto."},{"q":"Kateri od nastetih koeficientov je smiseln?","options":["BDP Nemčije / število zaposlenih v kmetijstvu Španije","Promet podjetja A v 2023 / število zaposlenih v podjetju B v 2020","Pridelek hmelja v Nemčiji / površina hmeljišč v Nemčiji v istem letu","Število rojstev v Sloveniji / BDP Kitajske","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Koeficient je smiseln, ko sta števec in imenovalec vsebinsko logično povezana, nanašata se na isto enoto preučevanja in isto časovno obdobje. Pridelek / površina = hektarski pridelek — logična zveza, ista zemlja, isto leto."},{"q":"Kaj je stolpčna pogojna struktura v dvorazsežni tabeli?","options":["Delež vsake celice glede na skupni seštevek celotne tabele","Delež vsake celice glede na vsoto njenega stolpca","Vsota absolutnih vrednosti v posameznem stolpcu","Razmerje med vrsticami tabele","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Stolpčna pogojna struktura prikazuje, kako se vrednosti razporedijo ZNOTRAJ vsakega stolpca — vsaka celica se deli z vsoto svojega stolpca × 100. Vsota vrednosti v vsakem stolpcu je tako 100 %."},{"q":"Florence Nightingale je v statistiki znana po tem, da je razvila:","options":["Temelje opisne statistike s prikazom umrljivosti vojakov","Gaussovo krivuljo normalne porazdelitve","Korelacijski koeficient za merjenje odvisnosti","Metodo vzorčenja pri nadzoru kakovosti piva","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Florence Nightingale je z analizo skupin umrlih vojakov v Turčiji in Krimu postavila temelje opisne statistike."},{"q":"Karl Pearson je v statistiki razvil:","options":["Metodo linearne ekstrapolacije","Korelacijski koeficient","Normalno porazdelitev (Gaussovo krivuljo)","Top-down metodo razvrščanja dejavnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Karl Pearson je razvil korelacijski koeficient, ki meri stopnjo linearne odvisnosti med dvema spremenljivkama."},{"q":"Netnografija je metoda, ki preučuje:","options":["Odzive potrošnikov v fizičnih prodajalnah","Spletne strani in skupnosti na internetu","Demografsko strukturo prebivalstva","Primerjave indeksov cen med državami","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Spletna etnografija (netnografija) je analiza spletnih strani, forumov in skupnosti — oblika opazovalne študije na internetu."},{"q":"Meta podatki so:","options":["Statistični podatki o tujih državah","Podatki o podatkih (vsebina, struktura, kakovost)","Vzorčni podatki, pridobljeni z anketo","Administrativni podatki iz registrov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Meta podatki vsebujejo podatke o podatkih; obsegajo informacije o vsebini, strukturi, kakovosti, lastništvu in distribuciji podatkov."},{"q":"SKD je:","options":["Standardna klasifikacija dejavnosti v Sloveniji","Skupni koeficient demografije","Statistični kazalec dejanske aktivnosti","Sistem kratkih definicij","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"SKD je Standardna klasifikacija dejavnosti — slovenska različica NACE, s katero je do ravni razredov praktično identična."},{"q":"Strukturni odstotek se izračuna, ko je celota enaka:","options":["1","100","1000","10.000","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Strukturni odstotek je izražen v %, kjer je celota 100. Strukturni delež ima celoto 1, strukturni odtisoček (promil) pa 1000."},{"q":"Strukturni delež se izračuna, ko je celota enaka:","options":["100","1000","1","10","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni delež je izražen kot decimalno število med 0 in 1, kjer je celota 1 (100 %)."},{"q":"Strukturni krog (tortni grafikon) se najpogosteje uporablja za prikazovanje:","options":["Kronološke spremembe pojava","Frekvenčne porazdelitve zvezne spremenljivke","Strukture (deležev) celote","Razpršenosti podatkov v vzorcu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Strukturni krog je analitični grafikon, namenjen prikazovanju struktur — razčlembi celote na dele.","wrong":{"Kronološke spremembe pojava":"Časovne (kronološke) spremembe prikažemo z linijskim grafikonom, ne s strukturnim krogom.","Frekvenčne porazdelitve zvezne spremenljivke":"Frekvenčno porazdelitev zvezne spremenljivke prikažemo s histogramom.","Razpršenosti podatkov v vzorcu":"Razpršenost prikazujemo npr. s škatlo z brki (boxplot), ne s tortnim grafikonom."}},{"q":"Histogram se najpogosteje uporablja za prikazovanje:","options":["Strukture populacije po skupinah","Frekvenčne porazdelitve zvezne spremenljivke","Kronoloških sprememb indeksov","Korelacije med dvema spremenljivkama","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Histogram prikazuje frekvenčno porazdelitev zvezne (kontinuirane) spremenljivke, razvrščene v razrede."},{"q":"Koeficient je smiseln le, kadar sta podatka v števcu in imenovalcu:","options":["Izražena v različnih merskih enotah","Vsebinsko, prostorsko in časovno usklajena","Iz različnih populacij in različnih obdobij","Izračunana kot absolutni vrednosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient je smiseln le, kadar sta podatka v števcu in imenovalcu vsebinsko, prostorsko in časovno usklajena."},{"q":"PEST analiza je orodje za sistematično preučevanje dejavnikov:","options":["Notranjega okolja podjetja (prednosti in slabosti)","Zunanjega okolja (politično, ekonomsko, socialno, tehnološko)","Primerjalnih prednosti pred konkurenco","Demografske strukture ciljnih kupcev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"PEST analiza preučuje zunanje dejavnike poslovnega okolja: politične, ekonomske, socialne in tehnološke."},{"q":"Kateri od kazalcev SODI med koeficiente?","options":["Absolutni naravni prirastek","Indeks staranja","Splošna stopnja natalitete","Število živorojenih v enem letu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Splošna stopnja natalitete je koeficient — razmerje med številom živorojenih in srednim številom prebivalcev, izraženo v promilih."},{"q":"Enorazsežna struktura pomeni razčlenitev:","options":["Po dveh spremenljivkah hkrati","Po treh ali več spremenljivkah","Po eni spremenljivki","Po nominalnih spremenljivkah","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Enorazsežna struktura je razčlenitev po eni spremenljivki. Dvorazsežna je po dveh, večrazsežna pa po treh ali več."},{"q":"Izhodišče prvega krogovega izseka v strukturnem krogu je:","options":["Pri 90 stopinjah (ura 12.00)","Pri 180 stopinjah (ura 9.00)","Pri 0 stopinjah (ura 15.00)","Pri 270 stopinjah (ura 6.00)","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Izhodišče prvega krogovega izseka je pri 0 stopinjah (ura 15.00), krogove izseke pa nizamo v nasprotni smeri urinega kazalca."},{"q":"Krogove izseke v strukturnem krogu nanašamo:","options":["Naključno, brez posebnega vrstnega reda","Po velikosti od najmanjšega do največjega","Po abecednem redu kategorij","Po velikosti od največjega do najmanjšega","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Krogove izseke v strukturnem krogu nizamo v nasprotni smeri urinega kazalca po velikosti od največjega do najmanjšega."}]},{"id":"st-t5-2","name":"Strukture in koeficienti (tema 5) (2/2)","questions":[{"q":"Katero od navedenih pojasnuje, kaj je »Para podatek«?","options":["Podatek, ki opisuje vsebino in strukturo zbirke podatkov","Opis procesa zbiranja primarnih podatkov, ki omogoča razumevanje nastanka podatkov","Podatek, zbran vzporedno s primarnim za namen preverjanja","Sintetični kazalec na osnovi več spremenljivk","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Para podatki opisujejo proces interpretacije in ustvarjanja podatkov, ki omogoča razumevanje njihovega nastanka in evaluacijo."},{"q":"Koeficient po PREMI shemi (v) meri:","options":["Koliko delovnih ur je potrebnih za enoto producta","Koliko enot proizvoda nastane na enoto porabljenega dela","Koliko delovnih ur je opravljenih na zaposlenega","Koliko denarnih enot prihodka ustvari zaposleni","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient produktivnosti dela po premi shemi (v) = Q/T — pove, koliko enot proizvoda nastane na enoto porabljenega dela."},{"q":"Katera vrsta podatkov je primerna za izračun koeficienta, ki meri produktivnost na zaposlenega?","options":["Nominalni in ordinalni podatki","Samo diskretni (celoštevilski) podatki","Kvantitativni podatki (vrednostni ali naturalni)","Samo primarne podatke iz anket","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient produktivnosti dela zahteva kvantitativne podatke: mere obsega proizvodnje (Q) in potroška dela (T)."},{"q":"Katera vrsta grafičnega prikaza je primerna za prikazovanje koeficientov?","options":["Strukturni krog","Pravokotniki z enako ali različno širino","Starostna piramida","Razsevni diagram (XY)","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za prikazovanje koeficientov so primerni pravokotniki (stolpčni grafikon) z enako ali različno širino."},{"q":"Kateri kazalec meri razmerje med celotnim vzdrževanim delom populacije in delovno aktivnim delom?","options":["Indeks staranja","Stopnja aktivnosti","Koeficient starostne odvisnosti","Stopnja mortalitete","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient starostne odvisnosti = (osebe do 15 let + osebe 65+) / osebe 15–64 let × 100."},{"q":"Kolikšen je bil koeficient starostne odvisnosti v 2. polletju 2025?","options":["48,3","53,7","58,1","63,4","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Koeficient starostne odvisnosti je v 2. polletju 2025 znašal 58,1 (vir: SURS)."},{"q":"Kolikšen je bil delež bruto domačih izdatkov za R&R v BDP leta 2024?","options":["1,07 %","1,68 %","2,14 %","2,89 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež bruto domačih izdatkov za R&R v BDP je znašal 2,14 % v letu 2024 (vir: SURS)."},{"q":"Kolikšen je bil delež dnevnih ali skoraj dnevnih uporabnikov interneta (16–74 let) v letu 2025?","options":["72 %","81 %","88 %","94 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež oseb, ki vsak dan ali skoraj vsak dan uporabljajo internet, je bil 88 % v letu 2025 (vir: SURS)."},{"q":"Kolikšen je bil delež e-kupcev (16–74 let) v letu 2025?","options":["52,0 %","59,5 %","67,0 %","74,3 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delež e-kupcev je znašal 67,0 % v letu 2025 (vir: SURS)."},{"q":"Katera nadomestna mera za obseg proizvodnje NI primerna za izračun produktivnosti?","options":["Naturalne mere (npr. tone, kosi)","Vrednostne mere (EUR, dodana vrednost)","Pogojno naturalne mere (standardizirane enote)","Število zaposlenih v podjetju","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Število zaposlenih je mera potroška dela (T), ne obsega proizvodnje (Q). Nadomestne mere za Q so: naturalne, pogojno naturalne in vrednostne."},{"q":"Pri izračunu koeficienta, ki meri pridelek hmelja na hektar, je v imenovalcu:","options":["Število zaposlenih v hmeljogojstvu","Površina hmeljišč v hektarjih","Vrednost izvoženega hmelja v EUR","Število porabljenih ur pri pridelavi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pridelek hmelja / hmeljske površine (ha) je smiseln koeficient — meri donos na površinsko enoto. Imenovalec so hmeljske površine."},{"q":"Katera trditev o izvedenih demografskih kazalcih je pravilna?","options":["Absolutni naravni prirastek je izvedeni kazalec","Stopnja naravnega prirastka sodi med absolutne kazalce","Splošna stopnja mortalitete je izvedeni kazalec, ki sodi med koeficiente","Število umrlih v enem letu je relativni kazalec","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Splošna stopnja mortalitete (m) je izvedeni kazalec, ki sodi med koeficiente (razmerje med absolutnimi kazalci)."},{"q":"Katera od trditev o analitičnem prikazu podatkov s strukturnim krogom je NAPAČNA?","options":["Izseke nizamo v smeri urinega kazalca","Izseke nizamo po velikosti od največjega do najmanjšega","Izhodišče prvega izseka je pri 0 stopinjah (ura 15, desno)","3D strukturni krog je manj informativen kot 2D","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Napačna trditev je »v smeri urinega kazalca«: izseke nizamo v NASPROTNI smeri urinega kazalca (matematična smer), z izhodiščem pri 0° (ura 15, desno), po velikosti od največjega do najmanjšega. Ostale tri trditve so pravilne.","wrong":{"Izseke nizamo po velikosti od največjega do najmanjšega":"Ta trditev je PRAVILNA — izseke res nizamo od največjega do najmanjšega, zato ni iskana napačna trditev.","Izhodišče prvega izseka je pri 0 stopinjah (ura 15, desno)":"Ta trditev je PRAVILNA — izhodišče je pri 0° (ura 15, desno), zato ni iskana napačna trditev.","3D strukturni krog je manj informativen kot 2D":"Ta trditev je PRAVILNA — 3D popači zaznavo deležev in je manj informativen, zato ni iskana napačna trditev."}},{"q":"Kateri od navedenih ni predpogoj za smiselnost koeficienta?","options":["Vsebinska usklajenost podatkov v števcu in imenovalcu","Prostorska usklajenost podatkov v števcu in imenovalcu","Časovna usklajenost podatkov v števcu in imenovalcu","Enaka merska enota v števcu in imenovalcu","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Koeficient zahteva vsebinsko, prostorsko in časovno usklajenost — ni pa nujno, da sta merski enoti enaki (npr. kg / ha)."},{"q":"Katera je pravilna opredelitev staranja prebivalstva?","options":["Porast absolutnega števila oseb, starejših od 65 let","Naraščanje deleža starega prebiv. in padanje deleža mladega prebiv. v skupnem prebiv.","Porast koeficienta starostne odvisnosti brez spremembe indeksa staranja","Padanje stopnje natalitete ob hkratnem naraščanju mortalitete","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Demografsko staranje je proces, pri katerem narašča delež starega in pada delež mladega prebiv. v skupnem prebiv."},{"q":"Katera od navedenih je pravilna razlaga koeficienta produktivnosti dela po premi shemi v = Q/T = 5?","options":["Za enoto proizvoda je potrebnih 5 ur dela","Na enoto porabljenega dela nastane 5 enot proizvoda","Delavec zasluži 5 EUR na uro dela","Podjetje porabi 5 enot materiala na enoto proizvoda","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"v = Q/T = 5 pomeni: na enoto porabljenega dela (T) nastane 5 enot proizvoda (Q). Recipročna shema t = T/Q bi dala koliko dela je na enoto proizvoda.","wrong":{"Za enoto proizvoda je potrebnih 5 ur dela":"To opisuje INTENZIVNOST dela (t = T/Q), torej recipročno vrednost produktivnosti — koliko dela je potrebnega na enoto proizvoda, ne obratno.","Delavec zasluži 5 EUR na uro dela":"To je urna postavka oz. plača, ne koeficient produktivnosti dela.","Podjetje porabi 5 enot materiala na enoto proizvoda":"To je tehnični/materialni koeficient porabe materiala, ne produktivnost dela."}},{"q":"Kako imenujemo razliko med vrednostjo vzorčne ocene in pravo vrednostjo parametra?","options":["Standardni odklon","Koeficient variabilnosti","Vzorčna napaka","Mediana","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Razlika med vzorčno oceno in pravo vrednostjo parametra se imenuje vzorčna napaka (sampling error)."},{"q":"Katera od navedenih je pravilna opredelitev para podatka?","options":["Podatek o podatku (vsebina, struktura, kakovost)","Opis procesa zbiranja prim. podatkov, ki omogoča razumevanje nastanka","Vzporedno zbrani podatek za namene preverjanja","Sekundarni podatek iz javno dostopnih registrov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Para podatek opisuje proces interpretacije in ustvarjanja podatkov — dokumentira, kako in zakaj so bili zbrani."}]},{"id":"st-t6","name":"Enostavni indeksi in deflacioniranje (tema 6)","questions":[{"type":"match","q":"Poveži vrsto indeksa z opredelitvijo.","pairs":[{"term":"Časovni indeks","def":"Primerja isti pojav v dveh časovnih obdobjih"},{"term":"Krajevni (prostorski) indeks","def":"Primerja isti pojav v dveh krajih ob istem času"},{"term":"Stvarni indeks","def":"Primerja dva različna pojava ob istem času in kraju"}],"explanation":"Pri časovnem se spreminja čas, pri krajevnem kraj, pri stvarnem pa preučevani pojav."},{"q":"Kaj pomeni bazni enostavni indeks It/0 = 120?","options":["Vrednost se je zmanjšala za 120 enot","Vrednost je v tekočem obdobju za 20 % višja kot v baznem","Vrednost je v baznem obdobju za 20 % višja kot v tekočem","Vrednost je narasla za 120 enot","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Bazni indeks 120 pomeni, da je tekoča vrednost 120 % bazne vrednosti — torej za 20 % višja od bazne. Formula: It/0 = (yt / y0) × 100 = 120 → yt je za 20 % večji od y0."},{"q":"Kaj je verižni indeks?","options":["Indeks, ki primerja tekoče obdobje z enim fiksnim baznim obdobjem","Indeks, ki primerja vrednosti iz dveh različnih krajev ob istem času","Indeks, ki primerja vsako obdobje s prejšnjim (neposredno predhodnim) obdobjem","Produkt vseh baznih indeksov v obravnavanem obdobju","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Verižni indeks (Vt/t-1) primerja vsako obdobje s prejšnjim: Vt/t-1 = (yt / yt-1) × 100. Produkt vseh verižnih indeksov (deljenih s 100) pa da bazni indeks celotnega obdobja."},{"q":"Kaj je deflacioniranje?","options":["Množenje nominalne vrednosti s cenovnim indeksom","Pretvorba nominalnih vrednosti v realne z deljenjem s cenovnim indeksom × 100","Odštevanje stopnje inflacije od nominalne vrednosti","Izračun povprečne cene v baznem letu","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Deflacioniranje: realna vrednost = (nominalna vrednost / indeks cen) × 100. S tem 'izločimo' vpliv cen in dobimo realno spremembo količine oz. obsega. Deliš, ne množiš!"},{"q":"Kaj je prostorski (krajevni) indeks?","options":["Indeks, ki primerja vrednosti iz dveh zaporednih časovnih obdobij","Indeks, ki primerja vrednost istega pojava v dveh različnih krajih v istem časovnem obdobju","Indeks spremembe cen na različnih ravneh ekonomije","Verižni indeks za geografska območja","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Prostorski oz. krajevni indeks: I_A/B = (y_A / y_B) × 100. Primerja ISTO spremenljivko v dveh različnih krajih (državah, regijah...) ob ISTEM časovnem obdobju. Npr. BDP na preb. Avstrije glede na Slovenijo."},{"q":"Verižni indeksi so indeksi, pri katerih je osnova primerjave:","options":["Vedno isto bazno leto","Vedno predhodno obdobje v nizu","Povprečje celotnega opazovanega niza","Vrednost iz naslednjega obdobja","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Za verižne indekse je značilno, da je osnova primerjave vedno predhodno obdobje v nizu zaporednih obdobij."},{"q":"Tehnika imputacije pri urejanju podatkov se uporablja za:","options":["Razvrščanje enot v razrede frekvenčne porazdelitve","Obravnavo manjkajočih vrednosti","Preračun verižnih indeksov na stalno osnovo","Tehtanje podatkov pri izračunu skupinskih indeksov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Tehnika imputacije je postopek za obravnavo manjkajočih vrednosti pri urejanju podatkov."},{"q":"Enostavni indeks cen se izračuna kot:","options":["qt / qo × 100","Pt × qt / Po × qo × 100","pt / po × 100","(pt + po) / 2 × 100","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Enostavni indeks cen = pt / po × 100, kjer je pt cena v tekočem in po cena v baznem obdobju."},{"q":"Pri preračunu verižnih indeksov na stalno osnovo (0) delimo vsak člen indeksne vrste z:","options":["Prvim členom indeksne vrste","Zadnjim členom indeksne vrste","Stičnim členom × konstanta 100","Celotno indeksno vrsto z baznim indeksom","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Verižne indekse preračunamo na stalno osnovo tako, da vsak člen delimo s prvim členom indeksne vrste (ki je konstanta 100), oz. se izračuna kumulativno z množenjem."},{"q":"Kako dobimo vrednost pojava za celotno obdobje iz vrste verižnih indeksov?","options":["Z deljenjem zadnjega člena z baznim letom","S kumulativnim množenjem verižnih indeksov","Z računanjem aritmetične sredine vseh členov","Z deljenjem zadnjega člena z vsoto vseh členov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Kumulativno množenje verižnih indeksov pove, kako se je pojav spremenil v celotnem obdobju od prvega do zadnjega opazovanega período."}]},{"id":"st-t7","name":"Skupinski indeksi: Laspeyres in Paasche (tema 7)","questions":[{"type":"match","q":"Poveži indeks z načinom tehtanja oz. opredelitvijo.","pairs":[{"term":"Laspeyresov indeks","def":"Tehtanje z baznimi količinami (q₀)"},{"term":"Paaschejev indeks","def":"Tehtanje s tekočimi količinami (q₁)"},{"term":"Fisherjev indeks","def":"Geometrijska sredina Laspeyresovega in Paaschejevega"},{"term":"Deflator","def":"Indeks cen za pretvorbo nominalne vrednosti v realno"},{"term":"Verižni indeks","def":"Primerja vsako obdobje z neposredno predhodnim"}],"explanation":"Laspeyres uporablja bazne, Paasche tekoče uteži; Fisher je njuna geometrijska sredina."},{"q":"Kaj meri Laspeyresov indeks cen (IᴾL)?","options":["Za koliko so se spremenile cene, tehtane s tekočimi količinami (q₁)","Za koliko so se spremenile količine, tehtane z baznimi cenami (p₀)","Za koliko so se spremenile cene, tehtane z baznimi količinami (q₀)","Za koliko se je spremenila skupna vrednost","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IᴾL = Σ(q₀·p₁) / Σ(q₀·p₀) × 100. Meri spremembo cen, pri čemer kot uteži (ponderi) uporablja BAZNE količine (q₀). Ker uteži ostanejo enake, sprememba odraža samo vpliv cen."},{"q":"Kateri ponderi se uporabijo pri Paaschejevem indeksu cen (IᴾP)?","options":["Bazne cene (p₀)","Tekoče količine (q₁)","Bazne količine (q₀)","Tekoče cene (p₁)","Pravilna rešitev ni navedena"],"correct":1,"explanation":"IᴾP = Σ(q₁·p₁) / Σ(q₁·p₀) × 100. Paaschejev indeks cen kot uteži uporablja TEKOČE količine (q₁) — tiste iz tekočega, ne baznega obdobja. Zato je manjši od Laspeyresovega, kadar se kupuje relativno manj dragih stvari."},{"q":"Kdaj so strukturni premiki zavrli rast cen?","options":["Ko je IᴾL = IᴾP (enaka vrednost)","Ko je IᴾL < IᴾP (Paasche višji)","Ko je IᴾL > IᴾP (Laspeyres višji)","Ko je indeks vrednosti večji od 100","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IᴾL > IᴾP → strukturni premiki so zavrli rast cen. To pomeni, da so se v tekočem obdobju relativno povečale nakupljene količine cenejših vrst blaga. Posledično tekoče uteži (Paasche) dajejo nižji rezultat od baznih (Laspeyres)."},{"q":"Katera relacija med skupinskimi indeksi je pravilna?","options":["IV = IᴾL × IQL / 100","IV = IᴾL × IQP / 100","IV = IᴾP × IQP / 100","IV = IᴾL + IQP − 100","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Pravilni relaciji sta: IV = IᴾL × IQP / 100 in IV = IᴾP × IQL / 100. Vedno 'križi' — Laspeyresov cenovni × Paaschejev količinski (ali obratno). Nikoli L×L ali P×P!"},{"q":"Tehnika tehtanja pri urejanju podatkov se uporablja za:","options":["Izračun ponderiranih indeksov cen","Naknadno uskladitev strukture vzorca s strukturo populacije","Preverbo logičnih napak v podatkih","Razvrščanje ordinalnnih spremenljivk","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Tehnika tehtanja (weighting) se uporablja za naknadno uskladitev strukture vzorca s strukturo populacije."},{"q":"Kateri od koeficientov produktivnosti meri, koliko delovnega časa je potrebnega za enoto proizvoda?","options":["Koeficient po premi shemi (v = Q/T)","Koeficient po recipročni shemi (t = T/Q)","Skupinski indeks po Laspeyresu","Enostavni indeks cen","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Koeficient po recipročni shemi t = T/Q meri, koliko delovnega časa (T) je potrebnega za enoto proizvoda (Q)."},{"q":"Laspeyresov skupinski indeks cen se izračuna z:","options":["Ponderji iz tekočega (t) obdobja","Ponderji iz baznega (0) obdobja","Geometrijsko sredino Laspeyresovega in Paaschejevega","Aritmetično sredino cen brez ponderjev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Laspeyresov obrazec uporablja pondere iz baznega (0) obdobja — tistega, ki je v imenovalcu indeksa."},{"q":"Paaschejev skupinski indeks cen se izračuna z:","options":["Ponderji iz baznega (0) obdobja","Ponderji iz tekočega (t) obdobja","Geometrijsko sredino vseh cen v seriji","Aritmetično sredino Laspeyresovega in Paaschejevega","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Paaschejev obrazec uporablja pondere iz tekočega (t) obdobja — tistega, ki je v števcu indeksa."},{"q":"Katera od navedenih velja za skupinske indekse?","options":["Skupinski indeksi so enaki enostavnim indeksom pri eni dobri","Skupinski indeksi se delijo na agregatne in srednje indekse","Skupinski indeksi se vedno izračunavajo brez ponderjev","Skupinski indeksi so vedno Laspeyresovi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Skupinske indekse delimo glede na postopek izračuna na agregatne (Laspeyres, Paasche, Fisher) in srednje indekse."}]},{"id":"st-t8","name":"Skupinski indeksi: Fisher, strukturni premiki (tema 8)","questions":[{"type":"match","q":"Poveži skupinski indeks z njegovo lastnostjo.","pairs":[{"term":"Tehtana aritmetična sredina (TAS)","def":"Da enak rezultat kot agregatni Laspeyresov indeks"},{"term":"Tehtana harmonična sredina (THS)","def":"Da enak rezultat kot agregatni Paaschejev indeks"},{"term":"Indeks s stalno strukturo","def":"Uteži iz baznega obdobja; izhodišče za strukturne premike"},{"term":"Indeks s spremenljivo strukturo","def":"Indeks povprečne (srednje) cene homogenega proizvoda"}],"explanation":"TAS = agregatni Laspeyres, THS = agregatni Paasche. Indeks strukturnih premikov = razmerje obeh × 100."},{"q":"Kaj je Fisherjev idealni indeks?","options":["Aritmetična sredina Laspeyresovega in Paaschejevega indeksa","Harmonična sredina Laspeyresovega in Paaschejevega indeksa","Geometrijska sredina Laspeyresovega in Paaschejevega indeksa","Produkt vseh agregatnih indeksov / 100","Pravilna rešitev ni navedena"],"correct":2,"explanation":"IF = √(IᴾL × IᴾP). Fisherjev indeks je geometrijska sredina Laspeyresovega in Paaschejevega indeksa. Velja za 'idealnega', ker nima sistematične naprave ne navzgor ne navzdol."},{"q":"Kaj pomeni IV = 95?","options":["Skupna vrednost je narasla za 95 %","Skupna vrednost je padla za 5 %","Skupna vrednost je narasla za 5 %","Cene so padle za 5 %","Pravilna rešitev ni navedena"],"correct":1,"explanation":"IV = 95 pomeni, da je tekoča skupna vrednost (Σq₁p₁) enaka 95 % bazne skupne vrednosti (Σq₀p₀) — torej se je skupna vrednost zmanjšala za 5 %."},{"q":"Fisherjevo idealno indeksno število je:","options":["Aritmetična sredina Laspeyresovega in Paaschejevega","Geometrijska sredina Laspeyresovega in Paaschejevega","Harmonična sredina Laspeyresovega in Paaschejevega","Razlika med Laspeyresovim in Paaschejevim","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Fisherjevo idealno indeksno število je geometrijska sredina Laspeyresovega in Paaschejevega skupinskega indeksa."},{"q":"Indeks strukturnih premikov se izračuna kot:","options":["Enostavni indeks cen / skupinski indeks cen × 100","Indeks cen s spremenljivo strukturo / indeks cen s stalno strukturo × 100","Laspeyresov indeks / Paaschejev indeks × 100","Skupinski indeks / enostavni indeks × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Indeks strukturnih premikov = indeks cen s spremenljivo strukturo / indeks cen s stalno strukturo × 100."},{"q":"Indeks povprečne (srednje) cene se izračuna kot:","options":["Povprečna cena za tekoče / bazno obdobje × 100","Vsota cen tekočega / vsota cen baznega obdobja × 100","(Cena tekočega – cena baznega) / cena baznega × 100","Skupinski indeks cen / enostavni indeks cen × 100","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Indeks povprečne (srednje) cene = Pt / Po × 100, kjer je Pt povprečna cena v tekočem in Po povprečna cena v baznem obdobju."}]},{"id":"st-nal58","name":"Računske naloge · teme 5–8","calc":true,"questions":[{"q":"Naloga 1 · Struktura naložbenega portfelja","hint":"Relativno število strukture = (vrednost enote / skupna vrednost) × 100. Vsota vseh strukturnih deležev = 100 %.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Tvoj portfelj na koncu leta 2023 je sestavljen iz treh vrst sredstev. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Sredstvo</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Delnice (S&P 500 ETF)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">15.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Obveznice (US Treasury)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">9.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Denar in ekvivalenti</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">6.000 EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\"><b>SKUPAJ</b></td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\"><b>30.000 EUR</b></td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Strukturni delež delnic je 50 %.</div><div style=\"font-size:13.5px\"><b>b)</b> Strukturni delež obveznic je 25 %.</div><div style=\"font-size:13.5px\"><b>c)</b> Strukturni delež denarja je 20 %.</div><div style=\"font-size:13.5px\"><b>d)</b> Vsota vseh treh deležev je 100 %.</div></div>","options":["a + b","a + c + d","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Delnice 15.000/30.000×100 = <b>50 %</b> (a ✓). Obveznice 9.000/30.000×100 = <b>30 %</b>, ne 25 % (b ✗). Denar 6.000/30.000×100 = <b>20 %</b> (c ✓). Vsota 50+30+20 = <b>100 %</b> (d ✓). → pravilno <b>a + c + d</b>."},{"q":"Naloga 2 · Smiselnost koeficientov","hint":"Koeficient je smiseln, kadar sta števec in imenovalec vsebinsko povezana, se nanašata na isto enoto/območje in na isto (ali zaporedno) časovno obdobje.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Kateri koeficienti so smiselni?</div><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Dnevni promet NQ futures (USD, 2023) / št. trading dni na NQ (2023).</div><div style=\"font-size:13.5px\"><b>b)</b> BDP Japonske (USD, 2023) / promet NYSE (EUR, 2023).</div><div style=\"font-size:13.5px\"><b>c)</b> Neto dobiček sklada (EUR) / povpr. št. zaposlenih v skladu (2023).</div><div style=\"font-size:13.5px\"><b>d)</b> Prodane opcije na S&P 500 (okt. 2023) / AUM vseh hedge skladov (USD, 2019).</div></div>","options":["a","c","a + c","b + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"a) povprečni dnevni promet — isti pojav, isto obdobje → <b>smiseln</b>. c) dobiček na zaposlenega — vsebinsko povezano, isto obdobje → <b>smiseln</b>. b) različni valuti in nepovezana pojava → ne. d) različni obdobji (2023 vs 2019) in nesorazmerna agregata → ne. → <b>a + c</b>."},{"q":"Naloga 3 · Povprečni enostavni indeks — delniški portfelj","hint":"Enostavni indeks: i = (p₁/p₀)×100. Povprečni enostavni indeks = (Σi)/n. i < 100 = padec, i > 100 = rast.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Slediš štirim delnicam (bazno 2022 = 100, tekoče 2023). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Delnica</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀ (2022)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁ (2023)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">i</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">AAPL</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">150</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">180</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">120,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">MSFT</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">250</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">300</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">120,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">GOOGL</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">90</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">90,0</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">AMZN</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">210</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">105,0</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Povprečni enostavni indeks vseh štirih je 108,75.</div><div style=\"font-size:13.5px\"><b>b)</b> GOOGL je edina, ki je v 2023 izgubila vrednost.</div><div style=\"font-size:13.5px\"><b>c)</b> V povprečju so delnice zrasle za 8,75 %.</div><div style=\"font-size:13.5px\"><b>d)</b> Povprečni enostavni indeks je enak vrednostnemu indeksu portfelja.</div></div>","options":["a + b","a + b + c","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Povprečje indeksov = (120+120+90+105)/4 = 435/4 = <b>108,75</b> (a ✓). Le GOOGL ima i < 100 (b ✓). 108,75 − 100 = <b>+8,75 %</b> (c ✓). d ✗: vrednostni indeks tehta s količinami/vrednostmi posameznih delnic — enak bi bil le, če bi imel v vsako vloženo enako; tega tu ne vemo. → <b>a + b + c</b>."},{"q":"Naloga 4 · Deflacioniranje — realna vrednost S&P 500","hint":"Realna vrednost = (nominalna / indeks cen) × 100. Bazni indeks: Iₜ/₀ = (yₜ/y₀)×100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Podana je vrednost S&P 500 in CPI (osnova 2020 = 100). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Leto</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">S&P 500 (nom.)</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">CPI</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">S&P 500 (realno)</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2020</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.756</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.756</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2021</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.766</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">107,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.454</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2022</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.840</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">117,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3.282</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">2023</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">4.769</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">122,0</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">?</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Realna vrednost 2023 (po cenah 2020) ≈ 3.909.</div><div style=\"font-size:13.5px\"><b>b)</b> S&P 500 je 2022 nominalno padel glede na 2021.</div><div style=\"font-size:13.5px\"><b>c)</b> S&P 500 je 2023 realno presegel raven iz 2021.</div><div style=\"font-size:13.5px\"><b>d)</b> Bazni indeks nominalne vrednosti 2023 (2020 = 100) ≈ 127,0.</div></div>","options":["a + b","a + c","b + c + d","a + b + d","Pravilna rešitev ni navedena"],"correct":3,"htmlExpl":true,"explanation":"Realno 2023 = 4.769/122×100 = <b>3.909</b> (a ✓). Nominalno 3.840 < 4.766 → padec (b ✓). Realno: 3.909 (2023) < 4.454 (2021) → <b>ni</b> presegel (c ✗). Bazni indeks 4.769/3.756×100 = <b>126,97 ≈ 127</b> (d ✓). → <b>a + b + d</b>."},{"q":"Naloga 5 · Laspeyresov in Paaschejev indeks — futures","hint":"Σ(q₀p₀)=bazna vrednost. Σ(q₁p₀)=tek. količine × bazne cene. Σ(q₀p₁)=bazne količine × tek. cene. Σ(q₁p₁)=tek. vrednost. IᴾL=Σ(q₀p₁)/Σ(q₀p₀)×100; IQL=Σ(q₁p₀)/Σ(q₀p₀)×100; IᴾP=Σ(q₁p₁)/Σ(q₁p₀)×100; IV=Σ(q₁p₁)/Σ(q₀p₀)×100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Brokerska hiša je aprila (0) in maja (1) 2023 sklenila futures pogodbe. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Pogodba</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₁</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">NQ mini</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">50</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">20,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">60</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">22,00</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">ES mini</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">10,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">80</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">12,00</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Laspeyresov indeks cen IᴾL = 115.</div><div style=\"font-size:13.5px\"><b>b)</b> Laspeyresov indeks količin IQL = 100.</div><div style=\"font-size:13.5px\"><b>c)</b> Paaschejev indeks cen IᴾP = 114.</div><div style=\"font-size:13.5px\"><b>d)</b> Indeks vrednosti IV = 120.</div></div>","options":["a + b","a + b + c","a + b + c + d","a + c","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Σ(q₀p₀)=1000+1000=<b>2000</b>; Σ(q₀p₁)=1100+1200=<b>2300</b>; Σ(q₁p₀)=1200+800=<b>2000</b>; Σ(q₁p₁)=1320+960=<b>2280</b>. IᴾL=2300/2000×100=<b>115</b> (a ✓). IQL=2000/2000×100=<b>100</b> (b ✓). IᴾP=2280/2000×100=<b>114</b> (c ✓). IV=2280/2000×100=<b>114</b>, ne 120 (d ✗). → <b>a + b + c</b>."},{"q":"Naloga 6 · Skupinski indeksi — investicijski skladi","hint":"Izračunaj vse štiri vsote Σ(q₀p₀), Σ(q₁p₀), Σ(q₀p₁), Σ(q₁p₁), nato vstavi v formule (kot pri Nalogi 5).","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Podjetje prodaja dve vrsti skladov (bazno jan 2023, tekoče jul 2023). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Sklad</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₀</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">q₁</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">p₁</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">ETF skladi</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">30,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">250</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">33,00</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Obvezniški</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">300</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">20,00</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">200</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">22,00</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Laspeyresov indeks cen IᴾL = 110.</div><div style=\"font-size:13.5px\"><b>b)</b> Laspeyresov indeks količin IQL ≈ 95,8.</div><div style=\"font-size:13.5px\"><b>c)</b> Paaschejev indeks cen je večji (IᴾP > IᴾL).</div><div style=\"font-size:13.5px\"><b>d)</b> Skupna vrednost prodaje se je zmanjšala (IV < 100).</div></div>","options":["a","a + b","a + b + c","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"Σ(q₀p₀)=6000+6000=<b>12000</b>; Σ(q₀p₁)=6600+6600=<b>13200</b>; Σ(q₁p₀)=7500+4000=<b>11500</b>; Σ(q₁p₁)=8250+4400=<b>12650</b>. IᴾL=13200/12000×100=<b>110</b> (a ✓). IQL=11500/12000×100=<b>95,8</b> (b ✓). IᴾP=12650/11500×100=<b>110</b> → ni večji od IᴾL (c ✗). IV=12650/12000×100=<b>105,4</b> > 100 → vrednost zrasla (d ✗). → <b>a + b</b>."},{"q":"Naloga 7 · Fisherjev indeks in strukturni premiki — futures","hint":"IF = √(IᴾL × IᴾP). Relacija: IV = IᴾP × IQL/100 = IᴾL × IQP/100 (IQP = Paaschejev indeks količin). IᴾL > IᴾP → strukturni premiki zavrli rast cen.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Za par futures pogodb (NQ + ES) so že izračunani naslednji skupinski indeksi. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Skupinski indeks</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, cene (IᴾL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">115</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, količine (IQL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">100</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Paasche, cene (IᴾP)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">114</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Vrednostni (IV)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">114</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Fisherjev indeks cen ≈ 114,5.</div><div style=\"font-size:13.5px\"><b>b)</b> Ker je IᴾL > IᴾP (115 > 114), so strukturni premiki zavrli rast cen.</div><div style=\"font-size:13.5px\"><b>c)</b> Relacija IV = IᴾL × IQL/100 drži (115×100/100 = 115 = IV).</div><div style=\"font-size:13.5px\"><b>d)</b> Relacija IV = IᴾP × IQL/100 drži (114×100/100 = 114 = IV).</div></div>","options":["a + b","a + b + c","a + b + d","b + c + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"IF = √(115×114) = √13110 = <b>114,5</b> (a ✓). IᴾL > IᴾP → premiki zavrli rast cen (b ✓). c ✗: 115×100/100 = 115 ≠ IV (=114) — napačno sparjeno (IᴾL gre z IQP, ne IQL). d ✓: IᴾP×IQL/100 = 114×100/100 = 114 = IV. → <b>a + b + d</b>."},{"q":"Naloga 8 · Relacije med indeksi — skladi","hint":"IQP = Paaschejev indeks količin = Σ(q₁p₁)/Σ(q₀p₁)×100. Relacija: IV = IᴾL × IQP/100 = IᴾP × IQL/100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Za par investicijskih skladov so že izračunani naslednji indeksi. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Skupinski indeks</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, cene (IᴾL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">110</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Paasche, cene (IᴾP)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">110</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Laspeyres, količine (IQL)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">≈ 95,8</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Vrednostni (IV)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">≈ 105,4</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Fisherjev indeks cen = 110.</div><div style=\"font-size:13.5px\"><b>b)</b> Ker je IᴾL = IᴾP = 110, strukturni premiki niso vplivali na rast cen.</div><div style=\"font-size:13.5px\"><b>c)</b> Relacija IV = IᴾL × IQP/100 drži, pri čemer je IQP ≈ 95,8.</div><div style=\"font-size:13.5px\"><b>d)</b> Ker je IV (≈105,4) manjši od IᴾL (110), se je vrednost prodaje zmanjšala.</div></div>","options":["a + b","a + b + c","b + c + d","a + b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"IF = √(110×110) = <b>110</b> (a ✓). IᴾL = IᴾP → strukturnih premikov ni (b ✓). Z IQP ≈ 95,8 (Paaschejev količinski indeks): IV = IᴾL × IQP/100 = 110×95,8/100 = <b>105,4</b> ✓ (c ✓). d ✗: IV = 105,4 > 100 → vrednost je <b>zrasla</b> za 5,4 %; to, da je IV < IᴾL, ne pomeni padca. → <b>a + b + c</b>."}]},{"id":"st-t9-1","name":"Statistični sistem in klasifikacije (tema 9) (1/3)","questions":[{"type":"match","q":"Poveži klasifikacijo z njeno vsebino.","pairs":[{"term":"NACE / SKD","def":"Klasifikacija ekonomskih dejavnosti (EU / Slovenija)"},{"term":"ISIC","def":"Mednarodna klasifikacija dejavnosti (ZN), osnova za NACE"},{"term":"HS (Harmonized System)","def":"Razvrščanje blaga v zunanjetrgovinski statistiki in carini"},{"term":"PRODCOM","def":"Razvrščanje industrijskih proizvodov v EU"}],"explanation":"Ključno: NACE/SKD in ISIC razvrščajo dejavnosti (kdo kaj počne), HS in PRODCOM pa proizvode — HS blago za carino/zunanjo trgovino, PRODCOM industrijske proizvode v EU."},{"type":"grid","q":"Dopolni matriko klasifikacij: vstavi manjkajoče klasifikacije v prazne celice.","cols":["Dejavnosti","Proizvodi in storitve","Industrijski proizvodi"],"rows":[{"label":"OZN (svet)","cells":["ISIC","CPC","—"]},{"label":"Eurostat (EU)","cells":["NACE","CPA","PRODCOM"]},{"label":"SURS (SLO)","cells":["SKD","CPA","NIP"]}],"fixed":["0-2"],"explanation":"Dejavnosti: ISIC (OZN) → NACE (EU) → SKD (SLO). Proizvodi in storitve: CPC (OZN) → CPA (EU) → CPA (SLO). Industrijski proizvodi: na ravni OZN klasifikacija ne obstaja (—) → PRODCOM (EU) → NIP (SLO). Vrstice = predlagatelj (OZN/Eurostat/SURS), stolpci = predmet klasifikacije."},{"q":"Katera institucija je na vrhu Evropskega statističnega sistema (ESS)?","options":["SURS (Statistični urad RS)","Banka Slovenije","Eurostat (Evropski statistični urad)","AJPES","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Eurostat je Evropski statistični urad, ki koordinira Evropski statistični sistem (ESS). Na nacionalni ravni so glavni partnerji nacionalni statistični uradi — v Sloveniji je to SURS."},{"q":"Katera institucija je glavni izvajalec statističnih raziskovanj v Sloveniji?","options":["Banka Slovenije","AJPES (Agencija za javnopravne evidence)","NIJZ (Nacionalni inštitut za javno zdravje)","SURS (Statistični urad RS)","Pravilna rešitev ni navedena"],"correct":3,"explanation":"SURS (Statistični urad RS) je centralna institucija slovenskega statističnega sistema. Poleg SURS-a imajo pooblastila še Banka Slovenije, NIJZ, AJPES in drugi, a SURS je glavni koordinator."},{"q":"Katera klasifikacija razvršča ekonomske dejavnosti v EU?","options":["CPA (Classification of Products by Activity)","PRODCOM","HS (Harmonized System)","NACE (v Sloveniji SKD — Standardna klasifikacija dejavnosti)","Pravilna rešitev ni navedena"],"correct":3,"explanation":"NACE je evropska klasifikacija ekonomskih dejavnosti. V Sloveniji jo implementiramo kot SKD (Standardna klasifikacija dejavnosti). NACE temelji na mednarodni klasifikaciji ISIC (ZN)."},{"q":"Za kaj se uporablja klasifikacija HS (Harmonized System)?","options":["Razvrščanje dejavnosti podjetij v EU","Razvrščanje zaposlenih po izobrazbi","Razvrščanje blaga v zunanjetrgovinski statistiki in carinskih postopkih","Razvrščanje statističnih enot po geografski legi","Pravilna rešitev ni navedena"],"correct":2,"explanation":"HS (Harmonized System oz. Harmoniziran sistem) je mednarodna klasifikacija, ki se uporablja za razvrščanje blaga v zunanjetrgovinski statistiki in pri carinjenju. Je svetovna klasifikacija (ne samo EU)."},{"q":"Katera klasifikacija razvršča industrijske proizvode v EU?","options":["NACE","HS (Harmonized System)","PRODCOM","ISIC","Pravilna rešitev ni navedena"],"correct":2,"explanation":"PRODCOM (Production Communautaire) je klasifikacija, ki razvršča industrijske proizvode v EU. Temelji na klasifikaciji CPA in se ujema z HS na višjih ravneh."},{"q":"Kaj je lokalna enota?","options":["Enota, ki opravlja samo eno vrsto dejavnosti, ne glede na lokacijo","Geografsko locirana statistična enota — podjetje ali del podjetja na določenem naslovu/lokaciji","Pravna oz. institucionalna enota, ki opravlja ekonomsko dejavnost","Enota, registrirana pri lokalni upravi","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Lokalna enota = geografsko locirana statistična enota. Ker je opredeljena po lokaciji, ima isto podjetje toliko lokalnih enot, koliko ima različnih naslovov. Na enem naslovu sta lahko npr. dve dejavnosti — to je še vedno ena lokalna enota."},{"q":"Kaj je enota enovrstne dejavnosti (EED)?","options":["Enota na eni sami geografski lokaciji","Enota, ki opravlja samo eno vrsto dejavnosti, ne glede na lokacijo","Enota z enim samim lastnikom","Enota z manj kot 10 zaposlenimi","Pravilna rešitev ni navedena"],"correct":1,"explanation":"EED (enota enovrstne dejavnosti) = enota, ki opravlja samo eno vrsto dejavnosti, in to na eni lokaciji. Eno podjetje ima toliko EED, kolikor ima različnih kombinacij dejavnost + lokacija."},{"q":"Kako se določa glavna dejavnost podjetja?","options":["Po številu zaposlenih v posamezni dejavnosti","Po prihodkih od prodaje v posamezni dejavnosti","Po dodani vrednosti, ki jo ustvari posamezna dejavnost","Po geografski razpršenosti posameznih dejavnosti","Pravilna rešitev ni navedena"],"correct":0,"explanation":"Po ključu tega predmeta se glavna dejavnost določi po dejavnosti z največ zaposlenimi; pri več hierarhičnih ravneh po top-down metodi (seštevamo navzgor po ravneh)."},{"q":"Kaj so metapodatki?","options":["Surovi statistični podatki pred obdelavo in čiščenjem","Podatki o podatkih — opisujejo, kako so bili zbrani, obdelani in objavljeni","Agregiran povzetek statističnih analiz za javnost","Zaupni mikrostatistični podatki posameznih enot","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Metapodatki so 'podatki o podatkih'. Pojasnijo kontekst statističnih podatkov: kdo jih je zbral, kdaj, s kakšno metodologijo, kako so definirane spremenljivke, kakšna je kakovost... Brez metapodatkov podatki nimajo prave vrednosti."},{"q":"Katera je mednarodna klasifikacija dejavnosti (ZN), na kateri temelji NACE?","options":["CPA (Classification of Products by Activity)","CPC (Central Product Classification)","PRODCOM","ISIC (International Standard Industrial Classification)","Pravilna rešitev ni navedena"],"correct":3,"explanation":"ISIC (International Standard Industrial Classification of All Economic Activities) je klasifikacija ZN in mednarodna osnova za NACE. NACE je evropska prilagoditev ISIC."},{"q":"V katerem letu je bil v Sloveniji ustanovljen SURS?","options":["1944","1951","1985","1991","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"SURS (Statistični urad Republike Slovenije) je bil ustanovljen leta 1991 ob osamosvojitvi Slovenije."},{"q":"V katerem letu je Slovenija vstopila v EU in se vključila v ESS?","options":["1995","1999","2002","2004","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Slovenija je leta 2004 vstopila v EU in se hkrati vključila v Evropski statistični sistem (ESS)."},{"q":"Katera ustanova je Statistični urad Avstrije, ki je bil vzpostavljen leta 1863?","options":["Statistični urad Kraljevine Jugoslavije","Avstrijski centralni statistični urad","Zvezni zavod za statistiko Avstro-Ogrske","Eurostat predhodnik za Habsburžane","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Leta 1863 je bil vzpostavljen Avstrijski centralni statistični urad, ki je pokrival statistično dejavnost na območju današnje Slovenije."},{"q":"Katera od navedenih je vir SEKUNDARNIH podatkov?","options":["Osebni intervju s strankami","Opazovalna študija v prodajalni","Eksperiment v laboratoriju","Statistična baza podatkov Eurostata","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Podatkovne baze (kot je Eurostatova) so tipičen vir sekundarnih podatkov — zbral jih je nekdo drug za drugačen namen."},{"q":"Podjetje je v statistiki opredeljeno kot:","options":["Vsaka geografska lokacija, kjer poteka dejavnost","Najmanjša organizacijska enota s statusom pravne osebe","Skupina enot z enako šifro dejavnosti","Del podjetja na posamezni lokaciji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Podjetje je najmanjša organizacijska enota s statusom pravne osebe."},{"q":"Lokalna enota je statistična enota, ki je:","options":["Opredeljena glede na šifro dejavnosti","Geografsko opredeljena, z vsaj 1 zaposlenim","Opredeljena po pravnem statusu podjetja","Določena s finančno odvisnostjo od matičnega podjetja","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Lokalna enota je geografsko opredeljena enota, ne glede na pravni status ali vrsto dejavnosti, z vsaj eno zaposleno osebo."},{"q":"Institucionalna enota je opredeljena kot:","options":["Geografsko določena enota z eno šifro dejavnosti","Osnovni ekonomski center odločanja","Del podjetja, ki opravlja homogeno dejavnost","Organizacijska enota brez lastne pravne osebnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Institucionalna enota je osnovni ekonomski center odločanja."},{"q":"Enota enovrstne dejavnosti je podjetje ali del podjetja, ki:","options":["Deluje na točno eni geografski lokaciji","Na isti ali različnih lokacijah opravlja enovrstno dejavnost","Ima status samostojne pravne osebe","Zaposluje manj kot 50 delavcev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Enota enovrstne dejavnosti je podjetje ali del podjetja, ki na isti ali različnih lokacijah opravlja enovrstno dejavnost."}]},{"id":"st-t9-2","name":"Statistični sistem in klasifikacije (tema 9) (2/3)","questions":[{"q":"Skupina podjetij je v statistiki opredeljena kot:","options":["Podjetje z več kot eno lokacijo","Združenje podjetij na pravni ali finančni osnovi","Del podjetja s homogeno dejavnostjo","Enota, ki izpolnjuje pogoje lokalne enote","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Skupina podjetij je združenje podjetij na pravni ali finančni osnovi, ki lahko ima več centrov odločanja."},{"q":"Registri so:","options":["Tiskane publikacije z letnimi statističnimi podatki","Urejene zbirke z osnovnimi identifikacijskimi podatki o enotah","Vzorčne ankete, ki jih izvaja SURS vsako leto","Klasifikacijske sheme za razvrščanje dejavnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Registri so urejene, praviloma računalniško podprte zbirke, ki vsebujejo osnovne identifikacijske podatke o vseh enotah preučevanega pojava."},{"q":"NACE je:","options":["Mednarodna klasifikacija poklicev","Standardna klasifikacija dejavnosti na področju EU","Slovenska klasifikacija proizvodov","Nomenklatura industrijskih proizvodov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"NACE je standardna klasifikacija ekonomskih dejavnosti, ki se uporablja na področju EU."},{"q":"ISIC je:","options":["Standardna klasifikacija dejavnosti EU","Mednarodna standardna klasifikacija dejavnosti OZN","Nomenklatura industrijskih proizvodov","Klasifikacija statusa v zaposlitvi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"ISIC (International Standard Industrial Classification) je mednarodna standardna klasifikacija dejavnosti, ki jo je razvila OZN."},{"q":"ISCO je klasifikacija:","options":["Dejavnosti na ravni OZN","Poklicev na mednarodni ravni","Statusa v zaposlitvi","Izobrazbe in usposobljenosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"ISCO (International Standard Classification of Occupations) je mednarodna klasifikacija poklicev."},{"q":"CPA je klasifikacija:","options":["Poklicev na ravni EU","Statusa v zaposlitvi","Izobrazbe na ravni OZN","Proizvodov po dejavnosti na ravni EU","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"CPA je klasifikacija proizvodov po dejavnosti (Classification of Products by Activity) na ravni EU."},{"q":"ISCED je klasifikacija:","options":["Po izobrazbi (mednarodna standardna)","Dejavnosti na ravni OZN","Poklicev v EU","Statusa v zaposlitvi","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"ISCED (International Standard Classification of Education) je mednarodna standardna klasifikacija po izobrazbi."},{"q":"Eurostat je:","options":["Ministrstvo za finance EU","Evropski statistični urad","Agencija EU za trg dela","Centralna banka EU","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Eurostat je Evropski statistični urad — osrednja institucija Evropskega statističnega sistema."},{"q":"Katere države so poleg članic EU vključene v ESS?","options":["ZDA, Kanada in Japonska","Norveška, Islandija in Liechtenstein","Švica, Turčija in Albanija","Rusija, Belorusija in Ukrajiina","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"V ESS so poleg statistični uradov članic EU vključeni tudi statistični uradi Norveške, Islandije in Liechtensteina."},{"q":"Mikro statistični sistemi so:","options":["Samostojni in od podjetja neodvisni sistemi","Del poslovnih informacijskih sistemov","Istovetni z Evropskim statističnim sistemom","Registri, ki jih vodi SURS","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Mikro statistični sistemi so del poslovnih informacijskih sistemov podjetij."},{"q":"Enostavna statistična enota je primer:","options":["Podjetja (združba oseb)","Gospodinjstva (več oseb skupaj)","Posamezne osebe (prebivalec)","Skupine podjetij","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Enostavna statistična enota je npr. oseba (prebivalec), sestavljene pa so npr. gospodinjstvo ali podjetje."},{"q":"Načelo enoličnosti pri klasifikacijah zahteva, da:","options":["Vse enote uvrstimo v vsaj eno skupino","Vsako enoto uvrstimo v natanko eno skupino","Skupin je vedno vsaj 5","Vsebinsko sorodne enote uvrstimo skupaj","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Načelo enoličnosti zahteva nedvoumno razvrščanje — vsako enoto uvrstimo v natanko eno skupino."},{"q":"Načelo polnoštevilčnosti pri klasifikacijah zahteva, da:","options":["Vsako enoto uvrstimo v eno skupino","Skupin je vedno sodo število","Vse vrednosti najdejo svojo skupino","Skupin ne sme biti več kot 10","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Načelo polnoštevilčnosti (celovitosti) zahteva, da so vse vrednosti zajete — za vsako vrednost obstaja ustrezna skupina."},{"q":"V čem se nomenklatura razlikuje od klasifikacije?","options":["Nomenklatura zajema le opisne spremenljivke, klasifikacija le številske","Nomenklatura ne zagotavlja popolnosti razvrščanja, ker vsebuje le eksplicitno navedene enote","Klasifikacija je mednarodna, nomenklatura pa le nacionalna","Nomenklatura se uporablja le za razvrščanje poklicev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Nomenklatura je spisek eksplicitno določenih enot. Tiste, ki niso navedene, ne morejo biti uvrščene — ne zagotavlja popolnosti razvrščanja."},{"q":"Katera trditev o SKD in NACE je pravilna?","options":["SKD in NACE sta enaki do ravni skupin, SKD ima dodaten nivo — podrazrede","SKD in NACE sta do ravni razredov praktično identični; SKD ima dodatno raven podrazredov","NACE se v Sloveniji ne uporablja, nadomešča jo SKD","SKD je nastala neodvisno od NACE","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"SKD in NACE sta do ravni razredov praktično identični. SKD pa pozna dodatno raven — podrazrede, ki je NACE nima."},{"q":"Harmonizacija statističnih klasifikacij se je v Evropi začela:","options":["Na področju klasifikacije poklicev v 50. letih","Na področju zunanje trgovine v 70. letih","Na področju demografskih kazalcev v 80. letih","Na področju socialnih transferjev v 90. letih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Proces harmonizacije statističnih klasifikacij se je v Evropi pričel v 70. letih prejšnjega stoletja na področju zunanje trgovine."},{"q":"Katera trditev o kakovostnih standardih ESS o točnosti ocen je pravilna?","options":["Točnost meri hitrost objave podatkov","Točnost je skladnost med oceno in pravo vrednostjo za celotno populacijo","Točnost se nanaša na enostavnost dostopa do podatkov","Točnost opisuje primerljivost med različnimi državami","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Točnost ocen v ESS je opredeljena kot skladnost med oceno, dobljeno po statistični obdelavi, in pravo, a neznano vrednostjo za celotno populacijo."},{"q":"Načelo primerljivosti v ESS se nanaša na:","options":["Hitrost objave statističnih podatkov","Enostavnost dostopa do podatkov za javnost","Časovno in geografsko primerljivost med različnimi področji statistike","Strokovno neodvisnost statistov pri zbiranju podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Načelo primerljivosti v ESS se nanaša na časovno in geografsko primerljivost med različnimi področji statistike."},{"q":"Katera klasifikacija se v EU uporablja za razvrščanje po statusu v zaposlitvi?","options":["ISCO","ISCED","NACE","ICSE","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"ICSE (International Classification of Status in Employment) je klasifikacija statusa oz. položaja v zaposlitvi."},{"q":"Realna statistična enota se pojavlja v:","options":["Samo v razmičnih (intervalnih) statističnih množicah","Samo v trenutnih (momentnih) statističnih množicah","Sestavljata obe vrsti statističnih množic","Noben od odgovorov ni pravilen — realne enote so osebe, živali, stvari","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Realne enote (osebe, živali, stvari, pravne tvorbe) sestavljajo trenutne (momentne) statistične množice oz. populacije."}]},{"id":"st-t9-3","name":"Statistični sistem in klasifikacije (tema 9) (3/3)","questions":[{"q":"Nerealna statistična enota se pojavlja v:","options":["Trenutnih (momentnih) statističnih množicah","Razmičnih (intervalnih) statističnih množicah","Vedno v sestavljenih populacijah","Samo v vzorčnih populacijah","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Nerealne enote (rojstvo, nesreča, poroka, uvoz…) sestavljajo razmične (intervalne) statistične množice oz. populacije."},{"q":"Katera razsežnost kakovosti ESS kaže, v kolikšni meri statistični podatki zadovoljujejo potrebe uporabnikov?","options":["Točnost ocen","Pravočasnost objave","Ustreznost statističnih konceptov","Dostopnost in jasnost","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Ustreznost statističnih konceptov kaže, v kolikšni meri statistični podatki zadovoljujejo potrebe svojih uporabnikov."},{"q":"Katera razsežnost kakovosti ESS se nanaša na možnost preprostega in prijaznega dostopa do informacij?","options":["Točnost ocen","Primerljivost","Pravočasnost in točnost objave","Dostopnost in jasnost","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Dostopnost in jasnost poudarja možnost preprostega in uporabniku prijaznega dostopa do informacij v primerni obliki."},{"q":"Skladen statistični sistem po standardih ESS pomeni, da:","options":["Podatki so vedno objavljeni v istem časovnem roku","Podatke je mogoče na različne načine združevati za kompleksnejše rezultate","Podatki so zbrani z isto metodologijo v vseh državah EU","Podatki so dostopni vsem brez omejitev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Skladnost pomeni, da je podatke mogoče na različne načine združevati, zato da dobimo kompleksnejše rezultate."},{"q":"Koliko enot določimo podjetju Galeb, ki ima poslovalnice na treh lokacijah z različnimi dejavnostmi?","options":["Enako število lokalnih enot kot je dejavnosti","Enako število lokalnih enot kot je lokacij","Enako število enot enovrstne dejavnosti kot je lokacij","Vedno samo eno enoto enovrstne dejavnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Podjetju določimo toliko lokalnih enot, kot ima različnih lokacij za izvajanje dejavnosti."},{"q":"Pri podjetju Galeb je napačno določeno število enot pri kateri vrsti enote?","options":["Podjetje – 1 enota","Lokalne enote – 3 enote","Enote enovrstne dejavnosti (EED) – 3 enote","Lokalne enote enovrstne dejavnosti (LEVED) – 9 enot","Noben od navedenih odgovorov ni pravilen"],"correct":3,"explanation":"Pravilno: 1 podjetje, 3 lokalne enote (3 lokacije), 3 EED (3 različne šifre dejavnosti), <b>4 LEVED</b>. LEVED <b>ni</b> produkt lokacij × šifer (3×3 = 9), ampak število <b>dejansko obstoječih</b> kombinacij lokacija–šifra: Brnik–62.10, Lesce–62.20, Portorož–62.20, Portorož–63.30 = 4. Trditev »LEVED = 9« je torej napačna.","given":"<div style=\"margin-bottom:6px\"><b>Podjetje Galeb</b> posluje na treh lokacijah:</div><table style=\"border-collapse:collapse;font-size:13px\"><tr><th style=\"border:1px solid var(--line);padding:4px 10px;background:var(--paper2);text-align:left\">Lokacija</th><th style=\"border:1px solid var(--line);padding:4px 10px;background:var(--paper2)\">Šifra(-e) dejavnosti</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Brnik</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.10</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Lesce</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.20</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Portorož</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.20 in 63.30</td></tr></table>","htmlExpl":true},{"q":"Podjetje Galeb ima poslovalnice na Brniku (62.10), v Lescah (62.20) in v Portorožu (62.20 in 63.30). Koliko lokalnih enot enovrstne dejavnosti (LEVED) mu določimo?","options":["3","4","5","2","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"LEVED je vsaka kombinacija lokacija–šifra dejavnosti: Brnik 62.10, Lesce 62.20, Portorož 62.20, Portorož 63.30 = 4 LEVED."},{"q":"Skupno število vseh statističnih enot podjetja Galeb (podjetje + lokalne enote + EED + LEVED) je:","options":["9","10","11","12","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"1 podjetje + 3 lokalne enote (3 lokacije) + 3 EED (3 različne šifre: 62.10, 62.20, 63.30) + 4 LEVED (Brnik–62.10, Lesce–62.20, Portorož–62.20, Portorož–63.30) = <b>11 enot</b>.","given":"<div style=\"margin-bottom:6px\"><b>Podjetje Galeb</b> posluje na treh lokacijah:</div><table style=\"border-collapse:collapse;font-size:13px\"><tr><th style=\"border:1px solid var(--line);padding:4px 10px;background:var(--paper2);text-align:left\">Lokacija</th><th style=\"border:1px solid var(--line);padding:4px 10px;background:var(--paper2)\">Šifra(-e) dejavnosti</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Brnik</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.10</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Lesce</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.20</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 10px\">Portorož</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">62.20 in 63.30</td></tr></table>","htmlExpl":true},{"q":"Katera trditev o top-down metodi razvrščanja dejavnosti je pravilna?","options":["Začnemo z najnižjo ravnijo klasifikacije in se pomikamo navzgor","Začnemo z najvišjo ravnijo klasifikacije in se spuščamo navzdol","Metoda velja izključno za razvrščanje poklicev","Metoda se uporablja le v administrativnih registrih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pri top-down metodi začnemo z določitvijo šifre na najvišji ravni klasifikacije in se nato spuščamo navzdol do natančnejše šifre."},{"q":"Podjetje ima 32 zaposlenih v razredu 52.11, 20 v razredu 52.21 in 23 v razredu 52.25. Katera je glavna dejavnost?","options":["52.21 — sadje in zelenjava","52.25 — pijače","52.11 — nespecializirane prodajalne z živili","Dejavnost ni določljiva brez prihodkovnih podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Top-down metoda gre po ravneh hierarhije navzdol in NE izbere preprosto razreda z največ zaposlenimi. Najprej skupina: 52.1 (vsebuje 52.11) ima 32, skupina 52.2 (vsebuje 52.21 in 52.25) ima 20+23=43 → zmaga skupina 52.2. Znotraj 52.2 nato razred: 52.21=20 vs 52.25=23 → glavna dejavnost je 52.25 (pijače). Past je naivni sklep, da je glavna dejavnost kar razred z največ zaposlenimi (52.11)."},{"q":"Kateri od naslednjih izrazov opisuje razliko med klasifikacijo in nomenklaturo?","options":["Klasifikacija omogoča razvrščanje vseh vrednosti, nomenklatura pa le eksplicitno navedenih","Nomenklatura je mednarodni sistem, klasifikacija pa lokalni","Klasifikacija velja za dejavnosti, nomenklatura pa za osebe","Nomenklatura je dinamična, klasifikacija pa statična","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Klasifikacija zagotavlja celovitost (vsako enoto je mogoče razvrstiti). Nomenklatura vsebuje le eksplicitno navedene enote — enota, ki ni navedena, ne more biti uvrščena."},{"q":"Kateri od navedenih je neposredni cilj Eurostata?","options":["Statistična raziskovanja v državah EU izvajati neposredno","Zagotavljati statist. informacije za oblikovanje skupne politike EU in povezovati nac. statistične sisteme","Prevzemati naloge nacionalnih statističnih uradov","Izdajati pravno zavezujoče statistične standarde z zakonodajno močjo","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Eurostat zagotavlja statistične informacije za oblikovanje politike EU, z uporabo skupnih standardov povezuje nacionalne sisteme in zagotavlja dostop do podatkov."},{"q":"Katero načelo klasifikacij zahteva, da se skupini nižjega reda združujejo v skupino višjega reda?","options":["Načelo enoličnosti","Načelo polnoštevilčnosti","Načelo hierarhične združljivosti","Načelo logičnega poimenovanja","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Hierarhično načelo (združevanje skupin nižjega reda v višjega) je temeljno načelo klasifikacij: npr. razredi se združijo v skupino, te v oddelek, ti v področje."},{"q":"Katera kombinacija sestavlja skupno število statističnih enot pri podjetju na eni lokaciji z dvema dejavnostma?","options":["1 podjetje + 1 lokalna enota + 2 EED + 2 LEVED = 6 enot","1 podjetje + 1 lokalna enota + 2 EED + 2 LEVED = 5 enot","1 podjetje + 2 lokalni enoti + 2 EED + 2 LEVED = 7 enot","1 podjetje + 1 lokalna enota + 1 EED + 2 LEVED = 5 enot","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Na eni lokaciji z dvema dejavnostma: 1 podjetje + 1 lokalna enota + 2 EED + 2 LEVED = 6 enot skupaj."},{"q":"Katero od načel deluje SURS pri izvajanju uradne statistike?","options":["Pridobitnost, preglednost in tržnost","Nevtralnost, objektivnost in statistična zaupnost","Decentraliziranost, regionalnost in tržna usmerjenost","Ekskluzivnost, zaupnost in plačljivost dostopa","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Načela delovanja SURS: nevtralnost, objektivnost, strokovna neodvisnost, racionalnost, statistična zaupnost in preglednost."},{"q":"Katere statistične enote določimo podjetju z dvema dejavnostma na dveh različnih lokacijah?","options":["2 lokalni enoti, 2 EED, 2 LEVED","2 lokalni enoti, 2 EED, 4 LEVED","2 lokalni enoti, 4 EED, 4 LEVED","4 lokalne enote, 2 EED, 4 LEVED","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Lokalne enote = lokacije = 2. EED = dejavnosti = 2. LEVED = kombinacije lokacija×dejavnost: 2×2 = 4. Skupaj: 2 LE + 2 EED + 4 LEVED."},{"q":"Kateri od naslednjih opisuje pravilno ureditev ravni NACE klasifikacije od najširše do najožje?","options":["Razred → skupina → oddelek → področje","Področje → oddelek → skupina → razred","Oddelek → področje → razred → skupina","Skupina → oddelek → razred → področje","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"NACE je hierarhično urejena: področje (1 črkovna oznaka) → oddelek (2 cifri) → skupina (3 cifre) → razred (4 cifre)."},{"q":"Katera od navedenih razlag o hierarhičnem načelu klasifikacij je pravilna?","options":["Vsaka enota se uvrsti v natanko eno skupino","Skupini nižjega reda se brez preostanka združita v skupino višjega reda","Klasifikacije imajo vedno točno 4 ravni","Skupin nižjega reda ne smemo združevati","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Hierarhično načelo zahteva, da se skupini nižjega reda brez preostanka združujeta v skupino višjega reda (npr. razredi → skupina → oddelek → področje)."},{"q":"Kateri od navedenih je tipičen primer administrativnega registra?","options":["Vzorčna anketa o porabi časa gospodinjstev","Popis stanovanskega fonda","Sodni register poslovnih subjektov","Evidenca SURS o izvedenih statističnih raziskovanjih","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Sodni register je administrativni register, ki temelji na izvirnih podatkih iz formalnih (pravnih) dokumentov."}]},{"id":"st-t10","name":"Statistika prebivalstva (tema 10)","questions":[{"type":"match","q":"Poveži pojem statistike prebivalstva z opredelitvijo.","pairs":[{"term":"Naravni prirastek","def":"Živorojeni − umrli"},{"term":"Selitveni saldo","def":"Priseljeni − odseljeni"},{"term":"Skupni prirastek","def":"Naravni prirastek + selitveni saldo"},{"term":"Indeks staranja","def":"Razmerje starih (65+) in mladih (0–14), × 100"}],"explanation":"Skupni prirastek združuje naravno in selitveno gibanje."},{"q":"Kako izračunamo skupni prirastek (SP) prebivalstva?","options":["SP = živorojeni − umrli","SP = priseljeni − odseljeni","SP = naravni prirastek + selitveni saldo","SP = (živorojeni + odseljeni) − (umrli + priseljeni)","Pravilna rešitev ni navedena"],"correct":2,"explanation":"SP = NP + SS, kjer je NP = naravni prirastek = živorojeni − umrli in SS = selitveni saldo = priseljeni − odseljeni. Skupni prirastek vključuje oba dejavnika spremembe: naravno in selitveno gibanje."},{"q":"Kaj je v imenovalcu splošne stopnje natalitete (SSN)?","options":["Število žensk v rodni dobi (15–49 let)","Število živorojenih otrok v istem letu","Srednje število VSEH prebivalcev (P̄)","Skupno število gospodinjstev","Pravilna rešitev ni navedena"],"correct":2,"explanation":"SSN = (živorojeni / srednje število VSEH prebivalcev) × 1000. V imenovalcu je P̄ — srednje število vseh prebivalcev, ne samo žensk. Ko je v imenovalcu samo ženske v rodni dobi (15–49 let), govorimo o SPLOŠNI STOPNJI RODNOSTI (SSR)."},{"q":"Kaj pomeni negativen naravni prirastek (NP < 0)?","options":["Priseljenih je manj kot odseljenih","Umrlo je več oseb, kot se jih je rodilo","Skupni prirastek je negativen","Število prebivalcev se je nujno zmanjšalo","Pravilna rešitev ni navedena"],"correct":1,"explanation":"NP = živorojeni − umrli < 0 pomeni, da je umrlo VEČ, kot se je rodilo. Pozor: negativen NP ne pomeni nujno, da se je skupno število preb. zmanjšalo — selitveni saldo je lahko dovolj visok, da skupni prirastek ostane pozitiven."},{"q":"Katera dva dejavnika vplivata na skupno spremembo števila prebivalcev?","options":["Naravno gibanje in selitveno gibanje","Rodnost in smrtnost","Priseljevanje in odseljevanje","Ekonomski in socialni dejavniki","Pravilna rešitev ni navedena"],"correct":0,"explanation":"Skupni prirastek = naravno gibanje (rojstev − smrtnost) + selitveno gibanje (priseljeni − odseljeni). To sta dve skupini dejavnikov. Rodnost in smrtnost sta del naravnega, priseljevanje in odseljevanje pa del selitvenega gibanja."},{"q":"William Gosset je statistične metode razvijal pri:","options":["Popisu prebivalstva Rimskega cesarstva","Analizi bojiščnih žrtev v Krimski vojni","Preverjanju kakovosti piva pri Guinnessovi pivovarni","Izračunu indeksa cen življenjskih potrebščin","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Gosset je pri Guinnessovi pivovarni statistično preverjal kakovost piva in s tem prispeval k razvoju statističnih metod za majhne vzorce."},{"q":"Kdaj je bil v Sloveniji opravljen prvi popis prebivalstva?","options":["1754","1863","1918","1944","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Prvi popis prebivalstva na ozemlju današnje Slovenije je bil opravljen leta 1754."},{"q":"CRP je kratica za:","options":["Centralni register podjetij","Centralni register prebivalstva","Centralni register poklicev","Centralni register podatkov","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"CRP je Centralni register prebivalstva, ki vsebuje osnovne identifikacijske podatke o osebah s stalnim ali začasnim prebiv. v Sloveniji."},{"q":"SRDAP je kratica za:","options":["Statistični register delovno aktivnega prebivalstva","Skupni register davčnih plačnikov","Standardni register delovnih anketa","Statistični register delovnih akcij","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"SRDAP je Statistični register delovno aktivnega prebivalstva."},{"q":"N v demografskih formulah pomeni:","options":["Število umrlih v enem letu","Število živorojenih v enem letu","Število priseljenih v enem letu","Skupno število aktivnega prebivalstva","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"N v demografskih formulah označuje število živorojenih v enem letu."},{"q":"M v demografskih formulah pomeni:","options":["Število živorojenih v enem letu","Število priseljenih v enem letu","Število umrlih v enem letu","Skupno število stalnega prebivalstva","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"M v demografskih formulah označuje število umrlih v enem letu."},{"q":"Naravno gibanje prebivalstva zajema:","options":["Priselitve in odselitve","Rojstva in smrti","Zaposlitve in brezposelnost","Poroke in ločitve","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Naravno gibanje prebivalstva zajema rojstva (število živorojenih) in smrti (število umrlih)."},{"q":"Prostorsko (mehansko) gibanje prebivalstva zajema:","options":["Rojstva in smrti","Poroke in ločitve","Priselitve in odselitve","Zaposlitve in upokojevanja","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Prostorsko oz. mehansko gibanje prebivalstva zajema priselitve (I) in odselitve (E)."},{"q":"Aktivno prebivalstvo po klasifikaciji ILO sestavljajo:","options":["Vsi, starejši od 15 let","Zaposleni in brezposelni skupaj","Zaposleni, upokojenci in dijaki","Delovno aktivni in upokojenci","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Aktivno prebivalstvo po ILO sestavljata dve skupini: delovno aktivno prebivalstvo (zaposleni, samozaposleni, pomagajoči) in brezposelni."},{"q":"Delovno sposobno prebivalstvo je po definiciji ILO:","options":["Vsi stalno nastanjeni v državi","Prebivalstvo, starejše od 15 let","Vsi zaposleni s polnim delovnim časom","Osebe med 20. in 65. letom starosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Kot delovno sposobno prebivalstvo je upoštevano celotno prebivalstvo, ki je starejše od 15 let."},{"q":"Stopnja aktivnosti se izračuna kot:","options":["Brezposelni / aktivno prebivalstvo × 100","Aktivno prebiv. / delovno sposobno prebiv. × 100","Delovno aktivno prebiv. / skupno prebiv. × 100","Zaposleni / aktivno prebiv. × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja aktivnosti = aktivno prebivalstvo / delovno sposobno prebivalstvo × 100."},{"q":"Katera od trditev o pomagajočih družinskih članih je pravilna?","options":["Pomagajoči družinski člani so uvrščeni med brezposelne","Pomagajoči družinski člani so del delovno aktivnega prebivalstva","Pomagajoči družinski člani niso vključeni v aktivno prebiv.","Pomagajoči družinski člani so uvrščeni med neaktivno prebiv.","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Pomagajoči družinski člani so del delovno aktivnega prebivalstva — skupaj z zaposlenimi in samozaposlenimi."},{"q":"Splošna stopnja mortalitete (m) ima v imenovalcu:","options":["Število umrlih v enem letu","Srednje število žensk v rodni dobi","Srednje število celotnega prebivalstva (P30.6)","Število živorojenih v enem letu","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"m = M / P30.6 × 1000, kjer je P30.6 srednje število celotnega prebivalstva (stanje 30. junija)."},{"q":"Kolikšna je bila stopnja selitvenega prirastka v letu 2024?","options":["-1,3 ‰","2,8 ‰","5,4 ‰","9,1 ‰","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Stopnja selitvenega prirastka je bila 5,4 ‰ v letu 2024 (vir: SURS)."},{"q":"Katera formula pravilno izraža splošno stopnjo migracijskega prirastka?","options":["mg = (I − E) / P30.6 × 1000","mg = I / P30.6 × 1000","mg = E / P30.6 × 1000","mg = (I + E) / P30.6 × 1000","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Splošna stopnja migracijskega prirastka = (I − E) / P30.6 × 1000, kjer sta I priselitve in E odselitve."},{"q":"Kaj označuje P30.6 v demografskih formulah?","options":["Število živorojenih 30. junija","Srednje število celotnega prebivalstva (stanje 30. junija)","Projektirana populacija za 30 let naprej","Število žensk v rodni dobi na dan 30. junija","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"P30.6 je srednje število celotnega prebivalstva — stanje na dan 30. junija tekočega leta (sredina leta)."},{"q":"Kateri od navedenih registrov je konstruktiven?","options":["Register teritorialnih enot (RTE)","Statistični register delovno aktivnega prebiv. (SRDAP)","Sodni register poslovnih subjektov (poslovni register)","Centralni register prebivalstva (CRP)","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Sodni (poslovni) register je konstruktiven — z vpisom vanj poslovni subjekt pridobi pravno osebnost, ki je prej ni imel."},{"q":"Za izračun splošne stopnje priselitev je v imenovalcu:","options":["Število priseljenih (I)","Srednje število celotnega prebiv. (P30.6)","Število odseljenih (E)","Delovno aktivno prebiv.","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Splošna stopnja priselitev = I / P30.6 × 1000, imenovalec je torej srednje število celotnega prebivalstva."},{"q":"Katera od navedenih je pravilna formula za absolutni naravni prirastek?","options":["N + M","N − M","(N − M) / P30.6 × 1000","N / M × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Absolutni naravni prirastek = N − M (število živorojenih minus število umrlih). Relativna oblika (v ‰) pa je (N − M) / P30.6 × 1000."}]},{"id":"st-t11","name":"Stopnje in koeficienti prebivalstva (tema 11)","questions":[{"q":"Katera stopnja ima v imenovalcu ženske v rodni dobi (15–49 let)?","options":["Splošna stopnja natalitete (SSN)","Splošna stopnja rodnosti (SSR)","Splošna stopnja mortalitete (SSM)","Stopnja naravnega prirastka","Pravilna rešitev ni navedena"],"correct":1,"explanation":"SSR (splošna stopnja rodnosti) = živorojeni / ženske 15–49 × 1000. SSN (splošna stopnja natalitete) = živorojeni / VSI prebivalci × 1000. Ker je imenovalec SSR manjši, je SSR vedno višja od SSN."},{"q":"Kaj je v imenovalcu stopnje umrljivosti dojenčkov?","options":["Srednje število otrok, mlajših od 1 leta","Skupno število umrli dojenčkov v istem letu","Število živorojenih v istem letu","Srednje število vseh prebivalcev","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Stopnja umrljivosti dojenčkov = (umrli dojenčki / živorojeni) × 1000. V imenovalcu so ŽIVOROJENI (ne srednje število otrok). Pove, koliko dojenčkov (na 1000 živorojenih) umre pred prvim rojstnim dnem."},{"q":"Kaj meri koeficient maskulinitete ob rojstvu?","options":["Delež dečkov med vsemi živoremi, izražen v %","Število živorojenih dečkov na 1000 živorojenih deklic","Razmerje med moškimi in ženskami v celotni populaciji","Število dečkov na 1000 vseh živorojenih","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Koeficient maskulinitete = (živorojeni dečki / živorojene deklice) × 1000. Naravna vrednost je okrog 1050 — na 1000 deklic se rodi pribl. 1050 dečkov. Koeficient feminitete je obratno razmerje."},{"q":"Kaj meri skupni koeficient starostne odvisnosti?","options":["Delež neaktivnega prebivalstva (0–14 in 65+) v celotnem preb.","Število oseb 0–14 in 65+ na 100 oseb delovno aktivnega preb. (15–64)","Razmerje med starejšimi in mladimi v populaciji","Povprečna starost celotnega prebivalstva","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Skupni koeficient starostne odvisnosti = [(0–14 let) + (65+ let)] / (15–64 let) × 100. Pove, koliko 'vzdrževanih' oseb (mladi + stari) odpade na 100 delovno aktivnih. Višja vrednost = večje breme za delovno aktivne."},{"q":"Ženski rodni (fertilni) kontingent zajema ženske v starosti:","options":["18 do 45 let","15 do 49 let","16 do 44 let","20 do 50 let","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Ženski rodni (fertilni) kontingent zajema žensko prebivalstvo v starosti od 15 do 49 let in je osnova za preučevanje rodnosti."},{"q":"Indeks staranja je razmerje med:","options":["Osebami nad 65 let in skupnim številom prebiv.","Starimi (65+) in mladimi (do 15 let) × 100","Osebami 15–64 let in skupnim prebiv.","Umrlimi in živorojenimi × 100","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Indeks staranja = (osebe 65 let in več / osebe do 15 let) × 100. Kaže razmerje med starim in mladim delom populacije."},{"q":"Splošna stopnja natalitete (n) ima v imenovalcu:","options":["Srednje število žensk v rodni dobi","Srednje število celotnega prebivalstva (P30.6)","Število živorojenih v enem letu","Število umrlih v enem letu","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"n = N / P30.6 × 1000, kjer je P30.6 srednje število celotnega prebivalstva."},{"q":"Stopnja celotne rodnosti (Tf) se izračuna kot:","options":["f / 35","f × 35","n × 35","m × 35","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Tf = f × 35, ker predpostavljamo, da traja rodna doba ženske 35 let (od 15. do 49. leta)."},{"q":"Kolikšna je bila stopnja celotne rodnosti v Sloveniji v letu 2024?","options":["1,22","1,52","1,75","2,10","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja celotne rodnosti v letu 2024 je znašala 1,52 (vir: SURS)."},{"q":"Stopnja celotne rodnosti (Tf) je pri stopnji fertilnosti f = 0,050 enaka:","options":["0,050","1,250","1,750","0,143","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Tf = f × 35 = 0,050 × 35 = 1,750. (Opomba: f je tu splošna stopnja rodnosti v obliki koeficienta, ne v promilih.)"},{"q":"Katera od navedenih trditev o specifičnih stopnjah rodnosti (fx) je pravilna?","options":["Računamo jih, da ugotovimo vpliv starosti na rodnost","Računamo jih, da primerjamo rodnost med državami","Računamo jih iz skupnega števila umrlih in živorojenih","Računamo jih iz razmerja med selitvenim in naravnim prirastkom","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Specifične stopnje rodnosti fx računamo zato, da odkrijemo vpliv posebnih dejavnikov (predvsem starosti) na rodnost."},{"q":"Demografski prehod opisuje:","options":["Prehod iz podeželskega v urbano okolje","Prehod iz visoke natalitete in mortalitete k nizki nataliteti in mortaliteti","Prehod iz razmičnih v trenutne statistične množice","Prehod iz registriranih v anketne podatke","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Demografski prehod je prehod iz visoke stopnje natalitete in mortalitete v nizko stopnjo natalitete in mortalitete."},{"q":"Katera od navedenih trditev o specifičnih stopnjah umrljivosti (mx) je pravilna?","options":["Računamo jih le za žensko populacijo v rodni dobi","Računamo jih z ločenimi imenovalci za vsako starostno skupino","Enačba je ista kot za splošno stopnjo mortalitete, le brez množitelja 1000","Specifičnih stopenj umrljivosti ne merimo za dojenčke","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Specifične stopnje umrljivosti (mx) se računajo za vsako starostno skupino (x) posebej z ustreznim imenovalcem (srednje število oseb te starostne skupine)."},{"q":"Katera trditev o primerjavi stopnje rodnosti in stopnje fertilnosti je pravilna?","options":["Stopnja rodnosti in fertilnosti imata enaka imenovalca","Stopnja fertilnosti ima v imenovalcu le ženske v rodni dobi, stopnja rodnosti pa vso populacijo","Stopnja rodnosti (n) se izraža v %, stopnja fertilnosti (f) pa v ‰","Stopnji sta po definiciji enaki, razlika je le v poimenovanju","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Stopnja natalitete (n) ima v imenovalcu srednje število celotne populacije. Stopnja fertilnosti (f) ima v imenovalcu le srednje število žensk v rodni dobi (15–49 let)."},{"q":"Katera od navedenih trditev o starostnih kontingentih je pravilna?","options":["Delovno sposobno prebiv. zajema osebe od 18 do 65 let","Ženski rodni kontingent zajema ženske od 18 do 44 let","Delovno sposobno prebiv. zajema osebe, starejše od 15 let","Otroci do 14 let niso del nobenega starostnega kontingenta","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Delovno sposobno prebivalstvo po definiciji zajema vse osebe, ki so starejše od 15 let."}]},{"id":"st-t12b","name":"Analiza ekonomske aktivnosti (tema 12)","questions":[{"q":"Katera metoda napovedovanja predpostavlja konstantno absolutno rast?","options":["Geometrijska metoda (metoda povprečne letne stopnje rasti)","Eksponentna metoda","Metoda linearne ekstrapolacije (aritmetična metoda)","Logistična (S-krivulja) metoda","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Linearna ekstrapolacija: Pt = P0 + t × d, kjer je d konstanten absolutni prirastek. Geometrijska metoda: Pt = P0 × (1+r)^t predpostavlja konstantno STOPNJO rasti r. Obe sta preprosti matematični metodi s svojimi omejitvami."},{"q":"Pri pozitivni stopnji rasti (r > 0), katera metoda da višjo napoved za daljše obdobje?","options":["Linearna metoda vedno da višjo napoved od geometrijske","Geometrijska metoda vedno da višjo napoved od linearne","Obe metodi vedno data enako napoved","Katera da višjo napoved, je odvisno od podatkov","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Geometrijska metoda upošteva obrestno-obrestni efekt — rast se iz leta v leto obrestuje. Zato pri pozitivni stopnji rasti vedno da VIŠJO napoved od linearne za enake izhodiščne pogoje. Razlika je majhna za kratka obdobja, večja pa za daljša."},{"q":"Kaj je produktivnost dela, izražena v kosih?","options":["Čas, ki ga delavec porabi za izdelavo enega kosa","Število delavcev, ki so potrebni za en kos na dan","Število kosov, ki jih delavec izdela v določenem časovnem obdobju","Skupni strošek materiala na en kos","Pravilna rešitev ni navedena"],"correct":2,"explanation":"Produktivnost dela (v kosih) = število kosov / število delavcev v določenem časovnem obdobju. Npr. na dan: kosi / (delavci × delovni dnevi). Na uro: kosi / (delavci × dnevi × ur/dan)."},{"q":"Kaj je intenzivnost dela (čas na kos)?","options":["Isto kot produktivnost dela — sta sinonima","Obratna vrednost produktivnosti — čas, ki ga en delavec potrebuje za en kos","Skupni delovni čas vseh delavcev v mesecu","Število delavcev, potrebnih za eno enoto na uro","Pravilna rešitev ni navedena"],"correct":1,"explanation":"Intenzivnost dela = 1 / produktivnost dela (v kosih/uro) = čas na kos [ur/kos]. Npr. če delavec izdela 0,2 kosa/uro, je intenzivnost 1/0,2 = 5 ur/kos. Sta obratni vrednosti ena drugi."},{"q":"Opisna statistična analiza se ukvarja z:","options":["Posploševanjem rezultatov z vzorca na populacijo","Zbiranjem in analizo podatkov za populacijo kot celoto","Ocenjevanjem parametrov iz vzorčnih podatkov","Napovedovanjem vrednosti spremenljivk v prihodnosti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Opisna statistika zajema metode zbiranja, razvrščanja in prikazovanja podatkov ter opisovanje značilnosti celotne populacije."},{"q":"Katera trditev o Porterjevem modelu petih silnic je pravilna?","options":["Preučuje politično, ekonomsko, socialno in tehnološko okolje","Ocenjuje privlačnost panoge na osnovi rivalstva, substitutov, moči dobaviteljev in kupcev ter vstopnih ovir","Analizira prednosti, slabosti, priložnosti in nevarnosti podjetja","Meri stopnjo inflacije in rast BDP v posamezni panogi","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Porterjev model petih silnic ocenjuje privlačnost panoge prek: rivalstva med podjetji, substitutov, moči dobaviteljev, moči kupcev in vstopnih ovir."},{"q":"BDP je:","options":["Vrednost uvoženih dobrin in storitev v enem letu","Vrednost proizvodnje rezidenčnih poslovnih enot na ekon. ozemlju v enem letu","Skupna vrednost davkov in prispevkov v enem letu","Vrednost zasebne potrošnje gospodinjstev v enem letu","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"BDP je vrednost proizvodnje, ki jo rezidenčne poslovne enote ustvarijo na ekonomskem ozemlju določene države v obdobju enega leta."},{"q":"Inflacija je:","options":["Splošna rast plač v določenem obdobju","Splošna rast cen proizvodov in storitev","Splošno zmanjševanje brezposelnosti","Splošno zmanjševanje BDP v recesiji","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Inflacija je pojav splošne rasti cen proizvodov in storitev. V Sloveniji jo merimo z indeksom cen življenjskih potrebščin (ICŽP)."},{"q":"Totalna produktivnost meri:","options":["Razmerje med ustvarjeno proizvodnjo in porabljenim delom","Razmerje med ustvarjeno proizvodnjo in vsemi porabljenimi produkcijskimi faktorji","Razmerje med vrednostjo izvoza in skupno proizvodnjo","Razmerje med dodano vrednostjo in številom zaposlenih","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Totalna produktivnost je razmerje med količino ustvarjene proizvodnje v določenem obdobju in vsemi za to proizvodnjo porabljenimi produkcijskimi faktorji."},{"q":"Parcialna (delna) produktivnost dela meri:","options":["Razmerje med ustvarjeno proizvodnjo in vsemi produkcijskimi faktorji","Razmerje med ustvarjeno proizvodnjo in porabljenim delom","Razmerje med ustvarjeno proizvodnjo in porabljenimi surovinami","Razmerje med izvozom in skupno zaposlenostjo","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Parcialna produktivnost dela je razmerje med količino ustvarjene proizvodnje in za to porabljenim delom (potroškom dela)."},{"q":"Gostota prebivalstva se izračuna kot:","options":["Število prebiv. / površina km²","Površina km² / število prebiv.","Število prebiv. / BDP","Število prebiv. / površina ha × 100","Noben od navedenih odgovorov ni pravilen"],"correct":0,"explanation":"Gostota prebivalstva = število prebivalcev / površina (v km²)."},{"q":"Kolikšen je bil BDP na prebivalca v EUR v tekočih cenah v Sloveniji leta 2025?","options":["27.450 EUR","30.100 EUR","33.062 EUR","36.500 EUR","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"BDP na prebivalca v EUR v tekočih cenah je znašal 33.062 EUR v letu 2025 (vir: SURS)."},{"q":"BDP na prebivalca v standardih kupne moči (EU=100) je bil v Sloveniji leta 2025:","options":["78","86","91","103","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"BDP na prebivalca v SKM (EU=100) je znašal 91, torej pod povprečjem EU (vir: Eurostat)."},{"q":"Kolikšna je bila realna rast BDP v Q1 2026 glede na Q1 2025?","options":["1,9 %","3,0 %","3,1 %","4,9 %","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Realna rast BDP v Q1 2026/Q1 2025 je bila 3,0 % (vir: SURS). Vrednost 3,1 % je letna stopnja rasti cen."},{"q":"Kolikšna je bila letna stopnja rasti cen (april 2026 / april 2025)?","options":["1,9 %","2,4 %","3,1 %","4,0 %","Noben od navedenih odgovorov ni pravilen"],"correct":2,"explanation":"Letna stopnja rasti cen (april 2026/april 2025) je znašala 3,1 % (vir: SURS)."},{"q":"Linearno ekstrapolacijo izberemo, kadar predpostavljamo, da se bo spremenljivka:","options":["Gibala po enaki povprečni letni stopnji rasti kot v preteklem obdobju","Gibala z enakim povprečnim letnim absolutnim prirastkom kot v preteklem obdobju","Gibala po enaki geometrični vrsti kot v preteklem obdobju","Ustabilizirala na ravni zadnjega opazovanega podatka","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Linearna ekstrapolacija predpostavlja enakomerno absolutno rast — enak povprečni letni absolutni prirastek."},{"q":"Metoda povprečne letne stopnje rasti za oceno prihodnjega stanja predpostavlja:","options":["Enako absolutno rast v vsakem letu","Enako relativno (%) rast v vsakem letu","Logistično krivuljo rasti","Stagnacijo po obdobju rasti","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Metoda povprečne letne stopnje rasti predpostavlja geometrijsko (eksponentno) rast — enako relativno spremembo v vsakem letu."},{"q":"Kaj je merjenje obsega ustvarjene proizvodnje (Q) pri izračunu produktivnosti?","options":["Bruto prihodek od prodaje brez DDV","Neto dodana vrednost (vrednost brez vmesne porabe in obrabe osnovnih sredstev)","Skupni stroški dela in materiala","Bilančna vrednost osnovnih sredstev","Noben od navedenih odgovorov ni pravilen"],"correct":1,"explanation":"Obseg ustvarjene proizvodnje (Q) pri produktivnosti najpravilneje merimo z neto dodano vrednostjo: vrednost proizvodnje brez vmesne porabe in obrabe osnovnih sredstev."}]},{"id":"st-nal912","name":"Računske naloge · teme 9–12","calc":true,"questions":[{"q":"Naloga 9 · Standardne klasifikacije","hint":"NACE (EU)/SKD (SLO) = dejavnosti. ISIC (ZN) = osnova za NACE. CPA = proizvodi po dejavnosti. PRODCOM = industrijski proizvodi (EU). HS = blago za carinjenje.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Katere trditve o standardnih klasifikacijah so pravilne?</div><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Za razvrščanje podjetij po dejavnosti se v EU uporablja NACE (v SLO SKD).</div><div style=\"font-size:13.5px\"><b>b)</b> HS (Harmonized System) se uporablja za razvrščanje zaposlenih po dejavnosti.</div><div style=\"font-size:13.5px\"><b>c)</b> PRODCOM je klasifikacija industrijskih proizvodov v EU.</div><div style=\"font-size:13.5px\"><b>d)</b> ISIC je mednarodna klasifikacija dejavnosti (ZN), na kateri temelji NACE.</div></div>","options":["a + c","a + d","b + c","a + c + d","Pravilna rešitev ni navedena"],"correct":3,"htmlExpl":true,"explanation":"a ✓ NACE/SKD = dejavnosti. b ✗ HS je za <b>blago</b> (carina), ne zaposlene. c ✓ PRODCOM = industrijski proizvodi EU. d ✓ ISIC (ZN) je osnova za NACE. → <b>a + c + d</b>."},{"q":"Naloga 10 · Statistične enote — TradeX","hint":"Lokalna enota = enota na danem naslovu/lokaciji. EED = enota enovrstne (ene) dejavnosti. Podjetje = institucionalna enota. Glavna dejavnost = dejavnost z največ zaposlenimi (pri več hierarhičnih ravneh po top-down metodi).","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Brokerska hiša »TradeX« ima naslednje enote. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Lokacija</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Zaposleni</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Dejavnost (SKD)</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Ljubljana (A)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">20</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">66.120 fut. posredništvo</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Ljubljana (A)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">15</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">66.300 upravljanje prem.</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Maribor (B)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">25</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">66.120 fut. posredništvo</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> TradeX ima 2 lokalni enoti (Ljubljana, Maribor).</div><div style=\"font-size:13.5px\"><b>b)</b> TradeX ima 3 enote enovrstne dejavnosti (EED).</div><div style=\"font-size:13.5px\"><b>c)</b> Glavna dejavnost je fut. posredništvo, ker je tam 45/60 zaposlenih.</div><div style=\"font-size:13.5px\"><b>d)</b> TradeX je ena podjetniška statistična enota.</div></div>","options":["a + b","a + b + d","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"a ✓ dva naslova → 2 lokalni enoti. b ✓ tri kombinacije lokacija×dejavnost → 3 EED. c ✓ glavna dejavnost je <b>66.120 (fut. posredništvo)</b> — z največ zaposlenimi: 20 + 25 = 45 od 60. d ✓ ena pravna/podjetniška enota. → <b>a + b + c + d</b>."},{"q":"Naloga 11 · Absolutna demografska števila — SLO 2023","hint":"Naravni prirastek NP = N − M. Selitveni saldo SS = I − E. Skupni prirastek SP = NP + SS.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Slovenija je 2023 beležila naslednje tokove. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Parameter</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Živorojeni (N)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">18.700</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Umrli (M)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">21.200</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Priseljeni (I)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">28.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Odseljeni (E)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">10.500</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Naravni prirastek je negativen, −2.500.</div><div style=\"font-size:13.5px\"><b>b)</b> Selitveni saldo je +17.500.</div><div style=\"font-size:13.5px\"><b>c)</b> Skupni prirastek je +15.000.</div><div style=\"font-size:13.5px\"><b>d)</b> Slovenija je 2023 beležila pozitiven naravni prirastek.</div></div>","options":["a + b","a + b + c","a + b + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"NP = 18.700 − 21.200 = <b>−2.500</b> (a ✓). SS = 28.000 − 10.500 = <b>+17.500</b> (b ✓). SP = −2.500 + 17.500 = <b>+15.000</b> (c ✓). d ✗: NP je negativen. → <b>a + b + c</b>."},{"q":"Naloga 12 · Splošne demografske stopnje — SLO 2023","hint":"SSN (natalitete) = N / srednje št. VSEH preb. ×1000. SSM (mortalitete) = M / srednje št. preb. ×1000. Splošna stopnja NP = SSN − SSM.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Podatki za Slovenijo 2023. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Parameter</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Živorojeni (N)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">18.700</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Umrli (M)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">21.200</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Srednje št. preb. (P̄)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">2.116.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Ženske 15–49</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">480.000</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Splošna stopnja natalitete ≈ 8,8 ‰.</div><div style=\"font-size:13.5px\"><b>b)</b> V imenovalcu SSN je srednje št. žensk v rodni dobi.</div><div style=\"font-size:13.5px\"><b>c)</b> Splošna stopnja mortalitete ≈ 10,0 ‰.</div><div style=\"font-size:13.5px\"><b>d)</b> Splošna stopnja NP je negativna, ≈ −1,2 ‰.</div></div>","options":["a + c","a + b + d","a + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"SSN = 18.700/2.116.000×1000 = <b>8,8 ‰</b> (a ✓). b ✗: imenovalec je <b>vse</b> prebivalstvo, ne ženske 15–49. SSM = 21.200/2.116.000×1000 = <b>10,0 ‰</b> (c ✓). SSNP = 8,8 − 10,0 = <b>−1,2 ‰</b> (d ✓). → <b>a + c + d</b>."},{"q":"Naloga 13 · Specifične demografske stopnje — SLO 2023","hint":"SSR (rodnosti) = živorojeni / ženske 15–49 ×1000 (zato SSR > SSN). Stopnja umrljivosti dojenčkov = umrli dojenčki / živorojeni ×1000.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Dopolnilni podatki (živorojeni N = 18.700). Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Parameter</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Ženske 15–49</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">480.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Umrli dojenčki (<1 leto)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">37</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Srednje št. preb. (P̄)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">2.116.000</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Splošna stopnja rodnosti (SSR) ≈ 39,0 ‰.</div><div style=\"font-size:13.5px\"><b>b)</b> SSR je višja od SSN (8,8 ‰), ker je imenovalec manjši.</div><div style=\"font-size:13.5px\"><b>c)</b> Stopnja umrljivosti dojenčkov ≈ 2,0 ‰.</div><div style=\"font-size:13.5px\"><b>d)</b> V imenovalcu stopnje umrljivosti dojenčkov je št. otrok < 1 leta.</div></div>","options":["a + b","a + b + c","a + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":1,"htmlExpl":true,"explanation":"SSR = 18.700/480.000×1000 = <b>39,0 ‰</b> (a ✓). SSR > SSN, ker je imenovalec (ženske 15–49) manjši od vsega prebivalstva (b ✓). Umrljivost dojenčkov = 37/18.700×1000 = <b>2,0 ‰</b> (c ✓). d ✗: imenovalec je <b>živorojeni</b>, ne št. dojenčkov. → <b>a + b + c</b>."},{"q":"Naloga 14 · Starostna struktura in koeficienti odvisnosti","hint":"Koef. odvisnosti mladih = (0–14)/(15–64)×100. Koef. odvisnosti starih = (65+)/(15–64)×100. Skupni = (0–14 + 65+)/(15–64)×100.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Starostna sestava prebivalstva Slovenije 2023. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Skupina</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">0–14 let</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">295.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">15–64 let</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">1.380.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">65+ let</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">441.000</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\"><b>SKUPAJ</b></td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\"><b>2.116.000</b></td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Koef. odvisnosti mladih ≈ 21,4 %.</div><div style=\"font-size:13.5px\"><b>b)</b> Koef. odvisnosti starih ≈ 32,0 %.</div><div style=\"font-size:13.5px\"><b>c)</b> Skupni koef. odvisnosti ≈ 53,3 %.</div><div style=\"font-size:13.5px\"><b>d)</b> Delovno aktivni (15–64) so ≈ 70 % celote.</div></div>","options":["a + b + c","a + b + d","a + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":0,"htmlExpl":true,"explanation":"Mladi: 295.000/1.380.000×100 = <b>21,4 %</b> (a ✓). Stari: 441.000/1.380.000×100 = <b>32,0 %</b> (b ✓). Skupni: 736.000/1.380.000×100 = <b>53,3 %</b> (c ✓). d ✗: 1.380.000/2.116.000×100 = <b>65,2 %</b>, ne 70 %. → <b>a + b + c</b>."},{"q":"Naloga 15 · Napovedovanje prebivalstva — geometrijska metoda","hint":"Geometrijska metoda: Pₜ = P₀ × (1+r)ᵗ (konstantna STOPNJA rasti, obrestno-obrestni efekt). 1,007⁵ ≈ 1,0355; 1,007¹⁰ ≈ 1,0723.","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Slovenija 2020: P₀ = 2.100.000; pričakovana letna stopnja rasti r = 0,7 % = 0,007. Katere trditve so pravilne?</div><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Napoved za 2025 ≈ 2.174.000.</div><div style=\"font-size:13.5px\"><b>b)</b> Geometrijska metoda predpostavlja konstantno absolutno rast.</div><div style=\"font-size:13.5px\"><b>c)</b> Geometrijska metoda upošteva obrestno-obrestni efekt.</div><div style=\"font-size:13.5px\"><b>d)</b> Napoved za 2030 ≈ 2.252.000.</div></div>","options":["a + b","a + b + c","a + c + d","b + c + d","Pravilna rešitev ni navedena"],"correct":2,"htmlExpl":true,"explanation":"2025 (t=5): 2.100.000×1,0355 = <b>2.174.000</b> (a ✓). b ✗: predpostavlja konstantno <b>stopnjo</b> rasti, ne absolutne. c ✓ rast se obrestuje. 2030 (t=10): 2.100.000×1,0723 = <b>2.252.000</b> (d ✓). → <b>a + c + d</b>."},{"q":"Naloga 16 · Poslovni koeficienti — hedge sklad","hint":"Produktivnost dela = prihodki / št. zaposlenih. Rentabilnost prihodkov = poslovni izid / prihodki ×100. Rentabilnost sredstev = poslovni izid / sredstva ×100. Pozor na razliko v imenovalcu!","given":"<div style=\"font-size:13.5px;margin-bottom:4px\">Hedge sklad »AlphaFund« je za 2023 objavil naslednje. Katere trditve so pravilne?</div><table style=\"border-collapse:collapse;font-size:13px;margin:6px 0 4px\"><tr><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Parameter</th><th style=\"border:1px solid var(--line);padding:4px 9px;background:var(--paper2)\">Vrednost</th></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Prihodki</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">8,0 mio EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Stroški</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">3,0 mio EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Poslovni izid</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">5,0 mio EUR</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">Povpr. zaposlenih</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">25</td></tr><tr><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:left\">AUM (sredstva)</td><td style=\"border:1px solid var(--line);padding:4px 9px;text-align:center\">400 mio EUR</td></tr></table><div style=\"margin-top:10px;display:grid;gap:5px\"><div style=\"font-size:13.5px\"><b>a)</b> Produktivnost dela = 0,32 mio EUR/zaposlenega.</div><div style=\"font-size:13.5px\"><b>b)</b> Rentabilnost prihodkov = 62,5 %.</div><div style=\"font-size:13.5px\"><b>c)</b> Rentabilnost sredstev (AUM) je prav tako 62,5 %.</div><div style=\"font-size:13.5px\"><b>d)</b> AUM na zaposlenega = 16 mio EUR/zaposlenega.</div></div>","options":["a + b + d","a + c + d","b + c + d","a + b + c + d","Pravilna rešitev ni navedena"],"correct":0,"htmlExpl":true,"explanation":"Produktivnost = 8/25 = <b>0,32</b> mio/zap (a ✓). Rentab. prihodkov = 5/8×100 = <b>62,5 %</b> (b ✓). c ✗: rentab. sredstev = 5/400×100 = <b>1,25 %</b>, ne 62,5 % (drug imenovalec!). AUM/zap = 400/25 = <b>16</b> mio/zap (d ✓). → <b>a + b + d</b>."}]}],"notes":"\n<h2>1–4 · Osnove statistike</h2>\n<div class=\"note-card\">\n<h3>Temeljni pojmi in podatki</h3>\n<ul>\n<li><b>Statistika</b>: zbiranje, urejanje, prikaz in analiza množičnih podatkov. <b>Populacija</b> (vse enote) vs <b>vzorec</b> (del populacije).</li>\n<li><b>Merske lestvice (Stevens)</b>: imenska (kategorije), ordinalna (vrstni red), intervalna (enaki razmiki, brez prave ničle), razmernostna (prava ničla). Višja lestvica = več dovoljenih operacij.</li>\n<li><b>Vrste podatkov</b>: kvalitativni (opisni) vs kvantitativni (številski); <b>primarni</b> (anketa, intervju, opazovanje) vs <b>sekundarni</b> (npr. SURS SI-STAT).</li>\n<li><b>PEST</b> = analiza zunanjega okolja; <b>SWOT</b> = prednosti/slabosti.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Srednje vrednosti in razpršenost</h3>\n<ul>\n<li><b>Aritmetična sredina</b> (občutljiva na osamelce), <b>mediana</b> (razdeli niz na pol, odporna na osamelce), <b>modus</b> (najpogostejša vrednost), <b>geometrijska sredina</b> (za stopnje rasti).</li>\n<li><b>Razpršenost</b>: variacijski razmik, <b>varianca</b>, <b>standardni odklon</b> (koren variance), <b>koeficient variacije</b> = (σ/AS)×100.</li>\n<li><b>Strukture</b> (delež ×100; vsota 100 %) in <b>koeficienti</b> (razmerje dveh vsebinsko povezanih absolutnih števil).</li>\n</ul>\n</div>\n\n<h2>Prikazi podatkov (tabele in grafikoni)</h2>\n<div class=\"note-card\">\n<h3>Tabele</h3>\n<p><b>Razpredelnica surovih podatkov</b> (podatkovna matrika): enote v vrsticah, spremenljivke v stolpcih (logika Excela/SPSS).</p>\n<p><b>Frekvenčna tabela</b> — porazdelitev frekvenc ene spremenljivke:</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px;text-align:left\">Ocena</th><th style=\"border:1px solid var(--line);padding:4px 10px\">f</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">3</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">7</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">8</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\">8</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">12</td></tr>\n</table>\n<p><b>Kontingenčna (dvorazsežna) tabela</b> — dve opisni spremenljivki hkrati (v vrsticah in stolpcih):</p>\n<table style=\"border-collapse:collapse;font-size:13px;margin:6px 0\">\n<tr><th style=\"border:1px solid var(--line);padding:4px 10px\"></th><th style=\"border:1px solid var(--line);padding:4px 10px\">M</th><th style=\"border:1px solid var(--line);padding:4px 10px\">Ž</th></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Da</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">14</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">9</td></tr>\n<tr><td style=\"border:1px solid var(--line);padding:4px 10px\"><b>Ne</b></td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">6</td><td style=\"border:1px solid var(--line);padding:4px 10px;text-align:center\">11</td></tr>\n</table>\n</div>\n<div class=\"note-card\">\n<h3>Grafikoni — kateri za kaj</h3>\n<div style=\"display:flex;flex-wrap:wrap;gap:18px;align-items:flex-start\">\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"28\" y=\"92\" width=\"32\" height=\"23\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"60\" y=\"68\" width=\"32\" height=\"47\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"92\" y=\"40\" width=\"32\" height=\"75\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"124\" y=\"30\" width=\"32\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"156\" y=\"62\" width=\"32\" height=\"53\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n      <rect x=\"188\" y=\"95\" width=\"32\" height=\"20\" fill=\"var(--terra)\" opacity=\"0.75\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Histogram</b> — frekvenčna porazdelitev <i>zvezne</i> spremenljivke (stolpci se stikajo).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 120 120\" style=\"width:100%;max-height:120px\">\n      <!-- 0° pri ura 3 (desno); koti naraščajo v nasprotni smeri urinega kazalca (matematična smer); izseki od največjega -->\n      <path d=\"M60,60 L100,60 A40,40 0 0,0 20,60 Z\" fill=\"var(--terra)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L20,60 A40,40 0 0,0 72.36,98.04 Z\" fill=\"var(--teal)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <path d=\"M60,60 L72.36,98.04 A40,40 0 0,0 100,60 Z\" fill=\"var(--ink2)\" opacity=\"0.85\" stroke=\"var(--paper)\" stroke-width=\"1.5\"/>\n      <line x1=\"100\" y1=\"60\" x2=\"112\" y2=\"60\" stroke=\"var(--ink)\" stroke-width=\"1.6\"/>\n      <text x=\"103\" y=\"54\" font-size=\"9\" fill=\"var(--ink2)\">0°</text>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Strukturni krog (tortni)</b> — <i>struktura (deleži)</i> celote. Začnemo pri <b>0° (desno, ura 3)</b> in izseke nizamo po velikosti od največjega, v nasprotni smeri urinega kazalca (matematična smer kotov).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <polyline points=\"34,95 74,72 114,82 154,45 194,58 220,32\" fill=\"none\" stroke=\"var(--teal)\" stroke-width=\"2.5\"/>\n      <g fill=\"var(--teal)\"><circle cx=\"34\" cy=\"95\" r=\"2.5\"/><circle cx=\"74\" cy=\"72\" r=\"2.5\"/><circle cx=\"114\" cy=\"82\" r=\"2.5\"/><circle cx=\"154\" cy=\"45\" r=\"2.5\"/><circle cx=\"194\" cy=\"58\" r=\"2.5\"/><circle cx=\"220\" cy=\"32\" r=\"2.5\"/></g>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Linijski grafikon</b> — <i>kronološko</i> gibanje pojava (časovna vrsta).</figcaption>\n  </figure>\n  <figure style=\"margin:0;width:160px\">\n    <svg viewBox=\"0 0 240 140\" style=\"width:100%\">\n      <line x1=\"28\" y1=\"115\" x2=\"225\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <line x1=\"28\" y1=\"20\" x2=\"28\" y2=\"115\" stroke=\"var(--line)\" stroke-width=\"1.5\"/>\n      <rect x=\"42\" y=\"45\" width=\"30\" height=\"70\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"92\" y=\"70\" width=\"30\" height=\"45\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"142\" y=\"30\" width=\"30\" height=\"85\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n      <rect x=\"192\" y=\"78\" width=\"30\" height=\"37\" fill=\"var(--terra)\" opacity=\"0.8\"/>\n    </svg>\n    <figcaption style=\"font-size:12px;color:var(--ink2);margin-top:4px\"><b>Stolpčni grafikon</b> — primerjava <i>opisnih</i> kategorij (stolpci so ločeni).</figcaption>\n  </figure>\n</div>\n</div>\n\n<h2>5–8 · Relativna števila in indeksi</h2>\n<div class=\"note-card\">\n<h3>Enostavni indeksi</h3>\n<ul>\n<li><b>Enostavni indeks</b>: i = (y₁/y₀)×100. Razlaga: <b>I − 100</b> (za koliko %), <b>I : 100</b> (kolikokrat).</li>\n<li><b>Časovni</b> (dve obdobji), <b>krajevni</b> (dva kraja), <b>stvarni</b> (dva pojava). <b>Bazni</b> (stalna osnova) vs <b>verižni</b> (s predhodnim).</li>\n<li><b>Deflacioniranje</b>: realna vrednost = (nominalna / indeks cen)×100. Indeks vrednosti = indeks cen × indeks količin / 100.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Skupinski (agregatni in srednji) indeksi</h3>\n<ul>\n<li><b>Laspeyres</b> (uteži = bazne količine q₀), <b>Paasche</b> (uteži = tekoče količine q₁), <b>Fisher</b> = √(L·P).</li>\n<li><b>Srednji</b>: TAS = agregatni Laspeyres; THS = agregatni Paasche.</li>\n<li><b>Stalna struktura</b> (uteži baznega obdobja) vs <b>spremenljiva struktura</b> (indeks povprečne cene). <b>Strukturni premiki</b> = I(spremenljiva)/I(stalna)×100.</li>\n<li><b>Relacija (vedno „križ\")</b>: Iᵥ = Iₚ(Laspeyres)·I_q(Paasche)/100. Strukturni premiki zavrejo rast cen, ko je IᴾL &gt; IᴾP.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Agregatni vs srednji indeksi — prednosti in slabosti</h3>\n<p style=\"margin:0 0 6px\"><b>Agregatni indeksi</b> (Laspeyres, Paasche, Fisher) — iz vsot vrednosti Σ(p·q):</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: neposredna ekonomska interpretacija (primerjamo dejanske <i>skupne vrednosti</i> košarice); natančni, ker temeljijo na dejanskih cenah <i>in</i> količinah; omogočajo razčlenitev vrednostnega indeksa na cenovni in količinski del (Iᵥ = IᴾL·I_qP/100).</li>\n<li><b>Slabosti</b>: zahtevajo <i>popolne</i> podatke o cenah in količinah za vse postavke v obeh obdobjih (podatkovno zahtevni); izbira obdobja uteži premakne rezultat — <b>Laspeyres</b> (bazne uteži) navzgor precenjuje, <b>Paasche</b> (tekoče uteži) navzdol podcenjuje rast cen; težavni ob spremembi nabora postavk.</li>\n</ul>\n<p style=\"margin:8px 0 6px\"><b>Srednji indeksi</b> (tehtana sredina enostavnih indeksov): <b>TAS</b> tehtana z baznimi vrednostmi p₀q₀ = agregatni Laspeyres; <b>THS</b> tehtana s tekočimi vrednostmi p₁q₁ = agregatni Paasche.</p>\n<ul style=\"margin-top:0\">\n<li><b>Prednosti</b>: izračunljivi že iz <i>posameznih (enostavnih) indeksov</i> in vrednostnih uteži — ni potrebna cela matrika q in p; primerni, ko poznamo strukturo izdatkov/vrednosti, ne pa posameznih količin (tako se v praksi računa npr. indeks cen življenjskih potrebščin); prožni pri izbiri uteži.</li>\n<li><b>Slabosti</b>: rezultat je odvisen od <i>izbire uteži in tipa sredine</i> — napačna sredina (aritmetična namesto harmonične ali obratno) ali napačne uteži dajo pristranski indeks; manj neposredno ekonomsko interpretabilni kot agregati.</li>\n</ul>\n<p style=\"margin:8px 0 0\"><b>Ključno</b>: <b>TAS = Laspeyres</b> in <b>THS = Paasche</b> — ob pravilnih utežeh dasta agregatni in srednji pristop <i>enak</i> rezultat. Razlika ni v vrednosti, ampak v tem, <i>katere podatke imamo na voljo</i>.</p>\n</div>\n\n<h2>9–12 · Klasifikacije, prebivalstvo, ekon. aktivnost</h2>\n<div class=\"note-card\">\n<h3>Statistični sistem in klasifikacije</h3>\n<ul>\n<li><b>ESS</b>: na vrhu <b>Eurostat</b>; v Sloveniji glavni izvajalec <b>SURS</b>.</li>\n<li><b>Klasifikacije</b>: NACE (EU)/SKD (SLO) — dejavnosti; <b>ISIC</b> (ZN) — osnova za NACE; <b>HS</b> — blago/carina; <b>PRODCOM</b> — industrijski proizvodi; CPA — proizvodi po dejavnosti.</li>\n<li><b>Enote</b>: pravna, <b>lokalna</b> (po lokaciji), <b>EED</b> (enovrstna dejavnost). <b>Glavna dejavnost</b> = dejavnost z <b>največ zaposlenimi</b>; pri več hierarhičnih ravneh po <b>top-down metodi</b> (seštevamo navzgor po ravneh, ne izberemo kar največjega razreda). <b>Metapodatki</b> = podatki o podatkih.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Statistične enote — natančno razvrščanje (s primerom)</h3>\n<p style=\"margin:0 0 6px\">Iste podatke o podjetju razvrstimo v <b>štiri vrste enot</b>, vsako po svojem kriteriju:</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> (institucionalna/pravna enota): <b>1</b> na pravni subjekt. Kriterij: pravni status. <i>Primer:</i> Galeb = 1 podjetje.</li>\n<li><b>Lokalna enota (LE)</b>: podjetje ali del podjetja na <b>enem naslovu/lokaciji</b>. Število = <b>število različnih lokacij</b>. Kriterij: <i>geografija</i>. Na enem naslovu je vedno <b>ena</b> LE, tudi če tam tečeta dve dejavnosti.</li>\n<li><b>Enota enovrstne dejavnosti (EED)</b>: del podjetja, ki opravlja <b>eno vrsto dejavnosti</b> (eno šifro), <i>ne glede na lokacijo</i>. Število = <b>število različnih šifer dejavnosti</b>. Kriterij: <i>dejavnost</i>.</li>\n<li><b>Lokalna enota enovrstne dejavnosti (LEVED)</b>: <b>ena dejavnost na eni lokaciji</b>. Število = število <b>dejansko obstoječih kombinacij lokacija–šifra</b>. Kriterij: <i>lokacija IN dejavnost hkrati</i>.</li>\n</ul>\n<p style=\"margin:8px 0 4px\"><b>Pozor:</b> LEVED <b>ni</b> produkt lokacij × šifer. Šteješ samo kombinacije, ki res obstajajo.</p>\n<p style=\"margin:6px 0 4px\"><b>Primer (Galeb):</b> Brnik (62.10), Lesce (62.20), Portorož (62.20 in 63.30).</p>\n<ul style=\"margin-top:0\">\n<li><b>Podjetje</b> = 1.</li>\n<li><b>LE</b> = 3 (Brnik, Lesce, Portorož).</li>\n<li><b>EED</b> = 3 (tri različne šifre: 62.10, 62.20, 63.30 — čeprav 62.20 nastopa dvakrat, je <i>ena</i> dejavnost).</li>\n<li><b>LEVED</b> = 4 (Brnik–62.10, Lesce–62.20, Portorož–62.20, Portorož–63.30; <i>ne</i> 3×3 = 9).</li>\n<li><b>Skupaj</b> = 1 + 3 + 3 + 4 = <b>11 enot</b>.</li>\n</ul>\n<p style=\"margin:6px 0 0;font-size:13px;color:var(--ink2)\">Mini-pravilo: LE šteje <i>naslove</i>, EED šteje <i>šifre</i>, LEVED šteje <i>pare (naslov, šifra)</i>.</p>\n</div>\n<div class=\"note-card\">\n<h3>Prebivalstvo in ekonomska aktivnost</h3>\n<ul>\n<li><b>Skupni prirastek</b> = naravni prirastek (živorojeni − umrli) + selitveni saldo (priseljeni − odseljeni).</li>\n<li><b>SSN</b> = živorojeni / srednje št. <b>vseh</b> preb. ×1000; <b>SSR</b> = živorojeni / ženske 15–49 ×1000 (SSR &gt; SSN).</li>\n<li><b>Koef. maskulinitete</b> ≈1050; <b>koef. starostne odvisnosti</b> = (0–14 + 65+)/(15–64)×100; <b>indeks staranja</b> = (65+ / 0–14)×100.</li>\n<li><b>Napovedovanje</b>: linearno (konst. absolutni prirastek) vs geometrijsko (konst. stopnja rasti; pri r&gt;0 višja napoved). <b>Produktivnost</b> in <b>intenzivnost</b> = 1/produktivnost. PKM (Big Mac index).</li>\n</ul>\n</div>\n"}]},{"id":"inf","name":"Informatika","tier":"B","parts":[{"id":"k1","name":"1. kolokvij","type":"kolokvij","decks":[]},{"id":"k2","name":"2. kolokvij","type":"kolokvij","decks":[{"id":"biz","name":"Poslovna analitika in BI","questions":[{"q":"Kaj je značilno za operativno bazo podatkov (database)?","options":["Hrani vse vrste podatkov v surovi obliki za AI","Optimizirana je za vsakodnevne transakcije in strukturirane podatke","Je skladišče očiščenih podatkov iz več virov za poročanje","Je programski jezik za poizvedbe"],"correct":1,"explanation":"Operativna baza (npr. ERP) beleži vsakodnevne transakcije v realnem času — strukturirani podatki, optimizirano za hitro pisanje in branje."},{"q":"Kaj je Data Warehouse (DWH)?","options":["Surovo odlagališče vseh vrst podatkov","Operativna baza za realnočasovne transakcije","Centralizirano skladišče strukturiranih, očiščenih podatkov iz več virov za analitiko in poročanje","Orodje za vizualizacijo podatkov"],"correct":2,"explanation":"DWH zbira strukturirane, očiščene podatke iz več virov in je optimiziran za analitične poizvedbe ter BI poročanje."},{"q":"Kaj je Data Lake?","options":["Izključno strukturirani in očiščeni podatki","Operativna transakcijska baza","Shramba vseh podatkov v surovi obliki — strukturiranih, pol-strukturiranih in nestrukturiranih","Orodje za poročanje"],"correct":2,"explanation":"Data Lake hrani vse podatke v surovi obliki (slike, logi, JSON), je cenejši za shranjevanje in primeren za ML/AI projekte."},{"q":"Kaj pomeni kratica ETL?","options":["Evaluate, Test, Launch","Extract, Transform, Load","Export, Transfer, Link","Encrypt, Transmit, Log"],"correct":1,"explanation":"ETL (extract, transform, load) je proces, skozi katerega gredo podatki, preden se naložijo v podatkovno skladišče (DWH)."},{"q":"Katera je ključna razlika med DWH in Data Lake?","options":["DWH hrani surove podatke, Data Lake samo strukturirane","DWH je urejen in strukturiran za BI poročanje, Data Lake je surov ('vse noter') za napredno analitiko in AI","Med njima ni razlike","Data Lake je vedno dražji za shranjevanje"],"correct":1,"explanation":"DWH = urejeno, strukturirano, za poročanje; Data Lake = surovo, vse vrste podatkov, za napredno analitiko in AI.","more":"Hitra primerjava treh shramb: (1) operativna baza (database) — vsakodnevne transakcije v realnem času, strukturirani podatki (npr. ERP); (2) podatkovno skladišče (DWH) — centralizirani, očiščeni, strukturirani podatki iz več virov, optimizirani za BI poročanje; (3) data lake — vsi podatki v surovi obliki (strukturirani, pol-strukturirani, nestrukturirani), cenejša shramba, primerna za ML/AI. Podatki v DWH gredo skozi proces ETL (extract, transform, load)."},{"q":"Kateri primer najbolje ponazarja operativno bazo (database)?","options":["Skladišče podatkov za letno poročanje","ERP sistem, ki beleži naročila v realnem času","Jezero surovih log datotek","Power BI nadzorna plošča"],"correct":1,"explanation":"ERP sistem, ki v realnem času beleži transakcije, je tipična operativna baza."},{"q":"Kateri je pravilni vrstni red petih nivojev analitike (od najnižjega navzgor)?","options":["Diagnostična → Opisna → Napovedna → Kognitivna → Predpisna","Opisna → Diagnostična → Napovedna → Predpisna → Kognitivna","Opisna → Napovedna → Diagnostična → Predpisna → Kognitivna","Napovedna → Opisna → Diagnostična → Predpisna → Kognitivna"],"correct":1,"explanation":"Piramida vrst analitike: opisna → diagnostična → napovedna → predpisna → kognitivna.","more":"Vsaka raven odgovarja na svoje vprašanje: opisna (descriptive) — 'Kaj se je zgodilo?'; diagnostična — 'Zakaj se je zgodilo?'; napovedna (predictive) — 'Kaj se bo zgodilo?'; predpisna (prescriptive) — 'Kaj naj naredimo?'; kognitivna — sistem se uči in odloča avtonomno (UI). Višje ravni prinašajo večjo vrednost in zahtevnost."},{"q":"Na katero vprašanje odgovarja OPISNA (descriptive) analitika?","options":["Zakaj se je zgodilo?","Kaj se je zgodilo?","Kaj se bo zgodilo?","Kaj naj naredimo?"],"correct":1,"explanation":"Opisna analitika odgovarja na vprašanje 'Kaj se je zgodilo?'."},{"q":"Na katero vprašanje odgovarja DIAGNOSTIČNA analitika?","options":["Zakaj se je zgodilo?","Kaj se je zgodilo?","Kaj se bo zgodilo?","Kaj naj naredimo?"],"correct":0,"explanation":"Diagnostična analitika išče vzroke — odgovarja na 'Zakaj se je zgodilo?'."},{"q":"Na katero vprašanje odgovarja NAPOVEDNA (predictive) analitika?","options":["Kaj se je zgodilo?","Zakaj se je zgodilo?","Kaj se bo zgodilo?","Kaj naj naredimo?"],"correct":2,"explanation":"Napovedna analitika napoveduje prihodnje dogodke — 'Kaj se bo zgodilo?'."},{"q":"Na katero vprašanje odgovarja PREDPISNA (prescriptive) analitika?","options":["Kaj naj naredimo?","Kaj se je zgodilo?","Zakaj se je zgodilo?","Kaj se bo zgodilo?"],"correct":0,"explanation":"Predpisna analitika priporoča ukrepe — 'Kaj naj naredimo?'."},{"q":"Kaj je značilno za najvišjo, KOGNITIVNO raven analitike?","options":["Samo opisuje pretekle dogodke","Sistem se uči in odloča avtonomno (s pomočjo UI)","Ročno poročanje v Excelu","Zgolj zbiranje surovih podatkov"],"correct":1,"explanation":"Kognitivna analitika je najvišja raven — sistem se samodejno uči in odloča, temelji na umetni inteligenci."},{"q":"Kateri je pravilni vrstni red BI arhitekture (4 koraki)?","options":["Vizualizacija → DWH → podatkovni viri → analitični modeli","Podatkovni viri → DWH → analitični modeli → vizualizacija","DWH → podatkovni viri → vizualizacija → analitični modeli","Podatkovni viri → vizualizacija → analitični modeli → DWH"],"correct":1,"explanation":"BI arhitektura: podatkovni viri → DWH → analitični modeli → vizualizacija."},{"q":"Kaj sestavlja data-driven (na podatkih temelječ) pristop k odločanju?","options":["Intuicija + izkušnje + ugibanje","Interpretacija podatkov + poslovna analitika + odločanje","Samo zbiranje podatkov","Zgolj vizualizacija rezultatov"],"correct":1,"explanation":"Data-driven pristop združuje interpretacijo podatkov, poslovno analitiko in odločanje."},{"q":"Za kateri namen je Data Lake najbolj primeren?","options":["Za hitre vsakodnevne transakcije","Za strogo strukturirano finančno poročanje","Za ML/AI projekte, ki potrebujejo raznolike surove podatke","Za nadomestitev operativne baze"],"correct":2,"explanation":"Data Lake hrani raznolike surove podatke, kar je idealno za strojni in globoki učni (ML/AI) razvoj."}]}]},{"id":"k3","name":"3. kolokvij (zadnji)","type":"kolokvij","decks":[{"id":"is","name":"Razvoj IS / Digitalizacija","questions":[{"q":"Koliko faz ima SDLC (življenjski cikel IS)?","options":["3","5","7","10"],"correct":1,"explanation":"SDLC ima 5 faz: Začetek/Načrtovanje, Analiza, Izdelava, Uvajanje, Izvajanje in vzdrževanje."},{"q":"Katera NI ena od treh ravni načrtovanja digitalizacije?","options":["Strateški načrt podjetja","Prioritetni seznam delnih IS","Načrt prenove/razvoja delnega IS","Načrt trženja izdelka"],"correct":3,"explanation":"Tri ravni so strateški načrt, prioritetni seznam delnih IS in načrt prenove/razvoja delnega IS."},{"q":"V kateri fazi SDLC poteka odločitev 'naredi-kupi' (make-or-buy)?","options":["Začetek","Analiza","Uvajanje","Vzdrževanje"],"correct":1,"explanation":"V fazi Analize se ob podatkovnem modelu sprejme odločitev naredi-kupi (lasten razvoj vs. nakup paketa)."},{"q":"Pri analizi stroškov in koristi izberemo alternativo z…","options":["najnižjimi začetnimi stroški","največjo razliko med dolgoročnimi koristmi in stroški","najhitrejšo uvedbo","največ funkcijami"],"correct":1,"explanation":"Izberemo alternativo z največjo razliko med dolgoročnimi koristmi in dolgoročnimi stroški."},{"q":"Študija izvedljivosti v fazi Začetka NE preverja:","options":["tehnične izvedljivosti","ekonomske izvedljivosti","organizacijske izvedljivosti","barvne sheme vmesnika"],"correct":3,"explanation":"Študija izvedljivosti ocenjuje tehnično, ekonomsko in organizacijsko izvedljivost."},{"q":"Kateri dve smeri vplivata na strateški načrt digitalizacije?","options":["Poslovne potrebe (navzgor) in vpliv IT (navzdol)","Marketing in prodaja","Stroški in koristi","Strojna in programska oprema"],"correct":0,"explanation":"Vplivata poslovne potrebe/usmeritve od spodaj navzgor in vpliv informacijske tehnologije od zgoraj navzdol."},{"q":"Kaj pomeni 'technology for technology's sake'?","options":["Uvedba tehnologije samo zato, ker je nova","Brezplačna tehnologija","Tehnologija za izobraževanje","Odprtokodna tehnologija"],"correct":0,"explanation":"To je napačna odločitev — uvedba nove tehnologije samo zato, ker je nova, brez ekonomske upravičenosti."},{"q":"V kateri fazi poteka urjenje uporabnikov in prehod na nov sistem?","options":["Analiza","Izdelava","Uvajanje","Začetek"],"correct":2,"explanation":"V fazi Uvajanja: načrt uvajanja, urjenje uporabnikov, prehod na nov sistem, testiranje ustreznosti."},{"q":"Konceptualni podatkovni model (entitete in relacije) se zasnuje v fazi:","options":["Začetek","Analiza","Uvajanje","Vzdrževanje"],"correct":1,"explanation":"Zasnova podatkovnega modela je del faze Analize."},{"q":"Helpdesk in odpravljanje napak sodita v fazo Izvajanja in vzdrževanja.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — peta faza (Izvajanje in vzdrževanje) vključuje helpdesk, popravke napak in nadgradnje."},{"q":"Testiranje sistema in dokumentiranje sistema sodita v fazo Izdelave.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — faza Izdelave: programiranje, testiranje programa, dokumentiranje programa, testiranje in dokumentiranje sistema."},{"q":"Pri razvoju IS vsi udeleženci vedno razumejo zahteve enako.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — tipičen problem je, da vsak udeleženec razume zahteve drugače; rezultat pogosto ni to, kar je naročnik želel."},{"q":"IoT (Internet of Things) je ena od smernic prihodnjega razvoja IS.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — interoperabilnost naprav (IoT) je med smernicami prihodnosti, skupaj s 5G/6G, AI in GDPR."},{"q":"Vztrajanje na ekonomsko zastareli tehnologiji je primer napačne odločitve.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — poleg 'technology for technology's sake' je napačno tudi vztrajanje pri zastareli tehnologiji."},{"q":"Kaj vsebuje strateški načrt podjetja?","options":["Poslanstvo, vizijo, cilje in smernice","Samo proračun","Seznam zaposlenih","Tehnične specifikacije strežnikov"],"correct":0,"explanation":"Strateški načrt vsebuje poslanstvo, vizijo, cilje in smernice — vključuje strateški načrt digitalizacije."},{"q":"Prioritetni seznam delnih IS upošteva vse, RAZEN:","options":["ekonomske upravičenosti","usklajenosti s strateškim načrtom","informacijske arhitekture","barve logotipa"],"correct":3,"explanation":"Vsebuje ekonomsko upravičenost, usklajenost s strategijo, metode razvoja in informacijsko arhitekturo."}]},{"id":"varnost","name":"Varnost informacijskih virov","questions":[{"q":"Kako se izračuna tveganje?","options":["P1 + P2 + L","P1 × P2 × L","P1 × L − P2","(P1 + P2) × L"],"correct":1,"explanation":"Tveganje = P1 × P2 × L (verjetnost grožnje × verjetnost uspeha × izguba)."},{"q":"Pri P1=0.02, P2=0.10, L=1.000.000 € znaša tveganje:","options":["200 €","2.000 €","20.000 €","200.000 €"],"correct":1,"explanation":"0.02 × 0.10 × 1.000.000 = 2.000 €."},{"q":"Katera NI eden od štirih izidov managementa tveganj?","options":["Sprejetje tveganja","Zmanjšanje tveganja","Prenos tveganja","Ignoriranje brez analize"],"correct":3,"explanation":"Štirje izidi: sprejetje, zmanjšanje (kontrole), prenos (zavarovanje/outsourcing), opustitev preveč tvegane dejavnosti."},{"q":"Kaj je rešitev za odpornost na odpovedi diskov?","options":["RAID","VPN","RAM","DNS"],"correct":0,"explanation":"RAID (Redundant Array of Independent Disks) — redundantni nizi diskov."},{"q":"Socialni inženiring izkorišča predvsem:","options":["tehnične ranljivosti sistema","človekove slabosti / psihološko manipulacijo","napake v strojni opremi","šibko šifriranje"],"correct":1,"explanation":"Socialni inženiring uporablja psihološko manipulacijo in izkorišča človekove slabosti, ne tehničnih ranljivosti."},{"q":"Pri BEC napadu (Business Email Compromise) napadalci nazadnje:","options":["izbrišejo bazo podatkov","spremenijo bančni račun na računu in ga pošljejo žrtvi","šifrirajo datoteke za odkupnino","ukradejo strojno opremo"],"correct":1,"explanation":"Pri BEC zadržijo račun, spremenijo bančni račun (na denarno mulo) in ga pošljejo žrtvi."},{"q":"Kaj sestavlja CIA trikotnik informacijske varnosti?","options":["Cena, Integracija, Avtomatizacija","Zaupnost, Celovitost, Razpoložljivost","Kontrola, Identifikacija, Avtentikacija","Centralizacija, Internet, Aplikacije"],"correct":1,"explanation":"CIA = Confidentiality (zaupnost), Integrity (celovitost), Availability (razpoložljivost)."},{"q":"Koliko kontrolnih ciljev ima COBIT?","options":["10","27","34","215"],"correct":2,"explanation":"COBIT ima 34 kontrolnih ciljev, 215 kontrol in 4 domene."},{"q":"Pri asimetričnem šifriranju sporočilo šifriramo z…","options":["zasebnim ključem pošiljatelja","javnim ključem prejemnika","istim skupnim ključem","hash funkcijo"],"correct":1,"explanation":"Šifriramo z javnim ključem prejemnika, dešifriramo z njegovim zasebnim ključem."},{"q":"Glavna slabost simetričnega šifriranja je:","options":["počasnost","problem varne izmenjave ključa","prevelika dolžina ključa","nezdružljivost s spletom"],"correct":1,"explanation":"Simetrično je hitro, a ima problem varne izmenjave ključa (oba imata isti ključ)."},{"q":"Koliko faktorjev avtentikacije poznamo (osnova za MFA)?","options":["2","3","4","5"],"correct":1,"explanation":"3 faktorji: nekaj kar veš (geslo), kar imaš (token), kar si (biometrija)."},{"q":"Kdo izda digitalno potrdilo?","options":["Banka","Overitelj (CA), npr. SIGEN-CA","Ponudnik interneta","Uporabnik sam"],"correct":1,"explanation":"Izda ga overitelj (Certification Authority); v Sloveniji npr. SIGEN-CA."},{"q":"Digitaliziran ročni podpis (na tablici) je veljaven elektronski podpis.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — digitaliziran ročni podpis NI elektronski podpis. E-podpis je 'prstni odtis' besedila prek hash funkcije."},{"q":"Z razvojem orodij se znižuje tehnično znanje, potrebno za napad.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — orodja postajajo dostopnejša, zahtevano znanje storilcev pa pada."},{"q":"Integer overflow nastane, ko 16-bitni števec preseže 32.767 in se vrne na 0.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — klasična napaka v programih: prekoračitev 16-bitnega števca."},{"q":"ISO/IEC 27001 opredeljuje upravljanje informacijske varnosti.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — 27001 = upravljanje varnosti, 27002 = najboljše prakse."},{"q":"V praksi se uporablja hibridni pristop: asimetrično šifriramo simetrični ključ.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — hibridni pristop združi hitrost simetričnega in varno izmenjavo asimetričnega."},{"q":"Po Verizon (2021) je delež finančno motiviranih napadov:","options":["25%","45%","71%","90%"],"correct":2,"explanation":"71% napadov je finančno motiviranih, 25% vohunskih."},{"q":"Katera tehnika NE sodi med tehnike kraje podatkov?","options":["Keylogger","Sniffer","Phishing","RAID"],"correct":3,"explanation":"RAID je rešitev za odpornost diskov, ne tehnika kraje. Tehnike: spyware, keylogger, sniffer, socialni inženiring, phishing."}]},{"id":"ai","name":"Umetna inteligenca","questions":[{"q":"Kdo je leta 1956 uvedel termin 'umetna inteligenca'?","options":["Alan Turing","John McCarthy","Marvin Minsky","Claude Shannon"],"correct":1,"explanation":"John McCarthy je leta 1956 na konferenci Dartmouth College uvedel termin 'umetna inteligenca'."},{"q":"Kaj je Turing prispeval leta 1950?","options":["Deep Blue","Termin AI","Delo 'Computing Machinery and Intelligence'","ChatGPT"],"correct":2,"explanation":"Alan Turing je 1950 objavil 'Computing Machinery and Intelligence' — vprašanje, ali stroji lahko razmišljajo."},{"q":"Kako je urejena hierarhija od najširšega do najožjega pojma?","options":["ML → AI → DL → GAI","AI → ML → DL → GAI","DL → AI → ML → GAI","GAI → DL → ML → AI"],"correct":1,"explanation":"AI ⊃ ML ⊃ globoko učenje (DL) ⊃ generativna UI (GAI)."},{"q":"Kateri korak NI del delovanja LLM?","options":["Tokenizacija","Vdelovanje (embedding)","Samo-pozornost (self-attention)","RAID redundanca"],"correct":3,"explanation":"LLM: tokenizacija → embedding → self-attention → nevronska mreža → izhod. RAID je iz varnosti."},{"q":"Kaj velja za halucinacije LLM?","options":["So programska napaka, ki jo zlahka odpravimo","So lastnost, ne hrošč — odgovori so statistično verjetni","Se pojavljajo samo pri starih modelih","Pomenijo izpad strežnika"],"correct":1,"explanation":"Halucinacije so lastnost, ne hrošč. LLM odgovarjajo statistično verjetno, ne nujno resnično."},{"q":"Kaj ilustrira primer 'king − man + woman ≈ queen'?","options":["Šifriranje","Semantične odnose med besedami (embedding)","Hitrost procesorja","Zgodovino AI"],"correct":1,"explanation":"Prikazuje, da LLM razumejo semantične odnose med besedami prek vektorskih vdelav."},{"q":"Kaj je RLHF?","options":["Vrsta šifriranja","Reinforcement learning from human feedback","Mrežni protokol","Tip diska"],"correct":1,"explanation":"RLHF (učenje s spodbujanjem iz človeških povratnih informacij) — način nenehnega izboljševanja LLM."},{"q":"Kaj je 'knowledge cutoff'?","options":["Maksimalna dolžina odgovora","Datum, po katerem model ne pozna dogodkov","Cena modela","Hitrost generiranja"],"correct":1,"explanation":"Model pozna le učne podatke do določenega datuma (knowledge cutoff) — kasnejših dogodkov ne ve."},{"q":"Razlika med modelom in orodjem:","options":["Ni razlike","Model = inteligenca, orodje = vmesnik","Model = vmesnik, orodje = inteligenca","Oba sta strojna oprema"],"correct":1,"explanation":"Model je inteligenca (npr. Deepseek R1), orodje je vmesnik (npr. Perplexity). Isti model + drugo orodje = drugačna izkušnja."},{"q":"Kaj je glavni doprinos generativne UI v primerjavi s tradicionalno?","options":["Samo analizira podatke","Ustvarja nove vsebine (besedilo, slike, kodo)","Samo napoveduje","Samo razvršča"],"correct":1,"explanation":"Tradicionalna UI analizira in napoveduje; generativna UI ustvarja nove vsebine."},{"q":"Leta 1997 je IBM Deep Blue:","options":["uvedel termin AI","premagal šahovskega prvaka Kasparova","ustvaril ChatGPT","sprejel EU AI Act"],"correct":1,"explanation":"Deep Blue (1997) je premagal svetovnega šahovskega prvaka Garija Kasparova."},{"q":"Tesslerjev izrek pravi: ko AI postane rutinsko, ni več AI.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — 'AI je karkoli, kar še ni bilo narejeno; ko postane rutinsko, ni več AI'."},{"q":"Bolj specifično kot je vprašanje, manjša je verjetnost halucinacije.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — bolj specifično vprašanje pomeni večjo verjetnost halucinacije."},{"q":"EU AI Act klasificira sisteme glede na tveganje.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — EU Akt o umetni inteligenci je regulatorni okvir s klasifikacijo sistemov po tveganju."},{"q":"Pristranskost LLM izhaja iz pristranskosti v učnih podatkih ('garbage in, garbage out').","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — modeli odražajo pristranskosti svojih učnih podatkov."},{"q":"LLM generira besedilo token po token na podlagi verjetnostne porazdelitve.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — izhod nastaja token po token glede na verjetnost naslednjega žetona."},{"q":"Globoko učenje (Deep Learning) temelji na:","options":["odločitvenih drevesih","umetnih nevronskih mrežah","tabelah SQL","blockchainu"],"correct":1,"explanation":"Globoko učenje je podzvrst ML, ki uporablja umetne nevronske mreže za odkrivanje vzorcev."},{"q":"Kaj je 'umetna gotovost' (artificial certainty)?","options":["Točnost izračunov","Nevarna iluzija strokovnega znanja iz avtoritativno zvenečih odgovorov","Vrsta šifriranja","Zanesljivost strojne opreme"],"correct":1,"explanation":"Laiki verjamejo, da razumejo kompleksne pojave, ker imajo dostop do avtoritativno zvenečih AI odgovorov."}]},{"id":"blockchain","name":"Blockchain / Veriženje blokov","questions":[{"q":"Na čem temelji blockchain?","options":["centralni bazi pri eni banki","distribuirani glavni knjigi (distributed ledger)","enem strežniku v oblaku","sistemu SWIFT"],"correct":1,"explanation":"Blockchain temelji na distribuirani glavni knjigi vseh transakcij — brez centralnega posrednika."},{"q":"Kdo potrdi vsak dogodek v glavni knjigi?","options":["centralna banka","večina udeležencev omrežja","država","en sam validator"],"correct":1,"explanation":"Vsak dogodek je potrjen s strani večine udeležencev — decentralizirano, brez posrednika."},{"q":"Kdo je razvil pametne pogodbe in kdaj?","options":["Bitcoin, 2009","Ethereum, 2015","Visa, 2010","SWIFT, 2008"],"correct":1,"explanation":"Pametne pogodbe je razvil Ethereum (2015). Moto: 'Code as Law'."},{"q":"Kaj so pametne pogodbe?","options":["pravni dokumenti pri notarju","programi, ki se samodejno izvršijo ob izpolnitvi pogojev","zavarovalne police","bančni računi"],"correct":1,"explanation":"So računalniški programi v mreži blokov, ki se avtomatsko izvršijo ob izpolnitvi vnaprej definiranih pogojev."},{"q":"Približna prepustnost Bitcoina je:","options":["~7 tx/s","~15 tx/s","~1.000 tx/s","~24.000 tx/s"],"correct":0,"explanation":"Bitcoin ~7 tx/s, Ethereum ~15 tx/s, Visa ~24.000 tx/s — skalabilnost je velik izziv."},{"q":"Kateri izziv se nanaša na porabo energije?","options":["Bitcoin mining porabi več kot vsa Norveška","Premajhna baza podatkov","Prepočasen internet","Premalo razvijalcev"],"correct":0,"explanation":"Bitcoin mining porabi več energije kot celotna Norveška."},{"q":"Kaj pomeni CBDC?","options":["Centralne bančne digitalne valute","Crypto Block Data Chain","Centralized Bitcoin Distribution","Code Based Digital Contract"],"correct":0,"explanation":"CBDC = centralne bančne digitalne valute (digitalni evro, digitalni juan)."},{"q":"Kaj je DeFi?","options":["Decentralizirane finance (brez bank in posrednikov)","Vrsta šifriranja","Mrežni protokol","Pametna pogodba"],"correct":0,"explanation":"DeFi = decentralizirane finance brez bank in posrednikov."},{"q":"Kaj je DAO?","options":["Data Access Object","Decentralizirane avtonomne organizacije","Digital Asset Ownership","Distributed Audit Operation"],"correct":1,"explanation":"DAO = decentralizirane avtonomne organizacije."},{"q":"Blockchain je alternativa kateremu sistemu za mednarodna nakazila?","options":["IBAN","SWIFT","SEPA","PayPal"],"correct":1,"explanation":"Blockchain je lahko alternativa sistemu SWIFT za hitrejša, cenejša in varnejša mednarodna nakazila."},{"q":"Katera platforma je zasebna/podjetniška?","options":["Ethereum","Hyperledger Fabric","Bitcoin","Dogecoin"],"correct":1,"explanation":"Hyperledger Fabric je zasebna/podjetniška; Ethereum je javna. Tudi R3 Corda in Quorum (JP Morgan)."},{"q":"Blockchain je samo tehnologija za kriptovalute.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — blockchain je infrastrukturna tehnologija (kot internet ni bil samo e-pošta). Kriptovalute so le ena uporaba."},{"q":"Pri blockchainu obstaja centralni posrednik, ki potrjuje transakcije.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — blockchain je decentraliziran; transakcije potrjuje večina udeležencev brez centralnega posrednika."},{"q":"Moto pametnih pogodb je 'Code as Law'.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — pametne pogodbe se samostojno izvršijo, koda je 'zakon'."},{"q":"51% napad je varnostno tveganje pri manjših blockchain omrežjih.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — če akter obvladuje >50% moči omrežja, lahko manipulira z verigo."},{"q":"Podvajanje podatkov (kopija pri vsakem vozlišču) je prednost blockchaina glede hrambe.","options":["Drži (pravilno)","Napačno"],"correct":1,"explanation":"Napačno — to je izziv: kopija pri vsakem vozlišču pomeni ogromne hrambne zahteve."},{"q":"Web3 predstavlja decentraliziran internet, ki cilja na razbitje internetnih monopolov.","options":["Drži (pravilno)","Napačno"],"correct":0,"explanation":"Drži — Web3 je del obetov za prihodnost: decentraliziran internet."},{"q":"Koncentracija moči pri blockchainu se kaže predvsem prek:","options":["mining poolov in večjih akterjev","centralne banke","vlade","SWIFT omrežja"],"correct":0,"explanation":"Izziv koncentracije moči: mining pooli in večji akterji dominirajo omrežje."}]}],"flashcards":[{"id":"fc-ris","name":"Razvoj IS (Pog. 6)","cards":[{"front":"Tri ravni načrtovanja digitalizacije","back":"Strateški načrt podjetja, prioritetni seznam delnih IS, načrt prenove/razvoja delnega IS."},{"front":"Kaj vsebuje strateški načrt podjetja?","back":"Poslanstvo, vizijo, cilje in smernice — vključno s strateškim načrtom digitalizacije."},{"front":"Dve smeri vpliva na strateški načrt","back":"Poslovne potrebe (od spodaj navzgor) in vpliv IT (od zgoraj navzdol)."},{"front":"Kaj je SDLC?","back":"Življenjski cikel informacijskega sistema — 5 faz razvoja IS."},{"front":"5 faz SDLC","back":"1) Začetek/načrtovanje, 2) analiza, 3) izdelava/nakup, 4) uvajanje, 5) izvajanje in vzdrževanje."},{"front":"Faza Začetek/načrtovanje","back":"Študija izvedljivosti (tehnična, ekonomska, organizacijska) in načrtovanje projekta."},{"front":"Kako ocenimo ekonomsko upravičenost?","back":"Z analizo stroškov in koristi — izberemo alternativo z največjo razliko med dolgoročnimi koristmi in stroški."},{"front":"Faza Analiza","back":"Podrobna analiza potreb z uporabniki, podatkovni model (entitete, relacije), odločitev naredi-kupi."},{"front":"Odločitev 'make-or-buy'","back":"Ali informacijski sistem razvijemo sami ali ga kupimo."},{"front":"Faza Uvajanje","back":"Načrt uvajanja, urjenje uporabnikov, prehod na nov sistem, testiranje ustreznosti."},{"front":"'Technology for technology's sake'","back":"Napačna odločitev: uvedba tehnologije samo zato, ker je nova (ali vztrajanje na zastareli)."},{"front":"Tipičen problem pri razvoju IS","back":"Vsak udeleženec razume zahteve drugače → rezultat pogosto ni to, kar je naročnik želel."},{"front":"Smernice prihodnosti IS","back":"Nižji stroški opreme, vpliv AI, boljša pismenost, 5G/6G, IoT, GDPR/zaščita podatkov."}]},{"id":"fc-var","name":"Varnost (Pog. 5)","cards":[{"front":"Formula za tveganje","back":"Tveganje = P1 × P2 × L (P1 = verjetnost grožnje, P2 = verjetnost uspeha, L = izguba)."},{"front":"Primer izračuna tveganja","back":"0,02 × 0,10 × 1.000.000 € = 2.000 €."},{"front":"4 izidi managementa tveganj","back":"Sprejetje, zmanjšanje (kontrole), prenos (zavarovanje/outsourcing), opustitev dejavnosti."},{"front":"Kaj je RAID?","back":"Redundant Array of Independent Disks — odpornost na odpovedi diskov."},{"front":"Integer overflow","back":"16-bitni števec preseže 32.767 in se vrne na 0."},{"front":"Socialni inženiring","back":"Psihološka manipulacija, ki izkorišča človekove slabosti — ne tehničnih ranljivosti."},{"front":"BEC (Business Email Compromise)","back":"Ukradejo geslo, spremljajo pošto in spremenijo bančni račun; najškodljivejši (povp. 45.400 €)."},{"front":"CIA trikotnik","back":"Zaupnost (Confidentiality), Celovitost (Integrity), Razpoložljivost (Availability)."},{"front":"3 faktorji avtentikacije","back":"Nekaj kar veš (geslo), kar imaš (kartica/token), kar si (biometrija). Kombinacija = MFA/2FA."},{"front":"Simetrično šifriranje","back":"Isti ključ; hitro, a problem izmenjave ključa (npr. Cezarjeva šifra)."},{"front":"Asimetrično šifriranje","back":"Par javni/zasebni ključ; šifriraš z javnim prejemnika, dešifriraš z zasebnim; počasnejše."},{"front":"Hibridni pristop","back":"Z asimetričnim šifriranjem prenesemo simetrični ključ."},{"front":"Digitalno potrdilo","back":"Izda overitelj (CA, npr. SIGEN-CA); omogoča šifriranje, dešifriranje in e-podpis."},{"front":"E-podpis","back":"'Prstni odtis' besedila prek hash funkcije. Digitaliziran ročni podpis NI e-podpis!"},{"front":"Standardi varnosti","back":"ISO/IEC 27001 (upravljanje varnosti), 27002 (najboljše prakse), ITIL (procesi IT), COBIT."},{"front":"Trajanje avtorske pravice","back":"Dosmrtno + 70 let po smrti avtorja."}]},{"id":"fc-ai","name":"Umetna inteligenca (Pog. 7)","cards":[{"front":"Kaj je umetna inteligenca?","back":"Programska oprema, ki opravlja naloge, ki zahtevajo človeško kognicijo."},{"front":"Spekter AI","back":"Od ozke (Narrow) do splošne (General)."},{"front":"Tesslerjev izrek","back":"AI je karkoli, kar še ni bilo narejeno — ko postane rutinsko, ni več AI."},{"front":"Mejniki: 1950 / 1956 / 1997","back":"1950 Turing; 1956 McCarthy uvede termin 'AI' (Dartmouth); 1997 Deep Blue premaga Kasparova."},{"front":"Hierarhija pojmov","back":"AI ⊃ strojno učenje (ML) ⊃ globoko učenje (DL) ⊃ generativna UI (GAI)."},{"front":"Strojno učenje (ML)","back":"Učenje iz podatkov brez eksplicitnega programiranja; DL temelji na nevronskih mrežah."},{"front":"Kako deluje LLM?","back":"Tokenizacija → vdelovanje (embedding) → samo-pozornost → nevronska mreža → izhod token po token (verjetnostno)."},{"front":"Primer semantike vdelav","back":"king − man + woman ≈ queen."},{"front":"Kaj je RLHF?","back":"Reinforcement learning from human feedback — izboljšanje modela s človeškimi povratnimi informacijami."},{"front":"Zakaj LLM halucinirajo?","back":"Halucinacije so lastnost, ne hrošč — model odgovarja statistično verjetno, ne nujno resnično."},{"front":"Model vs. orodje","back":"Model = inteligenca; orodje = vmesnik. Isti model + drugo orodje = drugačna izkušnja."},{"front":"Regulativa AI","back":"EU AI Act klasificira sisteme po tveganju; GDPR ureja podatke."}]},{"id":"fc-bc","name":"Blockchain (Pog. 8)","cards":[{"front":"Kaj je blockchain?","back":"Tehnologija porazdeljenih (decentraliziranih) zbirk na osnovi distribuirane glavne knjige."},{"front":"Kako se potrdi dogodek?","back":"Potrdi ga večina udeležencev v mreži — brez centralnega posrednika."},{"front":"Blockchain ≠ kriptovalute","back":"Je infrastrukturna tehnologija (kot internet ni bil samo e-pošta)."},{"front":"Pametne pogodbe","back":"Programi v mreži blokov, ki se samodejno izvršijo ob izpolnitvi pogojev."},{"front":"Razvoj pametnih pogodb","back":"Ethereum (2015); moto 'Code as Law'."},{"front":"Platforme za pametne pogodbe","back":"Ethereum, Hyperledger Fabric, R3 Corda, Quorum."},{"front":"Skalabilnost (tx/s)","back":"Bitcoin ~7, Ethereum ~15, Visa ~24.000 transakcij/s."},{"front":"Poraba energije","back":"Bitcoin mining porabi več kot vsa Norveška."},{"front":"51 % napad","back":"Izziv blockchaina — koncentracija moči (mining pooli) omogoči nadzor nad mrežo."},{"front":"CBDC","back":"Centralne bančne digitalne valute."},{"front":"Web3 / DeFi / DAO","back":"Decentraliziran internet / decentralizirane finance / decentralizirane avtonomne organizacije."}]}],"notes":"<h2>Poglavje 6 — Digitalizacija poslovanja: Razvoj IS</h2>\n<div class=\"note-card\">\n<h3>Tri ravni načrtovanja digitalizacije</h3>\n<ul>\n<li><b>Strateški načrt podjetja</b> — poslanstvo, vizija, cilji, smernice (vsebuje strateški načrt digitalizacije).</li>\n<li><b>Prioritetni seznam delnih IS</b> — ekonomska upravičenost, usklajenost s strategijo, metode razvoja, informacijska arhitektura.</li>\n<li><b>Načrt prenove/razvoja delnega IS</b> — viri, trajanje, funkcije, management projekta, omejitve.</li>\n</ul>\n<p>Na strateški načrt vplivata dve smeri: <i>poslovne potrebe</i> (od spodaj navzgor) in <i>vpliv IT</i> (od zgoraj navzdol).</p>\n</div>\n<div class=\"note-card\">\n<h3>SDLC — Življenjski cikel IS (5 faz)</h3>\n<ul>\n<li><b>1. Začetek/Načrtovanje</b> — študija izvedljivosti (tehnična, ekonomska, organizacijska), načrtovanje projekta. Ekonomska upravičenost prek analize stroškov in koristi — izberemo alternativo z največjo razliko med dolgoročnimi koristmi in stroški.</li>\n<li><b>2. Analiza</b> — podrobna analiza potreb z uporabniki, podatkovni model (entitete, relacije), odločitev <code>naredi-kupi</code> (make-or-buy).</li>\n<li><b>3. Izdelava/nakup</b> — programiranje, testiranje programa, dokumentiranje programa, testiranje sistema, dokumentiranje sistema.</li>\n<li><b>4. Uvajanje</b> — načrt uvajanja, urjenje uporabnikov, prehod na nov sistem, testiranje ustreznosti.</li>\n<li><b>5. Izvajanje in vzdrževanje</b> — helpdesk, popravki napak, nadgradnje.</li>\n</ul>\n<div class=\"warn\">Tipičen problem: vsak udeleženec (naročnik, vodja, projektant, inženir, prodajalec) razume zahteve drugače → rezultat pogosto ni to, kar je naročnik želel.</div>\n</div>\n<div class=\"note-card\">\n<h3>Napačne odločitve & smernice prihodnosti</h3>\n<ul>\n<li>Uvedba tehnologije samo ker je nova (<i>technology for technology's sake</i>) ali vztrajanje na zastareli.</li>\n<li>Prihodnost: nižji stroški opreme, vpliv AI, boljša pismenost uporabnikov, 5G/6G, IoT interoperabilnost, GDPR/zaščita podatkov.</li>\n</ul>\n</div>\n\n<h2>Poglavje 5 — Varnost in zaščita informacijskih virov</h2>\n<div class=\"note-card\">\n<h3>Izračun tveganja</h3>\n<p><code>Tveganje = P1 × P2 × L</code> (P1 = verjetnost grožnje, P2 = verjetnost uspeha, L = izguba).</p>\n<p>Primer: 0.02 × 0.10 × 1.000.000 € = <b>2.000 €</b>.</p>\n<h3>Management tveganj — 4 izidi</h3>\n<ul><li><b>Sprejetje</b> tveganja · <b>Zmanjšanje</b> (kontrole) · <b>Prenos</b> (zavarovanje/outsourcing) · <b>Opustitev</b> preveč tvegane dejavnosti.</li></ul>\n</div>\n<div class=\"note-card\">\n<h3>Vzroki nesreč & rešitve</h3>\n<ul>\n<li>Napačno ravnanje človeka (senčna AI, socialni inženiring), poškodbe opreme, strojne okvare, napake v programih in podatkih.</li>\n<li><b>RAID</b> (Redundant Array of Independent Disks) — odpornost na odpovedi diskov.</li>\n<li><b>Integer overflow</b>: 16-bitni števec preseže 32.767 → vrne se na 0.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Računalniški kriminal</h3>\n<ul>\n<li>Storilci: zaposleni (insider), zunanji, hackers, crackers. Trend: <b>manj tehničnega znanja</b> potrebno, orodja dostopnejša.</li>\n<li>Tehnike kraje: spyware, keylogger, sniffer, <b>socialni inženiring</b>, phishing.</li>\n<li><b>Socialni inženiring</b> = psihološka manipulacija; izkorišča človekove slabosti, NE tehničnih ranljivosti.</li>\n<li><b>BEC (Business Email Compromise)</b>: ukradejo geslo → posredovanje pošte → spremljajo → spremenijo bančni račun na računu → denarna mula. Najškodljivejši: povp. 45.400 €.</li>\n<li>Statistika (Verizon 2021): 71% napadov finančno motiviranih, 25% vohunskih.</li>\n<li>Avtorska pravica: dosmrtno + 70 let po smrti avtorja.</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Standardi & CIA</h3>\n<ul>\n<li><b>ISO/IEC 27001</b> (upravljanje varnosti), <b>27002</b> (najboljše prakse), <b>ITIL</b> (procesi IT), <b>COBIT</b> (34 ciljev, 215 kontrol, 4 domene).</li>\n<li>ISO 27001/2 = <b>10 področij</b> varnosti.</li>\n<li><b>CIA trikotnik</b>: Zaupnost (Confidentiality), Celovitost (Integrity), Razpoložljivost (Availability).</li>\n</ul>\n</div>\n<div class=\"note-card\">\n<h3>Nadzor dostopa & šifriranje</h3>\n<ul>\n<li><b>3 faktorji avtentikacije</b>: nekaj kar veš (geslo), kar imaš (kartica/token), kar si (biometrija). Kombinacija = <b>MFA/2FA</b>.</li>\n<li><b>Simetrično</b>: isti ključ; hitro, a problem izmenjave ključa (Cezarjeva šifra).</li>\n<li><b>Asimetrično</b>: par javni/zasebni ključ; šifriraš z javnim prejemnika, dešifriraš z zasebnim; počasnejše. Praksa = <b>hibridni pristop</b> (asimetrično prenesemo simetrični ključ).</li>\n<li><b>Digitalno potrdilo</b>: izda overitelj (CA, npr. SIGEN-CA); omogoča šifriranje, dešifriranje IN e-podpis.</li>\n<li><b>E-podpis</b> = 'prstni odtis' besedila prek <b>hash funkcije</b>. Pozor: digitaliziran ročni podpis (na tablici) NI elektronski podpis!</li>\n</ul>\n</div>\n\n<h2>Poglavje 7 — Umetna inteligenca (AI)</h2>\n<div class=\"note-card\">\n<h3>Osnove & zgodovina</h3>\n<ul>\n<li>AI = programska oprema, ki opravlja naloge, ki zahtevajo človeško kognicijo. Spekter: ozka (Narrow) → splošna (General).</li>\n<li><b>Tesslerjev izrek</b>: AI je karkoli, kar še ni bilo narejeno — ko postane rutinsko, ni več AI.</li>\n<li><b>1950</b> Turing (Computing Machinery and Intelligence) · <b>1956</b> McCarthy uvede termin \"AI\" (Dartmouth) · <b>1997</b> Deep Blue premaga Kasparova · <b>2022+</b> GenAI (ChatGPT, Claude, Gemini).</li>\n</ul>\n<h3>Hierarhija</h3>\n<p><b>AI ⊃ ML ⊃ Globoko učenje (DL) ⊃ Generativna UI (GAI)</b>. ML = uči se iz podatkov brez eksplicitnega programiranja; DL = nevronske mreže.</p>\n</div>\n<div class=\"note-card\">\n<h3>Veliki jezikovni modeli (LLM)</h3>\n<ul>\n<li>Delovanje: <b>tokenizacija</b> → <b>vdelovanje (embedding)</b> → <b>samo-pozornost (self-attention)</b> → nevronska mreža → izhod token po token (verjetnostno).</li>\n<li>Primer semantike: <code>king − man + woman ≈ queen</code>.</li>\n<li>Izboljšava prek <b>RLHF</b> (reinforcement learning from human feedback).</li>\n</ul>\n<div class=\"warn\"><b>Halucinacije so lastnost, ne hrošč!</b> LLM odgovarjajo statistično verjetno, ne nujno resnično. Bolj specifično vprašanje → večja verjetnost halucinacije.</div>\n<p>Druge omejitve: pristranskost (garbage in, garbage out), nerazumevanje konteksta/sarkazma, visoki stroški, <b>knowledge cutoff</b>.</p>\n</div>\n<div class=\"note-card\">\n<h3>Model vs. orodje · regulativa</h3>\n<ul>\n<li><b>Model</b> = inteligenca (npr. Deepseek R1); <b>orodje</b> = vmesnik (npr. Perplexity, ChatGPT). Isti model + različno orodje = drugačna izkušnja.</li>\n<li><b>EU AI Act</b> — klasifikacija sistemov po tveganju; GDPR za podatke.</li>\n<li>Tveganja: deep fake, dezinformacije, spearphishing, \"umetna gotovost\" (artificial certainty).</li>\n<li>66% vodij ne bi zaposlilo nekoga brez AI spretnosti (Microsoft 2024).</li>\n</ul>\n</div>\n\n<h2>Poglavje 8 — Tehnologija veriženja blokov (Blockchain)</h2>\n<div class=\"note-card\">\n<h3>Opredelitev & lastnosti</h3>\n<ul>\n<li>Blockchain = tehnologija <b>porazdeljenih (decentraliziranih)</b> podatkovnih zbirk na osnovi <b>distribuirane glavne knjige</b> (distributed ledger). Vsak dogodek potrdi <b>večina udeležencev</b> — brez centralnega posrednika.</li>\n<li><b>Blockchain ≠ samo kriptovalute</b> — je infrastrukturna tehnologija (kot internet ni bil samo e-pošta).</li>\n</ul>\n<h3>Pametne pogodbe (Smart Contracts)</h3>\n<p>Programi v mreži blokov, ki se <b>avtomatsko izvršijo</b> ob izpolnitvi pogojev. Razvil <b>Ethereum (2015)</b>. Moto: <i>Code as Law</i>. Platforme: Ethereum, Hyperledger Fabric, R3 Corda, Quorum.</p>\n</div>\n<div class=\"note-card\">\n<h3>Izzivi</h3>\n<ul>\n<li><b>Skalabilnost</b>: Bitcoin ~7 tx/s, Ethereum ~15 tx/s, Visa ~24.000 tx/s.</li>\n<li><b>Poraba energije</b>: Bitcoin mining > vsa Norveška. Podvajanje podatkov (kopija pri vsakem vozlišču).</li>\n<li>Regulacija, nezaupanje, koncentracija moči (mining pooli), 51% napadi.</li>\n</ul>\n<h3>Prihodnost</h3>\n<p><b>CBDC</b> (centralne bančne digitalne valute), <b>Web3</b> (decentraliziran internet), <b>DeFi</b> (decentralizirane finance), <b>DAO</b> (decentralizirane avtonomne organizacije). Alternativa SWIFT za nakazila.</p>\n</div>"},{"id":"izpit","name":"Izpit","type":"izpit","decks":[]}]}]}];

const TIER = {
  S: { label: "S", bg: "var(--terra)", fg: "#fff" },
  A: { label: "A", bg: "var(--ink)", fg: "var(--paper)" },
  B: { label: "B", bg: "var(--teal)", fg: "#fff" },
  C: { label: "C", bg: "#b9b2a3", fg: "var(--ink)" },
};

/* ---- obstojno shranjevanje napredka (localStorage + fallback) ---- */
const store = (() => {
  let mem = {};
  let ok = false;
  try { localStorage.setItem("__ix_t", "1"); localStorage.removeItem("__ix_t"); ok = true; } catch (e) { ok = false; }
  return {
    get(k, d) { try { if (ok) { const v = localStorage.getItem(k); return v == null ? d : JSON.parse(v); } } catch (e) {} return k in mem ? mem[k] : d; },
    set(k, v) { try { if (ok) { localStorage.setItem(k, JSON.stringify(v)); return; } } catch (e) {} mem[k] = v; },
  };
})();
